// Hyperreal Thermal Camera Painting: Sleeping Dog on a Sagging Sofa
// Rendered with p5.js v2 + p5.brush in WEBGL

const PALETTE = [
  { t: 0.00, c: [11, 10, 18] },     // Deep charcoal-indigo shadow
  { t: 0.08, c: [20, 19, 35] },     // Muted earth-slate indigo
  { t: 0.17, c: [32, 26, 56] },     // Deep Prussian indigo-violet
  { t: 0.27, c: [52, 30, 74] },     // Smoky aubergine / cool cushion violet
  { t: 0.37, c: [82, 34, 86] },     // Dusty plum-violet
  { t: 0.47, c: [122, 38, 86] },    // Rich magenta-plum
  { t: 0.57, c: [164, 48, 80] },    // Warm crimson-magenta
  { t: 0.67, c: [198, 69, 64] },    // Terracotta-magenta / sienna rose
  { t: 0.76, c: [224, 104, 50] },   // Cadmium orange / warm ochre-amber
  { t: 0.85, c: [242, 156, 56] },   // Luminous golden amber
  { t: 0.92, c: [252, 212, 98] },   // Blazing yellow-gold
  { t: 0.97, c: [255, 244, 178] },  // Incandescent cream-yellow
  { t: 1.00, c: [255, 253, 244] }   // Blazing yellow-white core
];

const EARTH_TONES = [
  "#1c1922", "#2b2429", "#3d3133", "#54413c",
  "#6e5347", "#8a6b56", "#a8876c", "#c4a888"
];

function sampleThermalRGB(t, earthMix = 0) {
  let v = constrain(t, 0, 1);
  let r = 11, g = 10, b = 18;
  for (let i = 0; i < PALETTE.length - 1; i++) {
    let p0 = PALETTE[i];
    let p1 = PALETTE[i + 1];
    if (v >= p0.t && v <= p1.t) {
      let f = (v - p0.t) / (p1.t - p0.t + 1e-6);
      f = f * f * (3 - 2 * f);
      r = lerp(p0.c[0], p1.c[0], f);
      g = lerp(p0.c[1], p1.c[1], f);
      b = lerp(p0.c[2], p1.c[2], f);
      break;
    }
  }
  if (earthMix > 0) {
    // Muted warm umber/ochre earth shift for tactile pigment grounding
    let er = lerp(38, 185, v);
    let eg = lerp(30, 148, v);
    let eb = lerp(28, 110, v);
    r = lerp(r, er, earthMix);
    g = lerp(g, eg, earthMix);
    b = lerp(b, eb, earthMix);
  }
  return [Math.round(r), Math.round(g), Math.round(b)];
}

function rgbHex(rgb) {
  let toH = (n) => constrain(Math.round(n), 0, 255).toString(16).padStart(2, "0");
  return "#" + toH(rgb[0]) + toH(rgb[1]) + toH(rgb[2]);
}

function thermalHex(t, earthMix = 0) {
  return rgbHex(sampleThermalRGB(t, earthMix));
}

// Smooth Gaussian helper with anisotropic rotation
function gauss2D(x, y, cx, cy, rx, ry, angleDeg = 0) {
  let rad = angleDeg * Math.PI / 180;
  let dx = x - cx;
  let dy = y - cy;
  let ux = dx * Math.cos(rad) + dy * Math.sin(rad);
  let uy = -dx * Math.sin(rad) + dy * Math.cos(rad);
  let d2 = (ux * ux) / (rx * rx) + (uy * uy) / (ry * ry);
  if (d2 > 9) return 0;
  return Math.exp(-d2);
}

// Distance to line segment with smooth falloff
function segGlow(px, py, x1, y1, x2, y2, radius) {
  let vx = x2 - x1, vy = y2 - y1;
  let wx = px - x1, wy = py - y1;
  let l2 = vx * vx + vy * vy + 1e-6;
  let u = constrain((wx * vx + wy * vy) / l2, 0, 1);
  let dx = px - (x1 + u * vx);
  let dy = py - (y1 + u * vy);
  let d2 = (dx * dx + dy * dy) / (radius * radius);
  if (d2 > 9) return 0;
  return Math.exp(-d2);
}

// Evaluate warm ghost handprint on left armrest
function getHandprintThermal(x, y) {
  if (x < 90 || x > 340 || y < 340 || y > 650) return 0;
  let h = 0;
  // Soft ambient palm halo diffused into the armrest fabric
  h += 0.24 * gauss2D(x, y, 202, 500, 68, 82, -22);

  // Palm heel: Thenar eminence (thumb side) & Hypothenar eminence (outer edge)
  h += 0.36 * gauss2D(x, y, 226, 534, 28, 38, -28);
  h += 0.30 * gauss2D(x, y, 168, 538, 22, 42, -12);
  // Distal palmar arch (knuckle pad ridge)
  h += 0.32 * gauss2D(x, y, 196, 480, 44, 20, -18);
  // Subtle cooling in the central hollow of the palm
  h -= 0.16 * gauss2D(x, y, 198, 514, 18, 20, -20);
  // Faint wrist fade
  h += 0.14 * gauss2D(x, y, 192, 595, 30, 35, -15);

  // Five fingers: [baseX, baseY, midX, midY, tipX, tipY, heat]
  const fingers = [
    // Thumb angled inward toward the dog
    [242, 520, 268, 502, 290, 488, 0.44],
    // Index finger
    [230, 466, 240, 432, 247, 404, 0.48],
    // Middle finger
    [202, 458, 207, 420, 210, 388, 0.50],
    // Ring finger
    [175, 466, 173, 430, 171, 398, 0.45],
    // Pinky finger
    [150, 482, 141, 454, 133, 430, 0.38]
  ];

  for (let f of fingers) {
    // Proximal & middle phalanges
    h += f[6] * 0.55 * segGlow(x, y, f[0], f[1], f[2], f[3], 10.5);
    h += f[6] * 0.65 * segGlow(x, y, f[2], f[3], f[4], f[5], 9.5);
    // Warm finger pad imprint at tip
    h += f[6] * 0.92 * gauss2D(x, y, f[4], f[5], 11, 13, -15);
  }

  return constrain(h, 0, 0.78);
}

// Evaluate sofa background and cushion thermal field
function getSofaThermal(x, y) {
  let t = 0.04;

  // Backrest cushions (cool indigo & violet, warming slightly toward bottom crease)
  if (y < 520) {
    let backWarmth = gauss2D(x, y, 670, 460, 420, 190, 0) * 0.22;
    let leftCushion = gauss2D(x, y, 490, 340, 230, 130, 4) * 0.14;
    let rightCushion = gauss2D(x, y, 950, 330, 220, 130, -5) * 0.12;
    t = 0.05 + backWarmth + leftCushion + rightCushion;
  }

  // Seat cushion base warmth
  let seatBase = gauss2D(x, y, 710, 700, 440, 220, -2) * 0.26;
  t = Math.max(t, 0.07 + seatBase);

  // Conductive thermal halo around the curled dog in the sagging hollow
  let dogHalo = gauss2D(x, y, 690, 650, 310, 210, -4) * 0.36;
  let deepSagGlow = gauss2D(x, y, 675, 695, 220, 145, -3) * 0.24;
  t += dogHalo + deepSagGlow;

  // Warm exhaled breath plume on cushion in front of the dog's nose (460, 655)
  let breathPlume = gauss2D(x, y, 412, 682, 68, 46, -24) * 0.52;
  let breathCore = gauss2D(x, y, 438, 668, 34, 24, -22) * 0.35;
  t += breathPlume + breathCore;

  // Left armrest base cool violet-indigo + warm handprint ghost
  let armMass = gauss2D(x, y, 185, 560, 140, 240, -12) * 0.16;
  t = Math.max(t, 0.06 + armMass);
  t += getHandprintThermal(x, y);

  // Subtle fabric sag fold modulations radiating from (685, 665)
  let dx = x - 685, dy = y - 665;
  let dist = Math.sqrt(dx * dx + dy * dy);
  if (dist > 140 && dist < 520 && y > 460 && y < 960 && x > 280) {
    let ang = Math.atan2(dy, dx);
    let foldWave = Math.sin(ang * 14 + dist * 0.018) * 0.028;
    t += foldWave * gauss2D(x, y, 685, 680, 380, 220, 0);
  }

  // Cool dark crevice along the sofa cushion front piping & lower skirt
  let pipingY = 900 + 55 * Math.exp(-Math.pow((x - 690) / 320, 2));
  if (y > pipingY - 18) {
    let skirtCool = constrain((y - (pipingY - 18)) / 90, 0, 1);
    t = lerp(t, 0.04 + 0.08 * gauss2D(x, y, 680, 1020, 380, 120, 0), skirtCool * 0.78);
  }

  return constrain(t, 0.02, 0.88);
}

// Comprehensive anatomical model of the curled sleeping dog
// Returns { inside: bool, t: thermal [0..1], angle: furAngleDeg, part: string, earth: number }
function getDogData(x, y) {
  // Quick bounding box rejection
  if (x < 405 || x > 985 || y < 415 || y > 875) {
    return { inside: false, t: 0, angle: 0, part: "none", earth: 0 };
  }

  // Check composite anatomical lobes to define the exact silhouette of the curled dog
  // 1. Main curled torso / ribcage / back (upper & right crescent)
  let torso = gauss2D(x, y, 695, 595, 225, 152, 8);
  // 2. Shoulder & withers (upper left-center)
  let shoulder = gauss2D(x, y, 575, 525, 118, 88, -22);
  // 3. Lumbar & croup / hip (right curve)
  let hip = gauss2D(x, y, 835, 635, 112, 128, 25);
  // 4. Haunch / thigh & lower hind leg (bottom right to bottom center)
  let thigh = gauss2D(x, y, 775, 735, 132, 84, -22);
  // 5. Curled tail wrapping the bottom edge
  let tail = gauss2D(x, y, 690, 800, 138, 46, -6);
  // 6. Head & cranium (left side)
  let skull = gauss2D(x, y, 512, 552, 74, 66, -18);
  // 7. Muzzle / snout projecting down-left
  let muzzle = gauss2D(x, y, 478, 632, 46, 54, 24);
  // 8. Floppy ear draping over neck
  let ear = gauss2D(x, y, 588, 565, 46, 68, -28);
  // 9. Tucked forelegs & paws region (lower left-center)
  let pawsArea = gauss2D(x, y, 585, 720, 96, 62, 15);

  let silhouetteField = Math.max(
    torso,
    shoulder * 0.95,
    hip * 0.96,
    thigh * 0.95,
    tail * 0.88,
    skull * 0.96,
    muzzle * 0.92,
    ear * 0.95,
    pawsArea * 0.92
  );

  // Soft indentation under the chin/muzzle so head and tail/paw separate cleanly
  let chinIndent = gauss2D(x, y, 442, 712, 48, 42, 10);
  silhouetteField -= chinIndent * 0.45;

  if (silhouetteField < 0.24) {
    return { inside: false, t: 0, angle: 0, part: "none", earth: 0 };
  }

  // Base dorsal coat thermal level (violet-magenta to warm terracotta-rose)
  let t = 0.40 + 0.22 * gauss2D(x, y, 675, 620, 210, 150, 0);
  let earth = 0.14;
  let part = "body";

  // Default anatomical fur flow around the curled spine
  let cx = 665, cy = 640;
  let ang = atan2(y - cy, x - cx) + 92;

  // --- A. OUTER RIBCAGE, SPINE & RADIAL SKIN CREVICES ---
  // Cool thicker guard hair along outer dorsal rim (indigo-violet-magenta)
  let outerRim = gauss2D(x, y, 710, 465, 190, 42, 6) +
                 gauss2D(x, y, 905, 620, 45, 135, 12);
  t -= outerRim * 0.12;

  // Warm skin partings / fissures between fur clumps radiating from center of curl
  let relAngle = Math.atan2(y - 635, x - 670);
  let radialCrevices = Math.pow(0.5 + 0.5 * Math.sin(relAngle * 11 + (x + y) * 0.015), 4);
  let midTorsoBand = gauss2D(x, y, 705, 555, 175, 95, 12);
  t += radialCrevices * midTorsoBand * 0.22;

  // Warm inter-scapular / shoulder fold
  let scapulaFold = segGlow(x, y, 585, 495, 635, 585, 22);
  t += scapulaFold * 0.20;

  // Warm hip/flank crease separating thigh from ribcage
  let flankCrease = segGlow(x, y, 715, 635, 835, 705, 20);
  t += flankCrease * 0.24;

  // --- B. BLAZING BELLY & CHEST CORE (Thermal Center) ---
  let bellyCore = gauss2D(x, y, 695, 645, 96, 68, -12);
  let bellyHotspot = gauss2D(x, y, 685, 650, 62, 42, -10);
  let chestPocket = gauss2D(x, y, 610, 645, 58, 48, 20);
  if (bellyCore > 0.15 || chestPocket > 0.2) {
    t = Math.max(t, 0.58 + bellyCore * 0.36 + bellyHotspot * 0.22 + chestPocket * 0.28);
    earth = 0.03;
    part = "belly";
    ang = atan2(y - 650, x - 680) + 75;
  }

  // --- C. TAIL (Feathery cooler plum-violet-magenta strands wrapping bottom) ---
  if (tail > 0.35 && y > 735) {
    let tailCool = gauss2D(x, y, 700, 812, 130, 34, -6);
    t = lerp(t, 0.30 + 0.22 * gauss2D(x, y, 790, 780, 70, 35, -15), constrain(tailCool * 1.2, 0, 0.85));
    earth = 0.22;
    part = "tail";
    // Flow from tail base (860, 765) toward tip (565, 795)
    ang = 172 + (x - 700) * 0.14;
  }

  // --- D. PAWS & BLAZING PAW PADS ---
  // Hind Paw 1 (around 625, 726)
  let hp1 = gauss2D(x, y, 625, 726, 36, 28, 20);
  if (hp1 > 0.2) {
    part = "paw";
    ang = 145;
    t = Math.max(t, 0.66 + hp1 * 0.18);
    // Main plantar pad + 4 digital toe pads (blazing yellow-white!)
    let padMain = gauss2D(x, y, 636, 728, 12, 14, 20);
    let toe1 = gauss2D(x, y, 612, 708, 6.5, 8.5, 10);
    let toe2 = gauss2D(x, y, 610, 722, 6.5, 8.5, 18);
    let toe3 = gauss2D(x, y, 615, 736, 6.5, 8.5, 25);
    let toe4 = gauss2D(x, y, 625, 748, 6.0, 8.0, 32);
    let padHeat = Math.max(padMain, toe1, toe2, toe3, toe4);
    t = Math.max(t, 0.78 + padHeat * 0.32);
    if (padHeat > 0.35) earth = 0.0;
  }

  // Hind Paw 2 tucked slightly behind at (682, 742)
  let hp2 = gauss2D(x, y, 682, 742, 28, 22, -10);
  if (hp2 > 0.25) {
    part = "paw";
    let p2Main = gauss2D(x, y, 688, 742, 10, 11, -10);
    let p2Toe1 = gauss2D(x, y, 670, 732, 6, 7.5, -5);
    let p2Toe2 = gauss2D(x, y, 668, 745, 6, 7.5, 5);
    let p2Toe3 = gauss2D(x, y, 674, 756, 5.5, 7, 12);
    let padHeat2 = Math.max(p2Main, p2Toe1, p2Toe2, p2Toe3);
    t = Math.max(t, 0.74 + padHeat2 * 0.30);
    if (padHeat2 > 0.35) earth = 0.0;
  }

  // Front Paw 1 curled near snout at (545, 735)
  let fp1 = gauss2D(x, y, 546, 734, 34, 26, -15);
  if (fp1 > 0.2) {
    part = "paw";
    ang = 160;
    t = Math.max(t, 0.68 + fp1 * 0.16);
    let fMain = gauss2D(x, y, 552, 732, 11, 13, -15);
    let fToe1 = gauss2D(x, y, 532, 718, 6.2, 8.0, -20);
    let fToe2 = gauss2D(x, y, 528, 731, 6.2, 8.0, -12);
    let fToe3 = gauss2D(x, y, 531, 744, 6.2, 8.0, -4);
    let fToe4 = gauss2D(x, y, 540, 755, 5.8, 7.5, 6);
    let fHeat = Math.max(fMain, fToe1, fToe2, fToe3, fToe4);
    t = Math.max(t, 0.80 + fHeat * 0.32);
    if (fHeat > 0.35) earth = 0.0;
  }

  // Front Paw 2 tucked under chin at (496, 695)
  let fp2 = gauss2D(x, y, 496, 695, 24, 18, 12);
  if (fp2 > 0.25) {
    part = "paw";
    let fp2Pad = Math.max(
      gauss2D(x, y, 492, 692, 7, 8, 10),
      gauss2D(x, y, 498, 703, 6.5, 7.5, 18)
    );
    t = Math.max(t, 0.75 + fp2Pad * 0.28);
  }

  // --- E. HEAD, CRANIUM, SLEEPING EYE, FLOPPY EAR & BLAZING NOSE ---
  if (skull > 0.22 || muzzle > 0.22 || ear > 0.22) {
    if (ear > 0.36 && x > 535) {
      // Floppy Ear Pinna (rich vascular magenta-orange with hot ear canal base)
      part = "ear";
      ang = 62 + (y - 540) * 0.22;
      t = 0.56 + 0.22 * gauss2D(x, y, 580, 560, 38, 56, -28);
      // Hot external ear canal opening at base of ear flap
      let earCanal = gauss2D(x, y, 556, 558, 18, 15, -15);
      t += earCanal * 0.38;
      // Branching auricular blood vessels
      let v1 = segGlow(x, y, 558, 555, 608, 585, 5.5);
      let v2 = segGlow(x, y, 562, 558, 592, 610, 5.0);
      let v3 = segGlow(x, y, 582, 570, 618, 568, 4.0);
      t += Math.max(v1, v2, v3) * 0.18;
      // Dark shadowed rim along lower-left edge of ear flap for crisp 3D separation
      let earShadowEdge = segGlow(x, y, 542, 535, 575, 622, 8.0);
      t -= earShadowEdge * 0.18;
    } else {
      // Skull & Muzzle
      part = "head";
      let headWarmth = gauss2D(x, y, 505, 565, 62, 58, -10);
      t = Math.max(t, 0.54 + headWarmth * 0.24);

      // Fur flow radiates from nose bridge (475, 625) up over forehead
      ang = atan2(y - 635, x - 468);
      if (y < 595) {
        ang = lerp(245, 345, constrain((x - 455) / 110, 0, 1));
      } else {
        ang = 120 + (x - 460) * 0.3;
      }

      // Sleeping closed eye slit & hot medial canthus (inner tear duct at 496, 596)
      let eyeSlit = segGlow(x, y, 496, 596, 532, 588, 5.5);
      let tearDuct = gauss2D(x, y, 496, 596, 9, 7, -12);
      let browRidge = segGlow(x, y, 492, 584, 536, 576, 9.0);
      t += eyeSlit * 0.28 + tearDuct * 0.34 + browRidge * 0.12;

      // Blazing yellow-white NOSE at (462, 654) as specified in style directives
      let noseBridge = segGlow(x, y, 486, 602, 464, 650, 18);
      let noseTip = gauss2D(x, y, 462, 654, 22, 18, 25);
      let nostrils = gauss2D(x, y, 456, 656, 13, 11, 20) + gauss2D(x, y, 468, 662, 11, 9, 25);
      t = Math.max(t, 0.62 + noseBridge * 0.22 + noseTip * 0.36 + nostrils * 0.25);
      if (noseTip > 0.25) {
        part = "nose";
        earth = 0.0;
      }
    }
  }

  return {
    inside: true,
    t: constrain(t, 0.18, 1.0),
    angle: ang,
    part: part,
    earth: earth
  };
}

// Unified scene query
function sampleSceneThermal(x, y) {
  let dog = getDogData(x, y);
  if (dog.inside) return dog;
  let sofaT = getSofaThermal(x, y);
  return { inside: false, t: sofaT, angle: 0, part: "sofa", earth: 0.18 };
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(42719);

  // Register custom brushes for airbrush thermal gradients, stipple spray, and hyperreal fur
  brush.add("thermal_airbrush", {
    type: "default",
    weight: 16,
    scatter: 1.35,
    sharpness: 0.06,
    grain: 0.14,
    opacity: 19,
    spacing: 0.35,
    pressure: [0.3, 1.0, 0.3],
    noise: 0.25
  });

  brush.add("thermal_soft", {
    type: "default",
    weight: 7.5,
    scatter: 0.85,
    sharpness: 0.14,
    grain: 0.22,
    opacity: 28,
    spacing: 0.3,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.3
  });

  brush.add("thermal_spray", {
    type: "spray",
    weight: 11,
    scatter: 2.2,
    opacity: 26,
    spacing: 0.55,
    pressure: [0.4, 1.0, 0.4]
  });

  brush.add("fur_pencil", {
    type: "default",
    weight: 0.42,
    scatter: 0.06,
    sharpness: 0.84,
    grain: 0.62,
    opacity: 92,
    spacing: 0.18,
    pressure: [0.15, 1.0, 0.08],
    noise: 0.45
  });

  brush.add("glow_strand", {
    type: "default",
    weight: 0.52,
    scatter: 0.08,
    sharpness: 0.72,
    grain: 0.45,
    opacity: 135,
    spacing: 0.16,
    pressure: [0.1, 1.15, 0.05],
    noise: 0.35
  });

  brush.add("ui_pen", {
    type: "default",
    weight: 0.55,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 0.18,
    opacity: 215,
    spacing: 0.12,
    pressure: [0.85, 1.0, 0.85],
    noise: 0.15
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#0b0a12");

  // 1. Foundational Watercolor & Wash Underpainting (Sofa & Thermal Halo)
  drawThermalUnderpainting();

  // 2. Sofa Sagging Cushions, Creases & Woven Upholstery Texture
  drawSofaStructureAndWeave();

  // 3. Warm Handprint Ghost on the Left Armrest
  drawWarmHandprintGhost();

  // 4. Dog Thermal Core Airbrushing (Indigo/Violet -> Magenta -> Blazing Yellow-White)
  drawDogThermalAirbrush();

  // 5. Hyperreal Anatomical Details (Belly Core, Paw Pads, Nose, Eye, Ear Vessels)
  drawDogAnatomicalHotspots();

  // 6. Hyperreal Fur Direction (Thousands of Fine Pencil Strands Drifting Through False Colour)
  drawHyperrealFurStrands();

  // 7. Whiskers, Guard Hairs & Fine Edge Rim Light
  drawWhiskersAndFineDetails();

  // 8. Corner Temperature-Scale Bar & Crosshair in Thin White Pen
  drawThermalHUD();

  noLoop();
}

// Helper to draw a closed smooth shape with wash/fill
function drawWashBlob(cx, cy, rx, ry, rotDeg, ptsCount, jitter = 0.06) {
  let rad = rotDeg * Math.PI / 180;
  brush.beginShape(0.55);
  for (let i = 0; i < ptsCount; i++) {
    let a = (i / ptsCount) * Math.PI * 2;
    let n = 1 + (noise(cx * 0.01 + Math.cos(a), cy * 0.01 + Math.sin(a)) - 0.5) * jitter * 2;
    let lx = Math.cos(a) * rx * n;
    let ly = Math.sin(a) * ry * n;
    let gx = cx + lx * Math.cos(rad) - ly * Math.sin(rad);
    let gy = cy + lx * Math.sin(rad) + ly * Math.cos(rad);
    brush.vertex(gx, gy);
  }
  brush.endShape(true);
}

// ============================================================================
// 1. FOUNDATIONAL WATERCOLOR & WASH UNDERPAINTING
// ============================================================================
function drawThermalUnderpainting() {
  brush.noField();
  brush.noStroke();

  // Deep cool indigo-earth room and sofa shadow washes
  const bgZones = [
    { x: 600, y: 180, rx: 680, ry: 220, rot: 0, t: 0.04, earth: 0.35, op: 180 },
    { x: 460, y: 340, rx: 310, ry: 170, rot: 3, t: 0.14, earth: 0.25, op: 150 },
