// ============================================================================
// 2. SOFA SAGGING CUSHIONS, CREASES & WOVEN UPHOLSTERY TEXTURE
// ============================================================================
function drawSofaStructureAndWeave() {
  // Airbrush passes across the sofa cushions to establish smooth indigo-violet-magenta gradients
  for (let i = 0; i < 950; i++) {
    let x = random(-20, 1220);
    let y = random(140, 1180);
    let d = getDogData(x, y);
    if (d.inside) continue;

    let t = getSofaThermal(x, y);
    let earthMix = map(y, 150, 1150, 0.28, 0.14) * (1 - t * 0.6);
    let col = thermalHex(t + random(-0.03, 0.03), earthMix);

    // Angle follows the sag of the sofa cushion
    let sagDrop = 65 * Math.exp(-Math.pow((x - 690) / 340, 2));
    let slopeAngle = atan2(sagDrop * -2 * (x - 690) / (340 * 340), 1);
    if (x < 310 && y > 320 && y < 920) {
      // Left armrest contour angle
      slopeAngle = -72 + (y - 500) * 0.08;
    }

    let bName = random() < 0.65 ? "thermal_airbrush" : "thermal_spray";
    let w = bName === "thermal_airbrush" ? random(1.1, 2.4) : random(0.8, 1.6);
    brush.set(bName, col, w);

    let len = random(45, 110);
    let x2 = x + cos(slopeAngle) * len;
    let y2 = y + sin(slopeAngle) * len;
    brush.line(x, y, x2, y2);
  }

  // Structural sofa seams & sagging fabric tension folds around the dog
  // A. Backrest-to-seat deep crease & vertical cushion seam
  drawSofaSeam([[285, 475], [480, 508], [690, 538], [920, 505], [1190, 468]], 0.11, 2.2);
  drawSofaSeam([[738, 195], [732, 310], [720, 425], [705, 495]], 0.09, 1.8);

  // B. Left armrest inner bolster seam & front fascia roll
  drawSofaSeam([[285, 340], [322, 460], [332, 575], [302, 740], [262, 910]], 0.12, 2.0);
  drawSofaSeam([[68, 595], [155, 570], [242, 595], [285, 675], [255, 905]], 0.10, 1.6);

  // C. Sagging front seat cushion piping seam (dips deeply under the dog's weight)
  let pipingPts = [];
  for (let x = 260; x <= 1190; x += 45) {
    let sag = 58 * Math.exp(-Math.pow((x - 690) / 310, 2));
    pipingPts.push([x, 892 + sag]);
  }
  drawSofaSeam(pipingPts, 0.08, 2.4);
  // Warm highlight along top lip of piping
  let pipingHighlight = pipingPts.map(p => [p[0], p[1] - 7]);
  drawSofaSeam(pipingHighlight, 0.30, 1.2);

  // D. Radiating sagging folds in the seat cushion fabric pulling toward the dog
  const sagFolds = [
    [[315, 560], [395, 605], [475, 640]],
    [[305, 680], [395, 705], [485, 715]],
    [[310, 815], [435, 795], [545, 775]],
    [[445, 915], [535, 865], [615, 818]],
    [[680, 948], [688, 885], [695, 835]],
    [[915, 915], [845, 855], [785, 795]],
    [[1095, 845], [985, 785], [885, 735]],
    [[1145, 680], [1035, 668], [935, 658]],
    [[1120, 535], [1015, 555], [915, 575]]
  ];

  for (let fold of sagFolds) {
    let mid = fold[1];
    let localT = getSofaThermal(mid[0], mid[1]);
    // Warm compressed valley of fold
    brush.set("thermal_soft", thermalHex(localT + 0.09, 0.08), 1.1);
    brush.spline(fold, 0.5);
    // Cool slack ridge beside fold
    let offsetFold = fold.map(p => [p[0] + 6, p[1] - 6]);
    brush.set("thermal_soft", thermalHex(Math.max(0.05, localT - 0.08), 0.22), 0.9);
    brush.spline(offsetFold, 0.5);
  }

  // E. Subtle woven upholstery thread texture (warp & weft) across sofa cushions
  for (let i = 0; i < 1100; i++) {
    let x = random(20, 1180);
    let y = random(180, 1080);
    if (getDogData(x, y).inside) continue;

    let t = getSofaThermal(x, y);
    let isWeft = random() < 0.55;
    let sagSlope = -0.18 * ((x - 690) / 320) * Math.exp(-Math.pow((x - 690) / 320, 2));
    let ang = isWeft ? degrees(atan(sagSlope)) : 88 + (x - 690) * 0.02;

    if (x < 315 && y > 330 && y < 900) {
      ang = isWeft ? -18 + (y - 500) * 0.05 : 72;
    }

    let dt = random(-0.06, 0.07);
    let col = thermalHex(constrain(t + dt, 0.03, 0.85), random(0.12, 0.35));
    brush.set(random() < 0.5 ? "2H" : "HB", col, random(0.35, 0.65));

    let len = random(14, 34);
    brush.line(
      x - cos(ang) * len * 0.5,
      y - sin(ang) * len * 0.5,
      x + cos(ang) * len * 0.5,
      y + sin(ang) * len * 0.5
    );
  }
}

function drawSofaSeam(pts, tVal, weightMult) {
  brush.set("thermal_airbrush", thermalHex(tVal, 0.25), weightMult);
  brush.spline(pts, 0.5);
  brush.set("2B", thermalHex(tVal * 0.8, 0.35), weightMult * 0.45);
  brush.spline(pts, 0.5);
}

