    if (h < 0.05) continue;

    let totalT = constrain(0.14 + h * 0.92 + random(-0.03, 0.03), 0.14, 0.84);
    let col = thermalHex(totalT, 0.08 * (1 - h));
    let bName = random() < 0.6 ? "thermal_soft" : "thermal_spray";
