// ============================================================================
// 6. HYPERREAL FUR DIRECTION (FINE PENCIL STRANDS DRIFTING THROUGH FALSE COLOUR)
// ============================================================================
function drawHyperrealFurStrands() {
  // Layer 1: Undercoat & mid-coat directional pencil strands across the entire dog
  const totalStrands = 3400;
  for (let i = 0; i < totalStrands; i++) {
    // Stratified sampling with extra density on head, ruff, back, belly rim, and tail
    let x = random(418, 965);
    let y = random(430, 855);
    let d = getDogData(x, y);
    if (!d.inside) continue;

    // Determine strand length and curvature by anatomical region
    let len = random(18, 38);
    let curve = random(-14, 14);
    if (d.part === "head" || d.part === "ear") {
      len = random(10, 22);
      curve = random(-8, 8);
    } else if (d.part === "nose") {
      continue; // Keep nose leather bare & glowing
    } else if (d.part === "paw") {
      len = random(8, 16);
    } else if (d.part === "tail") {
      len = random(28, 54);
      curve = random(-18, 18);
    } else if (d.part === "belly") {
      // Wispy longer chest/flank hairs drifting over the blazing belly
      len = random(20, 42);
    }

    let a1 = d.angle + random(-9, 9);
    let a2 = a1 + curve * 0.5;
    let a3 = a2 + curve * 0.5;

    let x1 = x;
    let y1 = y;
    let x2 = x1 + cos(a1) * (len * 0.36);
    let y2 = y1 + sin(a1) * (len * 0.36);
    let x3 = x2 + cos(a2) * (len * 0.36);
    let y3 = y2 + sin(a2) * (len * 0.36);
    let x4 = x3 + cos(a3) * (len * 0.28);
    let y4 = y3 + sin(a3) * (len * 0.28);

    // Sample thermal value at root and tip to create hyperreal false-color fur contrast:
    // Cooler guard hair tips drifting over warmer skin/undercoat, or glowing hot strands!
    let tipData = getDogData(x3, y3);
    let baseT = tipData.inside ? (d.t * 0.6 + tipData.t * 0.4) : d.t;

    let strandMode = random();
    let strandT, earthAmt, brushName, weight;

    if (strandMode < 0.42) {
      // Insulated cooler guard hair strand (indigo-violet-magenta-umber contrast)
      strandT = constrain(baseT - random(0.08, 0.20), 0.14, 0.88);
      earthAmt = d.earth + random(0.05, 0.22);
      brushName = random() < 0.6 ? "fur_pencil" : "cpencil";
      weight = random(0.45, 0.85);
    } else if (strandMode < 0.82) {
      // True local thermal color strand
      strandT = constrain(baseT + random(-0.04, 0.06), 0.20, 0.96);
      earthAmt = d.earth * 0.7;
      brushName = "fur_pencil";
      weight = random(0.5, 0.95);
    } else {
      // Electric glowing thermal strand (magenta -> amber -> blazing yellow-white)
      strandT = constrain(baseT + random(0.08, 0.22), 0.38, 1.0);
      earthAmt = 0.0;
      brushName = "glow_strand";
      weight = random(0.55, 1.05);
    }

    brush.set(brushName, thermalHex(strandT, earthAmt), weight);
    brush.spline([[x1, y1, 0.3], [x2, y2, 0.95], [x3, y3, 0.7], [x4, y4, 0.1]], 0.5);
  }

  // Layer 2: Concentrated glowing fur strands drifting across the blazing belly boundary,
  // neck ruff, ear fringe, and interdigital paw fur
  for (let i = 0; i < 650; i++) {
    let a = random(0, 360);
    let rx = random(45, 155);
    let ry = random(35, 115);
    let x = 675 + cos(a) * rx;
    let y = 645 + sin(a) * ry;
    let d = getDogData(x, y);
    if (!d.inside) continue;

    let len = random(18, 36);
    let dir = d.angle + random(-12, 12);
    // Curve inward toward the warm belly hollow
    let x2 = x + cos(dir) * len * 0.5;
    let y2 = y + sin(dir) * len * 0.5;
    let x3 = x2 + cos(dir + 10) * len * 0.5;
    let y3 = y2 + sin(dir + 10) * len * 0.5;

    let hotT = constrain(d.t + random(0.05, 0.18), 0.55, 1.0);
    brush.set("glow_strand", thermalHex(hotT, 0), random(0.55, 1.0));
    brush.spline([[x, y, 0.2], [x2, y2, 1.0], [x3, y3, 0.1]], 0.5);
  }
}

