    brush.set("fur_pencil", thermalHex(0.58, 0.1), 0.45);
    brush.spline(shadowW, 0.55);
  }

  // Fine feathery guard hairs breaking the outer silhouette along the spine, haunch, and tail
  for (let i = 0; i < 320; i++) {
    let tAngle = random(-155, 145);
    // Trace along outer perimeter of the curled dog
    let bx = 685 + cos(tAngle) * 245;
    let by = 635 + sin(tAngle) * 175;
    let d = getDogData(bx, by);
    if (!d.inside) continue;

    let len = random(16, 34);
    let a = d.angle + random(-15, 15);
    let x2 = bx + cos(a) * len * 0.5;
    let y2 = by + sin(a) * len * 0.5;
    let x3 = x2 + cos(a + random(-10, 10)) * len * 0.5;
    let y3 = y2 + sin(a + random(-10, 10)) * len * 0.5;

    let col = thermalHex(constrain(d.t + random(-0.06, 0.08), 0.24, 0.86), 0.15);
    brush.set("fur_pencil", col, random(0.45, 0.78));
    brush.spline([[bx, by, 0.4], [x2, y2, 0.8], [x3, y3, 0.05]], 0.5);
  }
}

