// 8. CORNER TEMPERATURE-SCALE BAR & CROSSHAIR IN THIN WHITE PEN
// ============================================================================
function drawThermalHUD() {
  const uiWhite = "#f4f1ea";
  const uiDim = "#c8c2b8";

  // --- A. TEMPERATURE-SCALE BAR (Top-Right Corner: x=1108, y=82..322) ---
  const barX = 1108;
  const barY = 82;
  const barW = 16;
  const barH = 240;
  const steps = 40;
  const stepH = barH / steps;

  // Fill the bar with the false-color thermal gradient (blazing yellow-white top -> indigo bottom)
  for (let i = 0; i < steps; i++) {
    let f = 1 - i / (steps - 1);
    let col = thermalHex(f, 0.04);
    let sy = barY + i * stepH;
    brush.set("thermal_soft", col, 0.55);
    for (let r = 0; r < 3; r++) {
      let ry = sy + (r / 3) * stepH;
      brush.line(barX + 1, ry, barX + barW - 1, ry);
    }
  }

  // Thin white pen frame around the temperature-scale bar
  brush.set("ui_pen", uiWhite, 0.85);
  brush.line(barX, barY, barX + barW, barY);
  brush.line(barX + barW, barY, barX + barW, barY + barH);
  brush.line(barX + barW, barY + barH, barX, barY + barH);
  brush.line(barX, barY + barH, barX, barY);

  // Scale graduation ticks and temperature readouts (39.5°C to 18.0°C)
  const tickCount = 8;
  for (let i = 0; i <= tickCount; i++) {
    let ty = barY + (i / tickCount) * barH;
    let isMajor = i % 2 === 0;
    let tickLen = isMajor ? 8 : 4.5;
    brush.set("ui_pen", uiWhite, isMajor ? 0.8 : 0.6);
    brush.line(barX - tickLen, ty, barX, ty);
  }

  // Draw crisp vector numerals in thin white pen beside major ticks
  drawVectorString("39.4", barX - 48, barY - 5, 7.5, uiWhite);
  drawVectorString("34.0", barX - 48, barY + barH * 0.25 - 5, 7.5, uiDim);
  drawVectorString("28.6", barX - 48, barY + barH * 0.50 - 5, 7.5, uiDim);
  drawVectorString("23.2", barX - 48, barY + barH * 0.75 - 5, 7.5, uiDim);
  drawVectorString("18.0", barX - 48, barY + barH - 5, 7.5, uiWhite);
  // Unit label °C above bar
  drawDegreeCelsius(barX + 2, barY - 20, 8.5, uiWhite);

  // --- B. CORNER CROSSHAIR & TARGET RETICLE IN THIN WHITE PEN ---
  // Positioned in the upper-left corner area (x=104, y=104) with subtle corner frame brackets
  const cx = 104;
  const cy = 104;
  brush.set("ui_pen", uiWhite, 0.82);

  // Outer broken target circle
  brush.arc(cx, cy, 22, 15, 75);
  brush.arc(cx, cy, 22, 105, 165);
  brush.arc(cx, cy, 22, 195, 255);
  brush.arc(cx, cy, 22, 285, 345);

  // Inner ring
  brush.circle(cx, cy, 6, 0.08);

  // Crosshair axes with central gap
  brush.line(cx - 34, cy, cx - 9, cy);
  brush.line(cx + 9, cy, cx + 34, cy);
  brush.line(cx, cy - 34, cx, cy - 9);
  brush.line(cx, cy + 9, cx, cy + 34);

  // Sub-millimeter calibration ticks on crosshair arms
  for (let d of [-24, -16, 16, 24]) {
    brush.line(cx + d, cy - 3, cx + d, cy + 3);
    brush.line(cx - 3, cy + d, cx + 3, cy + d);
  }

  // Small numeric readout next to corner crosshair
  drawVectorString("39.2", cx + 26, cy + 16, 7.0, uiWhite);
  drawDegreeCelsius(cx + 60, cy + 16, 7.0, uiWhite);

  // Secondary subtle spot-crosshair near bottom-right corner to balance frame
  const bx = 1116, by = 1116;
  brush.set("ui_pen", uiDim, 0.68);
  brush.line(bx - 18, by, bx - 5, by);
  brush.line(bx + 5, by, bx + 18, by);
  brush.line(bx, by - 18, bx, by - 5);
  brush.line(bx, by + 5, bx, by + 18);
  brush.circle(bx, by, 9, 0.08);

  // Delicate L-shaped viewfinder corner brackets at all 4 corners
  const m = 44;
  const bLen = 22;
  brush.set("ui_pen", uiDim, 0.65);
  // Top-left
  brush.line(m, m, m + bLen, m);
  brush.line(m, m, m, m + bLen);
  // Top-right
  brush.line(1200 - m, m, 1200 - m - bLen, m);
  brush.line(1200 - m, m, 1200 - m, m + bLen);
  // Bottom-left
  brush.line(m, 1200 - m, m + bLen, 1200 - m);
  brush.line(m, 1200 - m, m, 1200 - m - bLen);
  // Bottom-right
  brush.line(1200 - m, 1200 - m, 1200 - m - bLen, 1200 - m);
  brush.line(1200 - m, 1200 - m, 1200 - m, 1200 - m - bLen);
}

// Vector digit renderer using p5.brush pen strokes (no external font dependencies)
function drawVectorString(str, startX, startY, h, col) {
  let w = h * 0.62;
  let spacing = h * 0.88;
  brush.set("ui_pen", col, 0.72);

  for (let i = 0; i < str.length; i++) {
    let ch = str[i];
    let x = startX + i * spacing;
    let y = startY;

    if (ch === ".") {
      brush.line(x + w * 0.2, y + h - 1.5, x + w * 0.4, y + h);
      continue;
    }

    const segs = {
      "0": [[[0, 0], [1, 0], [1, 1], [0, 1], [0, 0]]],
      "1": [[[0.25, 0.2], [0.55, 0], [0.55, 1]], [[0.2, 1], [0.9, 1]]],
      "2": [[[0, 0.2], [0.2, 0], [0.85, 0], [1, 0.2], [1, 0.45], [0, 1], [1, 1]]],
      "3": [[[0, 0], [1, 0], [1, 0.48], [0.2, 0.48]], [[1, 0.48], [1, 1], [0, 1]]],
      "4": [[[0.8, 1], [0.8, 0], [0, 0.65], [1, 0.65]]],
      "6": [[[0.9, 0], [0.15, 0], [0, 0.25], [0, 1], [1, 1], [1, 0.5], [0, 0.5]]],
      "8": [[[0, 0], [1, 0], [1, 1], [0, 1], [0, 0]], [[0, 0.48], [1, 0.48]]],
      "9": [[[1, 0.5], [0, 0.5], [0, 0], [1, 0], [1, 1], [0.1, 1]]]
    };

    let paths = segs[ch];
    if (!paths) continue;
    for (let path of paths) {
      for (let j = 0; j < path.length - 1; j++) {
        let p0 = path[j];
        let p1 = path[j + 1];
        brush.line(x + p0[0] * w, y + p0[1] * h, x + p1[0] * w, y + p1[1] * h);
      }
    }
  }
}

function drawDegreeCelsius(x, y, h, col) {
  brush.set("ui_pen", col, 0.72);
  brush.circle(x + 2, y + 2.5, 2.2, 0.05);
  let cx = x + 7;
  let w = h * 0.65;
  brush.line(cx + w, y + 1, cx + 1.5, y + 1);
  brush.line(cx + 1.5, y + 1, cx, y + 3);
  brush.line(cx, y + 3, cx, y + h - 2);
  brush.line(cx, y + h - 2, cx + 1.5, y + h);
  brush.line(cx + 1.5, y + h, cx + w, y + h);
}

