const PAPER     = "#eef2fa"; // Crisp cool twilight manga paper
const WHITE     = "#ffffff"; // Pure gouged/scratched-out white highlight (kezuri)
const ICE       = "#dce3f2"; // Pale twilight highlight tone
const TONE_15   = "#b4c0d8"; // 15% dusky halftone
const TONE_30   = "#8996b3"; // 30% dusky halftone
const TONE_50   = "#586582"; // 50% twilight slate screentone
const TONE_70   = "#313a52"; // 70% deep dusk indigo-grey
const INK_DARK  = "#161b29"; // Rich dark twilight ink
const INK       = "#080a11"; // Purest deepest manga black ink
const YOLK_DEEP = "#1e1628"; // Subtle dusky twilight-plum depth for jammy yolk/chashu

// Scene center & dynamic diagonal framing (-12 degrees)
const CX = 608;
const CY = 652;
const TILT_DEG = -12;
const TILT_RAD = (TILT_DEG * Math.PI) / 180;
const COS_T = Math.cos(TILT_RAD);
const SIN_T = Math.sin(TILT_RAD);

// Transform local bowl coordinates (u, v) into tilted canvas coordinates [x, y]
function T(u, v) {
  return [
    CX + u * COS_T - v * SIN_T,
    CY + u * SIN_T + v * COS_T
  ];
}

// Transform an array of local [u, v] points
function TPoly(pts) {
  return pts.map(p => T(p[0], p[1]));
}

