// ============================================================================
// SAFE WRAPPERS FOR P5.BRUSH PRIMITIVES & POLYGONS
// ============================================================================

function bLine(x1, y1, x2, y2, bName = "gpen", col = INK, w = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, w);
  brush.line(x1, y1, x2, y2);
}

function bSpline(pts, curv = 0.5, bName = "gpen", col = INK, w = 1) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, w);
  brush.spline(pts, curv);
}

function washPoly(pts, col, alpha = 255) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  let p = new brush.Polygon(pts);
  p.wash(col, alpha);
  brush.noWash();
}

function hatchPoly(pts, bName, col, w, dist, angleDeg, randVal = 0.0) {
  if (!pts || pts.length < 3) return;
  brush.noFill();
  brush.noWash();
  brush.set(bName, col, w);
  brush.hatchStyle(bName, col, w);
  let p = new brush.Polygon(pts);
  p.hatch(dist, angleDeg + TILT_DEG, { rand: randVal });
  brush.noHatch();
}

function drawPolyOutline(pts, bName = "gpen", col = INK, w = 1, closed = true, curv = 0.35) {
  if (!pts || pts.length < 2) return;
  let arr = closed ? [...pts, pts[0]] : pts;
  bSpline(arr, curv, bName, col, w);
}

function makeEllipsePoly(u0, v0, rx, ry, n = 48, rotDeg = 0, wobble = 0) {
  let pts = [];
  let rotRad = (rotDeg * Math.PI) / 180;
  let cr = Math.cos(rotRad), sr = Math.sin(rotRad);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let radMod = wobble > 0 ? 1 + wobble * (noise(u0 * 0.02 + Math.cos(a) * 1.5, v0 * 0.02 + Math.sin(a) * 1.5) - 0.5) : 1;
    let lx = Math.cos(a) * rx * radMod;
    let ly = Math.sin(a) * ry * radMod;
    let u = u0 + lx * cr - ly * sr;
    let v = v0 + lx * sr + ly * cr;
    pts.push(T(u, v));
  }
  return pts;
}

function makeArcBandPoly(u0, v0, rx1, ry1, rx2, ry2, aStartDeg, aEndDeg, n = 40) {
  let pts = [];
  for (let i = 0; i <= n; i++) {
    let a = ((aStartDeg + (aEndDeg - aStartDeg) * (i / n)) * Math.PI) / 180;
    pts.push(T(u0 + Math.cos(a) * rx1, v0 + Math.sin(a) * ry1));
  }
  for (let i = n; i >= 0; i--) {
    let a = ((aStartDeg + (aEndDeg - aStartDeg) * (i / n)) * Math.PI) / 180;
    pts.push(T(u0 + Math.cos(a) * rx2, v0 + Math.sin(a) * ry2));
  }
  return pts;
}

// White knife-scratch highlight hatch (manga kezuri technique)
function drawKezuriScratch(u0, v0, widthSpan, lengthSpan, angleDeg, count, col = WHITE, w = 0.9) {
  let aRad = (angleDeg * Math.PI) / 180;
  let pRad = aRad + Math.PI / 2;
  for (let i = 0; i < count; i++) {
    let t = count > 1 ? i / (count - 1) - 0.5 : 0;
    let offset = t * widthSpan;
    let len = lengthSpan * (1 - 0.35 * Math.abs(t)) * random(0.75, 1.15);
    let cu = u0 + Math.cos(pRad) * offset;
    let cv = v0 + Math.sin(pRad) * offset;
    let p1 = T(cu - Math.cos(aRad) * len * 0.5, cv - Math.sin(aRad) * len * 0.5);
    let p2 = T(cu + Math.cos(aRad) * len * 0.5, cv + Math.sin(aRad) * len * 0.5);
    bLine(p1[0], p1[1], p2[0], p2[1], "kezuri", col, w);
  }
}

