// ============================================================================

function drawCounterAndBackdrop() {
  // Base dusky paper wash
  washPoly([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], PAPER, 255);

  // Upper dark twilight izakaya wall / shadow zone above diagonal counter edge (v < -310)
  let wallPoly = TPoly([
    [-900, -900], [900, -900], [900, -305], [-900, -305]
  ]);
  washPoly(wallPoly, INK_DARK, 235);
  hatchPoly(wallPoly, "marupen", INK, 1.1, 7.5, 45, 0.03);
  hatchPoly(wallPoly, "marupen", INK, 1.0, 8.5, -45, 0.03);

  // Wooden counter surface (v >= -305)
  let counterPoly = TPoly([
    [-900, -305], [900, -305], [900, 900], [-900, 900]
  ]);
  washPoly(counterPoly, TONE_50, 195);

  // Screentone dot base on counter
  hatchPoly(counterPoly, "tone_dot_med", TONE_70, 0.95, 7.5, 15, 0.0);

  // Dense multi-directional cross-hatching across the counter
  hatchPoly(counterPoly, "marupen", TONE_70, 0.85, 8.0, 0, 0.02);
  hatchPoly(counterPoly, "marupen", INK_DARK, 0.85, 9.5, 28, 0.03);
  hatchPoly(counterPoly, "marupen", INK_DARK, 0.8, 11.0, -32, 0.03);

  // Darker vignette bands near top of counter and lower corners
  let upperCounterShadow = TPoly([
    [-900, -305], [900, -305], [900, -140], [-900, -140]
  ]);
  washPoly(upperCounterShadow, TONE_70, 145);
  hatchPoly(upperCounterShadow, "gpen", INK, 0.9, 7.0, -18, 0.02);
  hatchPoly(upperCounterShadow, "marupen", INK, 0.85, 7.5, 62, 0.02);

  let lowerCounterShadow = TPoly([
    [-900, 260], [900, 260], [900, 900], [-900, 900]
  ]);
  washPoly(lowerCounterShadow, TONE_70, 130);
  hatchPoly(lowerCounterShadow, "marupen", INK_DARK, 0.9, 8.5, 18, 0.02);

  // Crisp wood plank seams and wood-grain flow lines on the counter
  let plankVs = [-305, -210, -95, 45, 205, 390, 580];
  for (let pv of plankVs) {
    let p1 = T(-850, pv);
    let p2 = T(850, pv);
    bLine(p1[0], p1[1], p2[0], p2[1], "gpen", INK, pv === -305 ? 2.2 : 1.15);
    let p1h = T(-850, pv + 3);
    let p2h = T(850, pv + 3);
    bLine(p1h[0], p1h[1], p2h[0], p2h[1], "kezuri", TONE_15, 0.65);
  }

  // Subtle wood grain curves along each plank
  for (let i = 0; i < 65; i++) {
    let uStart = random(-780, 500);
    let uLen = random(140, 380);
    let vBase = random(-295, 550);
    let grainPts = [];
    for (let s = 0; s <= 6; s++) {
      let u = uStart + (uLen * s) / 6;
      let v = vBase + Math.sin(s * 0.9 + i) * 4.5;
      grainPts.push(T(u, v));
    }
    bSpline(grainPts, 0.5, "marupen", INK_DARK, random(0.45, 0.85));
  }

  // Heavy cast shadow of the ramen bowl on the counter
  let shadowOuter = makeEllipsePoly(25, 290, 385, 165, 48);
  washPoly(shadowOuter, INK_DARK, 210);
  hatchPoly(shadowOuter, "gpen", INK, 1.0, 5.5, 12, 0.02);
  hatchPoly(shadowOuter, "gpen", INK, 1.0, 5.5, -42, 0.02);
  hatchPoly(shadowOuter, "marupen", INK, 0.9, 6.0, 55, 0.02);

  let shadowCore = makeEllipsePoly(12, 315, 255, 108, 40);
  washPoly(shadowCore, INK, 250);
}

