  // Scratched-out white ceramic wheel ridges (rokuro-me) across the left highlight window
  for (let r = 0; r < 9; r++) {
    let f = r / 8;
    let vOff = 155 + f * 135;
    let arcPts = [];
    for (let s = 0; s <= 16; s++) {
      let a = (112 + (s / 16) * 38) * (Math.PI / 180);
      let rx = 445 - f * 175;
      let ry = 225 - f * 85;
      arcPts.push(T(Math.cos(a) * rx, vOff * 0.42 + Math.sin(a) * ry));
    }
    bSpline(arcPts, 0.4, "kezuri", r % 2 === 0 ? WHITE : TONE_15, r % 2 === 0 ? 1.05 : 0.7);
  }
  // Vertical white glaze scratches cutting across the highlight window
  drawKezuriScratch(-275, 232, 125, 48, 65, 24, WHITE, 0.95);
  drawKezuriScratch(-175, 268, 75, 38, 72, 14, ICE, 0.8);

  // Meridian contour lines showing the 3D curvature of the bowl exterior
  for (let i = -14; i <= 14; i++) {
    if (i >= -9 && i <= -4) continue; // keep specular window clean
    let a = (90 + i * 5.5) * (Math.PI / 180);
    let pTop = T(Math.cos(a) * 462, Math.sin(a) * 289);
    let pMid = T(Math.cos(a) * 365, 115 + Math.sin(a) * 205);
    let pBot = T(Math.cos(a) * 195, 295 + Math.sin(a) * 72);
    bSpline([pTop, pMid, pBot], 0.4, "marupen", TONE_70, 0.65);
  }

  // Bold fude outline around the bowl exterior belly
  drawPolyOutline(bellyPoly, "fude", INK, 1.85, false, 0.35);

  // 3. Outer & Inner Rim Lip
  let outerRimPts = makeEllipsePoly(0, 0, 466, 292, 64);
  let innerRimPts = makeEllipsePoly(0, 4, 434, 270, 64);

  // Rim lip band (between outerRim and innerRim)
  let rimLipBand = makeArcBandPoly(0, 2, 466, 292, 434, 270, 0, 360, 64);
  washPoly(rimLipBand, ICE, 255);
  hatchPoly(rimLipBand, "tone_dot_fine", TONE_30, 0.75, 5.5, 45, 0.0);

  // Highlight along front-left rim lip
  let frontRimHi = makeArcBandPoly(0, 2, 462, 289, 438, 273, 105, 225, 28);
  washPoly(frontRimHi, WHITE, 250);

  // 4. Inner Ceramic Wall (visible between innerRim and broth surface)
  let innerWallPoly = makeEllipsePoly(0, 4, 434, 270, 64);
  washPoly(innerWallPoly, PAPER, 255);

  // Screentone shading on left and right curved interior walls
  let leftWallTone = makeArcBandPoly(0, 12, 434, 270, 395, 240, 145, 245, 24);
  hatchPoly(leftWallTone, "tone_dot_fine", TONE_50, 0.85, 5.0, 25, 0.0);
  hatchPoly(leftWallTone, "marupen", TONE_70, 0.65, 5.5, 85, 0.01);

  let rightWallTone = makeArcBandPoly(0, 12, 434, 270, 395, 240, -55, 35, 24);
  hatchPoly(rightWallTone, "tone_dot_fine", TONE_50, 0.85, 5.0, -25, 0.0);
  hatchPoly(rightWallTone, "marupen", TONE_70, 0.65, 5.5, 95, 0.01);

  // 5. Authentic Raimon (Thunder Scroll / Meander Fret Pattern) on Inner Bowl Wall
  drawRaimonPattern();

  // Crisp double-ink rim contours
  drawPolyOutline(outerRimPts, "fude", INK, 1.9, true, 0.35);
  drawPolyOutline(innerRimPts, "gpen", INK, 1.4, true, 0.35);
}

// Project a classic square-spiral raimon fret pattern along the inner bowl wall
function drawRaimonPattern() {
  // Draw decorative double bounding rings on the upper inner wall (angles 158° to 382°)
  let ringTop = [], ringBot = [];
  let aMin = 158, aMax = 382, steps = 56;
  for (let i = 0; i <= steps; i++) {
    let a = ((aMin + (aMax - aMin) * (i / steps)) * Math.PI) / 180;
    ringTop.push(T(Math.cos(a) * 426, 8 + Math.sin(a) * 263));
    ringBot.push(T(Math.cos(a) * 408, 22 + Math.sin(a) * 248));
  }
  bSpline(ringTop, 0.3, "marupen", INK_DARK, 0.95);
  bSpline(ringBot, 0.3, "marupen", INK_DARK, 0.95);

  // Helper to map normalized (thetaDeg, rFrac 0=top..1=bot) on the inner wall to canvas [x, y]
  function wallPt(thetaDeg, rFrac) {
    let a = (thetaDeg * Math.PI) / 180;
    let rx = 423 - rFrac * 13;
    let ry = 260 - rFrac * 11;
    let vOff = 10 + rFrac * 10;
    return T(Math.cos(a) * rx, vOff + Math.sin(a) * ry);
  }

  // 18 spiral fret motifs along the visible inner wall arc
  let numMotifs = 18;
  let span = (aMax - aMin) / numMotifs;
  for (let m = 0; m < numMotifs; m++) {
    let a0 = aMin + m * span + span * 0.08;
    let da = span * 0.84;
    // Construct a classic interlocking square spiral in (theta, rFrac) space
    let localCoords = [
      [0.0, 0.85], [0.0, 0.15], [0.88, 0.15], [0.88, 0.82],
      [0.24, 0.82], [0.24, 0.36], [0.66, 0.36], [0.66, 0.62], [0.44, 0.62]
    ];
    let motifPts = localCoords.map(c => wallPt(a0 + c[0] * da, c[1]));
    for (let j = 0; j < motifPts.length - 1; j++) {
      bLine(
        motifPts[j][0], motifPts[j][1],
        motifPts[j + 1][0], motifPts[j + 1][1],
        "marupen", INK_DARK, 0.78
      );
    }
  }
}

