function drawNoriSheets() {
  // Three large roasted nori sheets tucked into the upper-right rim, fanning outward
  const sheets = [
    {
      // Back-left sheet
      corners: [[85, -145], [125, -365], [255, -335], [198, -118]],
      angle: 12
    },
    {
      // Middle hero sheet
      corners: [[172, -122], [252, -342], [378, -282], [278, -82]],
      angle: 26
    },
    {
      // Front-right sheet
      corners: [[248, -85], [362, -268], [462, -178], [332, -22]],
      angle: 40
    }
  ];

  for (let sIdx = 0; sIdx < sheets.length; sIdx++) {
    let s = sheets[sIdx];
    let [bl, tl, tr, br] = s.corners;

    // Build finely ragged organic perimeter for the roasted seaweed sheet
    let noriPoly = [];
    let edges = [[bl, tl], [tl, tr], [tr, br], [br, bl]];
    for (let e = 0; e < 4; e++) {
      let [pA, pB] = edges[e];
      let segs = 14;
      for (let i = 0; i < segs; i++) {
        let t = i / segs;
        let u = pA[0] + (pB[0] - pA[0]) * t;
        let v = pA[1] + (pB[1] - pA[1]) * t;
        let jitter = (e === 3) ? 1.5 : (noise(sIdx * 10 + e * 3 + i * 0.6) - 0.5) * 5.5;
        noriPoly.push(T(u + jitter, v + jitter));
      }
    }

    // 1. Deepest black ink wash
    washPoly(noriPoly, INK, 255);

    // 2. Hyperreal pressed-seaweed orthogonal grid hatching
    hatchPoly(noriPoly, "marupen", TONE_70, 0.75, 4.2, s.angle, 0.02);
    hatchPoly(noriPoly, "marupen", TONE_70, 0.75, 4.5, s.angle + 90, 0.02);
    hatchPoly(noriPoly, "gpen", INK, 0.85, 6.0, s.angle + 45, 0.04);

    // 3. Diagonal sheen band across the roasted nori surface (cut screentone + white kezuri)
    let sheenPoly = TPoly([
      [
        bl[0] * 0.55 + tl[0] * 0.45,
        bl[1] * 0.55 + tl[1] * 0.45
      ],
      [
        bl[0] * 0.25 + tl[0] * 0.75,
        bl[1] * 0.25 + tl[1] * 0.75
      ],
      [
        br[0] * 0.45 + tr[0] * 0.55,
        br[1] * 0.45 + tr[1] * 0.55
      ],
      [
        br[0] * 0.72 + tr[0] * 0.28,
        br[1] * 0.72 + tr[1] * 0.28
      ]
    ]);
    hatchPoly(sheenPoly, "tone_dot_fine", TONE_50, 0.8, 4.5, s.angle, 0.0);
    hatchPoly(sheenPoly, "kezuri", TONE_30, 0.65, 5.0, s.angle + 90, 0.02);

    // Scratched-out white flecks and woven grid highlights in the sheen zone
    let midU = (bl[0] + tl[0] + tr[0] + br[0]) * 0.25;
    let midV = (bl[1] + tl[1] + tr[1] + br[1]) * 0.25;
    drawKezuriScratch(midU, midV, 68, 22, s.angle + 90, 14, TONE_15, 0.65);
    drawKezuriScratch(midU + 8, midV - 14, 48, 14, s.angle, 10, WHITE, 0.75);

    // Crisp rim highlight along top and left edges of each nori sheet to separate overlapping planes
    let edgeHi1 = TPoly([bl, tl, [tl[0] * 0.6 + tr[0] * 0.4, tl[1] * 0.6 + tr[1] * 0.4]]);
    bSpline(edgeHi1, 0.15, "kezuri", WHITE, 0.95);

    // Crisp dark outer ink contour
    drawPolyOutline(noriPoly, "gpen", INK, 1.35, true, 0.15);

    // Wet glistening meniscus where the base of the nori dips into the hot broth
    let wetBase = [];
    for (let i = 0; i <= 10; i++) {
      let t = i / 10;
      let u = bl[0] + (br[0] - bl[0]) * t;
      let v = bl[1] + (br[1] - bl[1]) * t + Math.sin(t * Math.PI) * 5;
      wetBase.push(T(u, v));
    }
    bSpline(wetBase, 0.4, "kezuri", WHITE, 1.25);
  }
}

function drawMenmaAndKikurage() {
