    // Wet white specular streak along top ridge of bamboo shoot
    let h1 = T(m.u - hl * 0.65 * ca, m.v - hl * 0.65 * sa - 3);
    let h2 = T(m.u + hl * 0.65 * ca, m.v + hl * 0.65 * sa - 3);
    bLine(h1[0], h1[1], h2[0], h2[1], "kezuri", WHITE, 1.05);
