}

// ============================================================================
// LAYER 6: TANGLED GLISTENING RAMEN NOODLE BUNDLES
// ============================================================================

function drawRamenNoodles() {
  // Dark broth & crevice shadow bed underneath the main noodle mass
  let noodleBedPoly = makeEllipsePoly(85, 82, 245, 138, 40, -12, 0.15);
  washPoly(noodleBedPoly, INK_DARK, 235);

  // Define 6 interlocking flowing noodle bundles across the center, right, and front of the bowl
  const bundles = [
    // Bundle 1: Upper-center wave emerging from under menma/egg toward nori
    {
      spine: [[-45, -75], [15, -98], [85, -88], [155, -62], [215, -25]],
      strands: 10, spread: 9.5
    },
    // Bundle 2: Right-side sweeping wave below kikurage
    {
      spine: [[145, 5], [212, -8], [278, 18], [328, 65], [348, 118]],
      strands: 10, spread: 9.5
    },
    // Bundle 3: Central arched fold bridging chashu and egg
    {
      spine: [[-65, 18], [12, -12], [92, 8], [168, 48], [225, 98]],
      strands: 12, spread: 10.0
    },
    // Bundle 4: Sweeping lower-right cascade
    {
      spine: [[35, 85], [118, 68], [202, 88], [275, 132], [312, 172]],
      strands: 11, spread: 10.0
    },
    // Bundle 5: Front-center hero noodle wave
    {
      spine: [[-75, 125], [8, 95], [98, 115], [185, 158], [248, 195]],
      strands: 12, spread: 10.2
    },
    // Bundle 6: Lower-front rim fold
    {
      spine: [[-95, 182], [-12, 162], [78, 178], [162, 208], [215, 218]],
      strands: 9, spread: 9.5
    }
  ];

  for (let bIdx = 0; bIdx < bundles.length; bIdx++) {
    let b = bundles[bIdx];

    // Interpolate smooth high-res spine and normal vectors
    let denseSpine = [];
    let segs = 20;
    for (let i = 0; i <= segs; i++) {
      let t = i / segs;
      let scaled = t * (b.spine.length - 1);
      let idx = Math.min(Math.floor(scaled), b.spine.length - 2);
      let f = scaled - idx;
      let p0 = b.spine[Math.max(0, idx - 1)];
      let p1 = b.spine[idx];
      let p2 = b.spine[idx + 1];
      let p3 = b.spine[Math.min(b.spine.length - 1, idx + 2)];
      // Catmull-Rom interpolation + characteristic ramen crinkle wave
      let u = 0.5 * (
        (2 * p1[0]) +
        (-p0[0] + p2[0]) * f +
        (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * f * f +
        (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * f * f * f
      );
      let v = 0.5 * (
        (2 * p1[1]) +
        (-p0[1] + p2[1]) * f +
        (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * f * f +
        (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * f * f * f
      );
      let crinkle = Math.sin(t * Math.PI * 3.5 + bIdx * 1.7) * 6.5;
      denseSpine.push([u, v + crinkle]);
    }

    // Draw each individual noodle strand in the bundle from back to front
    for (let s = 0; s < b.strands; s++) {
      let offsetBase = (s - (b.strands - 1) * 0.5) * b.spread;
      let halfW = 5.4;
      let topPts = [];
      let botPts = [];
      let centerPts = [];
      let shadowPts = [];

      for (let i = 0; i < denseSpine.length; i++) {
        let p = denseSpine[i];
        let pNext = denseSpine[Math.min(denseSpine.length - 1, i + 1)];
        let pPrev = denseSpine[Math.max(0, i - 1)];
        let du = pNext[0] - pPrev[0];
        let dv = pNext[1] - pPrev[1];
        let len = Math.hypot(du, dv) || 1;
        let nu = -dv / len;
        let nv = du / len;

        // Slight individual wave per strand so noodles weave organically
        let wave = Math.sin((i / denseSpine.length) * Math.PI * 2.5 + s * 0.85 + bIdx) * 3.2;
        let off = offsetBase + wave;

        let cu = p[0] + nu * off;
        let cv = p[1] + nv * off;

        topPts.push(T(cu - nu * halfW, cv - nv * halfW));
        botPts.push(T(cu + nu * halfW, cv + nv * halfW));
        centerPts.push(T(cu - nu * 1.2, cv - nv * 1.2));
        shadowPts.push(T(cu + nu * (halfW - 1.6), cv + nv * (halfW - 1.6)));
      }

      let strandPoly = [...topPts, ...botPts.slice().reverse()];

      // 1. Opaque noodle body wash (alternating bright paper and pale ice tone for depth)
      washPoly(strandPoly, s % 3 === 0 ? ICE : PAPER, 255);

      // 2. Cylindrical shadow line along lower edge of each noodle strand
      bSpline(shadowPts, 0.4, "marupen", TONE_50, 0.72);

      // 3. Crisp G-pen ink contours on both sides of the strand
      bSpline(topPts, 0.4, "gpen", INK, 0.92);
      bSpline(botPts, 0.4, "gpen", INK, 1.08);

      // 4. Wet white specular highlight streak along the upper crest of the noodle curve
      if (s % 2 === 0) {
        let hiSub = centerPts.slice(3, centerPts.length - 3);
        bSpline(hiSub, 0.45, "kezuri", WHITE, 1.15);
      }
    }
  }
}

// ============================================================================
// LAYER 7: CHASHU PORK SLICES (HYPERREAL MARBLING, SEARED BARK, & SCREENTONES)
// ============================================================================

function drawSingleChashuSlice(u0, v0, rx, ry, rotDeg, seedOffset) {
  let rotRad = (rotDeg * Math.PI) / 180;
  let cr = Math.cos(rotRad), sr = Math.sin(rotRad);

  function toSlice(lx, ly) {
    return [
      u0 + lx * cr - ly * sr,
      v0 + lx * sr + ly * cr
    ];
  }

  // 1. Outer scalloped/seared bark contour of the rolled pork belly slice
  let outerPts = [];
  let innerMeatPts = [];
  let n = 56;
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let nVal = noise(seedOffset + Math.cos(a) * 1.8, seedOffset + Math.sin(a) * 1.8);
    let rMod = 0.92 + 0.14 * nVal + 0.03 * Math.sin(a * 7);
    let lx = Math.cos(a) * rx * rMod;
    let ly = Math.sin(a) * ry * rMod;
    let barkThick = 0.88 + 0.04 * Math.cos(a * 3);
    outerPts.push(T(...toSlice(lx, ly)));
    innerMeatPts.push(T(...toSlice(lx * barkThick, ly * barkThick)));
  }

  // Cast shadow on broth/noodles beneath the slice
  let dropShadowPts = outerPts.map(p => [p[0] + 6, p[1] + 10]);
  washPoly(dropShadowPts, INK, 215);

  // Dark soy-caramelized outer rind (bark)
  washPoly(outerPts, INK, 255);

  // Main chashu interior base (translucent glistening fat tone)
  washPoly(innerMeatPts, PAPER, 255);
  hatchPoly(innerMeatPts, "tone_dot_fine", TONE_15, 0.75, 4.8, rotDeg + 20, 0.0);

  // 2. Hyperreal Concentric Spiral Marbling: Alternating Lean Meat & Fat Ribbons
  // In rolled pork belly chashu, lean meat forms C-shaped / spiral crescent lobes separated by fat seams
  const leanLobes = [
    // Outer upper-left lean crescent
    { rIn: 0.62, rOut: 0.86, a1: -165, a2: -15, tone: TONE_50, hatchAng: 15 },
    // Outer lower-right lean crescent
    { rIn: 0.58, rOut: 0.85, a1: 12, a2: 172, tone: TONE_50, hatchAng: -25 },
    // Middle spiral lean muscle band A
    { rIn: 0.34, rOut: 0.54, a1: -115, a2: 75, tone: TONE_70, hatchAng: 40 },
    // Middle spiral lean muscle band B
    { rIn: 0.32, rOut: 0.52, a1: 98, a2: 232, tone: TONE_50, hatchAng: -35 },
    // Tender inner eye of meat
    { rIn: 0.05, rOut: 0.25, a1: 0, a2: 345, tone: TONE_70, hatchAng: 10 }
  ];

  for (let lIdx = 0; lIdx < leanLobes.length; lIdx++) {
    let lobe = leanLobes[lIdx];
    let lobePts = [];
    let steps = 28;
    // Outer arc of lean muscle lobe
    for (let i = 0; i <= steps; i++) {
      let aDeg = lobe.a1 + (lobe.a2 - lobe.a1) * (i / steps);
      let a = (aDeg * Math.PI) / 180;
      let wav = 1 + 0.06 * (noise(seedOffset + lIdx * 5 + i * 0.25) - 0.5);
      let lx = Math.cos(a) * rx * lobe.rOut * wav;
      let ly = Math.sin(a) * ry * lobe.rOut * wav;
      lobePts.push(T(...toSlice(lx, ly)));
    }
    // Inner arc of lean muscle lobe
    for (let i = steps; i >= 0; i--) {
      let aDeg = lobe.a1 + (lobe.a2 - lobe.a1) * (i / steps);
      let a = (aDeg * Math.PI) / 180;
      let wav = 1 + 0.06 * (noise(seedOffset + lIdx * 5 + 20 + i * 0.25) - 0.5);
      let lx = Math.cos(a) * rx * lobe.rIn * wav;
      let ly = Math.sin(a) * ry * lobe.rIn * wav;
      lobePts.push(T(...toSlice(lx, ly)));
    }

    // Wash and layered dot + line screentones for the lean meat fibers
    washPoly(lobePts, TONE_30, 235);
    hatchPoly(lobePts, "tone_dot_med", lobe.tone, 0.85, 4.4, rotDeg + lobe.hatchAng, 0.0);
    // Fine directional muscle-fiber line screentone (mansen)
    hatchPoly(lobePts, "marupen", INK_DARK, 0.72, 3.3, rotDeg + lobe.hatchAng + 75, 0.02);
    hatchPoly(lobePts, "marupen", YOLK_DEEP, 0.65, 5.2, rotDeg + lobe.hatchAng - 15, 0.02);

    // Sharp boundary cut between lean meat and translucent white fat
    drawPolyOutline(lobePts, "marupen", INK_DARK, 0.85, true, 0.3);

    // Radial meat-fiber segmentation lines & scratched-out white highlights across the meat grain
    for (let i = 2; i < steps - 2; i += 3) {
      let aDeg = lobe.a1 + (lobe.a2 - lobe.a1) * (i / steps);
      let a = (aDeg * Math.PI) / 180;
      let pIn = T(...toSlice(Math.cos(a) * rx * lobe.rIn, Math.sin(a) * ry * lobe.rIn));
      let pOut = T(...toSlice(Math.cos(a) * rx * lobe.rOut, Math.sin(a) * ry * lobe.rOut));
      bLine(pIn[0], pIn[1], pOut[0], pOut[1], "marupen", INK, 0.65);

      if (i % 6 === 2) {
        let pMid1 = T(...toSlice(Math.cos(a) * rx * (lobe.rIn + 0.04), Math.sin(a) * ry * (lobe.rIn + 0.04)));
        let pMid2 = T(...toSlice(Math.cos(a + 0.08) * rx * (lobe.rOut - 0.04), Math.sin(a + 0.08) * ry * (lobe.rOut - 0.04)));
        bLine(pMid1[0], pMid1[1], pMid2[0], pMid2[1], "kezuri", WHITE, 0.9);
      }
    }
  }

  // 3. Translucent Fat Marbling Details & Brilliant Scratched White Specular Highlights
  // Cellular fat globule contours and glossy highlights along the fat ribbons (r ≈ 0.56 and r ≈ 0.28)
  const fatRings = [0.56, 0.28];
  for (let rRing of fatRings) {
    for (let aDeg = 0; aDeg < 360; aDeg += 18) {
      let a1 = (aDeg * Math.PI) / 180;
      let a2 = ((aDeg + 12) * Math.PI) / 180;
      let p1 = T(...toSlice(Math.cos(a1) * rx * rRing, Math.sin(a1) * ry * rRing));
      let p2 = T(...toSlice(Math.cos(a2) * rx * rRing, Math.sin(a2) * ry * rRing));
      bLine(p1[0], p1[1], p2[0], p2[1], "kezuri", WHITE, 1.3);
    }
  }

  // White knife-scratches (kezuri) across the seared edges and fat marbling
  drawKezuriScratch(u0 - rx * 0.28, v0 - ry * 0.22, 55, 22, rotDeg + 35, 14, WHITE, 0.95);
  drawKezuriScratch(u0 + rx * 0.22, v0 + ry * 0.18, 48, 18, rotDeg - 25, 12, WHITE, 0.9);

  // Torch-seared char blisters (aburi) along the outer bark
  for (let i = 0; i < n; i += 4) {
    let p = outerPts[i];
    let pIn = innerMeatPts[i];
    bLine(p[0], p[1], pIn[0], pIn[1], "gpen", INK, 1.15);
    if (i % 8 === 0) {
      bLine(p[0] + 1, p[1] - 1, pIn[0] + 1, pIn[1] - 1, "kezuri", WHITE, 0.9);
    }
  }

  // Bold outer contour of the chashu slice
  drawPolyOutline(outerPts, "fude", INK, 1.45, true, 0.35);
}

