// ============================================================================
// LAYER 8: HALVED SOFT-BOILED EGG (AJITSUKE TAMAGO) WITH JAMMY YOLK
// ============================================================================

function drawSoftEggHalf(u0, v0, rx, ry, rotDeg, isHero) {
  let rotRad = (rotDeg * Math.PI) / 180;
  let cr = Math.cos(rotRad), sr = Math.sin(rotRad);

  function toEgg(lx, ly) {
    // Slightly pointed egg oval (narrower at top lx < 0 or > 0)
    let taper = 1 - 0.12 * (lx / rx);
    return [
      u0 + lx * cr - (ly * taper) * sr,
      v0 + lx * sr + (ly * taper) * cr
    ];
  }

  let n = 48;
  // 1. 3D Soy-Marinated Exterior Side Wall of the Egg Half
  let sideWallDepth = isHero ? 24 : 20;
  let topCutPts = [];
  let botBellyPts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let lx = Math.cos(a) * rx;
    let ly = Math.sin(a) * ry;
    topCutPts.push(T(...toEgg(lx, ly)));
    let drop = Math.sin(a) > -0.15 ? sideWallDepth * Math.pow(Math.max(0, Math.sin(a) + 0.15), 0.75) : 0;
    let pSide = toEgg(lx * 0.96, ly);
    botBellyPts.push(T(pSide[0] + drop * 0.15, pSide[1] + drop));
  }

  // Drop shadow on noodles/broth beneath the egg half
  let eggShadow = botBellyPts.map(p => [p[0] + 5, p[1] + 9]);
  washPoly(eggShadow, INK, 220);

  // Render the soy-marinated outer albumen wall (rich amber-brown translated to B&W screentones)
  washPoly(botBellyPts, TONE_70, 255);
  hatchPoly(botBellyPts, "tone_dot_med", INK_DARK, 0.85, 4.5, rotDeg + 25, 0.0);
  hatchPoly(botBellyPts, "marupen", INK, 0.78, 3.8, rotDeg - 55, 0.02);
  drawPolyOutline(botBellyPts, "gpen", INK, 1.35, true, 0.35);

  // Scratched white wet reflection along the curved 3D belly of the marinated egg
  drawKezuriScratch(u0 - rx * 0.25, v0 + ry * 0.88, 42, 12, rotDeg + 5, 11, WHITE, 0.85);

  // 2. Cut Face of the Egg White (Albumen)
  // Soy-marinade penetration rim (outer 8% of the cut white face)
  washPoly(topCutPts, TONE_30, 255);
  hatchPoly(topCutPts, "tone_dot_fine", TONE_70, 0.8, 4.2, rotDeg + 45, 0.0);

  // Gleaming pure white inner albumen face
  let innerWhitePts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    innerWhitePts.push(T(...toEgg(Math.cos(a) * rx * 0.91, Math.sin(a) * ry * 0.91)));
  }
  washPoly(innerWhitePts, WHITE, 255);

  // Subtle contour shading on the cut albumen near the yolk cavity
  let albumenShade = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    albumenShade.push(T(...toEgg(Math.cos(a) * rx * 0.64, Math.sin(a) * ry * 0.64)));
  }
  hatchPoly(albumenShade, "tone_dot_fine", TONE_15, 0.7, 5.0, rotDeg, 0.0);
  drawPolyOutline(topCutPts, "gpen", INK, 1.25, true, 0.35);

  // 3. THE JAMMY YOLK (Hyperreal Layered Dot & Line Screentones + Gouged White Highlights)
  let yRx = rx * 0.58;
  let yRy = ry * 0.59;
  let yOffX = -rx * 0.03;
  let yOffY = -ry * 0.02;

  function toYolk(lx, ly, rScale = 1, wobbleAmt = 0.04) {
    let a = Math.atan2(ly, lx);
    let mod = 1 + wobbleAmt * (noise(u0 * 0.05 + Math.cos(a) * 2, v0 * 0.05 + Math.sin(a) * 2) - 0.5);
    return toEgg(yOffX + lx * rScale * mod, yOffY + ly * rScale * mod);
  }

  let yolkOuter = [];
  let yolkMid = [];
  let yolkCore = [];
  let yolkDeepCenter = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let cx = Math.cos(a) * yRx;
    let cy = Math.sin(a) * yRy;
    yolkOuter.push(T(...toYolk(cx, cy, 1.0, 0.05)));
    yolkMid.push(T(...toYolk(cx, cy, 0.84, 0.08)));
    yolkCore.push(T(...toYolk(cx, cy, 0.62, 0.1)));
    yolkDeepCenter.push(T(...toYolk(cx, cy, 0.38, 0.08)));
  }

  // Layer A: Outer cooked-to-jammy transition ring (mid-tone wash + fine dot screentone + radial mansen)
  washPoly(yolkOuter, TONE_50, 255);
  hatchPoly(yolkOuter, "tone_dot_med", TONE_70, 0.85, 4.2, rotDeg + 15, 0.0);

  // Layer B: Rich viscous mid-yolk ring (deep twilight tone + dense dot screentone + cross-hatched line tone)
  washPoly(yolkMid, TONE_70, 250);
  hatchPoly(yolkMid, "tone_dot_heavy", INK_DARK, 0.9, 4.0, rotDeg - 30, 0.0);
  hatchPoly(yolkMid, "marupen", INK, 0.78, 3.2, rotDeg + 35, 0.02);

  // Layer C: Molten jammy center (deepest ink wash + cross-hatching)
  washPoly(yolkCore, YOLK_DEEP, 255);
  hatchPoly(yolkCore, "marupen", INK, 0.85, 2.8, rotDeg - 20, 0.01);
  hatchPoly(yolkCore, "marupen", INK, 0.85, 2.8, rotDeg + 70, 0.01);

  // Layer D: Pure black ink glossy pool at the heart of the molten yolk
  washPoly(yolkDeepCenter, INK, 255);

  // Radial crystalline/gelatinous mansen lines around the perimeter of the jammy yolk
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let r1 = 0.55 + 0.15 * (i % 2);
    let r2 = 0.98;
    let p1 = T(...toYolk(Math.cos(a) * yRx * r1, Math.sin(a) * yRy * r1, 1.0, 0));
    let p2 = T(...toYolk(Math.cos(a) * yRx * r2, Math.sin(a) * yRy * r2, 1.0, 0));
    bLine(p1[0], p1[1], p2[0], p2[1], "marupen", INK, 0.72);
  }

  // Viscous molten yolk drip cresting slightly over the lower-right albumen rim
  let dripPoly = [
    toYolk(yRx * 0.35, yRy * 0.75, 1, 0),
    toYolk(yRx * 0.65, yRy * 0.95, 1, 0),
    toYolk(yRx * 0.52, yRy * 1.18, 1, 0),
    toYolk(yRx * 0.18, yRy * 0.92, 1, 0)
  ].map(p => T(p[0], p[1]));
  washPoly(dripPoly, INK_DARK, 245);
  drawPolyOutline(dripPoly, "marupen", INK, 0.9, true, 0.4);

  // Crisp ink contour around the yolk meniscus
  drawPolyOutline(yolkOuter, "gpen", INK, 1.3, true, 0.35);

  // 4. RAZOR-SHARP SCRATCHED-OUT WHITE HIGHLIGHTS ON THE JAMMY YOLK
  // Primary upper-left curved liquid-gloss window
  let specArc1 = [];
  for (let s = 0; s <= 18; s++) {
    let a = ((192 + (s / 18) * 82) * Math.PI) / 180;
    specArc1.push(T(...toYolk(Math.cos(a) * yRx * 0.74, Math.sin(a) * yRy * 0.74, 1, 0)));
  }
  for (let s = 18; s >= 0; s--) {
    let a = ((192 + (s / 18) * 82) * Math.PI) / 180;
    specArc1.push(T(...toYolk(Math.cos(a) * yRx * 0.52, Math.sin(a) * yRy * 0.52, 1, 0)));
  }
  washPoly(specArc1, WHITE, 255);
  drawPolyOutline(specArc1, "kezuri", WHITE, 1.2, true, 0.35);

  // Feathered white knife-scratches (kezuri) radiating off the primary highlight into the dot screentone
  let hiCenter = toYolk(-yRx * 0.32, -yRy * 0.32, 1, 0);
  drawKezuriScratch(hiCenter[0], hiCenter[1], isHero ? 38 : 28, isHero ? 16 : 12, rotDeg - 35, 14, WHITE, 0.95);

  // Secondary lower-right meniscus gloss arc & bright liquid droplets
  let specArc2 = [];
  for (let s = 0; s <= 12; s++) {
    let a = ((18 + (s / 12) * 58) * Math.PI) / 180;
    specArc2.push(T(...toYolk(Math.cos(a) * yRx * 0.78, Math.sin(a) * yRy * 0.78, 1, 0)));
  }
  bSpline(specArc2, 0.4, "kezuri", WHITE, 1.65);

  // Glossy white pinpoint droplets on the molten center
  let dot1 = makeEllipsePoly(...toYolk(-yRx * 0.08, -yRy * 0.12, 1, 0), isHero ? 7.5 : 5.5, isHero ? 4.8 : 3.5, 14, rotDeg - 20);
  washPoly(dot1, WHITE, 255);
  let dot2 = makeEllipsePoly(...toYolk(yRx * 0.18, -yRy * 0.25, 1, 0), isHero ? 4.5 : 3.5, isHero ? 3.2 : 2.5, 12, rotDeg);
  washPoly(dot2, WHITE, 255);
}

function drawSoftBoiledEggs() {
