function drawNegiAndGarnishes() {
  // Mound of finely sliced scallion rings (negi) in the center (between chashu, egg, and noodles)
  const negiRings = [
    { u: -18, v: 22, rx: 19, ry: 12, rot: -15 },
    { u: 8, v: 14, rx: 21, ry: 13, rot: 22 },
    { u: -5, v: 38, rx: 20, ry: 12, rot: 5 },
    { u: 25, v: 32, rx: 18, ry: 11, rot: -28 },
    { u: -32, v: 36, rx: 17, ry: 11, rot: 35 },
    { u: 12, v: 52, rx: 19, ry: 12, rot: -8 },
    { u: -15, v: 56, rx: 16, ry: 10, rot: 18 },
    { u: -38, v: 12, rx: 18, ry: 11, rot: -40 },
    { u: 38, v: 18, rx: 16, ry: 10, rot: 12 },
    { u: -2, v: -2, rx: 17, ry: 11, rot: -12 },
    // Scattered outlier rings across broth, chashu, and noodles
    { u: -68, v: 45, rx: 15, ry: 9, rot: 25 },
    { u: 55, v: 58, rx: 15, ry: 9, rot: -18 },
    { u: -48, v: -28, rx: 14, ry: 9, rot: 8 },
    { u: 128, v: 62, rx: 15, ry: 9, rot: 32 },
    { u: -92, v: 22, rx: 13, ry: 8, rot: -22 },
    { u: 68, v: 88, rx: 14, ry: 8, rot: 14 }
  ];

  for (let n of negiRings) {
    let outerP = makeEllipsePoly(n.u, n.v, n.rx, n.ry, 22, n.rot);
    let innerP = makeEllipsePoly(n.u, n.v, n.rx * 0.55, n.ry * 0.55, 18, n.rot);
    let shadowP = outerP.map(p => [p[0] + 2, p[1] + 4]);

    washPoly(shadowP, INK, 185);
    washPoly(outerP, WHITE, 255);
    hatchPoly(outerP, "tone_dot_fine", TONE_30, 0.75, 3.8, n.rot, 0.0);

    // Dark hollow center of the scallion ring
    washPoly(innerP, INK_DARK, 220);

    // Crisp double-ring contours + cellular radial ticks
    drawPolyOutline(outerP, "gpen", INK, 0.95, true, 0.35);
    drawPolyOutline(innerP, "marupen", INK, 0.75, true, 0.35);

    // Bright white highlight on upper rim of scallion slice
    let hi = T(n.u - n.rx * 0.35, n.v - n.ry * 0.65);
    let hi2 = T(n.u + n.rx * 0.35, n.v - n.ry * 0.65);
    bLine(hi[0], hi[1], hi2[0], hi2[1], "kezuri", WHITE, 1.1);
  }

  // Toasted sesame seeds and cracked black pepper flecks across the bowl
  for (let i = 0; i < 75; i++) {
    let a = random(0, 360) * (Math.PI / 180);
    let r = Math.sqrt(random(0.05, 0.88));
    let u = Math.cos(a) * 340 * r;
    let v = 25 + Math.sin(a) * 195 * r;
    let pt = T(u, v);
    if (i % 3 === 0) {
      // White sesame seed
      bLine(pt[0] - 2, pt[1] - 1, pt[0] + 2, pt[1] + 1, "kezuri", WHITE, 1.05);
    } else {
      // Cracked black pepper speck
      bLine(pt[0] - 1.5, pt[1], pt[0] + 1.5, pt[1] + 1, "gpen", INK, 0.95);
    }
  }
}

// ============================================================================
// LAYER 10: RADIATING MANGA SPEED LINES (SHUCHUSEN) & PEN-OUTLINED STEAM WISPS
// ============================================================================

function drawRadiatingSpeedLines() {
  // Focal burst center slightly above bowl center (near the jammy egg & central noodles)
  const fU = 15;
  const fV = -12;
  const focalPt = T(fU, fV);

  // 260 radiating speed lines in rhythmic manga clusters (both pure ink & reverse white kezuri)
  const totalLines = 260;
  for (let i = 0; i < totalLines; i++) {
    // Cluster distribution using sine modulation so rays group naturally
    let baseAng = (i / totalLines) * 360;
    let clusterJitter = Math.sin(baseAng * 11 * (Math.PI / 180)) * 0.8 + random(-0.45, 0.45);
    let angDeg = baseAng + clusterJitter;
    let angRad = (angDeg * Math.PI) / 180;

    // Elliptical clear zone around the bowl's hero interior, with dramatic spikes overlapping the outer rim
    let spike = Math.pow(Math.abs(Math.sin(angDeg * 17 * (Math.PI / 180))), 3.0);
    let rStartScale = 0.90 + 0.24 * spike + random(-0.04, 0.06);

    // Distance from focal point to bowl rim at this angle
    let rimU = Math.cos(angRad) * 475 * rStartScale;
    let rimV = Math.sin(angRad) * 305 * rStartScale;
    let startPt = T(rimU, rimV);

    // Shoot all the way out beyond the 1200x1200 canvas borders
    let endU = Math.cos(angRad) * 1150;
    let endV = Math.sin(angRad) * 1150;
    let endPt = T(endU, endV);

    // Alternate dark ink speed lines with razor-sharp white reverse speed lines
    let isWhiteLine = (i % 5 === 0) || (spike > 0.65 && i % 2 === 0);
    if (isWhiteLine) {
      bLine(startPt[0], startPt[1], endPt[0], endPt[1], "kezuri", WHITE, random(0.75, 1.35));
    } else {
      let w = spike > 0.5 ? random(1.1, 1.85) : random(0.65, 1.25);
      bLine(startPt[0], startPt[1], endPt[0], endPt[1], "gpen", INK, w);
    }

    // Add fine secondary mid-way speed ticks near the outer edges of the frame
    if (i % 2 === 0) {
      let midU = Math.cos(angRad + 0.005) * random(540, 680);
      let midV = Math.sin(angRad + 0.005) * random(380, 520);
      let mPt = T(midU, midV);
      let ePt2 = T(Math.cos(angRad + 0.005) * 1150, Math.sin(angRad + 0.005) * 1150);
      bLine(mPt[0], mPt[1], ePt2[0], ePt2[1], "marupen", INK, random(0.55, 0.95));
    }
  }
}

function drawRisingSteamWisps() {
  // Steam rises in clean pen-outlined wisps against the dense cross-hatched counter
  // Defined in canvas coordinates [x, y] rising upward toward the top edge (y = 0..650)
  const plumes = [
    {
      // Plume 1: Rising from the left chashu pork slice
      spine: [
        T(-215, -35), T(-255, -135), T(-210, -255),
        T(-265, -385), T(-225, -525), T(-260, -680)
      ],
      widths: [10, 34, 52, 44, 62, 35]
    },
    {
      // Plume 2: Grand central billowing wisp rising from hot noodles & menma
      spine: [
        T(-35, -65), T(-75, -185), T(-15, -315),
        T(-68, -455), T(-8, -595), T(-45, -750)
      ],
      widths: [14, 46, 68, 56, 78, 48]
    },
    {
      // Plume 3: Rising behind the jammy egg and curling across the dark nori sheets
      spine: [
        T(128, -75), T(168, -195), T(118, -325),
        T(172, -465), T(135, -605), T(175, -760)
      ],
      widths: [12, 42, 62, 50, 70, 42]
    },
    {
      // Plume 4: Right-hand delicate tendril rising from the broth & noodles
      spine: [
        T(285, 15), T(338, -95), T(298, -215),
        T(348, -345), T(315, -485), T(355, -640)
      ],
      widths: [8, 28, 42, 34, 48, 24]
    }
  ];

  for (let pIdx = 0; pIdx < plumes.length; pIdx++) {
    let plume = plumes[pIdx];
    let leftContour = [];
    let rightContour = [];
    let innerFlow1 = [];
    let innerFlow2 = [];

    let steps = 28;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let scaled = t * (plume.spine.length - 1);
      let idx = Math.min(Math.floor(scaled), plume.spine.length - 2);
      let f = scaled - idx;

      let p1 = plume.spine[idx];
      let p2 = plume.spine[idx + 1];
      let w1 = plume.widths[idx];
      let w2 = plume.widths[idx + 1];

      let cx = p1[0] + (p2[0] - p1[0]) * f + Math.sin(t * Math.PI * 3 + pIdx) * 14;
      let cy = p1[1] + (p2[1] - p1[1]) * f;
      let w = (w1 + (w2 - w1) * f) * (0.85 + 0.25 * Math.sin(t * Math.PI * 4 + pIdx * 2));

      leftContour.push([cx - w, cy]);
      rightContour.push([cx + w, cy]);
      innerFlow1.push([cx - w * 0.35, cy]);
      innerFlow2.push([cx + w * 0.38, cy]);
    }

    let steamPoly = [...leftContour, ...rightContour.slice().reverse()];

    // 1. Translucent white/ice vapor wash that softly veils the dark cross-hatched counter
    washPoly(steamPoly, PAPER, 155);

    // Core brighter vapor ribbon inside each plume
    let corePoly = [...innerFlow1, ...innerFlow2.slice().reverse()];
    washPoly(corePoly, WHITE, 195);

    // 2. Scratched-out white hatch marks (kezuri) along the steam edges
    hatchPoly(steamPoly, "kezuri", WHITE, 0.85, 6.5, 68, 0.03);

    // 3. Clean, crisp manga pen outlines (double-contour effect) + internal thermal curls
    bSpline(leftContour, 0.5, "gpen", INK_DARK, 1.15);
    bSpline(rightContour, 0.5, "gpen", INK_DARK, 1.05);

    // Inner delicate white & dark pen lines for billowing volume
    bSpline(leftContour.map(p => [p[0] + 3.5, p[1]]), 0.5, "kezuri", WHITE, 1.25);
    bSpline(rightContour.map(p => [p[0] - 3.5, p[1]]), 0.5, "kezuri", WHITE, 1.1);
    bSpline(innerFlow1, 0.5, "marupen", TONE_50, 0.7);
    bSpline(innerFlow2, 0.5, "marupen", TONE_50, 0.65);

    // Detached floating curly steam eddies beside the main plumes
    for (let k = 1; k <= 4; k++) {
      let idx = Math.floor((k / 5) * steps);
      let side = k % 2 === 0 ? 1 : -1;
      let basePt = side > 0 ? rightContour[idx] : leftContour[idx];
      let eddyPts = [
        [basePt[0] + side * 8, basePt[1] + 18],
        [basePt[0] + side * 24, basePt[1] - 5],
        [basePt[0] + side * 14, basePt[1] - 32],
        [basePt[0] + side * 4, basePt[1] - 48]
      ];
      bSpline(eddyPts, 0.5, "kezuri", WHITE, 1.5);
      bSpline(eddyPts, 0.5, "marupen", INK_DARK, 0.85);
    }
  }
}

