function drawWindowAndSkySliver() {
  // 1. Outer Black EPDM Rubber Gasket (x: 430..1200, y: 0..350, corner radius 38 at bottom-left)
  let gasketPts = [[WIN_X, 0]];
  let rOut = 38;
  let cxOut = WIN_X + rOut;
  let cyOut = WIN_Y - rOut;
  for (let a = 180; a >= 90; a -= 5) {
    gasketPts.push([cxOut + rOut * cos(a), cyOut + rOut * sin(a)]);
  }
  gasketPts.push([1200, WIN_Y], [1200, 0]);
  let gasketPoly = new brush.Polygon(gasketPts);
  gasketPoly.wash("#171A20", 255);

  // 2. Inner Black Anodized Sash Frame (x: 462..1200, y: 0..318, corner radius 16)
  let sashX = 462;
  let sashY = 318;
  let rSash = 16;
  let sashPts = [[sashX, 0]];
  for (let a = 180; a >= 90; a -= 6) {
    sashPts.push([sashX + rSash + rSash * cos(a), sashY - rSash + rSash * sin(a)]);
