// ===========================================================================
// HYPERREAL ZONE 3: THE RIVETED SEAM (x: 345..430, y: 0..1200)
// ===========================================================================
function drawRivetedSeam() {
  // The left panel (x: 0..390) overlaps the right panel (x: 390..1200) in a vertical lap joint.
  // First, subtle oil-canning / pillowing along the vertical overlap strip (x: 350..402)
  for (let y = 26; y < 1200; y += 52) {
    let onBand1 = y >= BAND1_Y1 && y <= BAND1_Y2;
    let onBand2 = y >= BAND2_Y1 && y <= BAND2_Y2;

    if (!onBand1 && !onBand2) {
      // Subtle warm amber wave shadow between rivets on the yellow lap strip
      brush.set("fine_marker", "#E09200", 0.75);
      brush.line(SEAM_X - 3, y + 12, SEAM_X - 3, y + 38);
      brush.set("fine_marker", "#CC7A00", 0.65);
      brush.line(SEAM_X + 4, y + 8, SEAM_X + 4, y + 42);
    }
  }

  // 1. Recessed ambient-occlusion shadow immediately right of the lap edge (x: 391..395)
  brush.set("fine_marker", "#995200", 0.95);
  brush.line(SEAM_X + 2.5, 0, SEAM_X + 2.5, BAND1_Y1);
  brush.line(SEAM_X + 2.5, BAND1_Y2, SEAM_X + 2.5, BAND2_Y1);
  brush.line(SEAM_X + 2.5, BAND2_Y2, SEAM_X + 2.5, 1200);

  // 2. Razor-sharp dark crevice shadow along the vertical lap seam (x = 390)
  brush.set("micro_pen", "#1F0E00", 1.15);
  brush.line(SEAM_X + 0.8, 0, SEAM_X + 0.8, 1200);
  brush.set("micro_pen", "#000000", 1.25);
  brush.line(SEAM_X, 0, SEAM_X, 1200);

  // Where the vertical seam cuts through the Upper and Lower Black Rub Rails,
  // there is a physical butt-joint gap (~3.5px wide) between the left and right rail sections!
  let gap1 = new brush.Polygon([
    [SEAM_X - 1.5, BAND1_Y1], [SEAM_X + 2.5, BAND1_Y1],
    [SEAM_X + 2.5, BAND1_Y2], [SEAM_X - 1.5, BAND1_Y2]
  ]);
  gap1.wash("#020203", 255);

  let gap2 = new brush.Polygon([
    [SEAM_X - 1.5, BAND2_Y1], [SEAM_X + 2.5, BAND2_Y1],
    [SEAM_X + 2.5, BAND2_Y2], [SEAM_X - 1.5, BAND2_Y2]
  ]);
  gap2.wash("#020203", 255);

  // Glint of yellow paint peeking deep inside the vertical butt-joint gap of Upper Band
  brush.set("micro_pen", "#6E3D00", 0.55);
  brush.line(SEAM_X + 0.5, BAND1_Y1 + 15, SEAM_X + 0.5, BAND1_Y2 - 15);

  // 3. Crisp sunlit bevel catchlight along the cut edge of the overlapping left panel (x = 388.5)
  // On the Chrome Yellow sections:
  brush.set("fine_marker", "#FFE066", 0.7);
  brush.line(SEAM_X - 1.8, 0, SEAM_X - 1.8, BAND1_Y1);
  brush.line(SEAM_X - 1.8, BAND1_Y2, SEAM_X - 1.8, BAND2_Y1);
  brush.line(SEAM_X - 1.8, BAND2_Y2, SEAM_X - 1.8, 1200);

  brush.set("micro_pen", "#FFFCE0", 0.8);
  brush.line(SEAM_X - 1.2, 0, SEAM_X - 1.2, BAND1_Y1);
  brush.line(SEAM_X - 1.2, BAND1_Y2, SEAM_X - 1.2, BAND2_Y1);
  brush.line(SEAM_X - 1.2, BAND2_Y2, SEAM_X - 1.2, 1200);

  // On the Black Band butt-joint edges:
  brush.set("micro_pen", "#5C6E85", 0.75);
  brush.line(SEAM_X - 2, BAND1_Y1 + 2, SEAM_X - 2, BAND1_Y2 - 2);
  brush.line(SEAM_X + 3, BAND1_Y1 + 2, SEAM_X + 3, BAND1_Y2 - 2);
  brush.line(SEAM_X - 2, BAND2_Y1 + 2, SEAM_X - 2, BAND2_Y2 - 2);

  // At the dented corner (y: 865..925), the overlapping lip at x = 390 is peeled/curled up by the scrape,
  // catching a blindingly bright silver-white metallic edge highlight!
  brush.set("fine_marker", "#C8D6E5", 0.9);
  brush.line(SEAM_X - 1.5, 862, SEAM_X - 1.5, 928);
  brush.set("micro_pen", "#FFFFFF", 1.0);
  brush.line(SEAM_X - 1, 865, SEAM_X - 1, 924);

  // Faint secondary vertical lap impression line on the left at x = 342
  // (where the hidden inner flange of the right sheet terminates beneath the left sheet)
  brush.set("micro_pen", "#D98A00", 0.55);
  brush.line(342, 0, 342, BAND1_Y1);
  brush.line(342, BAND1_Y2, 342, BAND2_Y1);
  brush.line(342, BAND2_Y2, 342, 1200);
  brush.set("micro_pen", "#FFE066", 0.45);
  brush.line(340.8, 0, 340.8, BAND1_Y1);
  brush.line(340.8, BAND1_Y2, 340.8, BAND2_Y1);
  brush.line(340.8, BAND2_Y2, 340.8, 1200);

  // -------------------------------------------------------------------------
  // 4. THE VERTICAL COLUMN OF HYPERREAL DOME RIVETS ALONG THE SEAM
  // -------------------------------------------------------------------------
  let rivetX = 365; // Centered on the 48px overlap strip (342..390)

  // Yellow panel rivets (Upper Pillar: y = 0..490)
  let upperYellowYs = [28, 80, 132, 184, 236, 288, 340, 392, 444];
  for (let i = 0; i < upperYellowYs.length; i++) {
    drawHyperrealRivet(rivetX, upperYellowYs[i], 8.2, "yellow", {
      chipped: i === 2 || i === 6,
      weeping: i === 3 || i === 7
    });
  }

  // Upper Black Band seam rivets (Paired left & right of the butt-joint at x = 365 and x = 416)
  let band1Ys = [518, 570, 622];
  for (let i = 0; i < band1Ys.length; i++) {
    drawHyperrealRivet(rivetX, band1Ys[i], 8.6, "black", {
      chipped: i === 1,
      weeping: i === 2
    });
    drawHyperrealRivet(416, band1Ys[i], 8.6, "black", {
      chipped: i === 0,
      weeping: i === 2
    });
  }

  // Middle Yellow panel rivets (y = 650..850)
  let midYellowYs = [682, 734, 786, 826];
  for (let i = 0; i < midYellowYs.length; i++) {
    drawHyperrealRivet(rivetX, midYellowYs[i], 8.2, "yellow", {
      chipped: i === 1 || i === 3,
      weeping: i === 2
    });
  }

  // Lower Black Band left-side seam rivets (x = 365; right-side rivets are in the dented corner!)
  let band2Ys = [882, 934, 984];
  for (let i = 0; i < band2Ys.length; i++) {
    drawHyperrealRivet(rivetX, band2Ys[i], 8.6, "black", {
      chipped: i === 0 || i === 1,
      weeping: i === 2
    });
  }

  // Bottom Yellow skirt panel rivets (y = 1010..1200)
  let botYellowYs = [1042, 1094, 1146, 1192];
  for (let i = 0; i < botYellowYs.length; i++) {
    drawHyperrealRivet(rivetX, botYellowYs[i], 8.2, "yellow", {
      chipped: i === 0,
      weeping: i === 1 || i === 2
    });
  }
}

// ===========================================================================
// MICRO-HYPERREALISM HELPER: 3D BRAZIER-HEAD SOLID RIVET
// ===========================================================================
function drawHyperrealRivet(cx, cy, r, surfaceType, opts = {}) {
  let isYellow = surfaceType === "yellow";

  // 1. Subtle circular sheet-metal dimple / seating ring around rivet
  if (isYellow) {
    brush.set("micro_pen", "#CC7400", 0.65);
    brush.arc(cx, cy, r + 3.2, 195, 345);
    brush.set("micro_pen", "#FFE066", 0.65);
    brush.arc(cx, cy, r + 3.2, 15, 165);
  } else {
    brush.set("micro_pen", "#040507", 0.75);
    brush.arc(cx, cy, r + 3.0, 195, 345);
    brush.set("micro_pen", "#2C3645", 0.6);
    brush.arc(cx, cy, r + 3.0, 15, 165);
  }

  // 2. Optional vertical grime/oxidation weep streak below the rivet
  if (opts.weeping) {
    let weepCol = isYellow ? "#7A3B00" : "#050608";
    brush.set("micro_pen", weepCol, 0.75);
    brush.line(cx - 0.5, cy + r + 1, cx - 0.5, cy + r + 16);
    brush.set("micro_pen", isYellow ? "#4A2000" : "#3D1C0A", 0.5);
    brush.line(cx + 0.5, cy + r + 1, cx + 0.5, cy + r + 11);
  }

  // 3. Directional cast shadow falling down-right (~50 degrees)
  let shPts = [];
  for (let a = -35; a <= 125; a += 20) {
    shPts.push([cx + 3.8 + (r + 1.2) * cos(a), cy + 4.2 + (r + 1.2) * sin(a)]);
  }
  for (let a = 125; a >= -35; a -= 20) {
    shPts.push([cx + r * cos(a), cy + r * sin(a)]);
  }
  let shPoly = new brush.Polygon(shPts);
  shPoly.wash(isYellow ? "#6E3600" : "#020304", 235);

  // Core cast shadow tight against the lower-right lip of the dome
  brush.set("fine_marker", isYellow ? "#381800" : "#000000", 0.85);
  brush.arc(cx + 1.8, cy + 2.0, r + 0.5, -20, 115);

  // 4. Rivet Dome Base Polygon
  let domePts = [];
  for (let a = 0; a < 360; a += 18) {
    domePts.push([cx + r * cos(a), cy + r * sin(a)]);
  }
  let domePoly = new brush.Polygon(domePts);
  domePoly.wash(isYellow ? "#F09800" : "#12161E", 255);

  // 5. Equatorial Dark Horizon Band across the middle of the glossy spherical dome
  brush.set("fine_marker", isYellow ? "#803E00" : "#040508", 0.85);
  brush.spline([
    [cx - r * 0.85, cy + r * 0.1],
    [cx - r * 0.1, cy - r * 0.05],
    [cx + r * 0.85, cy - r * 0.2]
  ], 0.4);

  // 6. Lower-right Reflected Bounce Light Crescent (Chrome Yellow panel reflecting into underside of dome!)
  brush.set("fine_marker", isYellow ? "#FF7300" : "#B86B00", 0.75);
  brush.arc(cx, cy, r * 0.76, 15, 120);
  brush.set("micro_pen", isYellow ? "#FFD04D" : "#FFA600", 0.75);
  brush.arc(cx, cy, r * 0.82, 25, 105);

  // 7. Upper-left Sunlit Sky Crescent & Specular Pinpoint Spark
  brush.set("fine_marker", isYellow ? "#FFE670" : "#566D8A", 0.8);
  brush.arc(cx, cy, r * 0.72, 195, 305);

  brush.set("micro_pen", isYellow ? "#FFFBE0" : "#A8C6E8", 0.85);
  brush.arc(cx, cy, r * 0.65, 208, 285);

  // Pinpoint white sun glint at (-0.38r, -0.38r)
  brush.set("micro_pen", "#FFFFFF", 0.95);
  brush.line(cx - r * 0.45, cy - r * 0.32, cx - r * 0.22, cy - r * 0.48);

  // 8. Optional micro-chipped bare metal crescent on crown of rivet head
  if (opts.chipped) {
    brush.set("micro_pen", "#9BAAB8", 0.85);
    brush.arc(cx, cy, r * 0.42, 260, 350);
    brush.set("micro_pen", "#FFFFFF", 0.75);
    brush.line(cx + r * 0.05, cy - r * 0.38, cx + r * 0.32, cy - r * 0.22);
  }

  // 9. Seated dark meniscus ring around the entire base of the rivet head
  brush.set("micro_pen", isYellow ? "#2B1200" : "#000000", 0.85);
  brush.circle(cx, cy, r, 0.05);
}

const SEED = 8472;

