const PALETTE = {
  ivoryGround: "#f3ede0",
  ivoryLight: "#faf6ed",
  ivoryWarm: "#e7decb",
  ivoryMid: "#d6cbb4",
  indigoGhost: "#26334d",
  indigoDeep: "#182136",
  indigoSlate: "#3c4966",
  charcoalCore: "#0d0f14",
  charcoalSoft: "#1a1d26",
