  accentDeep: "#59150b",
  accentMid: "#9e2f17",
  accentBright: "#d65624",
  accentWarm: "#b86b52"
};

// Scar endpoints in stripe (u, v) space
const SCAR_A = { u: -280, v: -255 };
const SCAR_B = { u: -15, v: 40 };

async function setup() {
  createCanvas(1200, 1200, WEBGL);
