function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.ivoryGround);

  // 1. Warm ivory & faint indigo shadow undertone modeling the flank musculature
  renderUndertoneWashes();

  // 2. Subtle warp-thread & motion grain across the entire sheet
  renderWarpUndertone();

  // 3. Build stripe definitions (diagonal sweep + Y-bifurcation + scar displacement)
  const stripes = buildStripeSystem();

  // 4. Render ikat resist-bled watercolour & charcoal mass stripes
  renderIkatWatercolourLayers(stripes);
  renderCharcoalMassAndHatching(stripes);
  renderIkatDryDraggedEdges(stripes);

  // 5. Render the hyperreal healed scar cutting across the flank
  renderHyperrealScar();

  // 6. Render needle-sharp individual guard hairs emerging from the softness
  renderHyperrealCoatHairs(stripes);

  // 7. Render the hyperreal horsefly perched on the upper shoulder swell
  const flyPos = mapUV(235, -112, false);
  renderHyperrealFly(flyPos[0], flyPos[1], -128);

  noLoop();
}

// ============================================================================
// COORDINATE MAPPING & ANATOMICAL STRIPE FIELD
// ============================================================================

function getScarInfluence(u, v) {
  const dx = SCAR_B.u - SCAR_A.u;
  const dy = SCAR_B.v - SCAR_A.v;
  const lenSq = dx * dx + dy * dy;
  const len = Math.sqrt(lenSq);
  let t = ((u - SCAR_A.u) * dx + (v - SCAR_A.v) * dy) / lenSq;
  const clampedT = constrain(t, 0, 1);
  const px = SCAR_A.u + clampedT * dx;
  const py = SCAR_A.v + clampedT * dy;
  const dist = Math.hypot(u - px, v - py);

  // Signed distance across the scar line
  const cross = (u - SCAR_A.u) * dy - (v - SCAR_A.v) * dx;
  const side = cross >= 0 ? 1 : -1;

  // Taper at the ends of the scar
  const endTaper = t > 0.02 && t < 0.98 ? Math.sin(clampedT * Math.PI) : 0;
  return {
    t: clampedT,
    rawT: t,
    dist,
    side,
    endTaper,
    dirU: dx / len,
    dirV: dy / len
  };
}

// Maps stripe coordinates (u along sweep, v across sweep) to canvas (x, y)
function mapUV(u, v, applyScarShear = true) {
  let uMod = u;
  let vMod = v;

  if (applyScarShear) {
    const sc = getScarInfluence(u, v);
    if (sc.endTaper > 0 && sc.dist < 95) {
      const pull = Math.exp(-sc.dist / 32) * sc.endTaper;
      // Healed skin shear along the scar + slight puckering inward
      uMod += sc.side * sc.dirU * 22 * pull;
      vMod += sc.side * sc.dirV * 22 * pull - sc.side * 6 * pull;
    }
  }

  // Anatomical S-arch over the shoulder and ribcage barrel
  const arch =
    110 * Math.sin(uMod * 0.00165 + 0.35) +
    42 * Math.cos(uMod * 0.0031 - 0.75) +
    28 * Math.sin(vMod * 0.0022 + uMod * 0.001);

  // Slight muscular expansion toward the upper-right shoulder
  const fan = 1.0 + 0.15 * Math.tanh(uMod * 0.0014);
  const vc = vMod * fan + arch;

  // Diagonal sweep at -37 degrees (bottom-left to top-right)
  const ang = -37 * (Math.PI / 180);
  const ca = Math.cos(ang);
  const sa = Math.sin(ang);

  const x = 600 + uMod * ca - vc * sa;
  const y = 600 + uMod * sa + vc * ca;
  return [x, y];
}

function buildStripeSystem() {
  const defs = [
    { id: -6, baseV: -890, width: 88, splitSide: -1 },
    { id: -5, baseV: -735, width: 84, splitSide: -1 },
    { id: -4, baseV: -580, width: 80, splitSide: -1 },
    { id: -3, baseV: -425, width: 78, splitSide: -1 },
    { id: -2, baseV: -272, width: 74, splitSide: -1 },
    { id: -1, baseV: -125, width: 70, splitSide: -1 },
    // Y-junction trunk and two diverging shoulder branches
    { id: 0, baseV: 12, width: 86, splitSide: 0, type: "y_trunk", uMax: -45 },
    { id: 101, baseV: 12, width: 62, splitSide: -1, type: "y_upper", uMin: -135 },
    { id: 102, baseV: 12, width: 64, splitSide: 1, type: "y_lower", uMin: -135 },
    // Lower flank stripes
    { id: 1, baseV: 152, width: 74, splitSide: 1 },
    { id: 2, baseV: 305, width: 80, splitSide: 1 },
    { id: 3, baseV: 465, width: 84, splitSide: 1 },
    { id: 4, baseV: 630, width: 88, splitSide: 1 },
    { id: 5, baseV: 795, width: 90, splitSide: 1 },
    { id: 6, baseV: 955, width: 92, splitSide: 1 }
  ];

  const stripes = [];

  for (let d of defs) {
    const uStart = d.uMin !== undefined ? d.uMin : -980;
    const uEnd = d.uMax !== undefined ? d.uMax : 980;

    const centerFn = (u) => {
      // Smooth sigmoidal spreading of stripes around the Y-bifurcation at u = -110
      const s = 0.5 + 0.5 * Math.tanh((u + 110) / 210);
      const wave = 18 * (noise(d.id * 7.3 + 20, u * 0.002 + 10) - 0.5);

      if (d.type === "y_trunk") {
        return d.baseV + wave;
      } else if (d.type === "y_upper") {
        return d.baseV - 78 * s + wave;
      } else if (d.type === "y_lower") {
        return d.baseV + 78 * s + wave;
      } else {
        // Adjacent stripes bow outward smoothly to accommodate the Y-fork
        const distDecay = Math.exp(-Math.abs(d.baseV) * 0.00065);
        return d.baseV + d.splitSide * 82 * s * distDecay + wave;
      }
    };

    const halfWidthFn = (u) => {
      let hw = d.width * 0.5;
      // Natural swelling of stripe thickness over the flank
      hw *= 0.88 + 0.28 * noise(d.id * 11.1 + 5, u * 0.0025 + 30);

      if (d.type === "y_trunk") {
        // Trunk widens just before splitting, then tapers into the fork
        const swell = Math.exp(-Math.pow((u + 145) / 110, 2)) * 22;
        const taper = u > -110 ? map(u, -110, -45, 1, 0.2, true) : 1;
        hw = (hw + swell) * taper;
      } else if (d.type === "y_upper" || d.type === "y_lower") {
        const emerge = u < -40 ? map(u, -135, -40, 0.35, 1, true) : 1;
        hw *= emerge;
      }
      return hw;
    };

    stripes.push({
      id: d.id,
      type: d.type || "normal",
      uStart,
      uEnd,
      centerFn,
      halfWidthFn
    });
  }

  return stripes;
}

// Computes the ikat stepped edge offset for a given stripe and warp bundle
function getIkatStep(stripeId, u, sideSign) {
  // Quantize u into discrete warp-thread bundles (12 units wide)
  const bundleIdx = Math.floor((u + 1200) / 12);
  const subBundleIdx = Math.floor((u + 1200) / 5);

  const n1 = noise(stripeId * 19.3 + sideSign * 7, bundleIdx * 0.42);
  const n2 = noise(stripeId * 37.1 + sideSign * 13, subBundleIdx * 0.85);

  // Outward dye-creep flare (black bleeding into cream)
  let step = Math.pow(n1, 2.1) * 44;

  // Sharp ikat warp slips (long stepped spikes characteristic of tied resist)
  if (n2 > 0.66) {
    step += Math.pow((n2 - 0.66) / 0.34, 1.3) * 46;
  }

  // Occasional inward cream resist intrusion (undyed threads cutting into the black stripe)
  if (n1 < 0.34 && n2 < 0.42) {
    step -= (0.34 - n1) * 58;
  }

  return step;
}

// ============================================================================
// 1 & 2. UNDERTONE WASHES & WARP TEXTURE
// ============================================================================

function drawPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function renderUndertoneWashes() {
  brush.noStroke();

  // Warm ivory / parchment base variations
  brush.fill(PALETTE.ivoryWarm, 55);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.75, 0.35);
  drawPoly([
    [-80, 450], [520, -80], [1280, -80], [1280, 750], [450, 1280], [-80, 1280]
  ], 0.2);

  // Faint indigo shadow undertone in the lower-right belly curve & upper-left hollow
  brush.fill(PALETTE.indigoGhost, 26);
  brush.fillBleed(0.5, "out");
  brush.fillTexture(0.85, 0.45);

  // Lower-right flank roll shadow
  drawPoly([
    [350, 1260], [680, 720], [1050, 420], [1260, 320], [1260, 1260]
  ], 0.25);

  // Upper-left pre-scapular hollow shadow
  drawPoly([
    [-60, -60], [640, -60], [380, 340], [-60, 690]
  ], 0.25);

  // Mid-flank subtle muscular depression behind the shoulder
  brush.fill(PALETTE.indigoDeep, 18);
  brush.fillBleed(0.5, "out");
  drawPoly([
    [120, 920], [460, 560], [620, 640], [290, 1080]
  ], 0.3);
  drawPoly([
    [680, 920], [980, 620], [1250, 580], [1250, 1180], [820, 1250]
  ], 0.25);

  // Warm crown highlight along the upper shoulder swell (around where the fly perches)
  brush.fill(PALETTE.ivoryLight, 65);
  brush.fillBleed(0.4, "out");
  drawPoly([
    [480, 260], [880, 80], [1120, 220], [890, 580], [540, 520]
  ], 0.3);

  brush.noFill();
}

function renderWarpUndertone() {
  // Subtle diagonal warp thread & motion lines across the sheet
  // Warp angle runs at -28 degrees (slightly crossing the -37 deg stripe sweep)
  const warpAng = -28 * (Math.PI / 180);
  const ca = Math.cos(warpAng);
  const sa = Math.sin(warpAng);

  brush.set("2H", PALETTE.ivoryMid, 0.45);
  for (let i = 0; i < 320; i++) {
    const cx = random(-100, 1300);
    const cy = random(-100, 1300);
    const len = random(90, 280);
    brush.line(
      cx - ca * len * 0.5,
      cy - sa * len * 0.5,
      cx + ca * len * 0.5,
      cy + sa * len * 0.5
    );
  }

  // Faint indigo-slate warp threads in the shadow zones
  brush.set("2H", PALETTE.indigoSlate, 0.32);
  for (let i = 0; i < 140; i++) {
    const cx = random(-50, 1250);
    const cy = random(-50, 1250);
    const len = random(70, 210);
    brush.line(
      cx - ca * len * 0.5,
      cy - sa * len * 0.5,
      cx + ca * len * 0.5,
      cy + sa * len * 0.5
    );
  }
}

// ============================================================================
// 4. IKAT WATERCOLOUR, CHARCOAL MASS, AND DRY-DRAGGED FLARES
// ============================================================================

// Builds chunked polygon segments for a stripe, splitting cleanly if interrupted by the scar
function buildStripeChunks(stripe, chunkLen = 280, stepU = 12, widthScale = 1.0, extraFlare = 0) {
  const chunks = [];
  const warpShiftPerV = 0.38; // Slants the ikat steps along the warp/hair grain

  for (let u0 = stripe.uStart; u0 < stripe.uEnd; u0 += chunkLen) {
    const u1 = Math.min(stripe.uEnd, u0 + chunkLen + stepU);

    let currentTop = [];
    let currentBot = [];

    const flushSubChunk = () => {
      if (currentTop.length >= 3) {
        const poly = currentTop.concat(currentBot.slice().reverse());
        chunks.push(poly);
      }
      currentTop = [];
      currentBot = [];
    };

    for (let u = u0; u <= u1; u += stepU) {
      const vc = stripe.centerFn(u);
      const sc = getScarInfluence(u, vc);

      // Interrupt the black band where the scar cuts directly through it
      if (sc.endTaper > 0 && sc.dist < 13 * sc.endTaper) {
        flushSubChunk();
        continue;
      }

      const hw = stripe.halfWidthFn(u) * widthScale;
      const stepTop = (getIkatStep(stripe.id, u, -1) + extraFlare) * widthScale;
      const stepBot = (getIkatStep(stripe.id, u, 1) + extraFlare) * widthScale;

      const vTop = vc - hw - stepTop;
      const vBot = vc + hw + stepBot;

      // Skew u slightly by the flare amount so steps angle along the warp threads
      const uTop = u - stepTop * warpShiftPerV;
      const uBot = u + stepBot * warpShiftPerV;

      currentTop.push(mapUV(uTop, vTop, true));
      currentBot.push(mapUV(uBot, vBot, true));
    }
    flushSubChunk();
  }

  return chunks;
}

function renderIkatWatercolourLayers(stripes) {
  brush.noStroke();

  // Pass 1: Faint indigo resist-bleed halo (outer dye creep along warp bundles)
  const haloChunks = [];
  for (let s of stripes) {
    const c = buildStripeChunks(s, 320, 14, 1.05, 10);
    for (let poly of c) haloChunks.push(poly);
  }

  brush.fill(PALETTE.indigoGhost, 38);
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.85, 0.55);
  for (let poly of haloChunks) {
    drawPoly(poly, 0.05);
  }

  // Pass 2: Main dark charcoal-indigo watercolor body of the ikat stripes
  const mainChunks = [];
  for (let s of stripes) {
    const c = buildStripeChunks(s, 290, 11, 0.96, 0);
    for (let poly of c) mainChunks.push(poly);
  }

  brush.fill(PALETTE.charcoalSoft, 118);
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.9, 0.72);
  for (let poly of mainChunks) {
    drawPoly(poly, 0.02);
  }

  // Pass 3: Deep velvety core wash inside the stripes
  const coreChunks = [];
  for (let s of stripes) {
    const c = buildStripeChunks(s, 320, 14, 0.68, -6);
    for (let poly of c) coreChunks.push(poly);
  }

  brush.fill(PALETTE.charcoalCore, 135);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.85, 0.65);
  for (let poly of coreChunks) {
    drawPoly(poly, 0.05);
  }

  brush.noFill();
}

function renderCharcoalMassAndHatching(stripes) {
  brush.noStroke();
  brush.noFill();

  // Dry charcoal mass inside the stripe cores for powdery tooth
  for (let s of stripes) {
    const massChunks = buildStripeChunks(s, 260, 16, 0.72, -4);
    for (let i = 0; i < massChunks.length; i++) {
      const col = i % 2 === 0 ? PALETTE.charcoalCore : PALETTE.indigoDeep;
      brush.mass("charcoal", col, {
        precision: 0.25,
        strength: 0.55,
        gradient: 0.35,
        outline: false
      });
      drawPoly(massChunks[i], 0.05);
      brush.noMass();
    }
  }

  // Directional charcoal hatching along the warp angle (-28 deg) inside the stripes
  brush.hatchStyle("charcoal", PALETTE.charcoalCore, 0.95);
  brush.hatch(7, -28, { rand: 0.12, gradient: 0.25 });
  for (let s of stripes) {
    const hatchChunks = buildStripeChunks(s, 320, 16, 0.85, 0);
    for (let poly of hatchChunks) {
      drawPoly(poly, 0.02);
    }
  }
  brush.noHatch();
}

function renderIkatDryDraggedEdges(stripes) {
  // Dry-dragged watercolour & charcoal flares shooting along the warp threads
  // at every stepped ikat boundary, plus cream resist threads cutting inward.
  for (let s of stripes) {
    for (let u = s.uStart; u <= s.uEnd; u += 4.5) {
      const vc = s.centerFn(u);
      const sc = getScarInfluence(u, vc);
      if (sc.endTaper > 0 && sc.dist < 16 * sc.endTaper) continue;

      const hw = s.halfWidthFn(u);

      for (let side of [-1, 1]) {
        const step = getIkatStep(s.id, u, side);
        const vEdge = vc + side * (hw + step);

        // Warp drag direction: mostly along the warp/motion sweep with outward flare
        const flareLen = Math.max(12, Math.abs(step) * 1.35 + random(8, 34));
        const du = side * flareLen * 0.55 + random(-10, 10);
        const dv = side * flareLen * 0.92;

        const pStart = mapUV(u - du * 0.45, vc + side * hw * 0.65, true);
        const pMid = mapUV(u, vEdge, true);
        const pEnd = mapUV(u + du * 0.65, vEdge + dv, true);

        // Skip off-screen marks to save render budget
        if (
          pMid[0] < -60 || pMid[0] > 1260 ||
          pMid[1] < -60 || pMid[1] > 1260
        ) {
          continue;
        }

        // 1. Dry-dragged multi-bristle streak (watercolour drag along warp)
        const isDarkSpike = step > 8;
        if (isDarkSpike) {
          const dragCol = random() < 0.72 ? PALETTE.charcoalCore : PALETTE.indigoDeep;
          brush.set("ikat_drag", dragCol, random(0.65, 1.25));
          brush.spline([
            [pStart[0], pStart[1], 0.9],
            [pMid[0], pMid[1], 0.7],
            [pEnd[0], pEnd[1], 0.05]
          ], 0.25);

          // Feathered charcoal edge teeth
          if (random() < 0.65) {
            brush.set("charcoal", PALETTE.charcoalCore, random(0.45, 0.85));
            brush.line(pStart[0], pStart[1], pEnd[0], pEnd[1]);
          }
        } else {
          // Cream resist-dyed warp threads creeping into the black stripe
          const resistStart = mapUV(u + du * 0.6, vEdge + side * 24, true);
          const resistEnd = mapUV(u - du * 0.7, vc + side * hw * 0.22, true);
          const creamCol = random() < 0.65 ? PALETTE.ivoryGround : PALETTE.ivoryWarm;

          brush.set("ikat_drag", creamCol, random(0.6, 1.1));
          brush.line(resistStart[0], resistStart[1], resistEnd[0], resistEnd[1]);

          if (random() < 0.5) {
            brush.set("cpencil", PALETTE.ivoryLight, random(0.55, 0.95));
            brush.line(resistStart[0], resistStart[1], resistEnd[0], resistEnd[1]);
          }
        }

        // 2. Stepped horizontal/transverse resist tie marks at bundle transitions
        if (Math.abs((u + 1200) % 12) < 4.5 && random() < 0.45) {
          const prevStep = getIkatStep(s.id, u - 6, side);
          if (Math.abs(step - prevStep) > 10) {
            const pStepA = mapUV(u - 3, vc + side * (hw + prevStep), true);
            const pStepB = mapUV(u - 3, vc + side * (hw + step), true);
            brush.set("cpencil", PALETTE.charcoalSoft, 0.55);
            brush.line(pStepA[0], pStepA[1], pStepB[0], pStepB[1]);
          }
        }
      }
    }
  }
}

// ============================================================================
// 5. HYPERREAL SCAR ON THE FLANK
// ============================================================================

function renderHyperrealScar() {
  const steps = 48;
  const upperLip = [];
  const lowerLip = [];
  const innerTop = [];
  const innerBot = [];
  const spinePts = [];

  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const u = lerp(SCAR_A.u, SCAR_B.u, t);
    const v = lerp(SCAR_A.v, SCAR_B.v, t);

    // Slight organic kink in the healed wound
    const kink = 6 * Math.sin(t * Math.PI * 3.0) + 4 * (noise(t * 8, 99) - 0.5);
    const env = Math.sin(t * Math.PI);
    const halfW = (11 + 5 * noise(t * 12, 42)) * env;

    // Normal to scar in (u, v)
    const dx = SCAR_B.u - SCAR_A.u;
    const dy = SCAR_B.v - SCAR_A.v;
    const len = Math.hypot(dx, dy);
    const nu = -dy / len;
    const nv = dx / len;

    const cu = u + nu * kink;
    const cv = v + nv * kink;

    spinePts.push({ u: cu, v: cv, nu, nv, halfW, env, t });
    upperLip.push(mapUV(cu + nu * halfW * 1.45, cv + nv * halfW * 1.45, false));
    lowerLip.push(mapUV(cu - nu * halfW * 1.45, cv - nv * halfW * 1.45, false));
    innerTop.push(mapUV(cu + nu * halfW * 0.55, cv + nv * halfW * 0.55, false));
    innerBot.push(mapUV(cu - nu * halfW * 0.55, cv - nv * halfW * 0.55, false));
  }

  // 1. Sunken dermal shadow trough around the scar
  brush.noStroke();
  brush.fill(PALETTE.indigoDeep, 58);
  brush.fillBleed(0.18, "out");
  drawPoly(upperLip.concat(lowerLip.slice().reverse()), 0.1);

  // 2. Subtle warm raw-sienna / copper-umber dermal tint inside the scar (echoing the accent)
  brush.fill(PALETTE.accentWarm, 48);
  brush.fillBleed(0.12, "out");
  drawPoly(innerTop.concat(innerBot.slice().reverse()), 0.1);

  // 3. Pale fibrous keloid seam in the center of the scar
  brush.wash(PALETTE.ivoryLight, 185);
  drawPoly(innerTop.concat(innerBot.slice().reverse()), 0.08);
  brush.noWash();
  brush.noFill();

  // 4. Needle-sharp scar tissue creases, puckered skin edges, and disrupted cowlicked hairs
  for (let i = 1; i < spinePts.length - 1; i++) {
    const pt = spinePts[i];
    const pCenter = mapUV(pt.u, pt.v, false);
    const pTop = mapUV(pt.u + pt.nu * pt.halfW, pt.v + pt.nv * pt.halfW, false);
    const pBot = mapUV(pt.u - pt.nu * pt.halfW, pt.v - pt.nv * pt.halfW, false);

    // Dark exposed dermal border where hair follicles were destroyed
    brush.set("rotring", PALETTE.charcoalCore, 0.35 * pt.env + 0.15);
    const pNextTop = mapUV(
      spinePts[i + 1].u + spinePts[i + 1].nu * spinePts[i + 1].halfW * 0.75,
      spinePts[i + 1].v + spinePts[i + 1].nv * spinePts[i + 1].halfW * 0.75,
      false
    );
    brush.line(pTop[0], pTop[1], pNextTop[0], pNextTop[1]);

    // Transverse collagen cross-fibers (stitch-like healed tension marks)
    if (i % 2 === 0) {
      brush.set("needle", PALETTE.accentWarm, 0.22);
      brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);

      brush.set("needle", PALETTE.ivoryLight, 0.28);
      brush.line(
        lerp(pTop[0], pCenter[0], 0.25),
        lerp(pTop[1], pCenter[1], 0.25) + 1,
        lerp(pBot[0], pCenter[0], 0.25),
        lerp(pBot[1], pCenter[1], 0.25) + 1
      );
    }

    // Disrupted, cowlicked guard hairs parting and crisscrossing around the scar lips
    for (let k = 0; k < 5; k++) {
      const side = k % 2 === 0 ? 1 : -1;
      const rootU = pt.u + side * pt.nu * (pt.halfW * random(0.65, 1.6));
      const rootV = pt.v + side * pt.nv * (pt.halfW * random(0.65, 1.6));
      const tipU = rootU + side * pt.nu * random(10, 26) - random(8, 22);
      const tipV = rootV + side * pt.nv * random(8, 22) + random(-6, 12);

      const pRoot = mapUV(rootU, rootV, false);
      const pTip = mapUV(tipU, tipV, false);
      const pMid = [
        (pRoot[0] + pTip[0]) * 0.5 + random(-3, 3),
        (pRoot[1] + pTip[1]) * 0.5 + random(-3, 3)
      ];

      // Determine whether this hair is white or black based on nearby stripe
      const isWhiteHair = random() < 0.62;
      const hCol = isWhiteHair ? PALETTE.ivoryLight : PALETTE.charcoalCore;
      brush.set("needle", hCol, random(0.2, 0.36));
      brush.spline([
        [pRoot[0], pRoot[1], 0.9],
        [pMid[0], pMid[1], 0.6],
        [pTip[0], pTip[1], 0.05]
      ], 0.35);
    }
  }
}

// ============================================================================
// 6. HYPERREAL INDIVIDUAL HAIRS WITHIN THE SOFTNESS
// ============================================================================

function renderHyperrealCoatHairs(stripes) {
  // Coat hair flow runs from upper-right shoulder toward lower-left flank,
  // curving slightly across the stripe edges so sharp white hairs overlap black bands
  // and sharp black guard hairs overlap the cream ground.

  // Pass A: Crisp hairs anchored along the stripe edges (sharp against the soft ikat bleed)
  for (let s of stripes) {
    for (let u = s.uStart + 20; u <= s.uEnd - 20; u += 3.5) {
      const vc = s.centerFn(u);
      const hw = s.halfWidthFn(u);

      // Focus highest density of needle-sharp hairs on the upper shoulder & mid-flank focal zone
      const focusDist = Math.hypot(u - 80, vc + 60);
      const focusProb = map(focusDist, 0, 750, 0.92, 0.25, true);
      if (random() > focusProb) continue;

      for (let side of [-1, 1]) {
        const step = getIkatStep(s.id, u, side);
        const vBoundary = vc + side * (hw + step * 0.65);

        // Hair growth vector in (u, v): sweeping down-left (-u) and slightly downward (+v)
        const hairLenU = -random(14, 30);
        const hairLenV = random(6, 16) + side * random(-4, 8);

        const rootU = u + random(-6, 6);
        const rootV = vBoundary + side * random(-10, 12);
        const midU = rootU + hairLenU * 0.5;
        const midV = rootV + hairLenV * 0.45;
        const tipU = rootU + hairLenU;
        const tipV = rootV + hairLenV;

        const p0 = mapUV(rootU, rootV, true);
        const p1 = mapUV(midU, midV, true);
        const p2 = mapUV(tipU, tipV, true);

        if (p0[0] < -20 || p0[0] > 1220 || p0[1] < -20 || p0[1] > 1220) continue;

        // Top edge (side == -1): white hairs rooted in cream overlap downward into the black stripe
        // Bottom edge (side == 1): black hairs rooted in the stripe overlap downward into cream
        let hairCol;
        let weight;
        if (side === -1) {
          hairCol = random() < 0.78 ? PALETTE.ivoryLight : PALETTE.ivoryWarm;
          weight = random(0.18, 0.34);
        } else {
          hairCol = random() < 0.82 ? PALETTE.charcoalCore : PALETTE.indigoDeep;
          weight = random(0.18, 0.35);
        }

        brush.set("needle", hairCol, weight);
        brush.spline([
          [p0[0], p0[1], 0.85],
          [p1[0], p1[1], 0.6],
          [p2[0], p2[1], 0.05]
        ], 0.35);
      }
    }
  }

  // Pass B: Specular individual hairs glinting inside the black bands & shadow hairs in the cream bands
  for (let i = 0; i < 1350; i++) {
    // Bias sampling toward the shoulder and scar focal corridor
    const u = randomGaussian(60, 340);
    const v = randomGaussian(-70, 320);

    const p0 = mapUV(u, v, true);
    if (p0[0] < 0 || p0[0] > 1200 || p0[1] < 0 || p0[1] > 1200) continue;

    const du = -random(13, 25);
    const dv = random(5, 14);
    const p1 = mapUV(u + du * 0.5, v + dv * 0.42, true);
    const p2 = mapUV(u + du, v + dv, true);

    // Check if point is inside any stripe core
    let inBlack = false;
    for (let s of stripes) {
      if (u >= s.uStart && u <= s.uEnd) {
        const vc = s.centerFn(u);
        const hw = s.halfWidthFn(u);
        if (Math.abs(v - vc) < hw) {
          inBlack = true;
          break;
        }
      }
    }

    if (inBlack) {
      // Glossy slate/ivory specular highlight hair or jet-black hair inside the dark band
      const col = random() < 0.35 ? PALETTE.indigoSlate : (random() < 0.25 ? PALETTE.ivoryWarm : PALETTE.charcoalCore);
      brush.set("needle", col, random(0.16, 0.28));
    } else {
      // Crisp individual cream hair or indigo-grey shadow hair in the ivory band
      const col = random() < 0.55 ? PALETTE.ivoryLight : PALETTE.indigoSlate;
      brush.set("needle", col, random(0.15, 0.26));
    }

    brush.spline([
      [p0[0], p0[1], 0.8],
      [p1[0], p1[1], 0.55],
      [p2[0], p2[1], 0.05]
    ], 0.3);
  }
}

// ============================================================================
// 7. HYPERREAL HORSEFLY ON THE SHOULDER
// ============================================================================

function renderHyperrealFly(cx, cy, angleDeg) {
  push();
  translate(cx, cy);
  rotate(angleDeg);

  // Local coordinate system of the fly:
  // Head is towards +X (x ~ 22..38), Thorax is centered at (0, 0),
  // Abdomen extends towards -X (x ~ -10..-58), Wings sweep back towards -X.

  // --------------------------------------------------------------------------
  // A. CAST SHADOW ON THE ZEBRA COAT (Indigo-black watercolor bleed)
  // --------------------------------------------------------------------------
  // Light comes from upper-left; in local space (-128 deg), shadow offsets by (-9, -13)
  const sx = -8;
  const sy = -12;

  brush.noStroke();
  brush.fill(PALETTE.indigoDeep, 72);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.6, 0.4);

  // Body & wing cast shadow
  drawPoly([
    [32 + sx, -4 + sy],
    [14 + sx, -20 + sy],
    [-58 + sx, -34 + sy],
    [-64 + sx, -12 + sy],
    [-54 + sx, 16 + sy],
    [12 + sx, 18 + sy]
  ], 0.3);

  // Deep contact shadow directly beneath thorax and abdomen
  brush.fill(PALETTE.charcoalCore, 125);
  brush.fillBleed(0.12, "out");
  drawPoly([
    [24 + sx * 0.35, -8 + sy * 0.35],
    [-46 + sx * 0.35, -14 + sy * 0.35],
    [-50 + sx * 0.35, 6 + sy * 0.35],
    [20 + sx * 0.35, 10 + sy * 0.35]
  ], 0.35);
  brush.noFill();

  // --------------------------------------------------------------------------
  // B. SIX JOINTED LEGS WITH TIBIAL SPURS, SETAE, AND TARSAL CLAWS
  // --------------------------------------------------------------------------
  const legs = [
    // Forelegs (reaching forward to grip the hide)
    {
      side: 1,
      coxa: [14, 9],
      femur: [28, 22],
      tibia: [42, 30],
      tarsus: [52, 27],
      claw: [57, 29]
    },
    {
      side: -1,
      coxa: [14, -9],
      femur: [30, -20],
      tibia: [44, -26],
      tarsus: [54, -22],
      claw: [59, -24]
    },
    // Midlegs (splayed wide for lateral balance on the moving shoulder)
    {
      side: 1,
      coxa: [2, 13],
      femur: [6, 34],
      tibia: [-8, 50],
      tarsus: [-18, 58],
      claw: [-23, 62]
    },
    {
      side: -1,
      coxa: [2, -13],
      femur: [8, -32],
      tibia: [-4, -48],
      tarsus: [-14, -56],
      claw: [-19, -60]
    },
    // Hindlegs (braced backward alongside the abdomen)
    {
      side: 1,
      coxa: [-10, 12],
      femur: [-26, 28],
      tibia: [-50, 38],
      tarsus: [-68, 35],
      claw: [-74, 38]
    },
    {
      side: -1,
      coxa: [-10, -12],
      femur: [-24, -26],
      tibia: [-48, -36],
      tarsus: [-65, -33],
      claw: [-71, -36]
    }
  ];

  for (let leg of legs) {
    // Faint cast shadow of each leg on the zebra hairs
    brush.set("2B", PALETTE.indigoDeep, 0.55);
    brush.line(leg.coxa[0] + sx * 0.5, leg.coxa[1] + sy * 0.5, leg.femur[0] + sx * 0.7, leg.femur[1] + sy * 0.7);
    brush.line(leg.femur[0] + sx * 0.7, leg.femur[1] + sy * 0.7, leg.tibia[0] + sx * 0.4, leg.tibia[1] + sy * 0.4);
    brush.line(leg.tibia[0] + sx * 0.4, leg.tibia[1] + sy * 0.4, leg.claw[0], leg.claw[1]);

    // Femur (thick chitinous segment with burnt-sienna highlight)
    brush.set("rotring", PALETTE.charcoalCore, 1.35);
    brush.line(leg.coxa[0], leg.coxa[1], leg.femur[0], leg.femur[1]);
    brush.set("needle", PALETTE.accentMid, 0.42);
    brush.line(leg.coxa[0], leg.coxa[1] + leg.side * 0.8, leg.femur[0], leg.femur[1] + leg.side * 0.8);
    brush.set("needle", PALETTE.ivoryLight, 0.25);
    brush.line(leg.coxa[0], leg.coxa[1] + leg.side * 1.2, leg.femur[0], leg.femur[1] + leg.side * 1.2);

    // Tibia (slender with fine sensory bristles)
    brush.set("rotring", PALETTE.charcoalCore, 0.95);
    brush.line(leg.femur[0], leg.femur[1], leg.tibia[0], leg.tibia[1]);
    brush.set("needle", PALETTE.accentBright, 0.28);
    brush.line(leg.femur[0], leg.femur[1] + leg.side * 0.5, leg.tibia[0], leg.tibia[1] + leg.side * 0.5);

    // Microscopic tibial bristles (setae)
    for (let b = 0.15; b <= 0.9; b += 0.18) {
      const bx = lerp(leg.femur[0], leg.tibia[0], b);
      const by = lerp(leg.femur[1], leg.tibia[1], b);
      brush.set("needle", PALETTE.charcoalCore, 0.16);
      brush.line(bx, by, bx - 3.5, by + leg.side * 3.8);
    }

    // Segmented Tarsus (5 tarsomeres)
    for (let seg = 0; seg < 4; seg++) {
      const t0 = seg / 4;
      const t1 = (seg + 1) / 4;
      const tx0 = lerp(leg.tibia[0], leg.tarsus[0], t0);
      const ty0 = lerp(leg.tibia[1], leg.tarsus[1], t0);
      const tx1 = lerp(leg.tibia[0], leg.tarsus[0], t1);
      const ty1 = lerp(leg.tibia[1], leg.tarsus[1], t1);
      brush.set("rotring", PALETTE.charcoalCore, 0.65 - seg * 0.08);
      brush.line(tx0, ty0, tx1, ty1);
    }

    // Double curved tarsal claws + pale pulvilli pad gripping the zebra hairs
    brush.set("needle", PALETTE.ivoryWarm, 0.35);
    brush.line(leg.tarsus[0], leg.tarsus[1], leg.claw[0] - 1, leg.claw[1]);
    brush.set("needle", PALETTE.charcoalCore, 0.24);
    brush.line(leg.tarsus[0], leg.tarsus[1], leg.claw[0], leg.claw[1] + 2.2);
    brush.line(leg.tarsus[0], leg.tarsus[1], leg.claw[0] + 1.5, leg.claw[1] - 2.0);
  }

  // --------------------------------------------------------------------------
  // C. SEGMENTED ABDOMEN (Dark chitin with warm copper-amber lateral translucency)
  // --------------------------------------------------------------------------
  brush.noStroke();

  // Base abdomen silhouette
  const abdPoly = [
    [-8, -14], [-24, -18], [-42, -16], [-56, -10],
    [-62, 0],
    [-56, 10], [-42, 16], [-24, 18], [-8, 14]
  ];
  brush.wash(PALETTE.charcoalCore, 215);
  drawPoly(abdPoly, 0.25);
  brush.noWash();

  // Warm burnt-sienna / amber lateral tergite translucency (characteristic of Tabanidae)
  brush.fill(PALETTE.accentMid, 130);
  brush.fillBleed(0.08, "in");
  drawPoly([[-12, -15], [-38, -16], [-44, -7], [-14, -6]], 0.2);
  drawPoly([[-12, 15], [-38, 16], [-44, 7], [-14, 6]], 0.2);
  brush.noFill();

  // Tergite segment rings, median pale triangles, and micro-hatching
  const tergiteX = [-12, -21, -31, -41, -50, -57];
  for (let i = 0; i < tergiteX.length; i++) {
    const tx = tergiteX[i];
    const halfW = map(i, 0, 5, 16.5, 8.5);

    // Dark inter-segmental suture arc
    brush.set("rotring", PALETTE.charcoalCore, 0.45);
    brush.spline([
      [tx, -halfW, 0.4],
      [tx - 3.5, 0, 0.9],
      [tx, halfW, 0.4]
    ], 0.35);

    // Pale pruinose rim highlight & dorsal median triangle
    brush.set("needle", PALETTE.ivoryWarm, 0.26);
    brush.spline([
      [tx - 0.8, -halfW * 0.75, 0.2],
      [tx - 4.2, 0, 0.7],
      [tx - 0.8, halfW * 0.75, 0.2]
    ], 0.35);

    if (i < 4) {
      brush.set("needle", PALETTE.ivoryLight, 0.28);
      brush.line(tx, 0, tx - 6.5, -2.2);
      brush.line(tx, 0, tx - 6.5, 2.2);
    }
  }

  // Fine cylindrical cross-hatching & tiny abdominal hairs
  for (let a = 0; a < 55; a++) {
    const ax = random(-56, -12);
    const ay = random(-14, 14);
    if ( (ax + 34) * (ax + 34) / (26 * 26) + (ay * ay) / (16 * 16) <= 1.0 ) {
      const col = Math.abs(ay) > 6 ? PALETTE.accentBright : PALETTE.charcoalGrey;
      brush.set("needle", col, 0.16);
      brush.line(ax, ay, ax - 4.5, ay * 1.08);
    }
  }

  // --------------------------------------------------------------------------
  // D. THORAX (Mesonotum & Scutellum with longitudinal pruinose stripes)
  // --------------------------------------------------------------------------
  brush.noStroke();
  const thxPoly = [
    [19, -11], [6, -16], [-10, -15], [-16, -8],
    [-19, 0],
    [-16, 8], [-10, 15], [6, 16], [19, 11], [22, 0]
  ];
  brush.wash(PALETTE.charcoalCore, 235);
  drawPoly(thxPoly, 0.3);
  brush.noWash();

  // Longitudinal dusty-ivory pruinose vittae (stripes on horsefly thorax)
  for (let vy of [-7.5, 0, 7.5]) {
    brush.set("cpencil", PALETTE.ivoryMid, 0.55);
    brush.line(-11, vy, 16, vy * 0.82);
    brush.set("needle", PALETTE.ivoryLight, 0.22);
    brush.line(-9, vy + 0.5, 14, vy * 0.82 + 0.5);
  }

  // Scutellum (triangular rear shield at x = -10..-19)
  brush.set("rotring", PALETTE.charcoalCore, 0.5);
  brush.spline([[-9, -11, 0.5], [-14, 0, 0.9], [-9, 11, 0.5]], 0.3);
  brush.set("needle", PALETTE.accentWarm, 0.28);
  brush.spline([[-14, -8, 0.4], [-19, 0, 0.8], [-14, 8, 0.4]], 0.35);

  // Specular highlight on upper-right dome of thorax (catching top-left light)
  brush.set("needle", PALETTE.ivoryLight, 0.36);
  for (let h = 0; h < 12; h++) {
    const hx = map(h, 0, 11, -4, 13);
