// ============================================================================
// GEOMETRY & POLYGON CLIPPING HELPERS
// ============================================================================

function toWorld(cx, cy, cosA, sinA, lx, ly) {
  return [cx + lx * cosA - ly * sinA, cy + lx * sinA + ly * cosA];
}

function drawPoly(pts, curvature = 0.12) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function signedArea(poly) {
  let area = 0;
  for (let i = 0, n = poly.length; i < n; i++) {
    let p1 = poly[i];
    let p2 = poly[(i + 1) % n];
    area += p1[0] * p2[1] - p2[0] * p1[1];
  }
  return area * 0.5;
}

function ensureCCW(poly) {
  let copy = poly.map((p) => [p[0], p[1]]);
  if (signedArea(copy) < 0) copy.reverse();
  return copy;
}

// Sutherland-Hodgman polygon intersection for wrapper/candy overlaps
function intersectPolygons(subjectPoly, clipPoly) {
  let outputList = ensureCCW(subjectPoly);
  let clip = ensureCCW(clipPoly);

  for (let i = 0; i < clip.length; i++) {
    let inputList = outputList;
    outputList = [];
    if (inputList.length === 0) break;

    let A = clip[i];
    let B = clip[(i + 1) % clip.length];
    let edgeDx = B[0] - A[0];
    let edgeDy = B[1] - A[1];

    let inside = (p) => edgeDx * (p[1] - A[1]) - edgeDy * (p[0] - A[0]) >= 0;
    let intersect = (S, E) => {
      let sDx = E[0] - S[0];
      let sDy = E[1] - S[1];
      let denom = edgeDx * sDy - edgeDy * sDx;
      if (abs(denom) < 1e-6) return S;
      let t = (edgeDx * (A[1] - S[1]) - edgeDy * (A[0] - S[0])) / denom;
      return [S[0] + t * sDx, S[1] + t * sDy];
    };

    let S = inputList[inputList.length - 1];
    for (let j = 0; j < inputList.length; j++) {
      let E = inputList[j];
      if (inside(E)) {
        if (!inside(S)) outputList.push(intersect(S, E));
        outputList.push(E);
      } else if (inside(S)) {
        outputList.push(intersect(S, E));
      }
      S = E;
    }
  }
  return outputList;
}

