function addFillPoly(batchKey, pts) {
  if (fillBatches[batchKey] && pts && pts.length >= 3) {
    fillBatches[batchKey].push(pts);
  }
}

function addWashPoly(color, opacity, pts, curv = 0.06) {
  if (pts && pts.length >= 3) {
    washBatches.push({ color, opacity, pts, curv });
