// ============================================================================

function buildCandyHeap() {
  candies = [];

  // Layer 0: Border & Deep bed candies (dissolving into soft colour at borders)
  let deepGrid = 5;
  let stepD = 1200 / deepGrid;
  for (let gx = 0; gx <= deepGrid; gx++) {
    for (let gy = 0; gy <= deepGrid; gy++) {
      let cx = gx * stepD + random(-55, 55);
      let cy = gy * stepD + random(-55, 55);
      let flavor = (gx * 2 + gy + floor(random(3))) % 3;
      let rx = random(88, 125);
      let ry = random(65, 92);
      let angle = random(360);
      let isBorder = cx < 170 || cx > 1030 || cy < 170 || cy > 1030;
      candies.push(createCandy(cx, cy, rx, ry, angle, flavor, isBorder ? 0 : 1));
    }
  }

  // Layer 1: Midground tumbled heap (dense overlapping across canvas)
  let midPositions = [
    [180, 210], [420, 160], [690, 190], [960, 200], [1080, 410],
    [140, 470], [360, 410], [610, 380], [850, 430], [230, 720],
    [490, 650], [740, 670], [990, 690], [160, 980], [410, 940],
    [680, 960], [940, 970], [1070, 820], [80, 720], [540, 1100],
    [290, 1110], [860, 1120], [310, 80], [790, 75]
  ];
  for (let i = 0; i < midPositions.length; i++) {
    let [bx, by] = midPositions[i];
    let cx = bx + random(-40, 40);
    let cy = by + random(-40, 40);
    let flavor = (i + floor(random(2))) % 3;
    let rx = random(78, 108);
    let ry = random(58, 82);
    let angle = random(360);
    let isEdge = cx < 115 || cx > 1085 || cy < 115 || cy > 1085;
    candies.push(createCandy(cx, cy, rx, ry, angle, flavor, isEdge ? 0 : 1));
  }

  // Layer 2: Foreground Hero Candies (crisp, large, dazzlingly detailed)
  let heroPositions = [
    [260, 280], [540, 250], [830, 290],
    [190, 560], [450, 510], [730, 520], [980, 540],
    [320, 790], [590, 770], [870, 810],
    [240, 1010], [520, 980], [810, 1010],
    [380, 340], [640, 630], [1030, 310], [130, 330], [930, 680]
  ];
  for (let i = 0; i < heroPositions.length; i++) {
    let [bx, by] = heroPositions[i];
    let cx = bx + random(-28, 28);
    let cy = by + random(-28, 28);
    let flavor = i % 3;
    let shapeKind = i % 3 === 0 ? "pillow" : i % 3 === 1 ? "oval" : "round";
    let rx = shapeKind === "round" ? random(76, 92) : random(86, 112);
    let ry = shapeKind === "round" ? rx * random(0.88, 0.96) : rx * random(0.66, 0.78);
    let angle = random(360);
    candies.push(createCandy(cx, cy, rx, ry, angle, flavor, 2, shapeKind));
  }
}

function createCandy(cx, cy, rx, ry, angle, flavor, tier, shapeKind = "oval") {
  let cosA = cos(angle);
  let sinA = sin(angle);

  let flavKeys = ["rasp", "lime", "butt"];
  let fKey = flavKeys[flavor];

  // 1. Build core polygon in world coords
  let corePts = [];
  let glowPts = [];
  let richPts = [];
  let deepCrescentPts = [];
  let causticCrescentPts = [];

  let nCore = 20;
  for (let i = 0; i < nCore; i++) {
    let a = (i / nCore) * 360;
    let ca = cos(a);
    let sa = sin(a);
    // Superellipse exponent for pillow vs oval
    let p = shapeKind === "pillow" ? 0.78 : 1.0;
    let sx = Math.sign(ca) * pow(abs(ca), p) * rx;
    let sy = Math.sign(sa) * pow(abs(sa), p) * ry;
    let jitter = 1 + 0.03 * sin(a * 3 + cx);

    corePts.push(toWorld(cx, cy, cosA, sinA, sx * jitter, sy * jitter));
    glowPts.push(toWorld(cx, cy, cosA, sinA, sx * 1.38 * jitter, sy * 1.38 * jitter));
    richPts.push(toWorld(cx, cy, cosA, sinA, sx * 0.84 + rx * 0.05, sy * 0.84 + ry * 0.05));
  }

  // Internal deep crescent (bottom-right of local or world light direction)
  for (let i = 0; i <= 10; i++) {
    let a = -35 + (i / 10) * 195;
    let lx = cos(a) * rx * 0.92;
    let ly = sin(a) * ry * 0.92;
    deepCrescentPts.push(toWorld(cx, cy, cosA, sinA, lx, ly));
  }
  for (let i = 10; i >= 0; i--) {
    let a = -35 + (i / 10) * 195;
    let lx = cos(a) * rx * 0.48 + rx * 0.12;
    let ly = sin(a) * ry * 0.48 + ry * 0.14;
    deepCrescentPts.push(toWorld(cx, cy, cosA, sinA, lx, ly));
  }

  // Internal subsurface caustic glow crescent (opposite side)
  for (let i = 0; i <= 10; i++) {
    let a = 155 + (i / 10) * 165;
    let lx = cos(a) * rx * 0.82;
    let ly = sin(a) * ry * 0.82;
    causticCrescentPts.push(toWorld(cx, cy, cosA, sinA, lx, ly));
  }
  for (let i = 10; i >= 0; i--) {
    let a = 155 + (i / 10) * 165;
    let lx = cos(a) * rx * 0.45 - rx * 0.08;
    let ly = sin(a) * ry * 0.45 - ry * 0.1;
    causticCrescentPts.push(toWorld(cx, cy, cosA, sinA, lx, ly));
  }

  // 2. Build crinkled cellophane body envelope around the core
  let celloBodyPts = [];
  let nCello = 16;
  for (let i = 0; i < nCello; i++) {
    let a = (i / nCello) * 360;
    let crinkle = (i % 2 === 0 ? 1.18 : 1.07) * random(0.97, 1.05);
    let lx = cos(a) * rx * crinkle;
    let ly = sin(a) * ry * crinkle;
    celloBodyPts.push(toWorld(cx, cy, cosA, sinA, lx, ly));
  }

  // 3. Build twisted fan ends on both sides (-1 and +1)
  let fans = [];
  for (let side of [-1, 1]) {
    let neckX = side * rx * 1.06;
    let neckY = random(-ry * 0.12, ry * 0.12);
    let neckW = ry * 0.22;
    let fanLen = rx * random(1.15, 1.48);
    let fanSpread = random(34, 46); // half-angle in degrees
    let tilt = random(-14, 14);

    // Twist knot facets at the pinched neck
    let knotPoly1 = [
      toWorld(cx, cy, cosA, sinA, neckX - side * rx * 0.18, neckY - neckW * 1.3),
      toWorld(cx, cy, cosA, sinA, neckX + side * rx * 0.14, neckY - neckW * 0.5),
      toWorld(cx, cy, cosA, sinA, neckX + side * rx * 0.08, neckY + neckW * 1.1),
      toWorld(cx, cy, cosA, sinA, neckX - side * rx * 0.15, neckY + neckW * 0.6)
    ];
    let knotPoly2 = [
      toWorld(cx, cy, cosA, sinA, neckX - side * rx * 0.05, neckY - neckW * 0.9),
      toWorld(cx, cy, cosA, sinA, neckX + side * rx * 0.24, neckY - neckW * 1.2),
      toWorld(cx, cy, cosA, sinA, neckX + side * rx * 0.20, neckY + neckW * 0.9),
      toWorld(cx, cy, cosA, sinA, neckX - side * rx * 0.08, neckY + neckW * 0.4)
    ];

    // Pleated fan folds radiating from neck
    let nFolds = 5;
    let pleats = [];
    let fanOutline = [toWorld(cx, cy, cosA, sinA, neckX, neckY - neckW)];
    let hairlines = [];
    let outerRimPts = [];

    for (let f = 0; f < nFolds; f++) {
      let t0 = f / nFolds;
      let t1 = (f + 1) / nFolds;
      let a0 = tilt + map(t0, 0, 1, -fanSpread, fanSpread);
      let a1 = tilt + map(t1, 0, 1, -fanSpread, fanSpread);
      let aMid = (a0 + a1) * 0.5;

      let r0 = fanLen * random(0.88, 1.08);
      let rMid = fanLen * random(1.02, 1.16);
      let r1 = fanLen * random(0.86, 1.06);

      let pBase0 = toWorld(cx, cy, cosA, sinA, neckX + side * 4, neckY + map(t0, 0, 1, -neckW, neckW));
      let pBase1 = toWorld(cx, cy, cosA, sinA, neckX + side * 4, neckY + map(t1, 0, 1, -neckW, neckW));
      let pOut0 = toWorld(cx, cy, cosA, sinA, neckX + side * cos(a0) * r0, neckY + sin(a0) * r0);
      let pOutMid = toWorld(cx, cy, cosA, sinA, neckX + side * cos(aMid) * rMid, neckY + sin(aMid) * rMid);
      let pOut1 = toWorld(cx, cy, cosA, sinA, neckX + side * cos(a1) * r1, neckY + sin(a1) * r1);

      pleats.push({
        poly: [pBase0, pOut0, pOutMid, pOut1, pBase1],
        ridgeLine: [pBase0, pOutMid],
        valleyLine: [pBase1, pOut1],
        tintType: f % 2 === 0 ? "cyan" : "core"
      });

      fanOutline.push(pOut0, pOutMid);
      if (f === nFolds - 1) fanOutline.push(pOut1);
      outerRimPts.push(pOut0, pOutMid);
      if (f === nFolds - 1) outerRimPts.push(pOut1);

      // Generate 3 to 4 fine pen hairlines per pleat
      let nLines = tier === 2 ? 4 : 3;
      for (let h = 0; h < nLines; h++) {
        let fh = (h + random(0.15, 0.85)) / nLines;
        let ah = lerp(a0, a1, fh);
        let rh = fanLen * random(0.65, 1.06);
        let startP = toWorld(
          cx,
          cy,
          cosA,
          sinA,
          neckX - side * rx * random(0.05, 0.22),
          neckY + map(t0 + fh * (t1 - t0), 0, 1, -neckW * 0.9, neckW * 0.9)
        );
        let midP = toWorld(
          cx,
          cy,
          cosA,
          sinA,
          neckX + side * cos(ah + random(-4, 4)) * rh * 0.48,
          neckY + sin(ah + random(-4, 4)) * rh * 0.48
        );
        let endP = toWorld(
          cx,
          cy,
          cosA,
          sinA,
          neckX + side * cos(ah) * rh,
          neckY + sin(ah) * rh
        );
        hairlines.push({ pts: [startP, midP, endP], isCyan: (f + h) % 3 === 0 });
      }
    }
    fanOutline.push(toWorld(cx, cy, cosA, sinA, neckX, neckY + neckW));

    fans.push({
      side,
      neckWorld: toWorld(cx, cy, cosA, sinA, neckX, neckY),
      knotPoly1,
      knotPoly2,
      pleats,
      fanOutline,
      hairlines,
      outerRimPts
    });
  }

  // 4. Build diagonal crinkle creases & facets stretched across the candy core
  let creases = [];
  let nCreases = tier === 2 ? 5 : 3;
  for (let c = 0; c < nCreases; c++) {
    let frac = map(c, 0, nCreases - 1, -0.72, 0.72) + random(-0.08, 0.08);
    let yLeft = frac * ry * 0.45;
    let yMid1 = (frac + random(-0.22, 0.22)) * ry * 0.85;
    let yMid2 = (frac + random(-0.22, 0.22)) * ry * 0.85;
    let yRight = -frac * ry * 0.42;

    let p0 = toWorld(cx, cy, cosA, sinA, -rx * 1.04, yLeft);
    let p1 = toWorld(cx, cy, cosA, sinA, -rx * 0.35, yMid1);
    let p2 = toWorld(cx, cy, cosA, sinA, rx * 0.35, yMid2);
    let p3 = toWorld(cx, cy, cosA, sinA, rx * 1.04, yRight);

    // Offset points for cyan reflection & ribbon facet
    let off = 3.5;
    let c0 = toWorld(cx, cy, cosA, sinA, -rx * 1.02, yLeft + off);
    let c1 = toWorld(cx, cy, cosA, sinA, -rx * 0.35, yMid1 + off * 1.4);
    let c2 = toWorld(cx, cy, cosA, sinA, rx * 0.35, yMid2 + off * 1.2);
    let c3 = toWorld(cx, cy, cosA, sinA, rx * 1.02, yRight + off);

    let facetWidth = ry * random(0.1, 0.18);
    let facetPoly = [
      p0,
      p1,
      p2,
      p3,
      toWorld(cx, cy, cosA, sinA, rx * 0.4, yMid2 + facetWidth),
      toWorld(cx, cy, cosA, sinA, -rx * 0.4, yMid1 + facetWidth)
    ];

    creases.push({
      glintPts: [p0, p1, p2, p3],
      cyanPts: [c0, c1, c2, c3],
      facetPoly
    });
  }

  // 5. Build glossy specular dome windows on the upper-left side of the candy
  let specAngle = -55 - angle; // consistent global light from top-left
  let specR = rx * 0.62;
  let specPts = [];
  for (let i = 0; i <= 7; i++) {
    let a = specAngle - 38 + (i / 7) * 76;
    specPts.push(toWorld(cx, cy, cosA, sinA, cos(a) * rx * 0.74, sin(a) * ry * 0.74));
  }
  for (let i = 7; i >= 0; i--) {
    let a = specAngle - 38 + (i / 7) * 76;
    specPts.push(toWorld(cx, cy, cosA, sinA, cos(a) * rx * 0.52, sin(a) * ry * 0.52));
  }

  // Queue watercolor fills into batches based on tier
  addFillPoly("glow_" + fKey, glowPts);

  if (tier >= 1) {
    // Cellophane outer envelope & fan tints
    addFillPoly("cello_cyan", celloBodyPts);
    for (let fan of fans) {
      addFillPoly("glow_cyan", fan.fanOutline);
      for (let p of fan.pleats) {
        if (p.tintType === "cyan") {
          addFillPoly("cello_cyan", p.poly);
        } else {
          addFillPoly("glow_" + fKey, p.poly);
        }
      }
      addFillPoly("cello_violet", fan.knotPoly1);
    }

    // Core watercolor stack
    addFillPoly("core_mid_" + fKey, corePts);
    addFillPoly("caustic_" + fKey, causticCrescentPts);
    addFillPoly("core_rich_" + fKey, richPts);
    addFillPoly("deep_" + fKey, deepCrescentPts);
  } else {
    // Border dissolve candies: softer, higher-bleed dreamy watercolor stack
    addFillPoly("core_mid_" + fKey, corePts);
    addFillPoly("caustic_" + fKey, causticCrescentPts);
    for (let fan of fans) {
      addFillPoly("glow_cyan", fan.fanOutline);
      addFillPoly("glow_" + fKey, fan.pleats[1].poly);
    }
  }

  // Queue slick cellophane washes for midground & foreground
  if (tier >= 1) {
    addWashPoly(PALETTE.cyanBright, tier === 2 ? 38 : 26, creases[0].facetPoly, 0.08);
    if (creases.length > 2) {
      addWashPoly(PALETTE.whitePure, tier === 2 ? 62 : 40, creases[1].facetPoly, 0.05);
    }
    addWashPoly(PALETTE.whitePure, tier === 2 ? 95 : 55, specPts, 0.18);
    for (let fan of fans) {
      addWashPoly(PALETTE.whitePure, tier === 2 ? 68 : 42, fan.pleats[0].poly, 0.05);
      addWashPoly(PALETTE.cyanBright, tier === 2 ? 45 : 30, fan.pleats[2].poly, 0.05);
      addWashPoly(PALETTE.whitePure, tier === 2 ? 75 : 45, fan.knotPoly2, 0.04);
    }
  }

  return {
    cx,
    cy,
    rx,
    ry,
    angle,
    cosA,
    sinA,
    flavor,
    fKey,
    tier,
    corePts,
    celloBodyPts,
    fans,
    creases,
    specPts
  };
}

// ============================================================================
// OPTICAL OVERLAP COMPUTATION (DARKENING WHERE WRAPPERS/CANDIES CROSS)
// ============================================================================

function computeWrapperOverlaps() {
  for (let i = 0; i < candies.length; i++) {
    let A = candies[i];
    if (A.tier === 0) continue;

    for (let j = i + 1; j < candies.length; j++) {
      let B = candies[j];
      let d = dist(A.cx, A.cy, B.cx, B.cy);
      let maxReach = (A.rx + B.rx) * 2.25;
      if (d > maxReach) continue;

      // 1. Check Core-to-Core or Core-to-Wrapper overlaps
      let coreInter = intersectPolygons(A.celloBodyPts, B.celloBodyPts);
      if (coreInter.length >= 3 && abs(signedArea(coreInter)) > 120) {
        let batchKey = getOverlapBatchKey(A.flavor, B.flavor, true);
        addFillPoly(batchKey, coreInter);
        overlapPolys.push({ poly: coreInter, isCore: true });
      }

      // 2. Check Wrapper Fan-to-Body overlaps
      for (let fanA of A.fans) {
        let fanBodyInter = intersectPolygons(fanA.fanOutline, B.celloBodyPts);
        if (fanBodyInter.length >= 3 && abs(signedArea(fanBodyInter)) > 90) {
          let batchKey = getOverlapBatchKey(A.flavor, B.flavor, false);
          addFillPoly(batchKey, fanBodyInter);
          overlapPolys.push({ poly: fanBodyInter, isCore: false });
        }

        // 3. Check Wrapper Fan-to-Fan overlaps
        for (let fanB of B.fans) {
          let fanFanInter = intersectPolygons(fanA.fanOutline, fanB.fanOutline);
          if (fanFanInter.length >= 3 && abs(signedArea(fanFanInter)) > 85) {
            addFillPoly("overlap_deep_cyan", fanFanInter);
            addFillPoly("cello_violet", fanFanInter);
            overlapPolys.push({ poly: fanFanInter, isCore: false });
          }
        }
      }

      for (let fanB of B.fans) {
        let bodyFanInter = intersectPolygons(A.celloBodyPts, fanB.fanOutline);
        if (bodyFanInter.length >= 3 && abs(signedArea(bodyFanInter)) > 90) {
          let batchKey = getOverlapBatchKey(A.flavor, B.flavor, false);
          addFillPoly(batchKey, bodyFanInter);
          overlapPolys.push({ poly: bodyFanInter, isCore: false });
        }
      }
    }
  }
}

function getOverlapBatchKey(flavA, flavB, isCore) {
  if (flavA === flavB) {
    return ["deep_rasp", "deep_lime", "deep_butt"][flavA];
  }
  let pair = [min(flavA, flavB), max(flavA, flavB)].join("_");
  if (pair === "0_1") return "overlap_berry_teal"; // Raspberry + Lime
  if (pair === "0_2") return "overlap_ruby_amber"; // Raspberry + Butterscotch
  if (pair === "1_2") return "overlap_emerald_gold"; // Lime + Butterscotch
  return isCore ? "deep_rasp" : "overlap_deep_cyan";
}

// ============================================================================
// RENDERING PIPELINE
// ============================================================================

function renderBaseDissolveWashes() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Soft seamless pastel under-wash across the entire canvas so zero bare background exists
  let baseBeds = [
    { color: PALETTE.raspPale, op: 85, x: 220, y: 240, r: 390 },
    { color: PALETTE.limePale, op: 85, x: 650, y: 200, r: 380 },
    { color: PALETTE.buttPale, op: 90, x: 1020, y: 260, r: 390 },
    { color: PALETTE.cyanPale, op: 80, x: 180, y: 650, r: 360 },
    { color: PALETTE.buttPale, op: 85, x: 580, y: 600, r: 420 },
    { color: PALETTE.raspPale, op: 85, x: 980, y: 640, r: 380 },
    { color: PALETTE.limePale, op: 85, x: 260, y: 1020, r: 400 },
    { color: PALETTE.raspPale, op: 85, x: 640, y: 1000, r: 390 },
    { color: PALETTE.cyanPale, op: 80, x: 1040, y: 1020, r: 380 },
    { color: PALETTE.lilacPale, op: 75, x: 420, y: 420, r: 350 },
    { color: PALETTE.limePale, op: 80, x: 820, y: 820, r: 360 }
  ];

  for (let b of baseBeds) {
    brush.fill(b.color, b.op);
    brush.fillBleed(0.45, "out");
    brush.fillTexture(0.65, 0.2);
    brush.circle(b.x, b.y, b.r, 0.35);
  }
  brush.noFill();
}

function renderWatercolorBatches() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  for (let b of BATCH_ORDER) {
    let polys = fillBatches[b.key];
    if (!polys || polys.length === 0) continue;

    brush.fill(b.color, b.opacity);
    brush.fillBleed(b.bleed, "out");
    brush.fillTexture(b.tex, b.border);

    for (let i = 0; i < polys.length; i++) {
      drawPoly(polys[i], b.curv);
    }
  }
  brush.noFill();
}

function renderCellophaneWashes() {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();

  for (let i = 0; i < washBatches.length; i++) {
    let w = washBatches[i];
    brush.wash(w.color, w.opacity);
    drawPoly(w.pts, w.curv);
  }
  brush.noWash();
}

function renderAllCandyDetails() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();

  // First: crisp cyan & chromatic boundary lines along wrapper overlap intersections
  for (let i = 0; i < overlapPolys.length; i++) {
    let ov = overlapPolys[i];
    if (ov.poly.length < 3) continue;
    brush.set("cyan_razor", PALETTE.cyanEdge, 0.75);
    let p0 = ov.poly[0];
    let p1 = ov.poly[floor(ov.poly.length * 0.5)];
    brush.line(p0[0], p0[1], p1[0], p1[1]);

    if (i % 2 === 0) {
      brush.set("knife_glint", PALETTE.whitePure, 0.65);
      let p2 = ov.poly[1 % ov.poly.length];
      brush.line(p0[0] + 2, p0[1] - 2, p2[0] + 2, p2[1] - 2);
    }
  }

  // Render each candy's linear & specular details sorted by tier
  for (let i = 0; i < candies.length; i++) {
    let c = candies[i];
    renderSingleCandyStrokes(c);
  }
}

function renderSingleCandyStrokes(c) {
  let deepColors = [PALETTE.raspDeep, PALETTE.limeDeep, PALETTE.buttDeep];
  let richColors = [PALETTE.raspRich, PALETTE.limeRich, PALETTE.buttRich];
  let glowColors = [PALETTE.raspGlow, PALETTE.limeGlow, PALETTE.buttGlow];

  let deepCol = deepColors[c.flavor];
  let richCol = richColors[c.flavor];
  let glowCol = glowColors[c.flavor];

  // Border-dissolve candies get subtle, dreamy hints of hairlines and glints
  if (c.tier === 0) {
    for (let fan of c.fans) {
      brush.set("hairline_pen", richCol, 0.65);
      for (let h = 0; h < fan.hairlines.length; h += 2) {
        brush.spline(fan.hairlines[h].pts, 0.35);
      }
      brush.set("cyan_razor", PALETTE.cyanBright, 0.65);
      brush.spline(fan.hairlines[0].pts, 0.3);
    }
    brush.set("knife_glint", PALETTE.whitePure, 0.6);
    brush.spline(c.creases[0].glintPts, 0.35);
    return;
  }

  let weightScale = c.tier === 2 ? 1.05 : 0.82;

  // 1. Colored pencil optical rim refraction around the hard candy core
  brush.set("cpencil", deepCol, 0.9 * weightScale);
  let rimArcPts = [];
  for (let k = 0; k <= 8; k++) {
    let idx = floor(map(k, 0, 8, 1, c.corePts.length * 0.55));
    rimArcPts.push(c.corePts[idx % c.corePts.length]);
  }
  brush.spline(rimArcPts, 0.4);

  // Opposite warm caustic rim
  brush.set("cpencil", glowCol, 0.85 * weightScale);
  let litArcPts = [];
  for (let k = 0; k <= 6; k++) {
    let idx = floor(map(k, 0, 6, c.corePts.length * 0.58, c.corePts.length * 0.92));
    litArcPts.push(c.corePts[idx % c.corePts.length]);
  }
  brush.spline(litArcPts, 0.4);

  // 2. Twisted Ends: Fine pen hairlines fanning out + knot tension lines + jagged rim
  for (let fan of c.fans) {
    // Spiral twist knot dark refraction strokes at the pinched throat
    brush.set("rotring", deepCol, 0.75 * weightScale);
    let nw = fan.neckWorld;
    for (let k = -2; k <= 2; k++) {
      let pA = toWorld(
        c.cx,
        c.cy,
        c.cosA,
        c.sinA,
        fan.side * c.rx * (1.0 + k * 0.04),
        -c.ry * 0.18
      );
      let pB = toWorld(
        c.cx,
        c.cy,
        c.cosA,
        c.sinA,
        fan.side * c.rx * (1.08 + k * 0.04),
        c.ry * 0.18
      );
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }

    // Fanning pen hairlines
    for (let h = 0; h < fan.hairlines.length; h++) {
      let hl = fan.hairlines[h];
      if (hl.isCyan) {
        brush.set("cyan_razor", PALETTE.cyanEdge, 0.75 * weightScale);
      } else {
        brush.set("hairline_pen", h % 2 === 0 ? richCol : deepCol, 0.85 * weightScale);
      }
      brush.spline(hl.pts, 0.35);
    }

    // Pleat ridge cyan reflections & white razor glints
    for (let p = 0; p < fan.pleats.length; p++) {
      let pleat = fan.pleats[p];
      let r0 = pleat.ridgeLine[0];
      let r1 = pleat.ridgeLine[1];

      // Cool cyan edge reflection along every pleat crease
      brush.set("cyan_razor", PALETTE.cyanEdge, 0.85 * weightScale);
      brush.line(r0[0], r0[1] + 2.2, r1[0], r1[1] + 2.2);

      // Knife-thin white marker glint right on the ridge
      brush.set("knife_glint", PALETTE.whitePure, 0.82 * weightScale);
      brush.line(r0[0], r0[1], r1[0], r1[1]);
    }

    // Cut cellophane outer serrated edge reflection (cyan + white)
    for (let r = 0; r < fan.outerRimPts.length - 1; r++) {
      let pa = fan.outerRimPts[r];
      let pb = fan.outerRimPts[r + 1];
      brush.set("cyan_razor", PALETTE.cyanBright, 0.7 * weightScale);
      brush.line(pa[0] + 1.8, pa[1] + 1.8, pb[0] + 1.8, pb[1] + 1.8);
      if (r % 2 === 0) {
        brush.set("knife_glint", PALETTE.whitePure, 0.72 * weightScale);
        brush.line(pa[0], pa[1], pb[0], pb[1]);
      }
    }

    // Bright white twist-knot specular cross-glints
    brush.set("knife_glint", PALETTE.whitePure, 1.05 * weightScale);
    brush.line(nw[0] - 10, nw[1] - 8, nw[0] + 12, nw[1] + 6);
    brush.line(nw[0] - 6, nw[1] + 10, nw[0] + 9, nw[1] - 9);
  }

  // 3. Outer crinkled cellophane contour around the core (cyan edge + white glint segments)
  for (let k = 0; k < c.celloBodyPts.length; k++) {
    let pA = c.celloBodyPts[k];
    let pB = c.celloBodyPts[(k + 1) % c.celloBodyPts.length];
    brush.set("cyan_razor", PALETTE.cyanEdge, 0.8 * weightScale);
    brush.line(pA[0], pA[1], pB[0], pB[1]);

    if (k % 2 === 0) {
      brush.set("knife_glint", PALETTE.whitePure, 0.75 * weightScale);
      brush.line(pA[0] - 1.5, pA[1] - 1.5, pB[0] - 1.5, pB[1] - 1.5);
    }
  }

  // 4. Diagonal cellophane tension creases across the candy dome
  for (let cr = 0; cr < c.creases.length; cr++) {
    let crease = c.creases[cr];

    // Dark chromatic refraction shadow immediately under the crease
    brush.set("hairline_pen", deepCol, 0.85 * weightScale);
    let shadowPts = crease.glintPts.map((pt) => [pt[0] + 2.2, pt[1] + 2.8]);
    brush.spline(shadowPts, 0.38);

    // Cool cyan edge reflection hugging the crease
    brush.set("cyan_razor", PALETTE.cyanEdge, 1.0 * weightScale);
    brush.spline(crease.cyanPts, 0.38);

    // Slick marker sheen along the crease
    if (cr < 2) {
      brush.set("slick_sheen", PALETTE.cyanSoft, 0.9 * weightScale);
      brush.spline(crease.cyanPts, 0.35);
    }

    // Knife-thin white marker glint slicing along the crest of the crease
    brush.set("knife_glint", PALETTE.whitePure, (cr === 1 ? 1.25 : 0.95) * weightScale);
    brush.spline(crease.glintPts, 0.38);
  }

  // 5. Dazzling curved glossy sugar-dome window highlight & secondary catchlights
  let domeRibbon = [];
  for (let i = 0; i <= 5; i++) {
    let a = -95 - c.angle + i * 16;
    domeRibbon.push(toWorld(c.cx, c.cy, c.cosA, c.sinA, cos(a) * c.rx * 0.63, sin(a) * c.ry * 0.63));
  }
  brush.set("slick_sheen", PALETTE.cyanBright, 1.15 * weightScale);
  brush.spline(
    domeRibbon.map((p) => [p[0] + 3, p[1] + 3]),
    0.45
  );

  brush.set("slick_sheen", PALETTE.whitePure, 1.35 * weightScale);
  brush.spline(domeRibbon, 0.45);

  brush.set("knife_glint", PALETTE.whitePure, 1.3 * weightScale);
  brush.spline(domeRibbon, 0.45);

  // Secondary lower-right rim reflection inside the glassy core
  let rimGlint = [];
  for (let i = 0; i <= 4; i++) {
    let a = 45 - c.angle + i * 15;
    rimGlint.push(toWorld(c.cx, c.cy, c.cosA, c.sinA, cos(a) * c.rx * 0.72, sin(a) * c.ry * 0.72));
  }
  brush.set("cyan_razor", PALETTE.cyanBright, 0.95 * weightScale);
  brush.spline(rimGlint, 0.4);
  brush.set("knife_glint", PALETTE.whitePure, 0.8 * weightScale);
  brush.spline(rimGlint.slice(1, 4), 0.4);
}

function renderFinalSurfaceGlints() {
  // High-intensity micro-glints & crisp star-like crinkle vertices on foreground candies
  for (let i = 0; i < candies.length; i++) {
    let c = candies[i];
    if (c.tier < 2) continue;

    // Sharp triangular specular shards where creases intersect over the dome
    let shardCenter = toWorld(c.cx, c.cy, c.cosA, c.sinA, -c.rx * 0.22, -c.ry * 0.24);
    brush.noStroke();
    brush.wash(PALETTE.whitePure, 185);
    drawPoly(
      [
        [shardCenter[0] - 14, shardCenter[1] + 4],
        [shardCenter[0] + 8, shardCenter[1] - 12],
        [shardCenter[0] + 18, shardCenter[1] - 2],
        [shardCenter[0] - 2, shardCenter[1] + 9]
      ],
      0.02
    );
    brush.noWash();

    // Razor-sharp cross glints at the brightest crinkle apexes
    brush.set("knife_glint", PALETTE.whitePure, 1.15);
    brush.line(shardCenter[0] - 18, shardCenter[1] + 6, shardCenter[0] + 22, shardCenter[1] - 8);
    brush.line(shardCenter[0] - 5, shardCenter[1] - 14, shardCenter[0] + 7, shardCenter[1] + 14);
  }
}

// Hyperrealism: Open Bakery Box of Glazed Doughnuts on a Curling Thermal Till Receipt
// Rendered via warm-grey pen stipple, staggered dithered dot rows, and soft pastel receipt washes

const SEED = 48291;

// Receipt geometry constants (in 1200x1200 canvas space)
const REC_CX = 600;
const REC_HALF_W = 294; // width = 588px (306..894)
const REC_TOP = 58;
const REC_BOT = 1134;

// Graphic window on receipt (the open bakery box top-down view)
const IMG_U1 = 334;
const IMG_U2 = 866;
const IMG_V1 = 166;
const IMG_V2 = 964;

// Inner cardboard cavity of the bakery box
const BOX_U1 = 384;
const BOX_U2 = 816;
const BOX_V1 = 250;
const BOX_V2 = 888;

let doughnuts = [];
let crumbs = [];
let weakHeadCols = [];
let bandDropouts = [];

// Fast deterministic 2D hash in [0, 1)
function hash2(x, y) {
  let n = Math.sin(x * 127.1 + y * 311.7 + 74.7) * 43758.5453123;
  return n - Math.floor(n);
}

// Smooth value noise
function vnoise(x, y) {
  let ix = Math.floor(x);
  let iy = Math.floor(y);
  let fx = x - ix;
  let fy = y - iy;
  let ux = fx * fx * (3.0 - 2.0 * fx);
  let uy = fy * fy * (3.0 - 2.0 * fy);
  let a = hash2(ix, iy);
  let b = hash2(ix + 1, iy);
  let c = hash2(ix, iy + 1);
  let d = hash2(ix + 1, iy + 1);
  return a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
}

// 3-octave FBM
function fbm(x, y) {
  return (
    0.55 * vnoise(x, y) +
    0.30 * vnoise(x * 2.07 + 13.1, y * 2.07 + 7.9) +
    0.15 * vnoise(x * 4.19 + 29.4, y * 4.19 + 19.3)
  );
}

// Cellular Voronoi crackle for torn sugar crust (returns [f1, f2, cellId, dx1, dy1])
function voronoiCrackle(x, y) {
  let ix = Math.floor(x);
  let iy = Math.floor(y);
  let fx = x - ix;
  let fy = y - iy;
  let f1 = 10.0;
  let f2 = 10.0;
  let cid = 0;
  let bestDx = 0;
  let bestDy = 0;

  for (let j = -1; j <= 1; j++) {
    for (let i = -1; i <= 1; i++) {
      let cx = ix + i;
      let cy = iy + j;
      let rx = i - fx + 0.15 + 0.7 * hash2(cx, cy);
      let ry = j - fy + 0.15 + 0.7 * hash2(cx + 59.0, cy + 103.0);
      let d = Math.sqrt(rx * rx + ry * ry);
      if (d < f1) {
        f2 = f1;
        f1 = d;
        cid = hash2(cx * 3.1, cy * 7.7);
        bestDx = rx;
        bestDy = ry;
      } else if (d < f2) {
        f2 = d;
      }
    }
  }
  return [f1, f2, cid, bestDx, bestDy];
}

// Map flat receipt coordinates (u, v) -> curled 3D projection on canvas (x, y)
function paperX(u, v) {
  let s = (u - REC_CX) / REC_HALF_W; // -1..1
  let wave = 6.8 * Math.sin((v - 90) * 0.0051) - 3.6 * Math.cos((v - 120) * 0.0089);
  // Subtle flare at curled top and bottom edges
  let topDist = Math.max(0, 1.0 - (v - REC_TOP) / 140.0);
  let botDist = Math.max(0, 1.0 - (REC_BOT - v) / 150.0);
  let flare = s * (topDist * topDist * 4.5 + botDist * botDist * 6.2);
  return u + wave + flare;
}

function paperY(u, v) {
  let s = (u - REC_CX) / REC_HALF_W; // -1..1
  let arch = 1.0 - s * s;
  // Curling upward at top and bottom, plus subtle horizontal buckle waves
  let curlWave =
    -8.5 * arch * Math.cos((v - REC_TOP) * 0.0056) +
    2.8 * s * Math.sin((v - 200) * 0.0042);
  // Right-bottom corner slight diagonal droop before tear
  let cornerPull = s > 0.3 && v > 1020 ? (s - 0.3) * ((v - 1020) / 114) * 9.5 : 0;
  return v + curlWave + cornerPull;
}

// Top serrated edge v-offset as a function of u
function topSerratedV(u) {
  let pitch = 10.5;
  let phase = ((u - (REC_CX - REC_HALF_W)) % pitch) / pitch;
  let tri = 1.0 - Math.abs(2.0 * phase - 1.0); // 0..1 tooth
  let jitter = (vnoise(u * 0.15, 1.7) - 0.5) * 1.8;
  return REC_TOP + tri * 5.8 + jitter;
}

// Bottom torn serrated edge v-offset as a function of u
function botSerratedV(u) {
  let pitch = 10.8;
  let phase = ((u - (REC_CX - REC_HALF_W)) % pitch) / pitch;
  let tri = 1.0 - Math.abs(2.0 * phase - 1.0);
  let jitter = (vnoise(u * 0.18, 91.3) - 0.5) * 2.2;
  // Authentic diagonal paper tear near right edge where receipt ripped off the teeth
  let tearJump = 0;
  if (u > 775) {
    let t = (u - 775) / (REC_CX + REC_HALF_W - 775);
    tearJump = -t * t * 22.0 + (fbm(u * 0.12, 44.1) - 0.5) * 7.5;
    tri *= Math.max(0.15, 1.0 - t * 1.1);
  }
  return REC_BOT - tri * 8.2 + jitter + tearJump;
}

