// Thermal aging fade + horizontal banding multiplier at receipt coordinate (u, v)
function getThermalAttenuation(u, v) {
  // Normalized horizontal position across the receipt (0 at left, 1 at right)
  let nu = (u - (REC_CX - REC_HALF_W)) / (REC_HALF_W * 2);

  // Uneven chemical fade toward the right edge (and upper/lower right corners)
  let blotch =
    0.6 * fbm(u * 0.0055, v * 0.0042) +
    0.4 * vnoise(u * 0.016, v * 0.011);

  let rightFade = 1.0;
  let fadeStart = 0.44 - blotch * 0.16;
  if (nu > fadeStart) {
    let t = (nu - fadeStart) / (1.0 - fadeStart);
    rightFade = Math.max(0.08, 1.0 - Math.pow(t, 1.32) * (0.78 + 0.18 * (1.0 - blotch)));
  }

  // Slight fade near the very top and bottom edges of the receipt
  let edgeV = 1.0;
  if (v < 115) edgeV *= 0.65 + 0.35 * ((v - REC_TOP) / (115 - REC_TOP));
  if (v > 1075) edgeV *= 0.60 + 0.40 * ((REC_BOT - v) / (REC_BOT - 1075));

  // Periodic + noisy horizontal thermal printhead banding
  let fineBand = 1.0 - 0.055 * (0.5 + 0.5 * Math.sin(v * 0.44 + vnoise(u * 0.01, v * 0.08) * 1.6));
  let medBand = 1.0 - 0.085 * (0.5 + 0.5 * Math.sin(v * 0.092 + fbm(1.3, v * 0.015) * 3.5));
  let coarseBand = 0.92 + 0.11 * fbm(u * 0.003, v * 0.028);

  // Sharp horizontal step-motor feed dropouts
  let dropout = 1.0;
  for (let i = 0; i < bandDropouts.length; i++) {
    let dv = Math.abs(v - bandDropouts[i] - Math.sin(u * 0.012) * 1.4);
    if (dv < 3.2) {
      dropout *= 0.52 + 0.48 * (dv / 3.2);
    }
  }

  // Vertical weak printhead element streaks
  let headStreak = 1.0;
  for (let i = 0; i < weakHeadCols.length; i++) {
    let du = Math.abs(u - weakHeadCols[i]);
    if (du < 1.65) {
      headStreak *= 0.38 + 0.62 * (du / 1.65);
    }
  }

  return Math.max(0.05, Math.min(1.05, rightFade * edgeV * fineBand * medBand * coarseBand * dropout * headStreak));
}

// Evaluate hyperrealistic scene at receipt coordinate (u, v)
// Returns { dark: 0..1, spec: 0..1, crustEdge: 0..1, inHole: bool, onDoughnut: bool }
function evalBakeryScene(u, v) {
  // Light vector (overhead upper-left bakery window + soft right fill)
  const lx1 = -0.37, ly1 = -0.45, lz1 = 0.812;
  const hx1 = -0.21, hy1 = -0.25, hz1 = 0.945; // half-vector for primary wet specular
  const hx2 = 0.28, hy2 = 0.22, hz2 = 0.934;   // secondary rim bounce

  // 1. Check if (u, v) falls on or inside one of the 6 doughnuts
  let bestD = null;
  let bestSignedTube = 999;

  for (let i = 0; i < 6; i++) {
    let d = doughnuts[i];
    if (Math.abs(u - d.u) > 132 || Math.abs(v - d.v) > 132) continue;

    let du = (u - d.u) * d.eccX;
    let dv = (v - d.v) * d.eccY;
    let r = Math.sqrt(du * du + dv * dv);
    let theta = Math.atan2(dv, du) - d.rot;

    // Organic yeast proofing lobes around circumference
    let lobe =
      2.6 * Math.sin(theta * 5.0 + d.id * 1.7) +
      1.8 * Math.cos(theta * 3.0 - d.id * 2.3) +
      1.1 * Math.sin(theta * 8.0 + 0.9);

    let R_loc = d.R + lobe * 0.65;
    let rt_loc = d.rt + lobe * 0.45;

    if (d.style === "old_fashioned") {
      // Deep clefts and craggy petals on the old-fashioned glazed doughnut (#3)
      let petal = Math.sin(theta * 6.0) * 4.2 + Math.cos(theta * 12.0 + 0.6) * 2.4;
      R_loc += petal * 0.45;
      rt_loc += petal * 0.75;
    }

    // Contact squish against neighboring doughnuts and cardboard box walls
    let squish = 0;
    let contactCrease = 0;
    for (let j = 0; j < 6; j++) {
      if (i === j) continue;
      let nb = doughnuts[j];
      letvx = nb.u - d.u;
      letvy = nb.v - d.v;
      let distCenters = Math.sqrt(letvx * letvx + letvy * letvy);
      if (distCenters < 235) {
        let dirX = letvx / distCenters;
        let dirY = letvy / distCenters;
        let proj = (u - d.u) * dirX + (v - d.v) * dirY;
        let halfGap = distCenters * 0.5;
        if (proj > halfGap - 18) {
          let pen = Math.max(0, proj - (halfGap - 14));
          squish += pen * 0.62;
          contactCrease = Math.max(contactCrease, Math.min(1.0, pen / 14.0));
        }
      }
    }

    // Box wall compression
    if (u - BOX_U1 < 24 && u < d.u) squish += Math.max(0, 18 - (u - BOX_U1)) * 0.55;
    if (BOX_U2 - u < 24 && u > d.u) squish += Math.max(0, 18 - (BOX_U2 - u)) * 0.55;
    if (v - BOX_V1 < 24 && v < d.v) squish += Math.max(0, 18 - (v - BOX_V1)) * 0.55;
    if (BOX_V2 - v < 24 && v > d.v) squish += Math.max(0, 18 - (BOX_V2 - v)) * 0.55;

    let outerR = R_loc + rt_loc - squish;
    let innerR = Math.max(14.5, (R_loc - rt_loc * d.holePinch));

    if (r <= outerR) {
      bestD = {
        d,
        du,
        dv,
        r,
        theta,
        R_loc,
        rt_loc,
        outerR,
        innerR,
        contactCrease
      };
      break;
    } else if (r - outerR < bestSignedTube) {
      bestSignedTube = r - outerR;
    }
  }

  // If point is inside a doughnut's outer perimeter (either on the ring or inside the central hole)
  if (bestD !== null) {
    let { d, du, dv, r, theta, R_loc, outerR, innerR, contactCrease } = bestD;

    // CASE A: Inside the central dough hole! ("densest in the shadows of the dough holes")
    if (r < innerR) {
      let holeNorm = r / innerR; // 0 at center, 1 at inner dough wall
      // Overhanging doughnut rim casts a deep shadow from upper-left (-0.37, -0.45)
      let shadowShiftX = du - 8.5;
      let shadowShiftY = dv - 10.0;
      let shadowR = Math.sqrt(shadowShiftX * shadowShiftX + shadowShiftY * shadowShiftY) / innerR;

      // Deep velvety shadow under the rim + grease-stained dark floor
      let holeDark = 0.80 + 0.16 * Math.pow(holeNorm, 1.3);
      if (shadowR > 0.42) {
        holeDark = Math.min(0.98, holeDark + 0.14 * ((shadowR - 0.42) / 0.58));
      } else {
        // Tiny crescent of dimly lit grease-stained floor on lower-right of hole
        let grain = fbm(u * 0.18, v * 0.18);
        holeDark = 0.72 + 0.12 * grain;
      }

      // Glaze bead droplets pooled at the bottom of the dough hole
      let dripAng = Math.sin(theta * 7.0 + d.id * 2.1);
      let isHoleDrip = holeNorm > 0.68 && dripAng > 0.45;
      let holeSpec = 0;
      if (isHoleDrip && du > 0 && dv > 0) {
        holeSpec = 0.55;
        holeDark *= 0.45;
      }

      return {
        dark: Math.min(0.99, holeDark),
        spec: holeSpec,
        crustEdge: holeNorm > 0.82 ? 0.65 : 0.2,
        inHole: true,
        onDoughnut: false
      };
    }

    // CASE B: On the 3D Glazed Doughnut Ring (innerR <= r <= outerR)
    let midR = 0.5 * (innerR + outerR);
    let halfTube = 0.5 * (outerR - innerR);
    let s = (r - midR) / Math.max(1.0, halfTube); // -1 at inner hole lip, 0 at crest, +1 at outer edge
    s = Math.max(-0.995, Math.min(0.995, s));

    // Base 3D torus normal
    let radialX = r > 0.001 ? du / r : 1.0;
    let radialY = r > 0.001 ? dv / r : 0.0;
    let nz = Math.sqrt(Math.max(0.02, 1.0 - s * s));
    let nx = s * radialX;
    let ny = s * radialY;

    // Surface coordinates along and across the torus ring
    let su = theta * d.R;
    let sv = s * 46.0;

    // Glaze ripples & syrupy drips flowing down the inner and outer slopes
    let dripWave =
      Math.sin(theta * 11.0 + d.id * 1.9 + fbm(su * 0.04, sv * 0.04) * 2.8) * 0.5 +
      Math.cos(theta * 19.0 - sv * 0.08) * 0.5;
    let dripRidge = Math.max(0, dripWave - 0.15) * (0.35 + 0.65 * Math.abs(s)) * d.glazePool;

    // Old-fashioned doughnut deep radial clefts
    let cleftDepth = 0;
    if (d.style === "old_fashioned") {
      let cWave = Math.sin(theta * 6.0 + fbm(u * 0.05, v * 0.05) * 1.8);
      let cWave2 = Math.cos(theta * 13.0 - s * 2.5);
      if (cWave < -0.25 && Math.abs(s) < 0.78) {
        cleftDepth = Math.min(1.0, (-0.25 - cWave) * 1.8);
      }
      nx += 0.22 * cWave2 * (-radialY);
      ny += 0.22 * cWave2 * radialX;
    }

    // Perturb normal with glaze ripples and yeast bumps
    let bumpX = (vnoise(u * 0.09 + 1.2, v * 0.09) - 0.5) * 0.18;
    let bumpY = (vnoise(u * 0.09, v * 0.09 + 1.2) - 0.5) * 0.18;
    nx += bumpX + dripRidge * 0.14 * (-radialY);
    ny += bumpY + dripRidge * 0.14 * radialX;
    let nLen = Math.sqrt(nx * nx + ny * ny + nz * nz);
    nx /= nLen;
    ny /= nLen;
    nz /= nLen;

    // TORN SUGAR CRUST & CRYSTALLINE FRACTURES
    let [f1, f2, cid, cdx, cdy] = voronoiCrackle(su * 0.068 + d.id * 7.1, sv * 0.082 + d.id * 3.7);
    let [f1b, f2b] = voronoiCrackle(su * 0.155 + 19.3, sv * 0.175 + 41.2);
    let crackDist = f2 - f1;
    let fineCrackDist = f2b - f1b;

    // Patch mask determines where the sugar glaze shattered/flaked vs remained glassy smooth
    let crustMask = fbm(su * 0.025 + d.id * 5.0, sv * 0.032) + (d.style === "flaky_crust" ? 0.16 : 0) + (d.style === "old_fashioned" ? 0.22 : 0);

    let inFissure = false;
    let onFlakeEdgeBright = false;
    let onFlakeEdgeDark = false;
    let isSugarPlate = false;
    let crustEdgeStrength = 0;

    let crackThresh = d.style === "glossy_web" ? 0.075 : 0.115;
    if (crustMask > 0.42 && Math.abs(s) < 0.88) {
      if (crackDist < crackThresh) {
        // Inside a torn sugar fissure: exposed porous fried dough!
        inFissure = true;
        crustEdgeStrength = 0.85;
      } else if (crackDist < crackThresh + 0.065) {
        // The sharp broken edge of a torn sugar crust flake!
        crustEdgeStrength = 0.95;
        let edgeLight = cdx * lx1 + cdy * ly1;
        if (edgeLight > 0) {
          onFlakeEdgeBright = true;
        } else {
          onFlakeEdgeDark = true;
        }
      } else if (cid > 0.48 && crustMask > 0.54) {
        // Raised milky crystalline sugar crust island
        isSugarPlate = true;
      }
    }

    // Secondary fine spiderweb crackle lines in the glaze
    let inFineCrackle = fineCrackDist < 0.045 && crustMask > 0.34 && Math.abs(s) < 0.82;
    if (inFineCrackle) {
      crustEdgeStrength = Math.max(crustEdgeStrength, 0.65);
    }

    // Lighting computation
    let ndotl = Math.max(0, nx * lx1 + ny * ly1 + nz * lz1);
    let fillDot = Math.max(0, nx * 0.35 + ny * 0.30 + nz * 0.88);

    // Base glazed dough tone (0 = pure pale paper, 1 = deepest shadow)
    // Doughnuts have warm golden midtones and rapid darkening toward the hole (-1) and outer underside (+1)
    let rimDarken = Math.pow(Math.abs(s), 1.65) * 0.34;
    let holeSlopeDarken = s < -0.25 ? Math.pow((-s - 0.25) / 0.75, 1.35) * 0.48 : 0;

    // Pale "fry line" band along outer equator of yeast doughnuts
    let fryBand = s > 0.58 && s < 0.86 ? -0.07 * Math.sin(((s - 0.58) / 0.28) * Math.PI) : 0;

    let baseDark =
      0.56 -
      0.38 * ndotl -
      0.10 * fillDot +
      rimDarken +
      holeSlopeDarken +
      fryBand;

    // Apply torn sugar crust physics
    if (inFissure || cleftDepth > 0.15) {
      // Exposed matte fried dough inside crack/cleft: darker + grainy porous stipple
      let doughPores = vnoise(u * 0.42, v * 0.42) * 0.18 + vnoise(u * 0.18, v * 0.18) * 0.12;
      baseDark += 0.22 + cleftDepth * 0.24 + doughPores;
    } else if (onFlakeEdgeBright) {
      // Razor-sharp crystalline catch-light on torn sugar edge
      baseDark -= 0.28;
    } else if (onFlakeEdgeDark) {
      // Sharp undercut shadow beneath lifted sugar flake
      baseDark += 0.26;
    } else if (isSugarPlate) {
      // Milky semi-opaque crystallized sugar crust plateau
      let crystalGrain = (vnoise(u * 0.35, v * 0.35) - 0.5) * 0.08;
      baseDark = baseDark * 0.74 - 0.06 + crystalGrain;
    }

    if (inFineCrackle) {
      // Hairline crackle in glaze: dark hairline paired with faint bright ridge
      baseDark += (cdx + cdy > 0 ? 0.14 : -0.10);
    }

    // Syrupy glaze drip meniscus shading
    if (dripRidge > 0.08 && !inFissure) {
      let dripGrad = Math.cos(theta * 11.0 + d.id * 1.9);
      baseDark += dripGrad > 0 ? -0.09 * dripRidge : 0.13 * dripRidge;
      crustEdgeStrength = Math.max(crustEdgeStrength, 0.45 * dripRidge);
    }

    // STICKY WET SHEEN (Specular Highlights + Dark Meniscus Refraction Rim)
    let spec1 = Math.pow(Math.max(0, nx * hx1 + ny * hy1 + nz * hz1), 34.0);
    let spec2 = Math.pow(Math.max(0, nx * hx2 + ny * hy2 + nz * hz2), 42.0) * (s < -0.15 ? 0.85 : 0.35);

    // Modulate specular with organic glaze waves so highlights form liquid ribbons & beads
    let specMod = 0.72 + 0.45 * fbm(u * 0.055, v * 0.055) + 0.25 * dripRidge;
    let totalSpec = (spec1 + spec2 * 0.75) * specMod;

    let finalSpec = 0;
    if (!inFissure && cleftDepth < 0.25) {
      if (totalSpec > 0.36) {
        // Inside sticky wet specular highlight: pure pale receipt paper!
        finalSpec = Math.min(1.0, (totalSpec - 0.36) / 0.35);
        baseDark *= Math.max(0.0, 1.0 - finalSpec * 1.25);
      } else if (totalSpec > 0.22) {
        // Optical caustic / meniscus dark rim right around the wet highlight!
        baseDark += 0.13 * (1.0 - Math.abs(totalSpec - 0.29) / 0.07);
        crustEdgeStrength = Math.max(crustEdgeStrength, 0.75);
      }
    }

    if (onFlakeEdgeBright) {
      finalSpec = Math.max(finalSpec, 0.78);
    }

    // Contact shadow crease where doughnuts squish together or against box walls
    if (contactCrease > 0) {
      baseDark += contactCrease * 0.34;
      finalSpec *= 1.0 - contactCrease;
    }

    return {
      dark: Math.max(0.0, Math.min(0.96, baseDark)),
      spec: finalSpec,
      crustEdge: crustEdgeStrength,
      inHole: false,
      onDoughnut: true
    };
  }

  // 2. Outside the doughnuts: Inside the Open Cardboard Bakery Box cavity or on the Box Flaps
  let inBoxTray = u >= BOX_U1 && u <= BOX_U2 && v >= BOX_V1 && v <= BOX_V2;

  if (inBoxTray) {
    // Cardboard tray floor visible between doughnuts and in corners
    let cardGrain = 0.06 * vnoise(u * 0.04, v * 0.35) + 0.05 * fbm(u * 0.08, v * 0.08);
    let trayDark = 0.24 + cardGrain;

    // Diagonal corner fold lines on the bottom of the bakery box
    let dCornerTL = Math.abs((u - BOX_U1) - (v - BOX_V1));
    let dCornerTR = Math.abs((BOX_U2 - u) - (v - BOX_V1));
    let dCornerBL = Math.abs((u - BOX_U1) - (BOX_V2 - v));
    let dCornerBR = Math.abs((BOX_U2 - u) - (BOX_V2 - v));
    if (
      (dCornerTL < 2.2 && u - BOX_U1 < 75) ||
      (dCornerTR < 2.2 && BOX_U2 - u < 75) ||
      (dCornerBL < 2.2 && u - BOX_U1 < 75) ||
      (dCornerBR < 2.2 && BOX_U2 - u < 75)
    ) {
      trayDark += 0.22;
    }

    // Cast shadows and translucent grease haloes from the 6 doughnuts onto the cardboard floor
    let castShadow = 0;
    let greaseStain = 0;

    for (let i = 0; i < 6; i++) {
      let d = doughnuts[i];
      // Offset shadow center to lower-right (+13, +16)
      let sdu = (u - (d.u + 13.5)) * d.eccX;
      let sdv = (v - (d.v + 16.0)) * d.eccY;
      let sr = Math.sqrt(sdu * sdu + sdv * sdv);
      let sMax = d.R + d.rt;
      if (sr < sMax + 18) {
        let pen = Math.max(0, 1.0 - Math.max(0, sr - (sMax - 6)) / 24.0);
        castShadow = Math.max(castShadow, pen * 0.62);
      }

      // Grease ring halo around each doughnut base
      let gdu = u - d.u;
      let gdv = v - d.v;
      let gr = Math.sqrt(gdu * gdu + gdv * gdv) - (d.R + d.rt);
      let gMax = 26.0 + 14.0 * fbm(u * 0.06, v * 0.06);
      if (gr > -4 && gr < gMax) {
        let gFactor = 1.0 - gr / gMax;
        greaseStain = Math.max(greaseStain, gFactor * 0.21);
        // Slightly darker outer meniscus edge of grease stain
        if (Math.abs(gr - gMax * 0.82) < 3.0) {
          greaseStain += 0.07;
        }
      }
    }

    // Cast shadows from the left and top cardboard box walls onto the tray interior
    let wallShadowL = u - BOX_U1 < 28 ? (1.0 - (u - BOX_U1) / 28.0) * 0.42 : 0;
    let wallShadowT = v - BOX_V1 < 32 ? (1.0 - (v - BOX_V1) / 32.0) * 0.45 : 0;
    let wallAO_R = BOX_U2 - u < 14 ? (1.0 - (BOX_U2 - u) / 14.0) * 0.25 : 0;
    let wallAO_B = BOX_V2 - v < 14 ? (1.0 - (BOX_V2 - v) / 14.0) * 0.25 : 0;

    trayDark += Math.max(castShadow, wallShadowL + wallShadowT * 0.7) + greaseStain + wallAO_R + wallAO_B;

    // Fallen sugar crust flakes & crumbs on the box floor
    let crumbEdge = 0;
    for (let i = 0; i < crumbs.length; i++) {
      let c = crumbs[i];
      let cdu = u - c.u;
      let cdv = v - c.v;
      let cr = Math.sqrt(cdu * cdu + cdv * cdv);
      if (cr < c.r) {
        trayDark = c.isSugar ? 0.08 : 0.58;
        crumbEdge = 0.8;
        break;
      } else if (cr < c.r + 2.5 && cdu > 0 && cdv > 0) {
        trayDark += 0.24; // tiny cast shadow under crumb
        crumbEdge = 0.6;
      }
    }

    return {
      dark: Math.min(0.95, trayDark),
      spec: 0,
      crustEdge: crumbEdge,
      inHole: false,
      onDoughnut: false
    };
  }

  // 3. Cardboard Box Walls, Folded Flaps & Corner Locks (outside the inner tray)
  let cardTex = 0.05 * vnoise(u * 0.25, v * 0.05) + 0.04 * fbm(u * 0.07, v * 0.07);

  // Bowed outward left and right side walls
  let midBowL = 7.5 * Math.sin(((v - BOX_V1) / (BOX_V2 - BOX_V1)) * Math.PI);
  let flapL_outer = 342 - midBowL;
  let flapR_outer = 858 + midBowL;

  // Inner box wall thickness rim (bevel of double-folded cardboard, ~8px wide)
  let onRimL = u >= BOX_U1 - 8 && u < BOX_U1 && v >= BOX_V1 - 6 && v <= BOX_V2 + 6;
  let onRimR = u > BOX_U2 && u <= BOX_U2 + 8 && v >= BOX_V1 - 6 && v <= BOX_V2 + 6;
  let onRimT = v >= BOX_V1 - 8 && v < BOX_V1 && u >= BOX_U1 - 6 && u <= BOX_U2 + 6;
  let onRimB = v > BOX_V2 && v <= BOX_V2 + 8 && u >= BOX_U1 - 6 && u <= BOX_U2 + 6;

  if (onRimL || onRimR || onRimT || onRimB) {
    // Crisp bright cardboard fold lip + dark score crease line
    let isScoreEdge =
      Math.abs(u - BOX_U1) < 1.8 ||
      Math.abs(u - BOX_U2) < 1.8 ||
      Math.abs(v - BOX_V1) < 1.8 ||
      Math.abs(v - BOX_V2) < 1.8 ||
      Math.abs(u - (BOX_U1 - 8)) < 1.6 ||
      Math.abs(u - (BOX_U2 + 8)) < 1.6 ||
      Math.abs(v - (BOX_V1 - 8)) < 1.6 ||
      Math.abs(v - (BOX_V2 + 8)) < 1.6;
    return {
      dark: isScoreEdge ? 0.62 : 0.11 + cardTex,
      spec: isScoreEdge ? 0 : 0.35,
      crustEdge: isScoreEdge ? 0.85 : 0.1,
      inHole: false,
      onDoughnut: false
    };
  }

  // Open Top Lid Flap (v in [170..242])
  if (v >= 170 && v < BOX_V1 - 8) {
    let t = (BOX_V1 - 8 - v) / (BOX_V1 - 8 - 170); // 0 at hinge, 1 at top edge
    let lidLeft = BOX_U1 - 14 + t * 18;
    let lidRight = BOX_U2 + 14 - t * 18;
    // Tuck tab notch at very top
    if (v < 192) {
      lidLeft += 42;
      lidRight -= 42;
    }
    if (u >= lidLeft && u <= lidRight) {
      let onBorder =
        Math.abs(u - lidLeft) < 2.2 ||
        Math.abs(u - lidRight) < 2.2 ||
        Math.abs(v - 170) < 2.2 ||
        Math.abs(v - 192) < 1.8;
      let lidTone = 0.19 + t * 0.11 + cardTex + (u > 600 ? 0.05 : -0.02);
      return {
        dark: onBorder ? 0.64 : lidTone,
        spec: 0,
        crustEdge: onBorder ? 0.85 : 0.05,
        inHole: false,
        onDoughnut: false
      };
    }
  }

  // Open Bottom Front Flap (v in [BOX_V2+8..952])
  if (v > BOX_V2 + 8 && v <= 952) {
    let t = (v - (BOX_V2 + 8)) / (952 - (BOX_V2 + 8));
    let botLeft = BOX_U1 - 10 + t * 24;
    let botRight = BOX_U2 + 10 - t * 24;
    if (u >= botLeft && u <= botRight) {
      let onBorder =
        Math.abs(u - botLeft) < 2.2 ||
        Math.abs(u - botRight) < 2.2 ||
        Math.abs(v - 952) < 2.4;
      // Diagonal corner tuck lock lines on front flap
      let lockL = Math.abs((u - botLeft) - (v - BOX_V2) * 0.85) < 1.8;
      let lockR = Math.abs((botRight - u) - (v - BOX_V2) * 0.85) < 1.8;
      let botTone = 0.23 + t * 0.14 + cardTex;
      return {
        dark: onBorder || lockL || lockR ? 0.66 : botTone,
        spec: 0,
        crustEdge: onBorder || lockL || lockR ? 0.85 : 0.05,
        inHole: false,
        onDoughnut: false
      };
    } else if (v < 960 && u >= botLeft + 4 && u <= botRight + 10 && v <= 960) {
      // Soft drop shadow under front flap onto receipt
      return { dark: 0.42, spec: 0, crustEdge: 0.2, inHole: false, onDoughnut: false };
    }
  }

  // Left Side Flap (u in [flapL_outer..BOX_U1-8])
  if (u >= flapL_outer && u < BOX_U1 - 8 && v >= BOX_V1 - 12 && v <= BOX_V2 + 12) {
    let t = (BOX_U1 - 8 - u) / (BOX_U1 - 8 - flapL_outer);
    let vIn = t * 18;
    if (v >= BOX_V1 - 10 + vIn && v <= BOX_V2 + 10 - vIn) {
      let onBorder =
        Math.abs(u - flapL_outer) < 2.2 ||
        Math.abs(v - (BOX_V1 - 10 + vIn)) < 2.2 ||
        Math.abs(v - (BOX_V2 + 10 - vIn)) < 2.2;
      // Left flap tilts away from upper-left light slightly -> warm light-mid tone
      let flapTone = 0.16 + t * 0.16 + cardTex;
      return {
        dark: onBorder ? 0.62 : flapTone,
        spec: 0,
        crustEdge: onBorder ? 0.8 : 0.05,
        inHole: false,
        onDoughnut: false
      };
    }
  }

  // Right Side Flap (u in [BOX_U2+8..flapR_outer])
  if (u > BOX_U2 + 8 && u <= flapR_outer && v >= BOX_V1 - 12 && v <= BOX_V2 + 12) {
    let t = (u - (BOX_U2 + 8)) / (flapR_outer - (BOX_U2 + 8));
    let vIn = t * 18;
    if (v >= BOX_V1 - 10 + vIn && v <= BOX_V2 + 10 - vIn) {
      let onBorder =
        Math.abs(u - flapR_outer) < 2.2 ||
        Math.abs(v - (BOX_V1 - 10 + vIn)) < 2.2 ||
        Math.abs(v - (BOX_V2 + 10 - vIn)) < 2.2;
      // Right flap slopes away from light -> slightly deeper shade + cast shadow beneath it
      let flapTone = 0.30 + t * 0.18 + cardTex;
      return {
        dark: onBorder ? 0.68 : flapTone,
        spec: 0,
        crustEdge: onBorder ? 0.8 : 0.05,
        inHole: false,
        onDoughnut: false
      };
    } else if (u > flapR_outer && u < flapR_outer + 11 && v >= BOX_V1 + 12 && v <= BOX_V2 + 14) {
      // Cast shadow of the bakery box onto the receipt surface
      return { dark: 0.44, spec: 0, crustEdge: 0.2, inHole: false, onDoughnut: false };
    }
  }

  // Exterior cast shadow of the box along the right and bottom margins of the graphic frame
  if (
    u > BOX_U2 + 8 &&
    u < BOX_U2 + 24 &&
    v > BOX_V1 + 6 &&
    v < BOX_V2 + 22
  ) {
    let sd = 1.0 - (u - (BOX_U2 + 8)) / 16.0;
    return { dark: 0.38 * sd, spec: 0, crustEdge: 0, inHole: false, onDoughnut: false };
  }

  // Background inside graphic frame around the open box: subtle thermal receipt paper noise
  let bgNoise = fbm(u * 0.03, v * 0.03) * 0.08;
  return { dark: bgNoise, spec: 0, crustEdge: 0, inHole: false, onDoughnut: false };
}

// Helper to draw a curved line in receipt space (u1, v1) -> (u2, v2)
function drawReceiptLine(u1, v1, u2, v2, steps = 1) {
  if (steps <= 1) {
    brush.line(paperX(u1, v1), paperY(u1, v1), paperX(u2, v2), paperY(u2, v2));
    return;
  }
  for (let i = 0; i < steps; i++) {
    let t1 = i / steps;
    let t2 = (i + 1) / steps;
    let ua = u1 + (u2 - u1) * t1;
    let va = v1 + (v2 - v1) * t1;
    let ub = u1 + (u2 - u1) * t2;
    let vb = v1 + (v2 - v1) * t2;
    brush.line(paperX(ua, va), paperY(ua, va), paperX(ub, vb), paperY(ub, vb));
  }
}

// 3x5 micro dot-matrix font for authentic thermal receipt metadata
const GLYPHS = {
  A: [0b010, 0b101, 0b111, 0b101, 0b101],
  B: [0b110, 0b101, 0b110, 0b101, 0b110],
  C: [0b011, 0b100, 0b100, 0b100, 0b011],
  D: [0b110, 0b101, 0b101, 0b101, 0b110],
  E: [0b111, 0b100, 0b110, 0b100, 0b111],
  F: [0b111, 0b100, 0b110, 0b100, 0b100],
  G: [0b011, 0b100, 0b101, 0b101, 0b011],
  H: [0b101, 0b101, 0b111, 0b101, 0b101],
  I: [0b111, 0b010, 0b010, 0b010, 0b111],
  K: [0b101, 0b101, 0b110, 0b101, 0b101],
  L: [0b100, 0b100, 0b100, 0b100, 0b111],
  M: [0b101, 0b111, 0b101, 0b101, 0b101],
  N: [0b110, 0b101, 0b101, 0b101, 0b101],
  O: [0b010, 0b101, 0b101, 0b101, 0b010],
  P: [0b110, 0b101, 0b110, 0b100, 0b100],
  Q: [0b010, 0b101, 0b101, 0b011, 0b001],
  R: [0b110, 0b101, 0b110, 0b101, 0b101],
  S: [0b011, 0b100, 0b010, 0b001, 0b110],
  T: [0b111, 0b010, 0b010, 0b010, 0b010],
  U: [0b101, 0b101, 0b101, 0b101, 0b111],
  V: [0b101, 0b101, 0b101, 0b101, 0b010],
  W: [0b101, 0b101, 0b101, 0b111, 0b101],
  X: [0b101, 0b101, 0b010, 0b101, 0b101],
  Y: [0b101, 0b101, 0b010, 0b010, 0b010],
  Z: [0b111, 0b001, 0b010, 0b100, 0b111],
  "0": [0b111, 0b101, 0b101, 0b101, 0b111],
  "1": [0b010, 0b110, 0b010, 0b010, 0b111],
  "2": [0b110, 0b001, 0b010, 0b100, 0b111],
  "3": [0b110, 0b001, 0b010, 0b001, 0b110],
  "4": [0b101, 0b101, 0b111, 0b001, 0b001],
  "5": [0b111, 0b100, 0b110, 0b001, 0b110],
  "6": [0b011, 0b100, 0b111, 0b101, 0b111],
  "7": [0b111, 0b001, 0b010, 0b010, 0b010],
  "8": [0b111, 0b101, 0b111, 0b101, 0b111],
  "9": [0b111, 0b101, 0b111, 0b001, 0b110],
  ".": [0b000, 0b000, 0b000, 0b000, 0b010],
  ":": [0b000, 0b010, 0b000, 0b010, 0b000],
  "-": [0b000, 0b000, 0b111, 0b000, 0b000],
  "/": [0b001, 0b001, 0b010, 0b100, 0b100],
  "#": [0b101, 0b111, 0b101, 0b111, 0b101]
};

function drawDotMatrixText(str, startU, startV, pitchU = 2.4, pitchV = 2.5, charGap = 11.2) {
  for (let idx = 0; idx < str.length; idx++) {
    let ch = str[idx];
    let g = GLYPHS[ch];
    if (!g) continue;
    let cu = startU + idx * charGap;
    let fade = getThermalAttenuation(cu, startV);
    for (let r = 0; r < 5; r++) {
      let rowBits = g[r];
      let v = startV + r * pitchV;
      for (let c = 0; c < 3; c++) {
        if ((rowBits >> (2 - c)) & 1) {
          if (hash2(cu + c * 7.1, v + r * 3.3) < fade * 1.15) {
            let u = cu + c * pitchU;
            let px = paperX(u, v);
            let py = paperY(u, v);
            brush.line(px - 0.7, py, px + 0.7, py);
          }
        }
      }
    }
  }
}

