function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // =========================================================================
  // 1. AMBIENT TABLE SURFACE & SOFT CAST SHADOW OF THE CURLING RECEIPT
  // =========================================================================
  background("#ded7d6");

  // Soft ambient pastel washes on the background table surface
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.2);
  brush.fill("#d2c7c7", 42);
  brush.rect(40, 40, 1120, 1120);

  // Build receipt outline polygon vertices
  let uLeft = REC_CX - REC_HALF_W;
  let uRight = REC_CX + REC_HALF_W;
  let recPoly = [];

  // Top serrated edge (left -> right)
  for (let u = uLeft; u <= uRight; u += 4) {
    let v = topSerratedV(u);
    recPoly.push([paperX(u, v), paperY(u, v)]);
  }
  // Right edge (top -> bottom)
  for (let v = REC_TOP + 8; v <= REC_BOT - 12; v += 14) {
    recPoly.push([paperX(uRight, v), paperY(uRight, v)]);
  }
  // Bottom torn serrated edge (right -> left)
  for (let u = uRight; u >= uLeft; u -= 3.5) {
    let v = botSerratedV(u);
    recPoly.push([paperX(u, v), paperY(u, v)]);
  }
  // Left edge (bottom -> top)
  for (let v = REC_BOT - 12; v >= REC_TOP + 8; v -= 14) {
    recPoly.push([paperX(uLeft, v), paperY(uLeft, v)]);
  }

  // Draw multi-layered cast shadow under the curling receipt strip
  // Deeper & wider at the lifted top and bottom edges, tighter at the middle
  let shadowPasses = [
    { ox: 15, oy: 22, col: "#b5a6a9", alpha: 48, bleed: 0.42 },
    { ox: 9, oy: 13, col: "#99898d", alpha: 62, bleed: 0.28 },
    { ox: 4, oy: 6, col: "#7c6d71", alpha: 58, bleed: 0.14 }
  ];

  for (let sp of shadowPasses) {
    brush.noStroke();
    brush.fill(sp.col, sp.alpha);
    brush.fillBleed(sp.bleed, "out");
    brush.fillTexture(0.35, 0.18);
    brush.beginShape(0);
    for (let i = 0; i < recPoly.length; i++) {
      let [px, py] = recPoly[i];
      // Amplify shadow offset near top and bottom where paper curls up off the table
      let vDist = Math.abs(py - 600) / 540;
      let lift = 0.55 + 0.85 * vDist * vDist;
      brush.vertex(px + sp.ox * lift, py + sp.oy * lift);
    }
    brush.endShape(true);
  }

  // =========================================================================
  // 2. THERMAL RECEIPT PAPER STRIP (PALE IVORY + FAINT PINK-GREY TINT)
  // =========================================================================
  // Base pale warm ivory wash
  brush.noStroke();
  brush.wash("#f6f2ea", 252);
  brush.beginShape(0);
  for (let i = 0; i < recPoly.length; i++) {
    brush.vertex(recPoly[i][0], recPoly[i][1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Ghostly pink-grey chemical blush & soft pastel thermal paper aging washes
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.5, 0.22);

  // Batch 1: Faint pink-grey tint across the thermal paper
  brush.fill("#ead7dc", 52);
  brush.rect(318, 72, 564, 1040);
  brush.rect(520, 120, 360, 920);

  // Batch 2: Classic thermal roll "low-paper" soft pastel pink warning stripe near right edge
  brush.fill("#e7bfc8", 58);
  brush.beginShape(0);
  for (let v = REC_TOP + 12; v <= REC_BOT - 18; v += 24) {
    brush.vertex(paperX(uRight - 88, v), paperY(uRight - 88, v));
  }
  for (let v = REC_BOT - 18; v >= REC_TOP + 12; v -= 24) {
    brush.vertex(paperX(uRight - 14, v), paperY(uRight - 14, v));
  }
  brush.endShape(true);

  // Batch 3: Warm oxidized ivory patches where the receipt aged unevenly
  brush.fill("#ede3d2", 46);
  brush.rect(330, 180, 290, 420);
  brush.rect(410, 620, 380, 340);

  // Batch 4: 3D cylindrical curl shading bands across the receipt strip
  brush.fill("#d4c5c9", 36);
  brush.rect(312, 62, 576, 56);    // top curl roll-off
  brush.rect(312, 535, 576, 68);   // mid-strip subtle wave buckle
  brush.rect(312, 1055, 576, 72);  // bottom curl lift shade
  brush.noFill();

  // Crisp delicate paper edge contour & serrated teeth definition
  brush.set("2H", "#b4a3a7", 0.52);
  for (let i = 0; i < recPoly.length; i++) {
    let p1 = recPoly[i];
    let p2 = recPoly[(i + 1) % recPoly.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Extra shadow contrast right under the bottom torn serrated teeth
  brush.set("rotring", "#68585c", 0.38);
  for (let u = uLeft + 3; u < uRight - 3; u += 3.6) {
    let v1 = botSerratedV(u);
    let v2 = botSerratedV(u + 3.6);
    brush.line(paperX(u, v1) + 0.6, paperY(u, v1) + 1.1, paperX(u + 3.6, v2) + 0.6, paperY(u + 3.6, v2) + 1.1);
  }

  // =========================================================================
  // 3. TINY RULED LINES, MARGIN SCALES & DOT-MATRIX RECEIPT METADATA
  // =========================================================================
  // Subtle horizontal ruled receipt background lines across the entire strip
  brush.set("2H", "#dfd2d5", 0.35);
  for (let v = 90; v <= 1105; v += 12) {
    // Only draw faint ruled ledger hairlines outside the dense bakery box center or faintly through faded right margin
    if (v < IMG_V1 || v > IMG_V2) {
      drawReceiptLine(uLeft + 18, v, uRight - 18, v, 8);
    } else {
      drawReceiptLine(uLeft + 14, v, IMG_U1 + 6, v, 2);
      drawReceiptLine(IMG_U2 - 38, v, uRight - 14, v, 3);
    }
  }

  // Crisp ruled framing lines & micro-tick scales in warm grey pen
  brush.set("rotring", "#7c6c70", 0.36);

  // Header double rules (v = 82, 86 and v = 154, 158)
  let headerRules = [82, 86, 132, 156, 160];
  for (let rv of headerRules) {
    for (let u = uLeft + 22; u < uRight - 26; u += 16) {
      if (hash2(u, rv) < getThermalAttenuation(u, rv) * 1.1) {
        drawReceiptLine(u, rv, Math.min(uRight - 22, u + 14.5), rv, 1);
      }
    }
  }

  // Micro-ruler tick marks along top rule (v = 86..92) and bottom rule (v = 968..974)
  for (let u = uLeft + 24; u <= uRight - 24; u += 6) {
    let isMajor = (u - (uLeft + 24)) % 30 === 0;
    let tickLen = isMajor ? 5.2 : 2.6;
    if (hash2(u, 88) < getThermalAttenuation(u, 88) * 1.15) {
      drawReceiptLine(u, 86, u, 86 + tickLen, 1);
    }
    if (hash2(u, 968) < getThermalAttenuation(u, 968) * 1.15) {
      drawReceiptLine(u, 968, u, 968 + tickLen, 1);
    }
  }

  // Vertical side margin rules + registration ticks flanking the bakery box image
  for (let v = IMG_V1 - 6; v <= IMG_V2 + 6; v += 12) {
    drawReceiptLine(uLeft + 22, v, uLeft + 22, Math.min(IMG_V2 + 6, v + 10.5), 1);
    drawReceiptLine(uLeft + 26, v, uLeft + 26, Math.min(IMG_V2 + 6, v + 10.5), 1);
    if ((v - (IMG_V1 - 6)) % 24 === 0) {
      drawReceiptLine(uLeft + 17, v, uLeft + 26, v, 1);
    }

    if (hash2(uRight - 22, v) < getThermalAttenuation(uRight - 22, v) * 1.1) {
      drawReceiptLine(uRight - 22, v, uRight - 22, Math.min(IMG_V2 + 6, v + 10.0), 1);
      if ((v - (IMG_V1 - 6)) % 24 === 0) {
        drawReceiptLine(uRight - 26, v, uRight - 18, v, 1);
      }
    }
  }

  // Footer ruled lines (v = 968, 972, 1022, 1044, 1098)
  let footerRules = [968, 972, 1022, 1044, 1098];
  for (let rv of footerRules) {
    for (let u = uLeft + 22; u < uRight - 26; u += 14) {
      if (hash2(u, rv) < getThermalAttenuation(u, rv) * 1.1) {
        drawReceiptLine(u, rv, Math.min(uRight - 22, u + 12.2), rv, 1);
      }
    }
  }

  // Dashed tear-bar perforation rule just above the bottom serrated edge (v = 1114)
  for (let u = uLeft + 16; u < uRight - 18; u += 9) {
    if (hash2(u, 1114) < getThermalAttenuation(u, 1114) * 1.2) {
      drawReceiptLine(u, 1114, u + 4.8, 1114, 1);
    }
  }

  // Ghostly dot-matrix receipt text in header and footer
  brush.set("rotring", "#68585c", 0.42);
  drawDotMatrixText("PATISSERIE DE L AUBE  #04", 352, 98, 2.3, 2.4, 11.2);
  drawDotMatrixText("DATE 14-04  TIME 06:42:19", 352, 115, 2.2, 2.3, 11.2);
  drawDotMatrixText("QTY  ITEM DESCRIPTION           AMT", 342, 140, 2.1, 2.2, 10.2);

  drawDotMatrixText("01   BOX 6X GLAZED YEAST       8.40", 342, 982, 2.1, 2.3, 10.2);
  drawDotMatrixText("     HOT SUGAR CRUST / FRESH       ", 342, 1002, 2.1, 2.3, 10.2);
  drawDotMatrixText("TOTAL THERMAL PRINT            8.40", 342, 1028, 2.1, 2.3, 10.2);

  // Stippled thermal barcode at the bottom of the receipt (v = 1052..1088)
  for (let u = 380; u <= 810; u += 3.2) {
    let barHash = hash2(Math.floor(u / 3.2), 77.7);
    if (barHash > 0.34) {
      let fade = getThermalAttenuation(u, 1070);
      let isThick = barHash > 0.72;
      let vStart = 1052;
      let vEnd = 1088;
      // Break barcode vertically with horizontal thermal banding
      for (let v = vStart; v < vEnd; v += 4.5) {
        if (hash2(u, v) < fade * 1.08) {
          drawReceiptLine(u, v, u, Math.min(vEnd, v + 3.8), 1);
          if (isThick) {
            drawReceiptLine(u + 1.1, v, u + 1.1, Math.min(vEnd, v + 3.8), 1);
          }
        }
      }
    }
  }

  // =========================================================================
  // 4. HYPERREALISTIC BAKERY BOX & 6 GLAZED DOUGHNUTS:
  //    DITHERED DOT ROWS + FINE WARM-GREY PEN STIPPLE
  // =========================================================================
  const rowStep = 2.65;
  const colStep = 2.0;

  // Batched segment arrays for the 4 dithered dot-row tiers
  let rowRuns1 = []; // Pale warm pink-grey dither row
  let rowRuns2 = []; // Staggered mid-light warm grey dither row
  let rowRuns3 = []; // Crisp warm taupe-grey dither row
  let rowRuns4 = []; // Dense deep dough-hole & shadow dither row

  // Batched stipple arrays for fine warm-grey pen stippling
  let stippleLight = [];
  let stippleMid = [];
  let stippleDark = [];
  let stippleHole = []; // Extra dense stipple specifically for the dough holes & deep crevices
  let crustHighlights = []; // Pale ivory sugar-crust catchlights & sticky sheen glints

  let rowIdx = 0;
  for (let v = IMG_V1; v <= IMG_V2; v += rowStep, rowIdx++) {
    let open1 = null, open2 = null, open3 = null, open4 = null;
    // Stagger odd rows by half a dot step for authentic Bayer dot-matrix interleave
    let rowStagger = (rowIdx & 1) * 1.05;

    let colIdx = 0;
    for (let u = IMG_U1; u <= IMG_U2; u += colStep, colIdx++) {
      let sc = evalBakeryScene(u, v);
      let atten = getThermalAttenuation(u, v);

      // Nonlinear thermal aging response: midtones fade faster than deepest dough-hole shadows
      let dEff = Math.pow(sc.dark, 1.0 + (1.0 - atten) * 1.35) * atten;

      // 2x2 Bayer ordered dither modulation
      let bayer = (((rowIdx & 1) << 1) | (colIdx & 1)) * 0.032 - 0.048;
      let dDither = dEff + bayer;

      // Tier 1: Ghostly warm pink-grey undertone dot row (d > 0.11)
      if (dDither > 0.11 && sc.spec < 0.55) {
        if (open1 === null) open1 = u;
      } else if (open1 !== null) {
        rowRuns1.push([open1, u - colStep, v]);
        open1 = null;
      }

      // Tier 2: Mid-light staggered thermal dot row (d > 0.26)
      if (dDither > 0.26 && sc.spec < 0.35) {
        if (open2 === null) open2 = u + rowStagger;
      } else if (open2 !== null) {
        rowRuns2.push([open2, u - colStep + rowStagger, v]);
        open2 = null;
      }

      // Tier 3: Crisp detail & sugar crust thermal dot row (d > 0.44)
      if (dDither > 0.44 && sc.spec < 0.18) {
        if (open3 === null) open3 = u;
      } else if (open3 !== null) {
        rowRuns3.push([open3, u - colStep, v]);
        open3 = null;
      }

      // Tier 4: Deep shadow & dough-hole thermal dot row (d > 0.63)
      if (dDither > 0.63 && sc.spec < 0.08) {
        if (open4 === null) open4 = u + rowStagger * 0.6;
      } else if (open4 !== null) {
        rowRuns4.push([open4, u - colStep + rowStagger * 0.6, v]);
        open4 = null;
      }

      // Importance-sampled Fine Warm-Grey Pen Stipple Points
      let rnd = hash2(u * 1.37, v * 2.91);
      let stippleProb =
        0.16 * dEff +
        0.34 * Math.pow(dEff, 2.2) +
        0.28 * sc.crustEdge * atten +
        (sc.inHole ? 0.42 * atten : 0);

      if (rnd < stippleProb && sc.spec < 0.42) {
        let ju = u + (hash2(u, v + 17.3) - 0.5) * 2.1;
        let jv = v + (hash2(u + 31.1, v) - 0.5) * 2.1;
        let px = paperX(ju, jv);
        let py = paperY(ju, jv);
        let ang = hash2(ju, jv) * Math.PI * 2;

        if (sc.inHole && dEff > 0.52) {
          stippleHole.push([px, py, ang, 1.3]);
          // Double-pack stipples in the deepest dough-hole cores!
          if (dEff > 0.68) {
            let px2 = paperX(ju + (rnd - 0.5) * 1.8, jv + (hash2(v, u) - 0.5) * 1.8);
            let py2 = paperY(ju + (rnd - 0.5) * 1.8, jv + (hash2(v, u) - 0.5) * 1.8);
            stippleHole.push([px2, py2, ang + 1.1, 1.45]);
          }
        } else if (dEff > 0.58) {
          stippleDark.push([px, py, ang, 1.15]);
        } else if (dEff > 0.32 || sc.crustEdge > 0.55) {
          stippleMid.push([px, py, ang, 0.95]);
        } else if (dEff > 0.14) {
          stippleLight.push([px, py, ang, 0.85]);
        }
      }

      // Collect crystalline torn sugar crust catch-lights & sticky specular glints
      if (sc.onDoughnut && (sc.spec > 0.55 || (sc.crustEdge > 0.7 && sc.dark < 0.18))) {
        if (hash2(u + 9.2, v + 4.7) < 0.28) {
          crustHighlights.push([paperX(u, v), paperY(u, v)]);
        }
      }
    }

    // Close any open runs at the right edge of the scanline
    if (open1 !== null) rowRuns1.push([open1, IMG_U2, v]);
    if (open2 !== null) rowRuns2.push([open2, IMG_U2, v]);
    if (open3 !== null) rowRuns3.push([open3, IMG_U2, v]);
    if (open4 !== null) rowRuns4.push([open4, IMG_U2, v]);
  }

  // Helper to emit horizontal dithered dot-row runs following the receipt paper curl
  function renderDitherRuns(runs, maxSegLen = 28) {
    for (let i = 0; i < runs.length; i++) {
      let [u1, u2, v] = runs[i];
      if (u2 - u1 < 1.2) {
        let px = paperX(u1, v);
        let py = paperY(u1, v);
        brush.line(px - 0.65, py, px + 0.65, py);
      } else {
        let span = u2 - u1;
        let segs = Math.max(1, Math.ceil(span / maxSegLen));
        drawReceiptLine(u1, v, u2, v, segs);
      }
    }
  }

  // Execute the 4 Dithered Dot-Row Passes (from soft pastel rose-grey to deep warm charcoal)
  brush.set("dither_row_1", "#b5a1a5", 1.0);
  renderDitherRuns(rowRuns1, 34);

  brush.set("dither_row_2", "#8e7d81", 1.0);
  renderDitherRuns(rowRuns2, 30);

  brush.set("dither_row_3", "#635458", 1.0);
  renderDitherRuns(rowRuns3, 26);

  brush.set("dither_row_4", "#3d3135", 1.0);
  renderDitherRuns(rowRuns4, 22);

  // Execute the Fine Warm-Grey Pen Stipple Passes
  // Pass 1: Light warm grey-pink stipple
  brush.set("rotring", "#9a888c", 0.32);
  for (let i = 0; i < stippleLight.length; i++) {
    let [px, py, ang, len] = stippleLight[i];
    let dx = Math.cos(ang) * len * 0.5;
    let dy = Math.sin(ang) * len * 0.5;
    brush.line(px - dx, py - dy, px + dx, py + dy);
  }

  // Pass 2: Mid warm pigeon-grey stipple (torn sugar crust edges, glaze drips & box creases)
  brush.set("rotring", "#6e5e62", 0.36);
  for (let i = 0; i < stippleMid.length; i++) {
    let [px, py, ang, len] = stippleMid[i];
    let dx = Math.cos(ang) * len * 0.52;
    let dy = Math.sin(ang) * len * 0.52;
    brush.line(px - dx, py - dy, px + dx, py + dy);
  }

  // Pass 3: Dark warm sepia-slate stipple (deep glaze crevices & box corner shadows)
  brush.set("stipple_fine", "#473a3e", 0.92);
  for (let i = 0; i < stippleDark.length; i++) {
    let [px, py, ang, len] = stippleDark[i];
    let dx = Math.cos(ang) * len * 0.55;
    let dy = Math.sin(ang) * len * 0.55;
    brush.line(px - dx, py - dy, px + dx, py + dy);
  }

  // Pass 4: Maximum density warm charcoal-umber pen stipple inside the 6 dough holes
  brush.set("rotring", "#261d20", 0.44);
  for (let i = 0; i < stippleHole.length; i++) {
    let [px, py, ang, len] = stippleHole[i];
    let dx = Math.cos(ang) * len * 0.55;
    let dy = Math.sin(ang) * len * 0.55;
    brush.line(px - dx, py - dy, px + dx, py + dy);
  }

  // Pass 5: Crisp pale cream-ivory glints on sticky glaze sheen & torn crystalline sugar edges
  brush.set("2H", "#fbf8f1", 0.48);
  for (let i = 0; i < crustHighlights.length; i++) {
    let [px, py] = crustHighlights[i];
    brush.line(px - 0.9, py - 0.3, px + 0.9, py + 0.3);
  }

  noLoop();
}

