// ============================================================================
// GEOMETRY & WATERCOLOUR HELPERS
// ============================================================================

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawPoly(pts, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function makeOrganicBlob(cx, cy, rx, ry, nPts, irr, seed, rotDeg = 0) {
  let pts = [];
  let cRot = cos(rotDeg);
  let sRot = sin(rotDeg);
  for (let i = 0; i < nPts; i++) {
    let a = (i / nPts) * 360;
    let n1 = noise(cos(a) * 1.3 + seed, sin(a) * 1.3 + seed);
    let n2 = noise(cos(a) * 3.1 + seed * 2.1, sin(a) * 3.1 + seed * 2.1);
    let rMod = 1 + (n1 - 0.5) * irr * 1.5 + (n2 - 0.5) * irr * 0.75;
    let px = cos(a) * rx * rMod;
    let py = sin(a) * ry * rMod;
    let rxp = px * cRot - py * sRot;
    let ryp = px * sRot + py * cRot;
    pts.push([cx + rxp, cy + ryp]);
  }
  return pts;
}

function makeCrescentRing(cx, cy, rOuter, rInner, startAng, endAng, steps, irr, seed) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(startAng, endAng, i / steps);
    let n = noise(cos(a) * 1.8 + seed, sin(a) * 1.8 + seed);
    let r = rOuter * (1 + (n - 0.5) * irr);
    pts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = lerp(startAng, endAng, i / steps);
    let n = noise(cos(a) * 2.2 + seed + 40, sin(a) * 2.2 + seed + 40);
    let r = rInner * (1 + (n - 0.5) * irr * 1.4);
    pts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  return pts;
}

