function drawFarmhouseWall() {
  resetBrushState();

  // Broad granulating earth-tone plaster washes concentrated in the upper & mid wall
  const washes = [
    { x: 600, y: 280, rx: 620, ry: 310, col: PALETTE.plasterLight, a: 75, bleed: 0.45, s: 11 },
    { x: 350, y: 420, rx: 460, ry: 380, col: PALETTE.plasterMid, a: 52, bleed: 0.4, s: 22 },
    { x: 850, y: 390, rx: 430, ry: 360, col: PALETTE.plasterMid, a: 48, bleed: 0.42, s: 33 },
    { x: 580, y: 680, rx: 490, ry: 330, col: PALETTE.plasterLight, a: 60, bleed: 0.45, s: 44 },
    { x: 240, y: 180, rx: 320, ry: 220, col: PALETTE.plasterDark, a: 45, bleed: 0.35, s: 55 },
    { x: 940, y: 190, rx: 310, ry: 220, col: PALETTE.plasterDark, a: 42, bleed: 0.38, s: 66 }
  ];

  for (let w of washes) {
    brush.fill(w.col, w.a);
    brush.fillBleed(w.bleed, "out");
    brush.fillTexture(0.82, 0.72);
    let pts = makeOrganicBlob(w.x, w.y, w.rx, w.ry, 22, 0.25, w.s);
    drawPoly(pts, 0.3);
  }
  resetBrushState();

  // Subtle architectural stone/plaster joints & old timber beam shadow at very top
  brush.fill(PALETTE.earthUmber, 38);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.75, 0.65);
  drawPoly([[0, 0], [1200, 0], [1200, 48], [0, 56]], 0.1);
  resetBrushState();

  // Faint plaster cracks and limewash masonry lines in dry 2H pencil
  brush.set("2H", PALETTE.plasterDark, 0.55);
  const vJoints = [195, 515, 865, 1095];
  for (let x of vJoints) {
    let yCur = random(60, 150);
    while (yCur < 1120) {
      let seg = random(45, 130);
      if (random() < 0.45) {
        let jit = random(-4, 4);
        brush.line(x + jit, yCur, x - jit * 0.5, yCur + seg);
      }
      yCur += seg + random(30, 90);
    }
  }
  // Horizontal mortar hints in lower negative space
  for (let y of [790, 960, 1085]) {
    for (let x = 80; x < 1100; x += random(90, 190)) {
      if (random() < 0.5) {
        brush.set("2H", PALETTE.plasterDark, random(0.35, 0.65));
        brush.line(x, y + random(-3, 3), x + random(40, 110), y + random(-3, 3));
      }
    }
  }
}

