function drawCopperPan(pan) {
  const { cx, cy, r, rimDx, rimDy } = pan;

  // --- STEP A: 3D CYLINDRICAL SIDE WALL (BEZEL) ---
  drawPanSideWall(pan);

  // --- STEP B: BASE SALMON-PINK & BURNISHED COPPER GLAZES ---
  drawPanCopperBase(pan);

  // --- STEP C: BLURRED HOT-ORANGE WINDOW REFLECTION ---
  drawBlurredWindowReflection(pan);

  // --- STEP D: WET-IN-WET VERDIGRIS BLOSSOMS & HARD BACKRUN TIDE LINES ---
  drawVerdigrisBlossoms(pan);

  // --- STEP E: PITTED OXIDATION SPECKLE & LATHE RINGS ---
  drawPanSurfaceDetail(pan);

  // --- STEP F: CRISP PENCIL DENTS & HAMMER MARKS ---
  drawPanDents(pan);

  // --- STEP G: RIVETED FORGED IRON HANDLE & FLANGE (ÉCUSSON) ---
  if (pan.handle) {
    drawRivetedHandle(pan);
  }
  if (pan.hasHelperLoop) {
    drawBottomHelperLoop(pan);
  }
}

function drawPanSideWall(pan) {
  const { cx, cy, r, rimDx, rimDy, verdigrisSeed } = pan;
  const rx = cx + rimDx;
  const ry = cy + rimDy;

  resetBrushState();

  // Base wash of the cylindrical side wall
  brush.wash(PALETTE.copperDark, 215);
  let wallPts = makeOrganicBlob(rx, ry, r * 1.005, r * 1.005, 32, 0.02, verdigrisSeed + 1);
  drawPoly(wallPts, 0.2);
  resetBrushState();

  // Warm salmon-pink and amber specular bands along the curved side wall
  brush.fill(PALETTE.salmonPink, 150);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.78, 0.75);
  let band1 = makeCrescentRing(rx, ry, r * 1.005, r * 0.86, -80, 15, 16, 0.04, verdigrisSeed + 2);
  drawPoly(band1, 0.2);

  brush.fill(PALETTE.hotOrangeBright, 135);
  brush.fillBleed(0.22, "in");
  let band2 = makeCrescentRing(rx, ry, r * 1.002, r * 0.88, -35, 25, 12, 0.04, verdigrisSeed + 3);
  drawPoly(band2, 0.2);

  // Verdigris crust creeping along the outer lip of the side wall
  brush.fill(PALETTE.malachite, 155);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.88, 0.9);
  let lipGreen = makeCrescentRing(rx, ry, r * 1.01, r * 0.9, -155, -75, 14, 0.09, verdigrisSeed + 4);
  drawPoly(lipGreen, 0.25);
  resetBrushState();

  // Crisp graphite contour lines on the outer rim lip
  brush.set("2B", PALETTE.tarnishDeep, 1.05);
  brush.circle(rx, ry, r, 0.018);

  // Longitudinal draw/hammer lines between outer rim and pan base edge
  let rimAngle = atan2(rimDy, rimDx);
  for (let a = rimAngle - 85; a <= rimAngle + 85; a += 7) {
    let x1 = rx + cos(a) * r;
    let y1 = ry + sin(a) * r;
    let x2 = cx + cos(a) * r;
    let y2 = cy + sin(a) * r;
    let isLight = abs(a - (-20)) < 35;
    brush.set("2H", isLight ? PALETTE.windowGlow : PALETTE.tarnishDeep, 0.55);
    brush.line(x1, y1, x2, y2);
  }
}

function drawPanCopperBase(pan) {
  const { cx, cy, r, baseTone, midTone, darkTone, verdigrisSeed } = pan;
  resetBrushState();

  // 1. Opaque base luminous wash in warm salmon-pink so underlying pans are cleanly occluded
  brush.wash(PALETTE.salmonLight, 235);
  let baseDisc = makeOrganicBlob(cx, cy, r, r, 36, 0.015, verdigrisSeed + 10);
  drawPoly(baseDisc, 0.2);
  resetBrushState();

  // 2. Primary granulating watercolour glaze of warm salmon-pink copper
  brush.fill(baseTone, 145);
  brush.fillBleed(0.32, "in");
  brush.fillTexture(0.86, 0.82);
  let mainWash = makeOrganicBlob(cx, cy, r * 0.99, r * 0.99, 26, 0.04, verdigrisSeed + 11);
  drawPoly(mainWash, 0.25);

  // 3. Burnished copper & rose-salmon midtone crescent glazes
  brush.fill(midTone, 130);
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.88, 0.85);
  let midCrescent = makeCrescentRing(cx, cy, r * 0.96, r * 0.32, 85, 290, 18, 0.14, verdigrisSeed + 12);
  drawPoly(midCrescent, 0.25);

  // 4. Deep burnished sienna & muted earth tarnish around the upper-left / lower-left rim
  brush.fill(PALETTE.copperBurnished, 135);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.9, 0.88);
  let burnishZone = makeCrescentRing(cx, cy, r * 0.98, r * 0.48, 125, 265, 16, 0.16, verdigrisSeed + 13);
  drawPoly(burnishZone, 0.25);

  brush.fill(darkTone, 125);
  brush.fillBleed(0.3, "in");
  brush.fillTexture(0.92, 0.9);
  let tarnishRim = makeCrescentRing(cx, cy, r * 0.99, r * 0.72, 145, 245, 15, 0.15, verdigrisSeed + 14);
  drawPoly(tarnishRim, 0.25);

  // 5. Central warm salmon-pink glow
  brush.fill(PALETTE.salmonLight, 110);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.75, 0.65);
  let centerGlow = makeOrganicBlob(cx - r * 0.08, cy - r * 0.08, r * 0.46, r * 0.44, 18, 0.18, verdigrisSeed + 15);
  drawPoly(centerGlow, 0.3);

  resetBrushState();
}

function drawBlurredWindowReflection(pan) {
  const { cx, cy, r, winAngle, winRad, winScale, verdigrisSeed } = pan;
  resetBrushState();

  // Polished patch reflecting a blurred 4-pane farmhouse window in hot orange
  const wCx = cx + cos(winAngle) * r * winRad;
  const wCy = cy + sin(winAngle) * r * winRad;

  // Ambient hot-orange halo around the polished reflection zone
  brush.fill(PALETTE.hotOrangeDeep, 115);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.8, 0.72);
  let haloPts = makeCrescentRing(
    cx, cy,
    r * 0.88, r * 0.26,
    winAngle - 34 * winScale, winAngle + 34 * winScale,
    14, 0.1, verdigrisSeed + 20
  );
  drawPoly(haloPts, 0.25);

  // 4 Warped Window Panes (2 radial tiers x 2 angular columns) separated by blurred dark mullions
  const rInner1 = r * 0.32;
  const rMid1 = r * 0.56;
  const rMid2 = r * 0.62; // Mullion gap
  const rOuter2 = r * 0.84;

  const angSpan = 24 * winScale;
  const angGap = 2.8; // Crossbar mullion angular gap

  const panes = [
    { r1: rInner1, r2: rMid1, a1: winAngle - angSpan, a2: winAngle - angGap, col: PALETTE.hotOrangeBright },
    { r1: rInner1, r2: rMid1, a1: winAngle + angGap, a2: winAngle + angSpan, col: PALETTE.hotOrange },
    { r1: rMid2, r2: rOuter2, a1: winAngle - angSpan, a2: winAngle - angGap, col: PALETTE.hotAmber },
    { r1: rMid2, r2: rOuter2, a1: winAngle + angGap, a2: winAngle + angSpan, col: PALETTE.hotOrangeBright }
  ];

  for (let i = 0; i < panes.length; i++) {
    let p = panes[i];
    // Hot orange blurred pane wash
    brush.fill(p.col, 175);
    brush.fillBleed(0.28, "out");
    brush.fillTexture(0.75, 0.68);
    let panePts = makeCrescentRing(cx, cy, p.r2, p.r1, p.a1, p.a2, 8, 0.06, verdigrisSeed + 22 + i);
    drawPoly(panePts, 0.2);

    // Intense glowing core inside each window pane
    let rCore1 = lerp(p.r1, p.r2, 0.22);
    let rCore2 = lerp(p.r1, p.r2, 0.78);
    let aCore1 = lerp(p.a1, p.a2, 0.2);
    let aCore2 = lerp(p.a1, p.a2, 0.8);
    brush.fill(i === 2 ? PALETTE.windowSpec : PALETTE.windowGlow, 165);
    brush.fillBleed(0.22, "out");
    brush.fillTexture(0.65, 0.55);
    let corePts = makeCrescentRing(cx, cy, rCore2, rCore1, aCore1, aCore2, 6, 0.05, verdigrisSeed + 30 + i);
    drawPoly(corePts, 0.2);
  }

  // Secondary smaller hot-orange specular streak on opposite bevel
  brush.fill(PALETTE.hotOrange, 110);
  brush.fillBleed(0.3, "out");
  let oppStreak = makeCrescentRing(cx, cy, r * 0.93, r * 0.78, winAngle - 85, winAngle - 45, 10, 0.08, verdigrisSeed + 36);
  drawPoly(oppStreak, 0.25);

  resetBrushState();

  // Crisp dry-brush / colored pencil radial shimmer across the window reflection
  brush.set("cpencil", PALETTE.windowSpec, 0.85);
  for (let a = winAngle - angSpan * 0.8; a <= winAngle + angSpan * 0.8; a += 4.5) {
    if (abs(a - winAngle) < angGap) continue;
    brush.arc(cx, cy, random(rInner1 + 6, rOuter2 - 6), a - 3, a + 3);
  }
}

function drawVerdigrisBlossoms(pan) {
  const { cx, cy, r, verdigrisSeed, verdigrisAngles } = pan;
  resetBrushState();

  // Wet-in-wet blossoms of malachite, viridian, and powdery Paris green
  // with hard backrun edges imitating oxidation tide lines
  for (let idx = 0; idx < verdigrisAngles.length; idx++) {
    let baseAng = verdigrisAngles[idx];
    let distFactor = (idx % 2 === 0) ? random(0.62, 0.82) : random(0.35, 0.65);
    let bx = cx + cos(baseAng) * r * distFactor;
    let by = cy + sin(baseAng) * r * distFactor;
    let bRx = r * random(0.22, 0.38);
    let bRy = r * random(0.16, 0.30);
    let seed = verdigrisSeed + idx * 37;

    // 1. Outer wet-in-wet Viridian / Malachite bloom with strong granulation & border
    let outerCol = (idx % 2 === 0) ? PALETTE.viridian : PALETTE.malachite;
    brush.fill(outerCol, 155);
    brush.fillBleed(0.38, "out");
    brush.fillTexture(0.92, 0.95);
    let outerPts = makeOrganicBlob(bx, by, bRx, bRy, 22, 0.36, seed, baseAng + 90);
    drawPoly(outerPts, 0.28);

    // 2. Mid-layer Malachite / Cyan-Green blossom
    brush.fill(PALETTE.malachiteLight, 150);
    brush.fillBleed(0.28, "out");
    brush.fillTexture(0.9, 0.92);
    let midPts = makeOrganicBlob(
      bx + random(-8, 8), by + random(-8, 8),
      bRx * 0.72, bRy * 0.72,
      18, 0.34, seed + 11, baseAng + 75
    );
    drawPoly(midPts, 0.26);

    // 3. Powdery Paris Green crust in the core of the oxidation bloom
    brush.fill(PALETTE.parisGreen, 170);
    brush.fillBleed(0.18, "in");
    brush.fillTexture(0.94, 0.95);
    let innerPts = makeOrganicBlob(
      bx + random(-5, 5), by + random(-5, 5),
      bRx * 0.46, bRy * 0.46,
      16, 0.3, seed + 23, baseAng + 90
    );
    drawPoly(innerPts, 0.25);

    resetBrushState();

    // 4. Dry-media powdery Paris green crust mass (`brush.mass`) for chalky mineral texture
    brush.mass("cpencil", (idx % 2 === 0) ? PALETTE.parisPowder : PALETTE.parisChalk, {
      precision: 0.35,
      strength: 0.65,
      gradient: 0.4,
      outline: false
    });
    let crustPts = makeOrganicBlob(bx, by, bRx * 0.32, bRy * 0.3, 12, 0.28, seed + 31, baseAng + 90);
    drawPoly(crustPts, 0.2);
    resetBrushState();

    // 5. HARD BACKRUN EDGES IMITATING OXIDATION TIDE LINES
    // Trace irregular scalloped segments along outerPts and midPts with concentrated Viridian & Copper Oxide
    drawBackrunTideLine(outerPts, PALETTE.viridianDeep, PALETTE.copperBurnished, seed + 50);
    drawBackrunTideLine(midPts, PALETTE.viridian, PALETTE.parisPowder, seed + 70);
  }

  // Crescent tide-line crust right along the upper/left rim where moisture collects
  let rimCrustPts = makeCrescentRing(cx, cy, r * 0.98, r * 0.81, -155, -55, 18, 0.14, verdigrisSeed + 200);
  brush.fill(PALETTE.malachite, 145);
  brush.fillBleed(0.3, "in");
  brush.fillTexture(0.92, 0.95);
  drawPoly(rimCrustPts, 0.25);
  resetBrushState();

  drawBackrunTideLine(rimCrustPts, PALETTE.viridianDeep, PALETTE.parisGreen, verdigrisSeed + 210);
}

function drawBackrunTideLine(pts, darkCol, lightCol, seed) {
  resetBrushState();
  const n = pts.length;
  // Draw double-rimmed watercolour backrun tide line along segments of the polygon
  for (let i = 0; i < n; i++) {
    let nVal = noise(i * 0.35 + seed);
    if (nVal > 0.28) {
      let p1 = pts[i];
      let p2 = pts[(i + 1) % n];
      // Outer dark pigment-pooled backrun edge
      brush.set("tide_edge", darkCol, random(0.75, 1.35));
      brush.line(p1[0], p1[1], p2[0], p2[1]);

      // Inner pale salt/oxide tide ring parallel to the backrun
      if (nVal > 0.48) {
        brush.set("lathe_needle", lightCol, 0.85);
        brush.line(p1[0] + 1.8, p1[1] + 1.8, p2[0] + 1.8, p2[1] + 1.8);
      }
    }
  }
}

function drawPanSurfaceDetail(pan) {
  const { cx, cy, r, verdigrisSeed, verdigrisAngles } = pan;
  resetBrushState();

  // 1. Fine spray speckle for pitted oxidation texture
  for (let ang of verdigrisAngles) {
    let sx = cx + cos(ang) * r * 0.62;
    let sy = cy + sin(ang) * r * 0.62;

    brush.set("pitted_spray", PALETTE.viridianDeep, 0.95);
    brush.circle(sx, sy, r * 0.24, 0.25);

    brush.set("pitted_spray", PALETTE.parisPowder, 0.85);
    brush.circle(sx + random(-12, 12), sy + random(-12, 12), r * 0.14, 0.25);

    brush.set("pitted_spray", PALETTE.tarnishDeep, 0.8);
    brush.circle(sx + random(-18, 18), sy + random(-18, 18), r * 0.2, 0.3);
  }

  // Micro-pits (crisp tiny rotring & 2B dots where copper has corroded)
  for (let i = 0; i < 48; i++) {
    let a = random(360);
    let rad = r * sqrt(random(0.08, 0.94));
    let px = cx + cos(a) * rad;
    let py = cy + sin(a) * rad;
    let col = random() < 0.45 ? PALETTE.viridianDeep : (random() < 0.6 ? PALETTE.tarnishDeep : PALETTE.parisChalk);
    brush.set("rotring", col, random(0.45, 1.1));
    brush.line(px, py, px + random(-1.8, 1.8), py + random(-1.8, 1.8));
  }

  // 2. Spun copper concentric lathe rings in crisp 2H / lathe_needle
  const ringCount = floor(r / 11);
  for (let i = 2; i < ringCount; i++) {
    let ringR = (i / ringCount) * r * 0.96;
    let segs = floor(random(2, 5));
    for (let s = 0; s < segs; s++) {
      let aStart = random(360);
      let aEnd = aStart + random(25, 78);
      let isSpec = (aStart > -15 && aStart < 75);
      let col = isSpec ? PALETTE.windowGlow : (random() < 0.5 ? PALETTE.copperDark : PALETTE.salmonLight);
      brush.set("lathe_needle", col, random(0.55, 0.95));
      brush.arc(cx, cy, ringR, aStart, aEnd);
    }
  }

  // 3. Crisp graphite outer base bevel contour
  brush.set("2B", PALETTE.tarnishDeep, 0.95);
  brush.circle(cx, cy, r, 0.015);
  brush.set("HB", PALETTE.copperDark, 0.65);
  brush.arc(cx, cy, r * 0.97, 110, 310);
  brush.set("2H", PALETTE.windowSpec, 0.75);
  brush.arc(cx, cy, r * 0.985, -35, 65);
}

function drawPanDents(pan) {
  const { cx, cy, r, dents, verdigrisSeed } = pan;
  resetBrushState();

  // Crisp pencil dents & hammer facets across the copper base and rim
  for (let i = 0; i < dents; i++) {
    let a = (i / dents) * 360 + random(-18, 18);
    let dist = r * random(0.28, 0.88);
    let dx = cx + cos(a) * dist;
    let dy = cy + sin(a) * dist;
    let dRx = random(9, 22);
    let dRy = dRx * random(0.55, 0.82);
    let dRot = a + 90 + random(-20, 20);

    let dentPts = makeOrganicBlob(dx, dy, dRx, dRy, 8, 0.22, verdigrisSeed + 300 + i * 7, dRot);

    // Dark concave shadow half of the dent
    brush.fill(PALETTE.tarnishDeep, 115);
    brush.fillBleed(0.12, "in");
    brush.fillTexture(0.7, 0.8);
    drawPoly(dentPts, 0.15);
    resetBrushState();

    // Often a tiny pool of Paris green or malachite trapped inside the dent
    if (i % 2 === 0) {
      let oxPts = makeOrganicBlob(dx - 2, dy - 2, dRx * 0.6, dRy * 0.6, 7, 0.2, verdigrisSeed + 350 + i, dRot);
      brush.fill(PALETTE.parisGreen, 150);
      brush.fillBleed(0.15, "out");
      drawPoly(oxPts, 0.2);
      resetBrushState();
    }

    // Crisp 2B graphite crease lines defining the sharp dent ridge
    brush.set("2B", PALETTE.tarnishDeep, 0.85);
    for (let k = 0; k < 4; k++) {
      let p1 = dentPts[k];
      let p2 = dentPts[(k + 1) % dentPts.length];
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
    // Fine pencil hatching inside the dent hollow
    brush.set("2H", PALETTE.pencilDark, 0.5);
    brush.line(dx - dRx * 0.5, dy - dRy * 0.2, dx + dRx * 0.2, dy + dRy * 0.3);
    brush.line(dx - dRx * 0.3, dy + dRy * 0.1, dx + dRx * 0.4, dy + dRy * 0.4);

    // Bright specular catch-light on the opposite rim of the dent
    brush.set("cpencil", (a > -20 && a < 85) ? PALETTE.windowSpec : PALETTE.salmonLight, 0.9);
    for (let k = 4; k < 7; k++) {
      let p1 = dentPts[k];
      let p2 = dentPts[(k + 1) % dentPts.length];
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

// ============================================================================
// 4. CRISP PENCIL RIVETED HANDLES & MOUNTING FLANGES (ÉCUSSONS)
// ============================================================================

function drawRivetedHandle(pan) {
  const { cx, cy, r, handle, verdigrisSeed } = pan;
  const { attachAngle, endX, endY, width: hW, rivets, flangeType } = handle;

  // Attachment point just inside the rim of the pan
  const ax = cx + cos(attachAngle) * (r * 0.86);
  const ay = cy + sin(attachAngle) * (r * 0.86);

  const dirX = endX - ax;
  const dirY = endY - ay;
  const len = sqrt(dirX * dirX + dirY * dirY);
  const ux = dirX / len;
  const uy = dirY / len;
  const nx = -uy;
  const ny = ux;

  resetBrushState();

  // 1. Cast shadow of the handle shaft onto the wall / underlying pans
  brush.fill(PALETTE.shadowDeep, 95);
  brush.fillBleed(0.2, "out");
  brush.fillTexture(0.7, 0.65);
  drawPoly([
    [ax + nx * hW * 0.7 - 10, ay + ny * hW * 0.7 + 14],
    [endX + nx * hW * 0.55 - 10, endY + ny * hW * 0.55 + 14],
    [endX - nx * hW * 0.55 - 10, endY - ny * hW * 0.55 + 14],
    [ax - nx * hW * 0.7 - 10, ay - ny * hW * 0.7 + 14]
  ], 0.1);
  resetBrushState();

  // 2. Verdigris halo weeping around the riveted flange on the copper pan
  brush.fill(PALETTE.viridian, 165);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.92, 0.94);
  let flangeHalo = makeOrganicBlob(
    ax - ux * 16, ay - uy * 16,
    hW * 2.1, hW * 1.65,
    18, 0.32, verdigrisSeed + 400
  );
  drawPoly(flangeHalo, 0.25);

  brush.fill(PALETTE.parisGreen, 175);
  brush.fillBleed(0.2, "in");
  let flangeCrust = makeOrganicBlob(
    ax - ux * 14, ay - uy * 14,
    hW * 1.45, hW * 1.15,
    14, 0.28, verdigrisSeed + 410
  );
  drawPoly(flangeCrust, 0.25);
  resetBrushState();
  drawBackrunTideLine(flangeHalo, PALETTE.viridianDeep, PALETTE.parisPowder, verdigrisSeed + 420);

  // 3. Build the geometry of the mounting flange (`écusson`) + forged iron shaft
  const fSpread = hW * 1.65;
  const fDepth = hW * 1.75;
  let flangePts;
  if (flangeType === "heart") {
    flangePts = [
      [ax + ux * 12 + nx * hW * 0.52, ay + uy * 12 + ny * hW * 0.52],
      [ax - ux * (fDepth * 0.35) + nx * fSpread, ay - uy * (fDepth * 0.35) + ny * fSpread],
      [ax - ux * (fDepth * 0.85) + nx * (fSpread * 0.65), ay - uy * (fDepth * 0.85) + ny * (fSpread * 0.65)],
      [ax - ux * (fDepth * 1.15), ay - uy * (fDepth * 1.15)],
      [ax - ux * (fDepth * 0.85) - nx * (fSpread * 0.65), ay - uy * (fDepth * 0.85) - ny * (fSpread * 0.65)],
      [ax - ux * (fDepth * 0.35) - nx * fSpread, ay - uy * (fDepth * 0.35) - ny * fSpread],
      [ax + ux * 12 - nx * hW * 0.52, ay + uy * 12 - ny * hW * 0.52]
    ];
  } else {
    // Classic French triangular rivet plate
    flangePts = [
      [ax + ux * 12 + nx * hW * 0.5, ay + uy * 12 + ny * hW * 0.5],
      [ax - ux * (fDepth * 0.45) + nx * fSpread, ay - uy * (fDepth * 0.45) + ny * fSpread],
      [ax - ux * (fDepth * 1.2), ay - uy * (fDepth * 1.2)],
      [ax - ux * (fDepth * 0.45) - nx * fSpread, ay - uy * (fDepth * 0.45) - ny * fSpread],
      [ax + ux * 12 - nx * hW * 0.5, ay + uy * 12 - ny * hW * 0.5]
    ];
  }

  // Slightly curved forged shaft vertices from ax to endX
  const midX = (ax + endX) * 0.5 + nx * 6;
  const midY = (ay + endY) * 0.5 + ny * 6;
  const shaftPts = [
    [ax + ux * 8 + nx * hW * 0.48, ay + uy * 8 + ny * hW * 0.48],
    [midX + nx * hW * 0.38, midY + ny * hW * 0.38],
    [endX - ux * 18 + nx * hW * 0.52, endY - uy * 18 + ny * hW * 0.52],
    [endX + ux * 12 + nx * hW * 0.35, endY + uy * 12 + ny * hW * 0.35],
    [endX + ux * 12 - nx * hW * 0.35, endY + uy * 12 - ny * hW * 0.35],
    [endX - ux * 18 - nx * hW * 0.52, endY - uy * 18 - ny * hW * 0.52],
    [midX - nx * hW * 0.38, midY - ny * hW * 0.38],
    [ax + ux * 8 - nx * hW * 0.48, ay + uy * 8 - ny * hW * 0.48]
  ];

  // Opaque base wash for flange and shaft
  brush.wash(PALETTE.ironMid, 235);
  drawPoly(flangePts, 0.18);
  drawPoly(shaftPts, 0.18);
  resetBrushState();

  // Watercolour iron & warm rust-earth modulation on the handle
  brush.fill(PALETTE.ironDark, 155);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.8, 0.85);
  drawPoly(shaftPts, 0.18);
  resetBrushState();

  // Crisp pencil cross-hatching along the forged iron handle (`brush.hatch`)
  let handleAngle = atan2(dirY, dirX);
  brush.hatchStyle("2H", PALETTE.pencilDark, 0.65);
  brush.hatch(4.5, handleAngle + 35, { rand: 0.08 });
  drawPoly(shaftPts, 0.15);
  drawPoly(flangePts, 0.15);
  resetBrushState();

  // Crisp structural graphite outlines (`2B` and `HB`)
  brush.set("2B", PALETTE.ironDark, 1.05);
  drawPoly(flangePts, 0.18);
  drawPoly(shaftPts, 0.18);

  // Longitudinal bevel highlight & forged chamfer lines in crisp pencil
  brush.set("HB", PALETTE.ironHighlight, 0.9);
  brush.spline([
    [ax + ux * 10 + nx * hW * 0.22, ay + uy * 10 + ny * hW * 0.22, 0.5],
    [midX + nx * hW * 0.16, midY + ny * hW * 0.16, 1.0],
    [endX - ux * 20 + nx * hW * 0.2, endY - uy * 20 + ny * hW * 0.2, 0.5]
  ], 0.3);

  brush.set("2H", PALETTE.windowSpec, 0.65);
  brush.line(
    ax + ux * 16 + nx * hW * 0.26, ay + uy * 16 + ny * hW * 0.26,
    midX + nx * hW * 0.2, midY + ny * hW * 0.2
  );

  // Hanging eyelet hole at the tip of the handle (`endX, endY`)
  const eyeX = endX - ux * 4;
  const eyeY = endY - uy * 4;
  resetBrushState();
  brush.wash(PALETTE.plasterMid, 220);
  let eyePts = makeOrganicBlob(eyeX, eyeY, hW * 0.26, hW * 0.38, 12, 0.06, verdigrisSeed + 430, handleAngle);
  drawPoly(eyePts, 0.2);
  resetBrushState();

  brush.set("2B", PALETTE.ironDark, 1.0);
  drawPoly(eyePts, 0.2);
  brush.set("2H", PALETTE.windowSpec, 0.7);
  brush.arc(eyeX, eyeY, hW * 0.32, handleAngle - 60, handleAngle + 60);

  // 4. HYPER-DETAILED RIVETS ON THE MOUNTING FLANGE
  let rivetCoords = [];
  if (rivets === 3) {
    rivetCoords.push([
      ax - ux * (fDepth * 0.35) + nx * (fSpread * 0.54),
      ay - uy * (fDepth * 0.35) + ny * (fSpread * 0.54)
    ]);
    rivetCoords.push([
      ax - ux * (fDepth * 0.35) - nx * (fSpread * 0.54),
      ay - uy * (fDepth * 0.35) - ny * (fSpread * 0.54)
    ]);
    rivetCoords.push([
      ax - ux * (fDepth * 0.82),
      ay - uy * (fDepth * 0.82)
    ]);
  } else {
    rivetCoords.push([
      ax - ux * (fDepth * 0.42) + nx * (fSpread * 0.45),
      ay - uy * (fDepth * 0.42) + ny * (fSpread * 0.45)
    ]);
    rivetCoords.push([
      ax - ux * (fDepth * 0.42) - nx * (fSpread * 0.45),
      ay - uy * (fDepth * 0.42) - ny * (fSpread * 0.45)
    ]);
  }

  const rivR = hW * 0.32;
  for (let i = 0; i < rivetCoords.length; i++) {
    let [rx, ry] = rivetCoords[i];
    drawSingleRivet(rx, ry, rivR, verdigrisSeed + 450 + i * 13);
  }
}

function drawSingleRivet(rx, ry, rivR, seed) {
  resetBrushState();

  // Powdery Paris green crust ring weeping around the rivet head
  brush.fill(PALETTE.parisPowder, 185);
  brush.fillBleed(0.18, "out");
  let crustHalo = makeOrganicBlob(rx, ry + 1.5, rivR * 1.48, rivR * 1.48, 12, 0.25, seed);
  drawPoly(crustHalo, 0.25);
  resetBrushState();

  // Domed copper/bronze rivet head wash
  brush.wash(PALETTE.copperWarm, 235);
  let rivHead = makeOrganicBlob(rx, ry, rivR, rivR, 14, 0.08, seed + 1);
  drawPoly(rivHead, 0.25);
  resetBrushState();

  // Dark shadow crescent on lower-left of rivet dome
  brush.fill(PALETTE.tarnishDeep, 175);
  brush.fillBleed(0.1, "in");
  let shPts = makeCrescentRing(rx, ry, rivR, rivR * 0.35, 65, 235, 8, 0.08, seed + 2);
  drawPoly(shPts, 0.2);
  resetBrushState();

  // Crisp 2B pencil ring & hammer facets on the rivet head
  brush.set("2B", PALETTE.ironDark, 0.95);
  brush.circle(rx, ry, rivR, 0.05);
  brush.set("2H", PALETTE.pencilDark, 0.55);
  brush.line(rx - rivR * 0.5, ry + rivR * 0.2, rx + rivR * 0.2, ry + rivR * 0.5);
  brush.line(rx - rivR * 0.2, ry - rivR * 0.5, rx + rivR * 0.5, ry - rivR * 0.1);

  // Hot orange & pale specular glint on upper-right of the rivet dome
  brush.set("cpencil", PALETTE.hotAmber, 1.0);
  brush.arc(rx, ry, rivR * 0.65, -75, 25);
  brush.set("cpencil", PALETTE.windowSpec, 1.15);
  brush.line(rx + rivR * 0.2, ry - rivR * 0.35, rx + rivR * 0.42, ry - rivR * 0.15);
}

function drawBottomHelperLoop(pan) {
  const { cx, cy, r, verdigrisSeed } = pan;
  const lx = cx + 10;
  const ly = cy + r * 0.92;

  resetBrushState();
  // Verdigris stain under the bottom helper bracket
  brush.fill(PALETTE.malachite, 160);
  brush.fillBleed(0.28, "out");
  let ox = makeOrganicBlob(lx, ly - 10, 42, 24, 14, 0.3, verdigrisSeed + 500);
  drawPoly(ox, 0.25);
  resetBrushState();

  // Riveted horizontal bracket plate
  let platePts = [
    [lx - 34, ly - 12], [lx + 34, ly - 12],
    [lx + 28, ly + 6], [lx - 28, ly + 6]
  ];
  brush.wash(PALETTE.ironMid, 230);
  drawPoly(platePts, 0.15);
  resetBrushState();

  brush.set("2B", PALETTE.ironDark, 0.95);
  drawPoly(platePts, 0.15);

  drawSingleRivet(lx - 18, ly - 3, 6.5, verdigrisSeed + 510);
  drawSingleRivet(lx + 18, ly - 3, 6.5, verdigrisSeed + 520);

  // Forged iron D-ring loop hanging below the pan bottom
