  drawBlurredWindowReflection(ladlePan);
  drawVerdigrisBlossoms(ladlePan);
  drawPanSurfaceDetail(ladlePan);
  drawPanDents(ladlePan);

  // Perforated skimmer holes in crisp pencil & dark umber
  for (let ring = 1; ring <= 2; ring++) {
    let hr = ring * (bowlR * 0.3);
