// =============================================================================
// MOCHE RUNNER: HYPERREALIST SPRINTER'S CALF & SPIKED SHOE
// Fine iron-oxide red-brown penwork on warm cream slip ground (no tone wash)
// Wrapped around an implied curved ceramic vessel surface
// =============================================================================

const PALETTE = {
  slipBg: "#F2E6CE",        // Warm Moche kaolin cream slip ground
  slipBurnish: "#E5D5B5",   // Ultra-faint wheel burnish striation on clay
  slipRim: "#D8C49E",       // Faint outer vessel curvature edge lines
  oxideDeep: "#4A140B",     // Deepest roasted iron-oxide (structural contours)
  oxideDark: "#681F13",     // Primary iron-oxide red-brown pen
  oxideMid: "#822C1D",      // Mid-tone red-brown (dense parallel modeling)
  oxideLight: "#9E412E",    // Delicate secondary cross-contour hairlines
  accent: "#C04E22"         // Single terracotta-cinnabar accent
};

// -----------------------------------------------------------------------------
// 3D IMPLIED CURVED VESSEL PROJECTION
// Maps canonical (x, y) in [0..1200, 0..1200] onto a globular/cylindrical
// Moche stirrup-spout vessel surface so edges bend and foreshorten naturally.
// -----------------------------------------------------------------------------
function vesselPt(x, y) {
  const cx = 600;
  const cy = 600;
  const halfSpan = 520;

  let u = (x - cx) / halfSpan;
  let v = (y - cy) / halfSpan;

  // Clamp u slightly beyond [-1, 1] for safety
  let uClamped = constrain(u, -1.08, 1.08);

  // Longitude around the curved ceramic body (in degrees, angleMode is DEGREES)
  let lon = uClamped * 68;
  let sinLon = sin(lon) / sin(68);
  let cosLon = cos(lon);

  // Globular Moche belly profile: slightly fuller at mid-lower belly, tapering at shoulder & base
  let bellyProfile = 1.0 - 0.13 * v * v + 0.025 * v;

  // Cylindrical horizontal foreshortening + barrel taper
  let xProj = cx + halfSpan * sinLon * bellyProfile;

  // Vertical ring curvature: top bands bow gently along upper shoulder dome,
  // equatorial and bottom track bands curve upward toward vessel sides
  let arch = 1.0 - cosLon;
  let yCurve = -56 * arch * (0.30 + 0.72 * v);
  let yProj = y + yCurve;

  return [xProj, yProj];
}

// Local horizontal foreshortening factor (1 at center, ~0.37 at vessel edge)
function vesselForeshorten(x) {
  let u = constrain((x - 600) / 520, -1.05, 1.05);
  return max(0.32, cos(u * 68));
}

// Draw a warped polyline/spline on the vessel surface
function drawWarpedSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let mapped = [];
  for (let i = 0; i < pts.length; i++) {
    let p = vesselPt(pts[i][0], pts[i][1]);
    if (pts[i].length > 2) {
      mapped.push([p[0], p[1], pts[i][2]]);
    } else {
      mapped.push([p[0], p[1]]);
    }
  }
  if (mapped.length === 2) {
    brush.line(mapped[0][0], mapped[0][1], mapped[1][0], mapped[1][1]);
  } else {
    brush.spline(mapped, curvature);
  }
}

// Sample a dense warped curve between two points with optional normal bulge
function drawWarpedArc(x1, y1, x2, y2, bulge = 0, steps = 12, pStart = 0.8, pMid = 1.0, pEnd = 0.8) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy) || 1;
  let nx = -dy / len;
  let ny = dx / len;
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let s = sin(t * 180);
    let px = lerp(x1, x2, t) + nx * bulge * s;
    let py = lerp(y1, y2, t) + ny * bulge * s;
    let pr = t < 0.5 ? lerp(pStart, pMid, t * 2) : lerp(pMid, pEnd, (t - 0.5) * 2);
    pts.push([px, py, pr]);
  }
  drawWarpedSpline(pts, 0.5);
}

// Evaluate Catmull-Rom / cardinal smooth curve at parameter t in [0, 1]
function evalCurve(ctrlPts, t) {
  let n = ctrlPts.length - 1;
  let f = constrain(t, 0, 1) * n;
  let idx = min(floor(f), n - 1);
  let lt = f - idx;

  let p0 = ctrlPts[max(0, idx - 1)];
  let p1 = ctrlPts[idx];
  let p2 = ctrlPts[min(n, idx + 1)];
  let p3 = ctrlPts[min(n, idx + 2)];

  let lt2 = lt * lt;
  let lt3 = lt2 * lt;

  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * lt +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * lt2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * lt3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * lt +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * lt2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * lt3
  );
  return [x, y];
}

// Draw a foreshortened dot or small Moche bead on the curved vessel
function drawWarpedBead(x, y, r, filled = true) {
  let c = vesselPt(x, y);
  let fs = vesselForeshorten(x);
  let pts = [];
  let segs = 10;
  for (let i = 0; i < segs; i++) {
    let ang = (i / segs) * 360;
    pts.push([c[0] + cos(ang) * r * fs, c[1] + sin(ang) * r]);
  }
  pts.push(pts[0]);
  brush.spline(pts, 0.5);

  if (filled && r > 1.8) {
    let rIn = r * 0.52;
    let ptsIn = [];
    for (let i = 0; i < 8; i++) {
      let ang = (i / 8) * 360;
      ptsIn.push([c[0] + cos(ang) * rIn * fs, c[1] + sin(ang) * rIn]);
    }
    ptsIn.push(ptsIn[0]);
    brush.spline(ptsIn, 0.5);
  }
}

