function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.slipBg);
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noField();

  // 1. Subtle ceramic slip burnish & curved vessel meridian edges
  drawCeramicSlipGround();

  // 2. Upper & Lower Moche dotted borders + Stylised Track Lines register
  drawFramingRegisters();

  // 3. Background Moche kinetic stride glyphs & track impact dust volutes
