// =============================================================================
// 1. CERAMIC SLIP GROUND & VESSEL CURVATURE SILHOUETTE
// =============================================================================
function drawCeramicSlipGround() {
  // Faint horizontal wheel-burnish striations wrapping around the clay vessel
  brush.set("oxide_micro", PALETTE.slipBurnish, 0.55);
  for (let y = 90; y <= 1110; y += 16) {
    let xStart = 95 + random(0, 45);
    let xEnd = 1105 - random(0, 45);
    let pts = [];
    for (let x = xStart; x <= xEnd; x += 40) {
      pts.push([x, y + sin(x * 0.8 + y) * 0.8, 0.7]);
    }
    drawWarpedSpline(pts, 0.4);
  }

  // Left and right curved vessel wall meridian boundaries
  brush.set("oxide_pen", PALETTE.oxideMid, 0.75);
  for (let side of [-1, 1]) {
    let xEdge = 600 + side * 518;
    let xInner = 600 + side * 504;
    let ptsOuter = [];
    let ptsInner = [];
    for (let y = 92; y <= 1108; y += 24) {
      ptsOuter.push([xEdge, y, 0.9]);
      ptsInner.push([xInner, y, 0.7]);
    }
    drawWarpedSpline(ptsOuter, 0.5);
    brush.set("oxide_hair", PALETTE.oxideMid, 0.65);
    drawWarpedSpline(ptsInner, 0.5);

    // Small vertical Moche dot-bead border along the curved left/right vessel edges
    brush.set("oxide_hair", PALETTE.oxideDark, 0.65);
    for (let y = 198; y <= 902; y += 18) {
      drawWarpedBead(600 + side * 511, y, 2.3, false);
    }
    brush.set("oxide_pen", PALETTE.oxideMid, 0.75);
  }
}

// =============================================================================
// 2. DOTTED BORDERS & BAND OF STYLISED TRACK LINES
// =============================================================================
function drawFramingRegisters() {
  // Helper to draw a full-width horizontal line across the vessel at canonical y
  const drawLatLine = (y, brushName, col, w) => {
    brush.set(brushName, col, w);
    let pts = [];
    for (let x = 82; x <= 1118; x += 28) {
      pts.push([x, y, 0.9]);
    }
    drawWarpedSpline(pts, 0.5);
  };

  // --- UPPER REGISTER (y = 88 to 192) ---
  drawLatLine(88, "oxide_calligraphic", PALETTE.oxideDeep, 1.0);
  drawLatLine(95, "oxide_hair", PALETTE.oxideDark, 0.8);

  // Upper small dotted border (double staggered row of ceramic slip dots)
  brush.set("oxide_pen", PALETTE.oxideDark, 0.7);
  for (let x = 96; x <= 1104; x += 14) {
    drawWarpedBead(x, 108, 3.2, true);
    drawWarpedBead(x + 7, 118, 2.2, false);
  }

  drawLatLine(129, "oxide_pen", PALETTE.oxideDark, 0.85);
  drawLatLine(134, "oxide_hair", PALETTE.accent, 0.85);

  // Upper band of stylised Moche step-fret & sprint lane stagger blocks (y = 136..174)
  let stepW = 56;
  for (let x = 92; x < 1090; x += stepW) {
    let x2 = min(1108, x + stepW);
    let xm = (x + x2) * 0.5;

    // Step-fret diagonal & stepped runner terrace in dark iron-oxide
    brush.set("oxide_pen", PALETTE.oxideDark, 0.75);
    drawWarpedSpline([[x, 172], [x + 12, 172], [x + 12, 160], [x + 24, 160], [x + 24, 148], [xm + 6, 148], [xm + 6, 138], [x2, 138]], 0.1);

    // Parallel hairline hatching inside the lower terrace triangle
    brush.set("oxide_hair", PALETTE.oxideMid, 0.65);
    for (let h = 4; h < 28; h += 3.5) {
      drawWarpedArc(x + h, 172, x2 - 4, 138 + h * 1.1, 0, 4);
    }

    // Terracotta accent sprint-gate chevron
    brush.set("oxide_hair", PALETTE.accent, 0.85);
    drawWarpedSpline([[x + 4, 142], [x + 16, 142], [x + 8, 156]], 0.1);
  }

  drawLatLine(175, "oxide_pen", PALETTE.oxideDark, 0.85);
  // Second upper dotted border
  brush.set("oxide_hair", PALETTE.oxideDark, 0.75);
  for (let x = 94; x <= 1106; x += 12) {
    drawWarpedBead(x, 184, 2.4, true);
  }
  drawLatLine(192, "oxide_calligraphic", PALETTE.oxideDeep, 0.95);

  // --- LOWER REGISTER: BAND OF STYLISED TRACK LINES & DOTTED BORDERS (y = 910 to 1112) ---
  // Top edge of the running track (ground contact line for the sprinter's spikes)
  drawLatLine(912, "oxide_calligraphic", PALETTE.oxideDeep, 1.1);
  drawLatLine(917, "oxide_hair", PALETTE.accent, 0.9);

  // 6 Perspective Running Track Lanes (y = 917 to 1012)
  const laneYs = [917, 930, 945, 962, 981, 1002];
  for (let l = 0; l < laneYs.length - 1; l++) {
    let yTop = laneYs[l];
    let yBot = laneYs[l + 1];
    let yMid = (yTop + yBot) * 0.5;

    // Crisp double lane boundary line (like painted synthetic track lane lines)
    drawLatLine(yBot, "oxide_pen", PALETTE.oxideDark, 0.9);
    drawLatLine(yBot - 2.8, "oxide_hair", PALETTE.oxideMid, 0.65);

    // Fine rubberized Mondo track texture: hundreds of short horizontal dash-Pick strokes
    brush.set("oxide_micro", PALETTE.oxideLight, 0.55);
    let stepX = 18 + l * 2;
    for (let x = 92 + (l * 7) % 15; x <= 1104; x += stepX) {
      drawWarpedArc(x, yMid - 2, x + 9, yMid - 2, 0, 3);
      drawWarpedArc(x + 5, yMid + 2.5, x + 13, yMid + 2.5, 0, 3);
    }

    // Stylised Moche-Track Stagger Marks, Relay Zones & Hurdle Ticks in each lane
    let staggerX = 165 + l * 155;
    brush.set("oxide_pen", PALETTE.accent, 0.9);
    // Angled start-line stagger box
    for (let k = -8; k <= 8; k += 3.2) {
      drawWarpedArc(staggerX + k - 6, yBot, staggerX + k + 6, yTop, 0, 3);
    }
    // Moche bar-and-dot lane number tally next to the stagger line
    brush.set("oxide_pen", PALETTE.oxideDeep, 0.8);
    let tallyX = staggerX + 26;
    for (let d = 0; d <= l; d++) {
      drawWarpedBead(tallyX + d * 7, yMid, 2.1, true);
    }

    // Opposite-side relay exchange chevron ticks
    let relayX = 1040 - l * 130;
    brush.set("oxide_hair", PALETTE.oxideDark, 0.8);
    drawWarpedSpline([[relayX - 10, yTop + 2], [relayX, yMid], [relayX - 10, yBot - 2]], 0.1);
    drawWarpedSpline([[relayX - 4, yTop + 2], [relayX + 6, yMid], [relayX - 4, yBot - 2]], 0.1);
  }

  // Diagonal perspective finish-line tape / timing grid cutting across all lanes on the right
  brush.set("oxide_hair", PALETTE.oxideDark, 0.75);
  for (let offset = 0; offset <= 36; offset += 4.5) {
    drawWarpedArc(895 + offset, 912, 955 + offset, 1002, 0, 8);
  }

  // Lower Small Dotted Border Band (y = 1008 to 1042)
  drawLatLine(1010, "oxide_calligraphic", PALETTE.oxideDeep, 0.95);
  brush.set("oxide_pen", PALETTE.oxideDark, 0.75);
  for (let x = 94; x <= 1106; x += 13) {
    drawWarpedBead(x, 1020, 3.0, true);
    drawWarpedBead(x + 6.5, 1030, 2.3, false);
  }
  drawLatLine(1040, "oxide_pen", PALETTE.oxideDark, 0.85);
  drawLatLine(1045, "oxide_hair", PALETTE.accent, 0.85);

  // Bottom Moche Serrated Runner Wave Band (y = 1046 to 1094)
  let waveW = 44;
  for (let x = 90; x < 1095; x += waveW) {
    let x2 = min(1108, x + waveW);
    // Interlocking Moche wave scroll
    brush.set("oxide_pen", PALETTE.oxideDark, 0.8);
    drawWarpedSpline([
      [x, 1092], [x + 10, 1068], [x + 24, 1054],
      [x + 36, 1058], [x + 38, 1072], [x + 28, 1078],
      [x + 20, 1072], [x + 24, 1064]
    ], 0.55);

    // Fine parallel line shading under the wave crest
    brush.set("oxide_hair", PALETTE.oxideMid, 0.6);
    for (let s = 1; s <= 5; s++) {
      drawWarpedArc(x + 6 + s * 4, 1092, x + 20 + s * 3.5, 1066 + s * 4, 0, 4);
    }
  }

  drawLatLine(1094, "oxide_pen", PALETTE.oxideDark, 0.85);
  // Final bottom dotted bead border
  brush.set("oxide_hair", PALETTE.oxideDark, 0.7);
  for (let x = 96; x <= 1104; x += 14) {
    drawWarpedBead(x, 1103, 2.2, true);
  }
  drawLatLine(1112, "oxide_calligraphic", PALETTE.oxideDeep, 1.05);
}

// =============================================================================
// 3. MOCHE KINETIC STRIDE VOLUTES & TRACK CONTACT BURSTS
// =============================================================================
function drawMocheKineticAccents() {
  // Helper to draw a calligraphic spiral volute (classic Moche motion motif)
  const drawVolute = (cx, cy, rMax, dir, col, w) => {
    brush.set("oxide_hair", col, w);
    let pts = [];
    for (let a = 0; a <= 580; a += 20) {
      let frac = 1.0 - a / 620;
      let r = rMax * frac;
      pts.push([cx + cos(a * dir) * r, cy + sin(a * dir) * r, 0.5 + 0.5 * frac]);
    }
    drawWarpedSpline(pts, 0.6);
  };

  // Track-spike impact spirals & kinetic turf-dust lines under the forefoot (x = 610..910, y = 890..915)
  const spikeContactXs = [648, 694, 742, 790, 836, 878];
  for (let i = 0; i < spikeContactXs.length; i++) {
    let sx = spikeContactXs[i];
    // Radiating pressure lines into the track rubber
    brush.set("oxide_micro", PALETTE.oxideMid, 0.7);
    for (let a = 195; a <= 345; a += 25) {
      let rad = 14 + (i % 2) * 6;
      drawWarpedArc(sx, 912, sx + cos(a) * rad, 912 + sin(a) * rad * 0.45, 0, 4);
    }
    // Tiny Moche dust volute kicking backward (to the left) from each spike tip
    drawVolute(sx - 18, 902 - (i % 2) * 5, 6.5, -1, PALETTE.accent, 0.75);
  }

  // Trailing air-wake slipstream lines behind the heel tab and Achilles tendon
  brush.set("oxide_micro", PALETTE.oxideLight, 0.65);
  for (let i = 0; i < 9; i++) {
    let yBase = 480 + i * 32;
    let xBase = 365 - i * 11;
    let len = 55 + (i % 3) * 28;
    drawWarpedArc(xBase - 28, yBase, xBase - 28 - len, yBase + 14, -4, 8, 0.3, 0.85, 0.2);
    if (i % 2 === 0) {
      drawVolute(xBase - 28 - len - 8, yBase + 10, 9, 1, PALETTE.oxideMid, 0.65);
    }
  }

  // Sparse Moche dotted ceramic rosettes in the open upper-left & mid-right slip space
  const rosettes = [
    [225, 310, 14], [185, 445, 11], [310, 245, 10],
    [985, 380, 13], [945, 520, 11], [1015, 650, 12], [205, 815, 11]
  ];
  for (let [rx, ry, rr] of rosettes) {
    brush.set("oxide_hair", PALETTE.oxideMid, 0.7);
    drawWarpedBead(rx, ry, 3.2, true);
    for (let a = 0; a < 360; a += 45) {
      drawWarpedBead(rx + cos(a) * rr, ry + sin(a) * rr, 2.0, false);
    }
  }
}

// =============================================================================
// 4. HYPERREALIST TAWT CALF, ACHILLES TENDON & ANKLE (LINE ALONE)
// =============================================================================
function drawSprinterCalfAndTendon() {
  // Anatomical control points from t = 0 (top register border y=192) to t = 1 (ankle/heel collar)
  // Posterior border: popliteal fossa -> bulging lateral gastrocnemius -> myotendinous junction -> taut Achilles -> calcaneus
  const postCtrl = [
    [685, 192],
    [575, 248],
    [482, 322],
    [442, 392], // Peak bulge of contracted lateral gastrocnemius
    [446, 448], // Sharp inward step at myotendinous junction
    [426, 495], // Upper Achilles + soleus border
    [392, 552], // Razor-taut mid Achilles tendon cord
    [354, 608], // Lower Achilles tendon approaching calcaneus
    [325, 652]  // Insertion into heel collar
  ];

  // Medial head of gastrocnemius peeking behind the upper-left posterior contour (t in [0, 0.52])
  const medialGastrocCtrl = [
    [662, 192],
    [542, 244],
    [445, 318],
    [416, 382],
    [444, 438]
  ];

  // Anterior border: tibial tuberosity -> anterior shin crest -> extensor retinaculum at ankle crease
  const antCtrl = [
    [912, 192],
    [846, 268],
    [774, 352],
    [698, 438],
    [626, 518],
    [562, 588],
    [522, 636]  // Anterior ankle / shoe throat junction
  ];

  // Internal anatomical ridge 1: Gastrocnemius lower aponeurosis / Soleus boundary + Achilles anterior edge
  const gastrocSoleusCtrl = [
    [775, 192],
    [682, 265],
    [588, 348],
    [515, 422], // Tip of lateral gastrocnemius belly V-cleft
    [458, 458], // Myotendinous junction neck
    [448, 505], // Anterior edge of Achilles tendon
    [418, 562], // Kager's triangle hollow behind malleolus
    [386, 616],
    [358, 656]
  ];

  // Internal anatomical ridge 2: Fibularis (Peroneus) longus / Anterior Tibialis intermuscular septum
  // Leads straight down to the prominent Lateral Malleolus (outer ankle bone)
  const septumCtrl = [
    [848, 192],
    [772, 272],
    [694, 358],
    [618, 444],
    [544, 526],
    [484, 594],
    [452, 646]  // Center-front of Lateral Malleolus
  ];

  // --- A. MEDIAL GASTROCNEMIUS CRESCENT (Dense dark-oxide receding lines) ---
  brush.set("oxide_hair", PALETTE.oxideDark, 0.78);
  let stepsMed = 68;
  for (let i = 2; i < stepsMed; i++) {
    let t = i / stepsMed;
    let pOuter = evalCurve(medialGastrocCtrl, t);
    let pInner = evalCurve(postCtrl, t * 0.51);
    drawWarpedArc(pOuter[0], pOuter[1], pInner[0], pInner[1], -3.5, 6, 0.9, 1.0, 0.6);
  }
  brush.set("oxide_pen", PALETTE.oxideDeep, 0.85);
  let medOutline = [];
  for (let i = 0; i <= 32; i++) medOutline.push(evalCurve(medialGastrocCtrl, i / 32));
  drawWarpedSpline(medOutline, 0.5);

  // --- B. LATERAL GASTROCNEMIUS BELLY (t = 0 to 0.50 between postCtrl & gastrocSoleusCtrl) ---
  // 1. Sweeping pennate muscle fiber striation lines (longitudinal curved fibers)
  brush.set("oxide_micro", PALETTE.oxideMid, 0.72);
  let numFibers = 34;
  for (let f = 1; f < numFibers; f++) {
    let u = f / numFibers;
    let fiberPts = [];
    let tMax = 0.48 - 0.06 * sin(u * 180);
    for (let k = 0; k <= 18; k++) {
      let t = (k / 18) * tMax;
      let pPost = evalCurve(postCtrl, t);
      let pMid = evalCurve(gastrocSoleusCtrl, t);
      // Pennate feathering: fibers curve inward toward the lower tendon aponeurosis
      let uCurve = pow(u, 0.88 + 0.25 * (t / tMax));
      let px = lerp(pPost[0], pMid[0], uCurve);
      let py = lerp(pPost[1], pMid[1], uCurve);
      fiberPts.push([px, py, 0.55 + 0.45 * sin((k / 18) * 180)]);
    }
    drawWarpedSpline(fiberPts, 0.5);
  }

  // 2. Hundreds of hair-thin cross-contour strokes modeling the 3D cylindrical volume of the gastrocnemius
  let numGastrocCross = 115;
  for (let i = 1; i <= numGastrocCross; i++) {
    let t = (i / numGastrocCross) * 0.49;
    let pPost = evalCurve(postCtrl, t);
    let pMid = evalCurve(gastrocSoleusCtrl, t);

    // Primary cross-contour from posterior contour across the muscle belly
    let reach = 0.62 + 0.32 * pow(t / 0.49, 1.4); // Denser/wider near the lower overhang of the muscle belly
    let pEnd = [lerp(pPost[0], pMid[0], reach), lerp(pPost[1], pMid[1], reach)];
    brush.set("oxide_hair", i % 2 === 0 ? PALETTE.oxideDark : PALETTE.oxideMid, 0.68);
    drawWarpedArc(pPost[0], pPost[1], pEnd[0], pEnd[1], -11 * sin((t / 0.5) * 180), 8, 1.0, 0.85, 0.25);

    // Secondary short core-shadow hatching along the deep overhanging cleft of the gastrocnemius
    if (t > 0.18) {
      let pCleftStart = [lerp(pPost[0], pMid[0], 0.52), lerp(pPost[1], pMid[1], 0.52)];
      brush.set("oxide_hair", PALETTE.oxideDeep, 0.72);
      drawWarpedArc(pMid[0], pMid[1], pCleftStart[0], pCleftStart[1], 6, 6, 1.0, 0.8, 0.3);
    }
  }

  // --- C. THE ACHILLES TENDON & RETROCALCANEAL HOLLOW (t = 0.46 to 1.0) ---
  // Explicitly highlighted in prompt: "Hundreds of hair-thin parallel strokes model the tendon..."
  // 1. Dense longitudinal collagen tendon fibers (streaming tightly from aponeurosis to heel)
  let numTendonStrands = 38;
  for (let s = 0; s <= numTendonStrands; s++) {
    let u = s / numTendonStrands;
    let strandPts = [];
    for (let k = 0; k <= 20; k++) {
      let t = lerp(0.44, 0.99, k / 20);
      let pPost = evalCurve(postCtrl, t);
      let pAntEdge = evalCurve(gastrocSoleusCtrl, t);
      let px = lerp(pPost[0], pAntEdge[0], u);
      let py = lerp(pPost[1], pAntEdge[1], u);
      strandPts.push([px, py, 0.6 + 0.4 * sin((k / 20) * 180)]);
    }
    let isAccent = (s === 4 || s === 5 || s === numTendonStrands - 3);
    brush.set(
      s % 3 === 0 ? "oxide_hair" : "oxide_micro",
      isAccent ? PALETTE.accent : (u < 0.35 || u > 0.78 ? PALETTE.oxideDark : PALETTE.oxideMid),
      isAccent ? 0.75 : 0.68
    );
    drawWarpedSpline(strandPts, 0.5);
  }

  // 2. 140+ fine transverse curved cross-contour strokes wrapping the taut bowstring of the Achilles
  let numTendonCross = 140;
  for (let i = 0; i <= numTendonCross; i++) {
    let frac = i / numTendonCross;
    let t = lerp(0.45, 0.985, frac);
    let pPost = evalCurve(postCtrl, t);
    let pAntEdge = evalCurve(gastrocSoleusCtrl, t);

    // Wrap across the posterior edge of the tendon cord
    let wrapReach = 0.55 + 0.25 * sin(frac * 180);
    let pMidTendon = [lerp(pPost[0], pAntEdge[0], wrapReach), lerp(pPost[1], pAntEdge[1], wrapReach)];
    brush.set("oxide_micro", i % 2 === 0 ? PALETTE.oxideDark : PALETTE.oxideMid, 0.65);
    drawWarpedArc(pPost[0], pPost[1], pMidTendon[0], pMidTendon[1], -4.5, 5, 1.0, 0.75, 0.2);

    // Deep concave cross-hatching inside Kager's triangle (the hollow between Achilles & Malleolus)
    let pSept = evalCurve(septumCtrl, t);
    let hollowReach = 0.65 + 0.25 * sin(frac * 180);
    let pHollowEnd = [lerp(pAntEdge[0], pSept[0], hollowReach), lerp(pAntEdge[1], pSept[1], hollowReach)];
    brush.set("oxide_hair", i % 3 === 0 ? PALETTE.oxideDeep : PALETTE.oxideDark, 0.68);
    drawWarpedArc(pAntEdge[0], pAntEdge[1], pHollowEnd[0], pHollowEnd[1], 5.5, 6, 1.0, 0.85, 0.25);
  }

  // --- D. SOLEUS & FIBULARIS LONGUS COMPARTMENT (Between gastrocSoleusCtrl & septumCtrl) ---
  // 1. Longitudinal oblique muscle & peroneal tendon fibers
  let numSoleusFibers = 28;
  for (let f = 1; f < numSoleusFibers; f++) {
    let u = f / numSoleusFibers;
    let pts = [];
    for (let k = 0; k <= 22; k++) {
      let t = (k / 22) * 0.92;
      let pLeft = evalCurve(gastrocSoleusCtrl, t);
      let pRight = evalCurve(septumCtrl, t);
      pts.push([lerp(pLeft[0], pRight[0], u), lerp(pLeft[1], pRight[1], u), 0.7]);
    }
    brush.set("oxide_micro", f > 20 ? PALETTE.oxideDark : PALETTE.oxideLight, 0.62);
    drawWarpedSpline(pts, 0.5);
  }

  // 2. Cross-contour hatching along the soleus ridge and peroneal groove
  let numSoleusCross = 110;
  for (let i = 1; i <= numSoleusCross; i++) {
    let t = (i / numSoleusCross) * 0.88;
    let pLeft = evalCurve(gastrocSoleusCtrl, t);
    let pRight = evalCurve(septumCtrl, t);
    let pMid = [lerp(pLeft[0], pRight[0], 0.42), lerp(pLeft[1], pRight[1], 0.42)];

    brush.set("oxide_micro", PALETTE.oxideMid, 0.62);
    drawWarpedArc(pRight[0], pRight[1], pMid[0], pMid[1], -5, 5, 1.0, 0.7, 0.2);
  }

  // --- E. ANTERIOR SHIN COMPARTMENT: TIBIALIS ANTERIOR & EXTENSOR TENDONS ---
  // (Between septumCtrl and antCtrl)
  let numTibFibers = 24;
  for (let f = 1; f < numTibFibers; f++) {
    let u = f / numTibFibers;
    let pts = [];
    for (let k = 0; k <= 22; k++) {
      let t = k / 22;
      let pLeft = evalCurve(septumCtrl, t);
      let pRight = evalCurve(antCtrl, t);
      pts.push([lerp(pLeft[0], pRight[0], u), lerp(pLeft[1], pRight[1], u), 0.65]);
    }
    brush.set("oxide_micro", u > 0.75 ? PALETTE.oxideMid : PALETTE.oxideLight, 0.58);
    drawWarpedSpline(pts, 0.5);
  }

  // Cross-contours wrapping the anterior tibial crest and extensor retinaculum at the ankle bend
  let numAntCross = 105;
  for (let i = 1; i <= numAntCross; i++) {
    let t = i / numAntCross;
    let pLeft = evalCurve(septumCtrl, t);
    let pRight = evalCurve(antCtrl, t);

    // Wrap inward from the anterior shin contour
    let span = 0.38 + 0.32 * pow(t, 1.8);
    let pIn = [lerp(pRight[0], pLeft[0], span), lerp(pRight[1], pLeft[1], span)];
    brush.set("oxide_hair", t > 0.78 ? PALETTE.oxideDark : PALETTE.oxideMid, 0.64);
    drawWarpedArc(pRight[0], pRight[1], pIn[0], pIn[1], 6, 5, 0.95, 0.7, 0.2);

    // Extensor retinaculum transverse ligament bands across the front of the ankle (t in [0.76, 0.96])
    if (t > 0.76 && t < 0.96 && i % 2 === 0) {
      brush.set("oxide_hair", PALETTE.oxideDark, 0.72);
      drawWarpedArc(pLeft[0], pLeft[1], pRight[0], pRight[1], -8, 7, 0.7, 1.0, 0.7);
    }
  }

  // --- F. LATERAL MALLEOLUS (Prominent Outer Ankle Bone at x=432, y=628) ---
  const malX = 434;
  const malY = 626;
  // Concentric anatomical contour rings & radial shading modeling the spherical bony prominence
  for (let r = 6; r <= 34; r += 2.6) {
    let arcPts = [];
    for (let a = -155; a <= 135; a += 15) {
      let rx = r * 0.78;
      let ry = r * 1.05;
      // Rotate oval along the axis of the fibula (-38 degrees)
      let lx = cos(a) * rx;
      let ly = sin(a) * ry;
      let rot = -36;
      let gx = malX + lx * cos(rot) - ly * sin(rot);
      let gy = malY + lx * sin(rot) + ly * cos(rot);
      arcPts.push([gx, gy, 0.4 + 0.6 * sin(((a + 155) / 290) * 180)]);
    }
    brush.set("oxide_micro", r > 22 ? PALETTE.oxideDark : PALETTE.oxideLight, 0.65);
    drawWarpedSpline(arcPts, 0.5);
  }
  // Deep shadow cradle directly beneath and behind the lateral malleolus (peroneal retinaculum)
  brush.set("oxide_hair", PALETTE.oxideDeep, 0.8);
  for (let k = 0; k < 18; k++) {
    let a1 = 35 + k * 7;
    let a2 = a1 + 42;
    let rad = 24 + (k % 3) * 3.5;
    drawWarpedArc(
      malX + cos(a1) * rad * 0.85, malY + sin(a1) * rad,
      malX + cos(a2) * rad * 0.85, malY + sin(a2) * rad,
      3, 5, 0.6, 1.0, 0.6
    );
  }

  // --- G. SUPERFICIAL SUBCUTANEOUS VEIN NETWORK (Twin-hairline anatomical relief) ---
  const veinMain = [
    [685, 295], [642, 345], [608, 398], [566, 452], [534, 508], [496, 562], [468, 608]
  ];
  const veinBranch = [
    [608, 398], [548, 418], [498, 444], [464, 482]
  ];
  for (let vPath of [veinMain, veinBranch]) {
    brush.set("oxide_hair", PALETTE.oxideDeep, 0.75);
    let leftWall = [];
    let rightWall = [];
    for (let p of vPath) {
      leftWall.push([p[0] - 1.8, p[1] - 1.2, 0.85]);
      rightWall.push([p[0] + 1.8, p[1] + 1.2, 0.85]);
    }
    drawWarpedSpline(leftWall, 0.5);
    drawWarpedSpline(rightWall, 0.5);
  }

  // --- H. PRIMARY CALLIGRAPHIC ANATOMICAL CONTOURS OF THE LEG ---
  brush.set("oxide_calligraphic", PALETTE.oxideDeep, 1.05);
  let postFull = [];
  let antFull = [];
  for (let i = 0; i <= 45; i++) {
    postFull.push(evalCurve(postCtrl, i / 45));
    antFull.push(evalCurve(antCtrl, i / 45));
  }
  drawWarpedSpline(postFull, 0.5);
  drawWarpedSpline(antFull, 0.5);

  // Crisp Gastrocnemius-to-Achilles V-cleft ridge line
  brush.set("oxide_pen", PALETTE.oxideDeep, 0.9);
  let cleftLine = [];
  for (let i = 4; i <= 42; i++) {
    cleftLine.push(evalCurve(gastrocSoleusCtrl, i / 45));
  }
  drawWarpedSpline(cleftLine, 0.5);
}

// =============================================================================
// 5. HYPERREALIST SPRINTER'S SPIKED SHOE
// Stitched Heel Tab, Engineered Woven Mesh, Carbon Torsion Plate & 6 Track Spikes
// =============================================================================
function drawSpikedTrackShoe() {
  // Parametric upper contour of the shoe from heel collar (u=0) through ankle cutout,
  // up to the throat/instep peak (u=0.38), down the vamp/lacing to the upturned sprint toe (u=1.0)
  const shoeTopCtrl = [
    [312, 646], // 0.00: Rear heel collar top
    [358, 668], // 0.12: Dip under lateral malleolus ankle cutout
    [422, 682], // 0.24: Bottom of ankle collar scoop
    [486, 654], // 0.34: Rising toward instep collar
    [526, 632], // 0.42: Throat / tongue peak
    [594, 686], // 0.54: Upper vamp lacing ridge
    [668, 742], // 0.68: Lower vamp lacing ridge
    [748, 794], // 0.80: Forefoot throat base
    [828, 822], // 0.90: Toe box bridge
    [892, 848], // 0.96: Upturned sprint toe crest
    [904, 872]  // 1.00: Toe tip apex
  ];

  // Parametric bottom contour of the shoe upper (where upper mesh welds to the heel cup, arch shank & spike plate)
  const shoeBotCtrl = [
    [312, 646], // 0.00: Starts at rear heel collar
    [282, 692], // 0.10: Convex curve of rear calcaneus heel cup
    [298, 744], // 0.20: Bottom of heel pad (elevated high off the track mid-stride!)
    [372, 766], // 0.32: High vaulted rear arch
    [458, 804], // 0.46: Midfoot carbon arch bridge
    [546, 854], // 0.60: Descending to metatarsal ball of foot
    [632, 892], // 0.72: Rear of forefoot spike plate
    [722, 901], // 0.82: Ball of foot (lowest contact zone above track at y=912)
    [814, 896], // 0.91: Forefoot toe-off curve
    [876, 885], // 0.96: Upturned toe plate
    [904, 872]  // 1.00: Toe tip apex
  ];

  // Internal seam curve separating the Woven Mesh Upper from the Molded Heel Counter & Toe Rand
  const shoeSeamCtrl = [
    [358, 668], // Starts at ankle collar
    [354, 718], // Front edge of sculpted heel counter
    [388, 758], // Arch seam
    [474, 796], // Midfoot weld
    [568, 844],
    [654, 878], // Forefoot mudguard / rand seam
    [748, 884],
    [822, 874],
    [864, 846], // Toe cap boundary
    [828, 822]
  ];

  // --- A. STITCHED HEEL TAB & ACHILLES RELIEF COLLAR ---
  // Explicitly highlighted in prompt: "...and the stitched heel tab"
  // Ergonomic pull-tab loop & stitched Achilles heel spine extending behind [312, 646]..[282, 692]
  const tabOuter = [
    [332, 628], [296, 594], [274, 598], [268, 624], [282, 662], [272, 704], [294, 738]
  ];
  const tabInner = [
    [324, 636], [296, 608], [282, 612], [280, 630], [294, 664], [286, 702], [306, 734]
  ];

  // 1. Dense herringbone webbing lines inside the heel pull-tab & spine strap
  let tabSteps = 54;
  for (let i = 0; i <= tabSteps; i++) {
    let t = i / tabSteps;
    let pOut = evalCurve(tabOuter, t);
    let pIn = evalCurve(tabInner, t);
    let pMid = [lerp(pOut[0], pIn[0], 0.5), lerp(pOut[1], pIn[1], 0.5)];

    // Herringbone V-weave strokes
    brush.set("oxide_micro", i % 2 === 0 ? PALETTE.oxideDark : PALETTE.oxideMid, 0.72);
    drawWarpedArc(pOut[0], pOut[1], pMid[0] + 3, pMid[1] + 4, 0, 3);
    drawWarpedArc(pIn[0], pIn[1], pMid[0] + 3, pMid[1] + 4, 0, 3);
  }

  // 2. Terracotta-cinnabar accent racing stripe down the center of the heel tab
  brush.set("oxide_pen", PALETTE.accent, 0.95);
  let tabCenter = [];
  for (let i = 0; i <= 24; i++) {
    let t = i / 24;
    let pOut = evalCurve(tabOuter, t);
    let pIn = evalCurve(tabInner, t);
    tabCenter.push([lerp(pOut[0], pIn[0], 0.5), lerp(pOut[1], pIn[1], 0.5), 0.9]);
  }
  drawWarpedSpline(tabCenter, 0.5);

  // 3. Double rows of precision lock-stitching along the heel tab & collar padding
  brush.set("oxide_pen", PALETTE.oxideDeep, 0.85);
  drawWarpedSpline(tabOuter, 0.5);
  drawWarpedSpline(tabInner, 0.5);

  // Individual stitch dashes + needle hole dots along the heel tab & collar rim
  const drawStitchPath = (ctrl, count, offsetX, offsetY, col) => {
    brush.set("oxide_hair", col, 0.78);
    for (let i = 0; i < count; i++) {
      let t1 = (i + 0.15) / count;
      let t2 = (i + 0.75) / count;
      let p1 = evalCurve(ctrl, t1);
      let p2 = evalCurve(ctrl, t2);
      drawWarpedArc(p1[0] + offsetX, p1[1] + offsetY, p2[0] + offsetX, p2[1] + offsetY, 0, 2);
    }
  };
  drawStitchPath(tabOuter, 28, 2.2, 1.5, PALETTE.oxideDeep);
  drawStitchPath(tabInner, 28, -2.2, -1.5, PALETTE.oxideDeep);

  // Horizontal bar-tack reinforcement stitches where pull-tab joins the heel collar
  brush.set("oxide_hair", PALETTE.accent, 0.85);
  for (let b = 0; b < 7; b++) {
    let yy = 644 + b * 3.2;
    drawWarpedArc(280, yy, 314, yy - 6, 0, 3);
  }

  // Padded ankle collar band (u = 0.0 to 0.42 along shoeTopCtrl) with micro-perforations & double stitching
  const collarInnerCtrl = [
    [318, 662], [358, 688], [424, 704], [492, 676], [538, 652]
  ];
  brush.set("oxide_pen", PALETTE.oxideDeep, 0.85);
  drawWarpedSpline(collarInnerCtrl, 0.5);
  drawStitchPath(collarInnerCtrl, 32, 0, -3.5, PALETTE.oxideDark);
  drawStitchPath(collarInnerCtrl, 32, 0, 3.0, PALETTE.oxideDark);

  // Fine parallel contour lines & breathable foam perforations inside the ankle collar pad
  for (let i = 1; i <= 44; i++) {
    let t = i / 45;
    let pTop = evalCurve(shoeTopCtrl, t * 0.42);
    let pBot = evalCurve(collarInnerCtrl, t);
    brush.set("oxide_micro", PALETTE.oxideMid, 0.65);
    drawWarpedArc(pTop[0], pTop[1], pBot[0], pBot[1], -3, 4);
    if (i % 2 === 0) {
      brush.set("oxide_hair", PALETTE.oxideDeep, 0.7);
      drawWarpedBead(lerp(pTop[0], pBot[0], 0.5), lerp(pTop[1], pBot[1], 0.5), 1.4, true);
    }
  }

  // --- B. ENGINEERED WOVEN MESH UPPER (Hundreds of hair-thin parallel warp & weft strokes) ---
  // Explicitly highlighted in prompt: "Hundreds of hair-thin parallel strokes model the tendon,
  // the mesh of the shoe and the stitched heel tab, with no tone wash at all."

  // Helper to get top and bottom boundary of the mesh window at normalized foot position u in [0.08, 0.96]
  const getMeshBounds = (u) => {
    let pTop;
    if (u < 0.42) {
      let ct = constrain(u / 0.42, 0, 1);
      pTop = evalCurve(collarInnerCtrl, ct);
    } else {
      pTop = evalCurve(shoeTopCtrl, u);
    }
    let pBot = evalCurve(shoeSeamCtrl, constrain((u - 0.06) / 0.88, 0, 1));
    return [pTop, pBot];
  };

  // 1. 75 Longitudinal Curved Warp Threads (running from heel collar to toe box following 3D foot form)
  let numWarp = 74;
  for (let w = 1; w < numWarp; w++) {
    let v = w / numWarp; // 0 at top throat/vamp, 1 at bottom sole seam
    let warpPts = [];
    for (let k = 0; k <= 28; k++) {
      let u = lerp(0.08, 0.93, k / 28);
      let [pTop, pBot] = getMeshBounds(u);
      // Slight 3D metatarsal bulge in the mid-forefoot
      let archBend = sin(((u - 0.08) / 0.85) * 180) * 0.04 * sin(v * 180);
      let vv = constrain(v + archBend, 0.02, 0.98);
      warpPts.push([
        lerp(pTop[0], pBot[0], vv),
        lerp(pTop[1], pBot[1], vv),
        0.55 + 0.45 * sin((k / 28) * 180)
      ]);
    }
    brush.set(
      w % 4 === 0 ? "oxide_hair" : "oxide_micro",
      w % 4 === 0 ? PALETTE.oxideDark : PALETTE.oxideMid,
      w % 4 === 0 ? 0.68 : 0.56
    );
    drawWarpedSpline(warpPts, 0.5);
  }

  // 2. 135 Transverse Curved Weft Threads (crossing the warp to form the engineered monofilament weave)
  let numWeft = 135;
  for (let i = 0; i <= numWeft; i++) {
    let u = lerp(0.08, 0.93, i / numWeft);
    let [pTop, pBot] = getMeshBounds(u);

    // Compound 3D cross-contour curvature over the instep and metatarsal arch
    let bulge = (u < 0.55) ? -9 * sin((u / 0.55) * 180) : 8 * sin(((u - 0.55) / 0.40) * 180);
    let isRib = (i % 5 === 0);
    brush.set(
      isRib ? "oxide_hair" : "oxide_micro",
      isRib ? PALETTE.oxideDark : PALETTE.oxideLight,
      isRib ? 0.70 : 0.54
    );
    drawWarpedArc(pTop[0], pTop[1], pBot[0], pBot[1], bulge, 8, 0.9, 0.75, 0.95);
  }

  // 3. Engineered Open-Cell Diamond Ventilation Pores in the Midfoot & Forefoot Zones
  // Adds unmistakably hyperreal modern track-spike mesh detail
  brush.set("oxide_hair", PALETTE.oxideDeep, 0.72);
  for (let uCol = 0.24; uCol <= 0.80; uCol += 0.032) {
    let [pTop1, pBot1] = getMeshBounds(uCol);
    let [pTop2, pBot2] = getMeshBounds(uCol + 0.016);
    let [pTop3, pBot3] = getMeshBounds(uCol + 0.032);

    for (let vRow = 0.22; vRow <= 0.78; vRow += 0.085) {
      // Taper diamond zone into an aerodynamic almond window
      let centerDist = sq((uCol - 0.52) / 0.28) + sq((vRow - 0.50) / 0.30);
      if (centerDist < 0.92) {
        let vA = vRow;
        let vB = vRow + 0.04;
        let vC = vRow + 0.08;
        let dTop = [lerp(pTop2[0], pBot2[0], vA), lerp(pTop2[1], pBot2[1], vA)];
        let dLeft = [lerp(pTop1[0], pBot1[0], vB), lerp(pTop1[1], pBot1[1], vB)];
        let dBot = [lerp(pTop2[0], pBot2[0], vC), lerp(pTop2[1], pBot2[1], vC)];
        let dRight = [lerp(pTop3[0], pBot3[0], vB), lerp(pTop3[1], pBot3[1], vB)];

        drawWarpedSpline([dTop, dRight, dBot, dLeft, dTop], 0.15);
      }
    }
  }

  // 4. Laminated Dynamic Flywire Tension Cables (radiating in pairs from the 7 lace eyelets to the sole weld)
  const eyeletUs = [0.43, 0.49, 0.55, 0.61, 0.67, 0.73, 0.79];
  for (let e = 0; e < eyeletUs.length; e++) {
    let uEye = eyeletUs[e];
    let pEye = evalCurve(shoeTopCtrl, uEye);
    let uSoleA = constrain(uEye - 0.09, 0.15, 0.90);
    let uSoleB = constrain(uEye + 0.02, 0.20, 0.92);
    let [_, pSoleA] = getMeshBounds(uSoleA);
    let [__, pSoleB] = getMeshBounds(uSoleB);

    // Twin tension cable pair in terracotta accent + deep iron-oxide outline
    for (let pTarget of [pSoleA, pSoleB]) {
      brush.set("oxide_pen", PALETTE.oxideDeep, 0.78);
      drawWarpedArc(pEye[0] - 2, pEye[1] + 5, pTarget[0] - 1.5, pTarget[1], -2, 6);
      drawWarpedArc(pEye[0] + 2, pEye[1] + 5, pTarget[0] + 1.5, pTarget[1], -2, 6);
      brush.set("oxide_hair", PALETTE.accent, 0.85);
      drawWarpedArc(pEye[0], pEye[1] + 5, pTarget[0], pTarget[1], -2, 6);
    }
  }

  // --- C. MOLDED HEEL COUNTER, SYNTHETIC TOE RAND & DOUBLE-NEEDLE STITCHING ---
  // Dense diagonal & cross-contour hatching between shoeSeamCtrl and shoeBotCtrl
  let numRandCross = 120;
  for (let i = 0; i <= numRandCross; i++) {
    let t = i / numRandCross;
    let pSeam = evalCurve(shoeSeamCtrl, t);
    let uBot = lerp(0.06, 0.96, t);
    let pBot = evalCurve(shoeBotCtrl, uBot);

    brush.set("oxide_hair", i % 2 === 0 ? PALETTE.oxideDark : PALETTE.oxideMid, 0.72);
    drawWarpedArc(pSeam[0], pSeam[1], pBot[0], pBot[1], 3, 5, 0.9, 1.0, 0.9);
  }

  // Molded heel counter structural ribs (u = 0.0 to 0.30)
  for (let r = 0; r < 26; r++) {
    let f = r / 25;
    let pRear = evalCurve(shoeBotCtrl, f * 0.22);
    let pFront = evalCurve(shoeSeamCtrl, f * 0.22);
    brush.set("oxide_hair", PALETTE.oxideDeep, 0.72);
    drawWarpedArc(pRear[0], pRear[1], pFront[0], pFront[1], -4, 5);
  }

  // Reinforced Toe-Cap Bumper (u = 0.86 to 1.0) with dense cross-hatching
  for (let k = 0; k <= 34; k++) {
    let f = k / 34;
    let pTop = evalCurve(shoeTopCtrl, lerp(0.89, 1.0, f));
    let pBot = evalCurve(shoeBotCtrl, lerp(0.89, 1.0, f));
    brush.set("oxide_hair", PALETTE.oxideDeep, 0.78);
    drawWarpedArc(pTop[0], pTop[1], pBot[0], pBot[1], 3, 5);
  }

  // Crisp seam border + twin rows of lock-stitching along the entire heel counter & toe rand
  brush.set("oxide_pen", PALETTE.oxideDeep, 0.9);
  drawWarpedSpline(shoeSeamCtrl, 0.5);
  drawStitchPath(shoeSeamCtrl, 58, 0, -3.2, PALETTE.oxideDeep);
  drawStitchPath(shoeSeamCtrl, 58, 0, 3.0, PALETTE.oxideDark);

  // --- D. SCALLOPED TONGUE, EYELETS, RIBBED LACES & FLYING LACE LOOPS ---
  // Scalloped ultralight sprint tongue peeking above the throat (u = 0.40 to 0.78)
  const tongueCrest = [
    [514, 636], [534, 608], [566, 616], [608, 654], [658, 698], [714, 748], [754, 792]
  ];
  brush.set("oxide_pen", PALETTE.oxideDeep, 0.85);
  drawWarpedSpline(tongueCrest, 0.5);
  drawStitchPath(tongueCrest, 28, -2, 3, PALETTE.oxideDark);

  // Fine longitudinal ribbing & laser perforations on the tongue
  for (let i = 1; i <= 36; i++) {
    let f = i / 37;
    let pT = evalCurve(tongueCrest, f);
    let pB = evalCurve(shoeTopCtrl, lerp(0.41, 0.80, f));
    brush.set("oxide_micro", PALETTE.oxideMid, 0.65);
    drawWarpedArc(pT[0], pT[1], pB[0], pB[1], 2, 4);
  }

  // 7 Reinforced Grommet Eyelets & Criss-Crossed Ribbed Track Laces
  for (let e = 0; e < eyeletUs.length; e++) {
    let pEye = evalCurve(shoeTopCtrl, eyeletUs[e]);
    let pTongue = evalCurve(tongueCrest, (e + 0.4) / eyeletUs.length);

    // Grommet ring
    brush.set("oxide_pen", PALETTE.oxideDeep, 0.9);
    drawWarpedBead(pEye[0] - 3, pEye[1] + 5, 3.8, true);

    // Criss-crossing flat woven lace ribbon (5 parallel threads per lace strap)
    if (e < eyeletUs.length - 1) {
      let pNextEye = evalCurve(shoeTopCtrl, eyeletUs[e + 1]);
      let pNextTongue = evalCurve(tongueCrest, (e + 1.3) / eyeletUs.length);

      for (let s = -2; s <= 2; s++) {
        let isEdge = abs(s) === 2;
        brush.set(isEdge ? "oxide_pen" : "oxide_micro", isEdge ? PALETTE.oxideDeep : PALETTE.oxideMid, 0.75);
        drawWarpedArc(
          pEye[0] - 3 + s * 1.1, pEye[1] + 5 + s * 0.9,
          pNextTongue[0] + s * 1.1, pNextTongue[1] + 2 + s * 0.9,
          -3, 5
        );
        drawWarpedArc(
          pTongue[0] + s * 1.1, pTongue[1] + 3 + s * 0.9,
          pNextEye[0] - 3 + s * 1.1, pNextEye[1] + 5 + s * 0.9,
          3, 5
        );
      }
    }
  }

  // Dynamic Mid-Stride Flying Shoelace Bow & Aglets whipping upward from the top eyelet [526, 632]
  const knotX = 536;
  const knotY = 626;
  const loop1 = [[knotX, knotY], [575, 578], [622, 548], [648, 554], [628, 582], [582, 608], [knotX, knotY]];
  const loop2 = [[knotX, knotY], [592, 594], [648, 576], [674, 586], [646, 606], [594, 618], [knotX, knotY]];
  const tail1 = [[knotX, knotY], [588, 622], [644, 628], [696, 616], [724, 598]];
  const tail2 = [[knotX, knotY], [568, 642], [618, 658], [668, 656], [704, 642]];

  for (let ribbon of [loop1, loop2, tail1, tail2]) {
    for (let offset = -2.2; offset <= 2.2; offset += 1.1) {
      let isBorder = abs(offset) > 1.8;
      brush.set(isBorder ? "oxide_pen" : "oxide_micro", isBorder ? PALETTE.oxideDeep : PALETTE.oxideMid, 0.78);
      let shifted = ribbon.map(p => [p[0] + offset * 0.7, p[1] + offset]);
      drawWarpedSpline(shifted, 0.55);
    }
  }
  // Terracotta-accented lace aglets at the ends of tail1 & tail2
  brush.set("oxide_pen", PALETTE.accent, 0.95);
  drawWarpedArc(708, 608, 728, 595, 0, 3);
  drawWarpedArc(688, 648, 708, 640, 0, 3);

  // --- E. RIGID CARBON/PEBAX FOREFOOT SPIKE PLATE & VAULTED ARCH SHANK ---
  // Under-sole chassis thickness contour running beneath shoeBotCtrl from heel (u=0.14) to toe (u=0.99)
  const plateUnderCtrl = [
    [292, 742], // 0.00: Rear heel pad base
    [368, 778], // 0.16: Vaulted arch underside
    [452, 818], // 0.32: Carbon torsion shank belly
    [540, 868], // 0.48: Descending to forefoot plate
    [628, 902], // 0.64: Rear spike pod
    [722, 911], // 0.78: Main forefoot spike plate (just kissing the track at y=912!)
    [816, 906], // 0.89: Forefoot propulsion curve
    [878, 893], // 0.95: Toe-off plate
    [904, 872]  // 1.00: Toe tip
  ];

  // 1. Carbon-fiber diagonal weave & structural truss ribs along the vaulted arch & spike plate
  let plateSteps = 95;
  for (let i = 0; i <= plateSteps; i++) {
    let f = i / plateSteps;
    let pTop = evalCurve(shoeBotCtrl, lerp(0.18, 1.0, f));
    let pBot = evalCurve(plateUnderCtrl, f);

    // Diagonal carbon weave lines
    brush.set("oxide_hair", i % 3 === 0 ? PALETTE.oxideDeep : PALETTE.oxideDark, 0.78);
    drawWarpedArc(pTop[0], pTop[1], pBot[0], pBot[1], 0, 3);

    if (i < plateSteps - 2) {
      let pBotNext = evalCurve(plateUnderCtrl, (i + 2) / plateSteps);
      brush.set("oxide_micro", PALETTE.oxideMid, 0.65);
      drawWarpedArc(pTop[0], pTop[1], pBotNext[0], pBotNext[1], 0, 3);
    }

    // Secondary traction sharkskin micro-teeth under the arch and heel pad (f < 0.55)
    if (f < 0.52 && i % 2 === 0) {
      brush.set("oxide_pen", PALETTE.oxideDeep, 0.8);
      drawWarpedSpline([
        [pBot[0] - 2, pBot[1]],
        [pBot[0] - 1, pBot[1] + 5],
        [pBot[0] + 4, pBot[1] + 1]
      ], 0.1);
    }
  }

  // Terracotta accent torsion bar running through the midfoot arch shank
  brush.set("oxide_pen", PALETTE.accent, 0.95);
  let shankMid = [];
  for (let i = 6; i <= 55; i++) {
    let f = i / plateSteps;
    let pTop = evalCurve(shoeBotCtrl, lerp(0.18, 1.0, f));
    let pBot = evalCurve(plateUnderCtrl, f);
    shankMid.push([lerp(pTop[0], pBot[0], 0.5), lerp(pTop[1], pBot[1], 0.5), 0.9]);
  }
  drawWarpedSpline(shankMid, 0.5);

  // --- F. 6 PRECISION PYRAMID TRACK SPIKES (Foreground Lateral Row + Recessed Medial Row) ---
  const drawTrackSpike = (xBase, yBase, angleDeg, scaleFactor, isForeground) => {
    let rad = angleDeg;
    let ux = cos(rad);
    let uy = sin(rad);
    let nx = -uy;
    let ny = ux;

    // 1. Stepped hexagonal wrench flange / receptacle base
    let flangeW = 9.5 * scaleFactor;
    let flangeH = 4.2 * scaleFactor;
    let fTL = [xBase - ux * flangeW, yBase - uy * flangeW];
    let fTR = [xBase + ux * flangeW, yBase + uy * flangeW];
    let fBL = [fTL[0] + nx * flangeH, fTL[1] + ny * flangeH];
    let fBR = [fTR[0] + nx * flangeH, fTR[1] + ny * flangeH];

    brush.set("oxide_pen", isForeground ? PALETTE.oxideDeep : PALETTE.oxideDark, 0.9);
    drawWarpedSpline([fTL, fBL, fBR, fTR, fTL], 0.1);

    // Anodized terracotta ring on flange
    brush.set("oxide_hair", PALETTE.accent, 0.9);
    drawWarpedArc(
      lerp(fTL[0], fBL[0], 0.5), lerp(fTL[1], fBL[1], 0.5),
      lerp(fTR[0], fBR[0], 0.5), lerp(fTR[1], fBR[1], 0.5),
      0, 3
    );

    // 2. 4-Faceted Pyramid Spike Needle Point (biting into the track band)
    let baseCenter = [xBase + nx * flangeH, yBase + ny * flangeH];
    let pinW = 5.8 * scaleFactor;
    let pinLen = 17.5 * scaleFactor;
    let pLeft = [baseCenter[0] - ux * pinW, baseCenter[1] - uy * pinW];
    let pRight = [baseCenter[0] + ux * pinW, baseCenter[1] + uy * pinW];
    let pCenterRidge = [baseCenter[0] + ux * (pinW * 0.12), baseCenter[1] + uy * (pinW * 0.12)];
    let pTip = [baseCenter[0] + nx * pinLen, baseCenter[1] + ny * pinLen];

    // Dense horizontal parallel line shading on the dark left facet of the pyramid spike
    brush.set("oxide_micro", PALETTE.oxideDeep, 0.78);
    for (let s = 1; s <= 9; s++) {
      let sf = s / 10;
      drawWarpedArc(
        lerp(pLeft[0], pTip[0], sf), lerp(pLeft[1], pTip[1], sf),
        lerp(pCenterRidge[0], pTip[0], sf), lerp(pCenterRidge[1], pTip[1], sf),
        0, 2
      );
    }

    // Crisp outer silhouette & central bevel ridge of the pyramid spike
    brush.set("oxide_pen", PALETTE.oxideDeep, isForeground ? 0.95 : 0.78);
    drawWarpedSpline([pLeft, pTip, pRight], 0.08);
    brush.set("oxide_hair", PALETTE.oxideDeep, 0.8);
    drawWarpedArc(pCenterRidge[0], pCenterRidge[1], pTip[0], pTip[1], 0, 3);
  };

  // Recessed medial row of 3 spikes (slightly behind and angled in perspective)
  drawTrackSpike(668, 904, 4, 0.84, false);
  drawTrackSpike(758, 907, 1, 0.86, false);
  drawTrackSpike(844, 899, -8, 0.84, false);

  // Foreground lateral row of 4 primary spikes (biting into the track lane line)
  drawTrackSpike(638, 901, 7, 1.0, true);
  drawTrackSpike(716, 909, 3, 1.04, true);
  drawTrackSpike(798, 906, -3, 1.02, true);
  drawTrackSpike(868, 894, -12, 0.96, true);

  // --- G. MASTER CALLIGRAPHIC OUTLINES OF THE SPIKED SHOE ---
  brush.set("oxide_calligraphic", PALETTE.oxideDeep, 1.1);
  let topFull = [];
  let botFull = [];
  let plateFull = [];
  for (let i = 0; i <= 50; i++) {
    let f = i / 50;
    topFull.push(evalCurve(shoeTopCtrl, f));
    botFull.push(evalCurve(shoeBotCtrl, f));
    plateFull.push(evalCurve(plateUnderCtrl, f));
  }
  drawWarpedSpline(topFull, 0.5);
  drawWarpedSpline(botFull, 0.5);
  drawWarpedSpline(plateFull, 0.5);
}

// Hyperrealistic Tide Pool Specimen — Petri Dish Granite Rim, Watercolor Blooms & Ink Stipple
// p5.js 2.x + p5.brush (WEBGL)

const CX = 555;
const CY = 535;
const R_INNER = 382;
const R_OUTER = 440;

let colonies = {
  coralline: [],
  anemones: [],
  barnacles: [],
  microbes: [],
  crevices: []
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  generateColonyLayout();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#0b0e12");

  // 1. Dark Slate Field & Clinical Reference Markings
  drawSlateField();

  // 2. Deep Cast Shadow of the Granite Rim & Hand onto the Slate
  drawDishCastShadow();

  // 3. Tide Pool Interior Substrate (Luminous Agar-Limestone Floor & Deep Crevices)
  drawPoolSubstrate();

  // 4. Watercolor Blooms (Batched by Color: Agar Amber, Mustard, Olive, Carmine, Coralline Pink)
  drawWatercolorBlooms();

  // 5. Pink Coralline Crust Colonies (Calcified Lobes, Growth Rings & Conceptacle Pores)
  drawCorallineColonies();

  // 6. Agar-Amber & Mustard Microbial Rosettes + Stippled Watermark Borders
  drawMicrobialStippleZones();

  // 7. Barnacle Clusters (Faceted Calcified Plates, Sutures & Opercular Valves)
  drawBarnacleClusters();

  // 8. Sea Anemones (Oral Discs, Radial Striations, 3-Tier Fine Tentacles & Stippled Mouths)
  drawSeaAnemones();

  // 9. Crisp Ring of Wet Granite (Framed like a Petri Dish) + Rim-Climbing Barnacles
  drawWetGraniteRim();

  // 10. Clear Water Surface Reflections, Caustics & Oxygen Micro-Pearls
  drawWaterSurfaceReflections();

  // 11. Clinical & Alive Hand Holding the Lower-Right Rim
  drawHoldingHand();

  noLoop();
}

// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function drawPolyShape(pts, curvature = 0.25, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function makeNoisyBlob(cx, cy, baseR, nPts, irr = 0.25, freq = 1.6, stretch = 1.0, rotDeg = 0) {
  let pts = [];
  let cRot = cos(rotDeg);
  let sRot = sin(rotDeg);
  let nOffX = random(1000);
  let nOffY = random(1000);
  for (let i = 0; i < nPts; i++) {
    let a = (i / nPts) * 360;
    let nx = nOffX + cos(a) * freq;
    let ny = nOffY + sin(a) * freq;
    let nv = map(noise(nx, ny), 0, 1, 1 - irr, 1 + irr);
    let lx = cos(a) * baseR * nv * stretch;
    let ly = sin(a) * baseR * nv;
    let gx = cx + lx * cRot - ly * sRot;
    let gy = cy + lx * sRot + ly * cRot;
    pts.push([gx, gy]);
  }
  return pts;
}

function clampToPool(x, y, maxR = R_INNER - 4) {
  let dx = x - CX;
  let dy = y - CY;
  let d = sqrt(dx * dx + dy * dy);
  if (d > maxR) {
    let s = maxR / d;
    return [CX + dx * s, CY + dy * s];
  }
  return [x, y];
}

function stippleBatch(pts, brushName, col, weight, len = 0.85) {
  if (!pts || pts.length === 0) return;
  brush.set(brushName, col, weight);
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let ang = (i * 137.5) % 360;
    brush.line(p[0], p[1], p[0] + cos(ang) * len, p[1] + sin(ang) * len);
  }
}

// ============================================================================
// BIOLOGICAL COLONY LAYOUT GENERATOR (UNEVEN CLUSTERS THAT TOUCH)
// ============================================================================

function generateColonyLayout() {
  // Deep rock crevices inside the tide pool for high-contrast depth
  const creviceSeeds = [
    { x: CX - 95, y: CY - 115, r: 95, stretch: 1.5, rot: -25 },
    { x: CX + 35, y: CY + 75, r: 110, stretch: 1.4, rot: 35 },
    { x: CX - 175, y: CY + 40, r: 85, stretch: 1.6, rot: 75 },
    { x: CX + 165, y: CY - 30, r: 90, stretch: 1.5, rot: -65 },
    { x: CX - 10, y: CY - 15, r: 75, stretch: 1.3, rot: 15 },
    { x: CX + 85, y: CY - 210, r: 70, stretch: 1.7, rot: 20 }
  ];
  for (let c of creviceSeeds) {
    colonies.crevices.push(c);
  }

  // 1. Pink Coralline Crust plaques (fan-like encrusting colonies)
  const corallineHubs = [
    { x: CX - 130, y: CY - 175, count: 6, scale: 1.05 },
    { x: CX + 175, y: CY + 45, count: 7, scale: 1.15 },
    { x: CX - 45, y: CY + 195, count: 6, scale: 1.0 },
    { x: CX - 235, y: CY - 35, count: 5, scale: 0.95 },
    { x: CX + 55, y: CY - 95, count: 5, scale: 0.9 },
    { x: CX + 105, y: CY + 195, count: 5, scale: 0.95 },
    { x: CX - 155, y: CY + 145, count: 5, scale: 0.9 },
    { x: CX + 205, y: CY - 135, count: 4, scale: 0.85 }
  ];

  for (let hub of corallineHubs) {
    for (let i = 0; i < hub.count; i++) {
      let ang = (i / hub.count) * 360 + random(-22, 22);
      let dist = random(18, 62) * hub.scale;
      let lx = hub.x + cos(ang) * dist;
      let ly = hub.y + sin(ang) * dist;
      let clamped = clampToPool(lx, ly, R_INNER - 18);
      colonies.coralline.push({
        x: clamped[0],
        y: clamped[1],
        r: random(30, 56) * hub.scale,
        dir: ang + random(-25, 25),
        span: random(110, 165),
        shade: random(["#d94b66", "#c22744", "#e8768b", "#a61731", "#de5d75"])
      });
    }
  }

  // 2. Sea Anemones (Carmine, Olive-Mustard, Agar-Amber) clustered & touching
  const anemoneSpec = [
    // Upper-left Carmine & Amber cluster
    { x: CX - 95, y: CY - 110, r: 54, morph: "carmine" },
    { x: CX - 155, y: CY - 82, r: 38, morph: "carmine" },
    { x: CX - 48, y: CY - 148, r: 34, morph: "amber" },
    { x: CX - 130, y: CY - 152, r: 28, morph: "carmine" },
    { x: CX - 52, y: CY - 72, r: 31, morph: "olive" },
    { x: CX - 185, y: CY - 122, r: 24, morph: "carmine" },

    // Mid-left Olive-Mustard & Carmine cluster
    { x: CX - 205, y: CY + 32, r: 52, morph: "olive" },
    { x: CX - 140, y: CY + 58, r: 44, morph: "olive" },
    { x: CX - 168, y: CY - 15, r: 35, morph: "amber" },
    { x: CX - 248, y: CY + 85, r: 33, morph: "olive" },
    { x: CX - 195, y: CY + 102, r: 29, morph: "carmine" },
    { x: CX - 102, y: CY + 18, r: 27, morph: "olive" },

    // Central & South dense touching super-cluster
    { x: CX + 15, y: CY + 55, r: 58, morph: "carmine" },
    { x: CX - 52, y: CY + 95, r: 46, morph: "amber" },
    { x: CX + 78, y: CY + 92, r: 45, morph: "olive" },
    { x: CX + 35, y: CY + 135, r: 39, morph: "carmine" },
    { x: CX - 20, y: CY + 155, r: 34, morph: "olive" },
    { x: CX + 65, y: CY + 18, r: 36, morph: "amber" },
    { x: CX - 22, y: CY + 12, r: 30, morph: "carmine" },
    { x: CX + 95, y: CY + 152, r: 28, morph: "amber" },
    { x: CX - 85, y: CY + 138, r: 25, morph: "carmine" },

    // East / Right cluster
    { x: CX + 178, y: CY - 25, r: 49, morph: "amber" },
    { x: CX + 135, y: CY - 72, r: 38, morph: "olive" },
    { x: CX + 225, y: CY + 25, r: 37, morph: "carmine" },
    { x: CX + 148, y: CY + 38, r: 33, morph: "amber" },
    { x: CX + 235, y: CY - 62, r: 27, morph: "olive" },
    { x: CX + 195, y: CY + 82, r: 26, morph: "carmine" },

    // Upper-Right rim pocket cluster
    { x: CX + 72, y: CY - 215, r: 40, morph: "olive" },
    { x: CX + 122, y: CY - 195, r: 31, morph: "carmine" },
    { x: CX + 32, y: CY - 242, r: 25, morph: "amber" },
    { x: CX + 112, y: CY - 248, r: 21, morph: "olive" }
  ];

  for (let a of anemoneSpec) {
    colonies.anemones.push(a);
  }

  // 3. Barnacle Clusters (wedged along the granite wall and between anemones)
  const barnacleZones = [
    // Rim-hugging reefs
    { angStart: 135, angEnd: 245, rMin: 315, rMax: 374, count: 28 },
    { angStart: 275, angEnd: 350, rMin: 310, rMax: 374, count: 22 },
    { angStart: 20, angEnd: 105, rMin: 305, rMax: 374, count: 25 },
    // Interior interstitial clusters
    { cx: CX - 95, cy: CY - 20, spread: 58, count: 14 },
    { cx: CX + 110, cy: CY - 135, spread: 55, count: 13 },
    { cx: CX - 115, cy: CY + 195, spread: 62, count: 15 },
    { cx: CX + 145, cy: CY + 125, spread: 58, count: 14 },
    { cx: CX + 5, cy: CY - 105, spread: 48, count: 11 }
  ];

  let candBarnacles = [];
  for (let z of barnacleZones) {
    if (z.angStart !== undefined) {
      for (let i = 0; i < z.count; i++) {
        let a = random(z.angStart, z.angEnd);
        let rad = random(z.rMin, z.rMax);
        let bx = CX + cos(a) * rad;
        let by = CY + sin(a) * rad;
        let br = map(rad, z.rMin, z.rMax, random(11, 21), random(7, 15));
        candBarnacles.push({ x: bx, y: by, r: br });
      }
    } else {
      for (let i = 0; i < z.count; i++) {
        let a = random(360);
        let d = pow(random(), 0.7) * z.spread;
        let bx = z.cx + cos(a) * d;
        let by = z.cy + sin(a) * d;
        let br = random(8, 19);
        candBarnacles.push({ x: bx, y: by, r: br });
      }
    }
  }

  // Filter & relax barnacles so they pack tightly around anemones without covering anemone mouths
  for (let b of candBarnacles) {
    let dCenter = dist(b.x, b.y, CX, CY);
    if (dCenter > R_INNER + 4) continue;

    let insideAnemoneCore = false;
    for (let an of colonies.anemones) {
      let da = dist(b.x, b.y, an.x, an.y);
      if (da < an.r * 0.68 + b.r * 0.5) {
        insideAnemoneCore = true;
        break;
      }
    }
    if (insideAnemoneCore) continue;

    // Prevent extreme overlap with existing barnacles while keeping them touching
    let tooClose = false;
    for (let eb of colonies.barnacles) {
      let db = dist(b.x, b.y, eb.x, eb.y);
      if (db < (b.r + eb.r) * 0.58) {
        tooClose = true;
        break;
      }
    }
    if (!tooClose) {
      b.rot = random(360);
      b.sides = int(random(5, 8));
      colonies.barnacles.push(b);
    }
  }

  // 4. Agar-Amber & Mustard Microbial / Colonial Ascidian Stipple Zones
  const microbeCenters = [
    { x: CX + 85, y: CY - 45, r: 48, col: "amber" },
    { x: CX - 15, y: CY - 185, r: 52, col: "mustard" },
    { x: CX - 125, y: CY + 115, r: 42, col: "olive" },
    { x: CX + 175, y: CY + 155, r: 46, col: "amber" },
    { x: CX - 245, y: CY - 115, r: 38, col: "mustard" },
    { x: CX + 15, y: CY + 245, r: 44, col: "amber" },
    { x: CX + 245, y: CY - 145, r: 40, col: "olive" }
  ];
  for (let m of microbeCenters) {
    colonies.microbes.push(m);
  }
}

// ============================================================================
// 1. DARK SLATE FIELD & CLINICAL SPECIMEN MARKINGS
// ============================================================================

function drawSlateField() {
  brush.noStroke();
  brush.noFill();

  // Layered dark slate rock plates across background
  const slateTones = ["#070a0d", "#0f141a", "#141b23", "#18212b", "#090c10"];
  for (let i = 0; i < 18; i++) {
    let sx = random(-100, 1300);
    let sy = random(-100, 1300);
    // Skip center of pool to save overdraw
    if (dist(sx, sy, CX, CY) < R_INNER - 60) continue;
    let pts = makeNoisyBlob(sx, sy, random(180, 420), 10, 0.35, 1.4, random(1.2, 2.0), random(-35, 35));
    brush.wash(random(slateTones), random(45, 95));
    drawPolyShape(pts, 0.2, true);
  }
  brush.noWash();

  // Slate cleavage hatching in deep graphite tones
  const hatchZones = [
    { x: 60, y: 60, w: 380, h: 380, ang: 28, col: "#1b242e" },
    { x: 760, y: 50, w: 390, h: 390, ang: 26, col: "#171f28" },
    { x: 40, y: 720, w: 420, h: 430, ang: 30, col: "#151d26" },
    { x: 0, y: 0, w: 1200, h: 1200, ang: -62, col: "#06080b" }
  ];
  for (let hz of hatchZones) {
    brush.hatchStyle("charcoal", hz.col, 0.65);
    brush.hatch(random(14, 22), hz.ang, { rand: 0.12 });
    brush.noStroke();
    brush.rect(hz.x, hz.y, hz.w, hz.h, "corner");
    brush.noHatch();
  }

  // Fine mineral grain & diagonal slate fractures
  brush.set("2B", "#232e3a", 0.45);
  for (let i = 0; i < 65; i++) {
    let x1 = random(0, 1200);
    let y1 = random(0, 1200);
    if (dist(x1, y1, CX, CY) < R_OUTER - 10) continue;
    let len = random(40, 190);
    let ang = 27 + random(-8, 8);
    brush.line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
  }

  // Subtle dark & pale slate spatter
  let darkDust = [];
  let lightDust = [];
  for (let i = 0; i < 450; i++) {
    let px = random(20, 1180);
    let py = random(20, 1180);
    if (dist(px, py, CX, CY) < R_OUTER - 5) continue;
    if (random() < 0.65) darkDust.push([px, py]);
    else lightDust.push([px, py]);
  }
  stippleBatch(darkDust, "rotring", "#050709", 0.55, 1.1);
  stippleBatch(lightDust, "rotring", "#2d3a47", 0.4, 0.8);

  // Subtle clinical petri-dish alignment ticks & specimen calibration marks on the slate
  brush.set("rotring", "#334252", 0.35);
  // Top-left calibration crosshair
  brush.line(85, 85, 145, 85);
  brush.line(85, 85, 85, 145);
  for (let t = 0; t <= 5; t++) {
    let tx = 85 + t * 12;
    brush.line(tx, 82, tx, 88);
    let ty = 85 + t * 12;
    brush.line(82, ty, 88, ty);
  }
  // Bottom-left scale bar & ticks
  brush.line(85, 1105, 205, 1105);
  for (let t = 0; t <= 10; t++) {
    let tx = 85 + t * 12;
    let th = (t % 5 === 0) ? 7 : 3.5;
    brush.line(tx, 1105 - th, tx, 1105 + th);
  }
  // Faint cardinal axis ticks outside the dish rim
  const cardAngles = [0, 90, 180, 270];
  for (let ca of cardAngles) {
    if (ca === 0 || ca === 90) continue; // Hand covers lower-right
    let r1 = R_OUTER + 18;
    let r2 = R_OUTER + 36;
    brush.line(CX + cos(ca) * r1, CY + sin(ca) * r1, CX + cos(ca) * r2, CY + sin(ca) * r2);
  }
}

// ============================================================================
// 2. DEEP CAST SHADOW OF THE DISH & HAND
// ============================================================================

function drawDishCastShadow() {
  brush.noStroke();
  brush.noFill();

  // Directional light from top-left (-135 deg) casts deep shadow toward bottom-right (+45 deg)
  for (let i = 7; i >= 1; i--) {
    let off = i * 6.5;
    let rad = R_OUTER + i * 4.5;
    let pts = makeNoisyBlob(CX + off * 0.85, CY + off * 0.95, rad, 48, 0.015, 1.2);
    brush.wash("#030507", map(i, 1, 7, 135, 35));
    drawPolyShape(pts, 0.25, true);
  }
  brush.noWash();
}

// ============================================================================
// 3. TIDE POOL SUBSTRATE (LUMINOUS AGAR-LIMESTONE FLOOR & DARK CREVICES)
// ============================================================================

function drawPoolSubstrate() {
  brush.noStroke();
  brush.noFill();

  // Solid luminous mineral / agar-cream base so watercolor blooms glow with high contrast
  let baseCircle1 = makeNoisyBlob(CX, CY, R_INNER + 4, 60, 0.008, 1.0);
  brush.wash("#e8dfd0", 250);
  drawPolyShape(baseCircle1, 0.25, true);

  let baseCircle2 = makeNoisyBlob(CX, CY, R_INNER + 2, 60, 0.01, 1.1);
  brush.wash("#f4efe4", 240);
  drawPolyShape(baseCircle2, 0.25, true);

  // Subtle warm agar-ivory & cool wet limestone patches
  for (let i = 0; i < 8; i++) {
    let a = random(360);
    let d = random(30, R_INNER - 90);
    let pts = makeNoisyBlob(CX + cos(a) * d, CY + sin(a) * d, random(75, 150), 16, 0.25, 1.5);
    brush.wash(i % 2 === 0 ? "#fcf8f0" : "#ded4c1", random(90, 150));
    drawPolyShape(pts, 0.3, true);
  }

  // Deep high-contrast rock crevices & shadow pockets between colony beds
  for (let c of colonies.crevices) {
    let outerPts = makeNoisyBlob(c.x, c.y, c.r, 18, 0.32, 1.8, c.stretch, c.rot);
    for (let i = 0; i < outerPts.length; i++) {
      outerPts[i] = clampToPool(outerPts[i][0], outerPts[i][1], R_INNER - 6);
    }
    brush.wash("#2a3329", 140);
    drawPolyShape(outerPts, 0.3, true);

    let midPts = makeNoisyBlob(c.x, c.y, c.r * 0.72, 16, 0.3, 1.9, c.stretch, c.rot);
    for (let i = 0; i < midPts.length; i++) {
      midPts[i] = clampToPool(midPts[i][0], midPts[i][1], R_INNER - 10);
    }
    brush.wash("#17201f", 190);
    drawPolyShape(midPts, 0.3, true);

    let corePts = makeNoisyBlob(c.x, c.y, c.r * 0.42, 14, 0.28, 2.0, c.stretch, c.rot);
    for (let i = 0; i < corePts.length; i++) {
      corePts[i] = clampToPool(corePts[i][0], corePts[i][1], R_INNER - 14);
    }
    brush.wash("#0b1012", 220);
    drawPolyShape(corePts, 0.3, true);
  }

  brush.noWash();
}

// ============================================================================
// 4. WATERCOLOR BLOOMS (AGAR AMBER, MUSTARD, OLIVE, CARMINE, CORALLINE PINK)
// ============================================================================

function drawWatercolorBlooms() {
  brush.noStroke();
  brush.noWash();

  // Group watercolor fills by color batch for optimal caching & organic bleed
  let batches = {
    agarAmberLight: { col: "#eda62b", alpha: 82, bleed: 0.38, shapes: [] },
    agarAmberDeep:  { col: "#c9730e", alpha: 95, bleed: 0.34, shapes: [] },
    mustardLight:   { col: "#e3b824", alpha: 85, bleed: 0.36, shapes: [] },
    mustardRich:    { col: "#b8890d", alpha: 92, bleed: 0.32, shapes: [] },
    oliveSoft:      { col: "#687d31", alpha: 88, bleed: 0.36, shapes: [] },
    oliveDeep:      { col: "#384718", alpha: 105, bleed: 0.30, shapes: [] },
    corallinePink:  { col: "#e66c80", alpha: 85, bleed: 0.35, shapes: [] },
    carmineVivid:   { col: "#bd1936", alpha: 98, bleed: 0.36, shapes: [] },
    carmineDark:    { col: "#78091d", alpha: 110, bleed: 0.28, shapes: [] }
  };

  // Blooms radiating beneath anemones
  for (let an of colonies.anemones) {
    let pts1 = makeNoisyBlob(an.x, an.y, an.r * 1.48, 16, 0.28, 1.7, random(1.0, 1.25), random(360));
    let pts2 = makeNoisyBlob(an.x + random(-10, 10), an.y + random(-10, 10), an.r * 1.15, 14, 0.25, 1.9);
    for (let i = 0; i < pts1.length; i++) pts1[i] = clampToPool(pts1[i][0], pts1[i][1], R_INNER - 2);
    for (let i = 0; i < pts2.length; i++) pts2[i] = clampToPool(pts2[i][0], pts2[i][1], R_INNER - 2);

    if (an.morph === "carmine") {
      batches.corallinePink.shapes.push(pts1);
      batches.carmineVivid.shapes.push(pts2);
    } else if (an.morph === "olive") {
      batches.mustardLight.shapes.push(pts1);
      batches.oliveSoft.shapes.push(pts2);
    } else {
      batches.agarAmberLight.shapes.push(pts1);
      batches.agarAmberDeep.shapes.push(pts2);
    }
  }

  // Blooms under coralline crusts
  for (let i = 0; i < colonies.coralline.length; i += 2) {
    let cc = colonies.coralline[i];
    let pts = makeNoisyBlob(cc.x, cc.y, cc.r * 1.35, 14, 0.3, 1.8, 1.2, cc.dir);
    for (let j = 0; j < pts.length; j++) pts[j] = clampToPool(pts[j][0], pts[j][1], R_INNER - 2);
    if (i % 4 === 0) batches.carmineVivid.shapes.push(pts);
    else batches.corallinePink.shapes.push(pts);
  }

  // Blooms in the microbial agar / mustard / olive zones & open water channels
  for (let m of colonies.microbes) {
    let ptsOuter = makeNoisyBlob(m.x, m.y, m.r * 1.65, 16, 0.34, 1.7, 1.3, random(360));
    let ptsInner = makeNoisyBlob(m.x, m.y, m.r * 1.05, 14, 0.28, 2.0, 1.15, random(360));
    for (let j = 0; j < ptsOuter.length; j++) ptsOuter[j] = clampToPool(ptsOuter[j][0], ptsOuter[j][1], R_INNER - 2);
    for (let j = 0; j < ptsInner.length; j++) ptsInner[j] = clampToPool(ptsInner[j][0], ptsInner[j][1], R_INNER - 2);

    if (m.col === "amber") {
      batches.agarAmberLight.shapes.push(ptsOuter);
      batches.agarAmberDeep.shapes.push(ptsInner);
    } else if (m.col === "mustard") {
      batches.mustardLight.shapes.push(ptsOuter);
      batches.mustardRich.shapes.push(ptsInner);
    } else {
      batches.oliveSoft.shapes.push(ptsOuter);
      batches.oliveDeep.shapes.push(ptsInner);
    }
  }

  // Deep shadow-bloom accents at colony intersections
  for (let i = 0; i < 10; i++) {
    let an = colonies.anemones[(i * 3) % colonies.anemones.length];
    let pts = makeNoisyBlob(an.x + random(-22, 22), an.y + random(-22, 22), an.r * 0.85, 12, 0.25, 1.6);
    for (let j = 0; j < pts.length; j++) pts[j] = clampToPool(pts[j][0], pts[j][1], R_INNER - 4);
    if (i % 2 === 0) batches.carmineDark.shapes.push(pts);
    else batches.oliveDeep.shapes.push(pts);
  }

  // Execute batched watercolor fills
  brush.fillTexture(0.78, 0.68);
  const order = [
    "agarAmberLight", "mustardLight", "corallinePink",
    "oliveSoft", "agarAmberDeep", "mustardRich",
    "carmineVivid", "oliveDeep", "carmineDark"
  ];

  for (let key of order) {
    let b = batches[key];
    brush.fill(b.col, b.alpha);
    brush.fillBleed(b.bleed, "out");
    for (let pts of b.shapes) {
      drawPolyShape(pts, 0.35, true);
    }
  }

  brush.noFill();
}

// ============================================================================
// 5. PINK CORALLINE CRUST COLONIES (LITHOTHAMNION PLAQUES)
// ============================================================================

function drawCorallineColonies() {
  let poreDotsDark = [];
  let poreDotsLight = [];

  for (let cc of colonies.coralline) {
    // Build a ruffled fan / kidney lobe shape
    let fanPts = [];
    let halfSpan = cc.span * 0.5;
    let steps = 16;

    // Inner attachment arc
    let innerR = cc.r * 0.22;
    for (let i = 0; i <= 5; i++) {
      let a = cc.dir + map(i, 0, 5, halfSpan * 0.6, -halfSpan * 0.6);
      let p = clampToPool(cc.x + cos(a) * innerR, cc.y + sin(a) * innerR, R_INNER - 3);
      fanPts.push(p);
    }

    // Outer scalloped calcified margin
    let outerMarginPts = [];
    for (let i = 0; i <= steps; i++) {
      let a = cc.dir + map(i, 0, steps, -halfSpan, halfSpan);
      let ruffle = 1.0 + 0.14 * sin(i * 55) + 0.1 * (noise(cc.x * 0.02 + i * 0.4, cc.y * 0.02) - 0.5);
      let rad = cc.r * ruffle;
      let p = clampToPool(cc.x + cos(a) * rad, cc.y + sin(a) * rad, R_INNER - 3);
      fanPts.push(p);
      outerMarginPts.push(p);
    }

    // Drop shadow under the calcified crust wafer
    let shadowPts = fanPts.map(p => [p[0] + 2.5, p[1] + 3.0]);
    brush.noStroke();
    brush.wash("#240811", 130);
    drawPolyShape(shadowPts, 0.25, true);

    // Opaque coralline crust body
    brush.wash(cc.shade, 215);
    drawPolyShape(fanPts, 0.28, true);

    // Darker carmine inner core wash
    let corePts = fanPts.map(p => [
      lerp(cc.x, p[0], 0.62),
      lerp(cc.y, p[1], 0.62)
    ]);
    brush.wash("#8c142c", 125);
    drawPolyShape(corePts, 0.25, true);
    brush.noWash();

    // Concentric calcareous growth striae
    for (let ring = 1; ring <= 4; ring++) {
      let frac = map(ring, 1, 4, 0.38, 0.86);
      let ringPts = [];
      for (let i = 0; i < outerMarginPts.length; i += 2) {
        let mp = outerMarginPts[i];
        ringPts.push([
          lerp(cc.x, mp[0], frac),
          lerp(cc.y, mp[1], frac)
        ]);
      }
      if (ringPts.length >= 3) {
        brush.set("pen", ring % 2 === 0 ? "#f7c6cf" : "#6e0b1e", 0.32);
        brush.spline(ringPts, 0.35);
      }
    }

    // Crisp bleached-white / pale-blush calcified outer rim
    if (outerMarginPts.length >= 3) {
      brush.set("pen", "#fff0f3", 0.68);
      brush.spline(outerMarginPts, 0.35);
      let underEdge = outerMarginPts.map(p => [p[0] + 1.4, p[1] + 1.8]);
      brush.set("rotring", "#3b0510", 0.42);
      brush.spline(underEdge, 0.35);
    }

    // Conceptacle reproductive pores (stippled dots)
    for (let k = 0; k < 16; k++) {
      let a = cc.dir + random(-halfSpan * 0.75, halfSpan * 0.75);
      let d = random(cc.r * 0.3, cc.r * 0.78);
      let px = cc.x + cos(a) * d;
      let py = cc.y + sin(a) * d;
      if (dist(px, py, CX, CY) < R_INNER - 6) {
        poreDotsDark.push([px, py]);
        if (k % 3 === 0) poreDotsLight.push([px - 0.8, py - 0.8]);
      }
    }
  }

  stippleBatch(poreDotsDark, "rotring", "#3d0612", 0.45, 0.9);
  stippleBatch(poreDotsLight, "rotring", "#fff5f7", 0.38, 0.7);
}

// ============================================================================
// 6. AGAR-AMBER & MUSTARD MICROBIAL ROSETTES + STIPPLED WATERMARK BORDERS
// ============================================================================

function drawMicrobialStippleZones() {
  let sepiaStipple = [];
  let oliveStipple = [];
  let carmineStipple = [];
  let goldStipple = [];
  let creamStipple = [];

  // Stippled pen boundaries sharpening the watercolor blooms & microbial plaques
  for (let m of colonies.microbes) {
    // Draw delicate dendritic / concentric petri-dish colony rings
    for (let ring = 1; ring <= 3; ring++) {
      let rad = m.r * (0.45 + ring * 0.32);
      let ringPts = makeNoisyBlob(m.x, m.y, rad, 24, 0.22, 2.1, 1.15, ring * 35);
      for (let i = 0; i < ringPts.length; i++) {
        ringPts[i] = clampToPool(ringPts[i][0], ringPts[i][1], R_INNER - 5);
      }

      // Trace thin cellular margin with fine pen
      brush.set("rotring", m.col === "olive" ? "#293612" : "#593508", 0.3);
      let closedRing = ringPts.concat([ringPts[0]]);
      brush.spline(closedRing, 0.3);

      // Dense stipple along the watermark perimeter
      for (let i = 0; i < ringPts.length; i++) {
        let bp = ringPts[i];
        for (let s = 0; s < 4; s++) {
          let sx = bp[0] + randomGaussian(0, 4.2);
          let sy = bp[1] + randomGaussian(0, 4.2);
          if (dist(sx, sy, CX, CY) < R_INNER - 5) {
            if (m.col === "olive") oliveStipple.push([sx, sy]);
            else sepiaStipple.push([sx, sy]);
          }
        }
      }
    }

    // Colonial tunicate / Botryllus star-rosettes inside the agar bloom
    let nRosettes = 5;
    for (let r = 0; r < nRosettes; r++) {
      let ra = (r / nRosettes) * 360 + random(-20, 20);
      let rd = random(8, m.r * 0.75);
      let rx = m.x + cos(ra) * rd;
      let ry = m.y + sin(ra) * rd;
      if (dist(rx, ry, CX, CY) > R_INNER - 16) continue;

      let nPetals = int(random(6, 10));
      for (let p = 0; p < nPetals; p++) {
        let pa = (p / nPetals) * 360;
        let px1 = rx + cos(pa) * 2.5;
        let py1 = ry + sin(pa) * 2.5;
        let px2 = rx + cos(pa) * 7.5;
        let py2 = ry + sin(pa) * 7.5;
        brush.set("pen", m.col === "amber" ? "#f5c84c" : "#d99b1a", 0.55);
        brush.line(px1, py1, px2, py2);
        sepiaStipple.push([px2, py2]);
      }
      creamStipple.push([rx, ry]);
    }
  }

  // Stipple halos around all anemones & crevices to sharpen watercolor bleeds
  for (let an of colonies.anemones) {
    let nDots = int(an.r * 2.4);
    for (let i = 0; i < nDots; i++) {
      let a = random(360);
      let d = an.r * random(0.95, 1.52);
      let dx = an.x + cos(a) * d;
      let dy = an.y + sin(a) * d;
      if (dist(dx, dy, CX, CY) < R_INNER - 4) {
        if (an.morph === "carmine") carmineStipple.push([dx, dy]);
        else if (an.morph === "olive") oliveStipple.push([dx, dy]);
        else sepiaStipple.push([dx, dy]);

        if (i % 5 === 0) goldStipple.push([dx + 1.5, dy + 1.5]);
      }
    }
  }

  stippleBatch(sepiaStipple, "rotring", "#2b1908", 0.42, 0.85);
  stippleBatch(oliveStipple, "rotring", "#19240b", 0.42, 0.85);
  stippleBatch(carmineStipple, "rotring", "#3b0612", 0.42, 0.85);
  stippleBatch(goldStipple, "rotring", "#d49415", 0.5, 0.95);
  stippleBatch(creamStipple, "rotring", "#fff8e8", 0.5, 0.9);
}

// ============================================================================
// 7. BARNACLE CLUSTERS (CALCIFIED PLATES, SUTURES & OPERCULAR VALVES)
// ============================================================================

function drawBarnacleClusters() {
  let barnacleStippleDark = [];
  let barnacleStippleLight = [];

  for (let idx = 0; idx < colonies.barnacles.length; idx++) {
    let b = colonies.barnacles[idx];
    let nSides = b.sides;
    let outerVerts = [];
    let innerVerts = [];

    for (let i = 0; i < nSides; i++) {
      let a = b.rot + (i / nSides) * 360;
      let rOut = b.r * random(0.9, 1.12);

      // Compress outer radius if pressing against a neighboring barnacle
      let vx = b.x + cos(a) * rOut;
      let vy = b.y + sin(a) * rOut;
      for (let j = 0; j < colonies.barnacles.length; j++) {
        if (i === idx) continue;
        let nb = colonies.barnacles[j];
        let dCenter = dist(b.x, b.y, nb.x, nb.y);
        if (dCenter > 0 && dCenter < (b.r + nb.r) * 1.15) {
          let dVert = dist(vx, vy, nb.x, nb.y);
          if (dVert < nb.r * 0.88) {
            rOut = min(rOut, dCenter - nb.r * 0.48);
          }
        }
      }
      rOut = max(rOut, b.r * 0.58);
      outerVerts.push([b.x + cos(a) * rOut, b.y + sin(a) * rOut]);

      let rIn = b.r * 0.40 * random(0.88, 1.12);
      // Slight shift toward top-left for 3D cone perspective
      innerVerts.push([b.x - 0.8 + cos(a) * rIn, b.y - 0.8 + sin(a) * rIn]);
    }

    // 1. Base contact shadow on the substrate
    let shadowVerts = outerVerts.map(v => [v[0] + 2.2, v[1] + 2.6]);
    brush.noStroke();
    brush.wash("#0c1114", 160);
    drawPolyShape(shadowVerts, 0.1, true);

    // 2. Faceted calcareous parietal plates (individually shaded by light angle)
    const platePalette = ["#f7f4ec", "#ebe6da", "#d9d3c5", "#b8bfc4", "#8e98a1", "#6c7680"];
    for (let i = 0; i < nSides; i++) {
      let ni = (i + 1) % nSides;
      let quad = [outerVerts[i], outerVerts[ni], innerVerts[ni], innerVerts[i]];
      let midAng = b.rot + ((i + 0.5) / nSides) * 360;
      // Top-left (-135 deg) receives brightest chalky white; bottom-right (+45 deg) is shadowed
      let lightDiff = cos(midAng - (-135));
      let colIdx = int(map(lightDiff, 1, -1, 0, platePalette.length - 0.01));
      brush.wash(platePalette[colIdx], 235);
      drawPolyShape(quad, 0.05, true);
    }

    // 3. Dark abyssal opercular cavity in center
    brush.wash("#090d11", 245);
    drawPolyShape(innerVerts, 0.12, true);
    brush.noWash();

    // 4. Radial plate sutures & growth ridges
    brush.set("rotring", "#252e36", 0.35);
    for (let i = 0; i < nSides; i++) {
      let ni = (i + 1) % nSides;
      // Suture line between plates
      brush.line(outerVerts[i][0], outerVerts[i][1], innerVerts[i][0], innerVerts[i][1]);
      // Outer polygon edge
      brush.line(outerVerts[i][0], outerVerts[i][1], outerVerts[ni][0], outerVerts[ni][1]);
      // Inner rim edge
      brush.line(innerVerts[i][0], innerVerts[i][1], innerVerts[ni][0], innerVerts[ni][1]);

      // Mid-plate radial rib
      let mxOut = (outerVerts[i][0] + outerVerts[ni][0]) * 0.5;
      let myOut = (outerVerts[i][1] + outerVerts[ni][1]) * 0.5;
      let mxIn = (innerVerts[i][0] + innerVerts[ni][0]) * 0.5;
      let myIn = (innerVerts[i][1] + innerVerts[ni][1]) * 0.5;
      brush.line(mxOut, myOut, mxIn, myIn);
    }

    // 5. Opercular valve suture (scutum & tergum beak split across the dark center)
    let v0 = innerVerts[0];
    let vOpp = innerVerts[int(nSides / 2)];
    let vMid = [b.x + random(-1.5, 1.5), b.y + random(-1.5, 1.5)];
    brush.set("pen", "#e6e1d6", 0.45);
    brush.spline([v0, vMid, vOpp], 0.25);
    brush.set("rotring", "#030507", 0.4);
    brush.line(v0[0] + 0.9, v0[1] + 0.9, vOpp[0] + 0.9, vOpp[1] + 0.9);

    // 6. Stipple texture on shadowed side & bright chalk highlight on lit side
    for (let s = 0; s < 7; s++) {
      let sa = random(0, 120); // Shadow side
      let sd = random(b.r * 0.45, b.r * 0.92);
      barnacleStippleDark.push([b.x + cos(sa) * sd, b.y + sin(sa) * sd]);
    }
    barnacleStippleLight.push([b.x + cos(-135) * b.r * 0.52, b.y + sin(-135) * b.r * 0.52]);
  }

  stippleBatch(barnacleStippleDark, "rotring", "#1d252b", 0.38, 0.8);
  stippleBatch(barnacleStippleLight, "rotring", "#ffffff", 0.48, 0.9);
}

// ============================================================================
// 8. SEA ANEMONES (ORAL DISCS, FINE TENTACLE LINES & STIPPLED MOUTHS)
// ============================================================================

function drawSeaAnemones() {
  // Sort so larger dominant anemones render with full tentacle crowns over smaller peripheral ones
  let sortedAnemones = [...colonies.anemones].sort((a, b) => a.r - b.r);

  let mouthStippleDark = [];
  let mouthStippleLight = [];
  let tipDotsCarmine = [];
  let tipDotsGold = [];
  let tipDotsIvory = [];
  let acrorhagiBeads = [];

  for (let idx = 0; idx < sortedAnemones.length; idx++) {
    let an = sortedAnemones[idx];
    let x = an.x;
    let y = an.y;
    let r = an.r;

    // Color scheme per morph
    let colColumn, colDiscOuter, colDiscInner, colRayLight, colTentDark, colTentMain, colTentBright;
    if (an.morph === "carmine") {
      colColumn = "#420510";
      colDiscOuter = "#7a0c20";
      colDiscInner = "#4a0512";
      colRayLight = "#d93852";
      colTentDark = "#38040d";
      colTentMain = "#bf1733";
      colTentBright = "#eb4662";
    } else if (an.morph === "olive") {
      colColumn = "#1d260e";
      colDiscOuter = "#3b4d1b";
      colDiscInner = "#232e10";
      colRayLight = "#a6b839";
      colTentDark = "#18210a";
      colTentMain = "#6a8029";
      colTentBright = "#dbab1d";
    } else {
      // Agar-Amber morph
      colColumn = "#3d2005";
      colDiscOuter = "#8f4e0c";
      colDiscInner = "#522a05";
      colRayLight = "#f0ac2b";
      colTentDark = "#2e1703";
      colTentMain = "#d48113";
      colTentBright = "#f7c448";
    }

    // 1. Basal column shadow & outer collar
    brush.noStroke();
    let colPts = makeNoisyBlob(x + 2, y + 2.5, r * 0.82, 24, 0.08, 1.5);
    brush.wash("#080c0e", 175);
    drawPolyShape(colPts, 0.25, true);

    let bodyPts = makeNoisyBlob(x, y, r * 0.72, 24, 0.08, 1.6);
    brush.wash(colColumn, 225);
    drawPolyShape(bodyPts, 0.25, true);

    // 2. Oral Disc (with concentric washes)
    let discPts1 = makeNoisyBlob(x, y, r * 0.54, 24, 0.07, 1.6);
    brush.wash(colDiscOuter, 235);
    drawPolyShape(discPts1, 0.25, true);

    let discPts2 = makeNoisyBlob(x, y, r * 0.34, 20, 0.07, 1.6);
    brush.wash(colDiscInner, 225);
    drawPolyShape(discPts2, 0.25, true);
    brush.noWash();

    // 3. Mesenterial radial striations across the oral disc
    let nRays = int(map(r, 20, 58, 18, 36));
    for (let i = 0; i < nRays; i++) {
      let a = (i / nRays) * 360 + random(-2, 2);
      let r1 = r * 0.14;
      let r2 = r * 0.50;
      brush.set("rotring", i % 2 === 0 ? colTentDark : colRayLight, 0.32);
      brush.line(x + cos(a) * r1, y + sin(a) * r1, x + cos(a) * r2, y + sin(a) * r2);
    }

    // Marginal spherules / acrorhagi beads under the tentacle collar for carmine morph
    if (an.morph === "carmine" && r > 30) {
      for (let b = 0; b < 18; b++) {
        let ba = (b / 18) * 360;
        acrorhagiBeads.push([x + cos(ba) * r * 0.64, y + sin(ba) * r * 0.64]);
      }
    }

    // 4. Helper to deform tentacle length when pressing against adjacent anemones or rim
    const getMaxReach = (ang, desiredR) => {
      let reach = desiredR;
      let tx = x + cos(ang) * reach;
      let ty = y + sin(ang) * reach;

      // Clamp to granite pool inner wall
      let dPool = dist(tx, ty, CX, CY);
      if (dPool > R_INNER - 4) {
        reach *= (R_INNER - 4) / dPool;
      }

      // Compress slightly where two anemones press against each other
      for (let other of sortedAnemones) {
        if (other === an) continue;
        let dCenters = dist(x, y, other.x, other.y);
        if (dCenters < (r + other.r) * 1.08) {
          let angToOther = atan2(other.y - y, other.x - x);
          let diff = abs(((ang - angToOther + 540) % 360) - 180);
          if (diff < 48) {
            let maxContact = dCenters - other.r * 0.52;
            let factor = map(diff, 0, 48, 0.72, 1.0);
            reach = min(reach, max(r * 0.55, maxContact * factor));
          }
        }
      }
      return reach;
    };

    // 5. Three concentric tiers of fine tentacle lines
    const tiers = [
      { countMult: 1.45, rStart: 0.50, rEndMin: 0.94, rEndMax: 1.16, wMain: 0.68, col: colTentMain },
      { countMult: 1.20, rStart: 0.42, rEndMin: 0.74, rEndMax: 0.94, wMain: 0.60, col: colTentBright },
      { countMult: 0.85, rStart: 0.33, rEndMin: 0.54, rEndMax: 0.72, wMain: 0.50, col: colRayLight }
    ];

    let swirlDir = (idx % 2 === 0 ? 1 : -1) * random(10, 24);

    for (let tIdx = 0; tIdx < tiers.length; tIdx++) {
      let tier = tiers[tIdx];
      let nTent = max(14, int(r * tier.countMult));

      for (let i = 0; i < nTent; i++) {
        let baseAng = (i / nTent) * 360 + tIdx * 7 + random(-3.5, 3.5);
        let r0 = r * tier.rStart * random(0.94, 1.06);
        let rawEnd = r * random(tier.rEndMin, tier.rEndMax);
        let r3 = getMaxReach(baseAng, rawEnd);

        // Organic S-curve / water-current deflection along tentacle
        let wave = sin(baseAng * 3 + idx * 45) * 9 + swirlDir * (1 - tIdx * 0.25);
        let a1 = baseAng + wave * 0.35;
        let a2 = baseAng + wave * 0.75;
        let a3 = baseAng + wave * 1.0 + random(-5, 5);

        let r1 = lerp(r0, r3, 0.36);
        let r2 = lerp(r0, r3, 0.72);

        let p0 = [x + cos(baseAng) * r0, y + sin(baseAng) * r0];
        let p1 = [x + cos(a1) * r1, y + sin(a1) * r1];
        let p2 = [x + cos(a2) * r2, y + sin(a2) * r2];
        let p3 = [x + cos(a3) * r3, y + sin(a3) * r3];

        // Dark shadow under-stroke for high-contrast 3D separation
        let shadowPts = [
          [p0[0] + 1.1, p0[1] + 1.3],
          [p1[0] + 1.1, p1[1] + 1.3],
          [p2[0] + 1.1, p2[1] + 1.3],
          [p3[0] + 1.1, p3[1] + 1.3]
        ];
        brush.set("rotring", colTentDark, tier.wMain * 0.65);
        brush.spline(shadowPts, 0.4);

        // Main pigmented tentacle stroke
        brush.set("pen", tier.col, tier.wMain);
        brush.spline([p0, p1, p2, p3], 0.4);

        // Fine bright axial highlight on upper/inner tentacles
        if (tIdx >= 1 && i % 2 === 0) {
          let hiCol = an.morph === "carmine" ? "#ff8fa3" : (an.morph === "olive" ? "#f2dc5c" : "#ffe699");
          brush.set("rotring", hiCol, 0.28);
          brush.spline([p1, p2, p3], 0.35);
        }

        // Swollen acrosphere tentacle tip dot
        if (an.morph === "olive") {
          tipDotsCarmine.push(p3); // Classic Anthopleura magenta/carmine tips
        } else if (an.morph === "carmine") {
          tipDotsGold.push(p3);
        } else {
          tipDotsIvory.push(p3);
        }
      }
    }

    // 6. Central Mouth (Actinopharynx Slit & Puckered Siphonoglyphs)
    let mAngle = random(360);
    let mRx = r * 0.19;
    let mRy = r * 0.11;
    let mouthPts = [];
    for (let i = 0; i < 14; i++) {
      let a = (i / 14) * 360;
      let lx = cos(a) * mRx;
      let ly = sin(a) * mRy;
      let gx = x + lx * cos(mAngle) - ly * sin(mAngle);
      let gy = y + lx * sin(mAngle) + ly * cos(mAngle);
      mouthPts.push([gx, gy]);
    }
    brush.noStroke();
    brush.wash("#080305", 240);
    drawPolyShape(mouthPts, 0.3, true);
    brush.noWash();

    // Lip folds & siphonoglyph highlights at the slit corners
    let lipCol = an.morph === "carmine" ? "#f59cb0" : "#f2cf7e";
    brush.set("pen", lipCol, 0.45);
    brush.spline(mouthPts.slice(0, 8), 0.35);

    // Dense stipple around the mouth & inner oral disc
    for (let s = 0; s < 24; s++) {
      let sa = random(360);
      let sd = random(r * 0.10, r * 0.35);
      let sx = x + cos(sa) * sd;
      let sy = y + sin(sa) * sd;
      mouthStippleDark.push([sx, sy]);
      if (s % 4 === 0) mouthStippleLight.push([sx, sy]);
    }
  }

  // Batch render all tentacle tip dots, acrorhagi beads & oral stipples
  stippleBatch(acrorhagiBeads, "pen", "#80dfff", 0.75, 1.2);
  stippleBatch(tipDotsCarmine, "pen", "#f22e52", 0.7, 1.15);
  stippleBatch(tipDotsGold, "pen", "#ffd166", 0.65, 1.1);
  stippleBatch(tipDotsIvory, "pen", "#fff9e6", 0.65, 1.1);
  stippleBatch(mouthStippleDark, "rotring", "#090406", 0.42, 0.8);
  stippleBatch(mouthStippleLight, "rotring", "#ffe8d6", 0.36, 0.75);
}

// ============================================================================
// 9. CRISP RING OF WET GRANITE (PETRI DISH RIM)
// ============================================================================

function drawWetGraniteRim() {
  brush.noStroke();
  brush.noFill();

  // 1. Steep inner granite wall shadow (top-left) & submerged rock shelf (bottom-right)
  let wallSegs = 48;
  for (let i = 0; i < wallSegs; i++) {
    let a1 = (i / wallSegs) * 360;
    let a2 = ((i + 1.03) / wallSegs) * 360;
    let midA = (a1 + a2) * 0.5;
    let rIn = R_INNER - map(cos(midA - (-135)), 1, -1, 14, 5);
    let rOut = R_INNER + 4;

    let quad = [
      [CX + cos(a1) * rIn, CY + sin(a1) * rIn],
      [CX + cos(a2) * rIn, CY + sin(a2) * rIn],
      [CX + cos(a2) * rOut, CY + sin(a2) * rOut],
      [CX + cos(a1) * rOut, CY + sin(a1) * rOut]
    ];
    let isShadowed = cos(midA - (-135)) > -0.15;
    brush.wash(isShadowed ? "#090d11" : "#262e34", isShadowed ? 215 : 145);
    drawPolyShape(quad, 0.05, true);
  }

  // 2. Main Wet Granite Ring constructed from interlocking arcuate blocks
  let rimSegs = 60;
  const graniteBaseCols = ["#2c3138", "#363c44", "#434952", "#23282e", "#505761"];
  for (let i = 0; i < rimSegs; i++) {
    let a1 = (i / rimSegs) * 360;
    let a2 = ((i + 1.04) / rimSegs) * 360;
    let midA = (a1 + a2) * 0.5;

    // Slight natural micro-variation while remaining a crisp petri-dish ring
    let n1 = map(noise(cos(a1) * 2 + 10, sin(a1) * 2 + 10), 0, 1, -2.2, 2.2);
    let n2 = map(noise(cos(a2) * 2 + 10, sin(a2) * 2 + 10), 0, 1, -2.2, 2.2);
    let r1In = R_INNER + n1;
    let r2In = R_INNER + n2;
    let r1Out = R_OUTER + n1 * 0.8;
    let r2Out = R_OUTER + n2 * 0.8;

    let block = [
      [CX + cos(a1) * r1In, CY + sin(a1) * r1In],
      [CX + cos(a2) * r2In, CY + sin(a2) * r2In],
      [CX + cos(a2) * r2Out, CY + sin(a2) * r2Out],
      [CX + cos(a1) * r1Out, CY + sin(a1) * r1Out]
    ];

    // Directional studio lighting across the granite ring
    let lightVal = cos(midA - (-135));
    let baseCol = graniteBaseCols[i % graniteBaseCols.length];
    if (lightVal > 0.45) baseCol = "#5c636b";
    else if (lightVal < -0.45) baseCol = "#1b2026";

    brush.wash(baseCol, 250);
    drawPolyShape(block, 0.04, true);

    // Second pass to ensure 100% opaque granite ring framing the water
    brush.wash(lightVal > 0 ? "#464d56" : "#22272e", 180);
    drawPolyShape(block, 0.04, true);
  }

  // 3. Coarse Granite Crystalline Flecks (Feldspar Pink, Quartz White, Biotite Black, Gray Hornblende)
  const grainBatches = [
    { col: "#111519", alpha: 235, count: 160, minR: 3.5, maxR: 8.5 }, // Biotite black
    { col: "#d99d95", alpha: 215, count: 120, minR: 3.5, maxR: 8.0 }, // Orthoclase feldspar salmon-pink
    { col: "#e3dad0", alpha: 220, count: 130, minR: 3.0, maxR: 7.5 }, // Plagioclase cream
    { col: "#7a828c", alpha: 210, count: 110, minR: 4.0, maxR: 9.0 }, // Smoky quartz
    { col: "#ffffff", alpha: 230, count: 80,  minR: 2.5, maxR: 5.5 }  // Wet specular quartz
  ];

  for (let gb of grainBatches) {
    brush.wash(gb.col, gb.alpha);
    for (let i = 0; i < gb.count; i++) {
      let a = random(360);
      let r = random(R_INNER + 6, R_OUTER - 6);
      let gx = CX + cos(a) * r;
      let gy = CY + sin(a) * r;
      let gr = random(gb.minR, gb.maxR);
      let gPts = [];
      let nV = int(random(4, 7));
      let gRot = random(360);
      for (let v = 0; v < nV; v++) {
        let va = gRot + (v / nV) * 360;
        let vr = gr * random(0.65, 1.25);
        gPts.push([gx + cos(va) * vr, gy + sin(va) * vr]);
      }
      drawPolyShape(gPts, 0.05, true);
    }
  }
  brush.noWash();

  // 4. Dense Fine Mineral Stipple & Radial Micro-Fissures on the Granite Rim
  let rimBlackDots = [];
  let rimWhiteDots = [];
  let rimFeldsparDots = [];
  for (let i = 0; i < 1100; i++) {
    let a = random(360);
    let r = random(R_INNER + 2, R_OUTER - 2);
    let px = CX + cos(a) * r;
    let py = CY + sin(a) * r;
    let pick = i % 3;
    if (pick === 0) rimBlackDots.push([px, py]);
    else if (pick === 1) rimWhiteDots.push([px, py]);
    else rimFeldsparDots.push([px, py]);
  }
  stippleBatch(rimBlackDots, "rotring", "#07090c", 0.5, 1.0);
  stippleBatch(rimWhiteDots, "rotring", "#f5f2eb", 0.45, 0.9);
  stippleBatch(rimFeldsparDots, "rotring", "#cfa099", 0.48, 0.95);

  // Radial granite cleavage hairlines
  brush.set("rotring", "#0b0e12", 0.38);
  for (let i = 0; i < 38; i++) {
    let a = random(360);
    let r1 = random(R_INNER, R_INNER + 18);
    let r2 = random(r1 + 12, R_OUTER);
    let p1 = [CX + cos(a) * r1, CY + sin(a) * r1];
    let p2 = [CX + cos(a + random(-1.8, 1.8)) * ((r1 + r2) * 0.5), CY + sin(a + random(-1.8, 1.8)) * ((r1 + r2) * 0.5)];
