    brush.spline([p1, p2, p3], 0.3);
  }

  // 5. Crisp Petri-Dish Inner & Outer Bevel Contours + Wet Specular Highlights
  brush.set("rotring", "#06080a", 0.85);
  brush.arc(CX, CY, R_INNER, 0, 360);
  brush.arc(CX, CY, R_OUTER, 0, 360);

  // Inner meniscus wet glass-like specular ring
  brush.set("pen", "#ffffff", 0.95);
  brush.arc(CX, CY, R_INNER + 2.5, 185, 295);
  brush.arc(CX, CY, R_INNER + 2.5, 10, 80);

  brush.set("rotring", "#d4f0ff", 0.55);
  brush.arc(CX, CY, R_INNER + 5, 170, 320);
  brush.arc(CX, CY, R_INNER + 5, 0, 105);

  // Outer bevel wet granite specular highlights
  brush.set("pen", "#ffffff", 0.85);
  brush.arc(CX, CY, R_OUTER - 3, 190, 285);
  brush.arc(CX, CY, R_OUTER - 3, 25, 72);

  // 6. Rim-Encroaching Barnacles (growing right on the inner lip of the wet granite)
  const rimBarnacles = [
    { a: 162, r: 12 }, { a: 167, r: 9 }, { a: 218, r: 13 }, { a: 223, r: 10 },
    { a: 308, r: 11 }, { a: 313, r: 8 }, { a: 58, r: 12 }, { a: 63, r: 9 }
  ];
  for (let rb of rimBarnacles) {
    let bx = CX + cos(rb.a) * (R_INNER + 2);
    let by = CY + sin(rb.a) * (R_INNER + 2);
    let bPts = makeNoisyBlob(bx, by, rb.r, 6, 0.15, 1.5);
    brush.noStroke();
    brush.wash("#e8e3d8", 235);
    drawPolyShape(bPts, 0.1, true);
    let inPts = makeNoisyBlob(bx, by, rb.r * 0.42, 6, 0.12, 1.5);
    brush.wash("#0b0f13", 240);
    drawPolyShape(inPts, 0.1, true);
    brush.noWash();
    brush.set("rotring", "#242c33", 0.35);
    for (let v = 0; v < 6; v++) {
      brush.line(bPts[v][0], bPts[v][1], inPts[v][0], inPts[v][1]);
    }
  }
}

