// 10. CLEAR WATER SURFACE REFLECTIONS, CAUSTICS & OXYGEN MICRO-PEARLS
// ============================================================================

function drawWaterSurfaceReflections() {
  // 1. Faint Water Caustic Web across the pool interior
  const causticCells = 22;
  let cellCenters = [];
  for (let i = 0; i < causticCells; i++) {
    let a = (i / causticCells) * 360 + random(-12, 12);
    let d = random(45, R_INNER - 45);
    cellCenters.push([CX + cos(a) * d, CY + sin(a) * d]);
  }

  for (let i = 0; i < cellCenters.length; i++) {
    let c = cellCenters[i];
    let rad = random(42, 78);
    let arcPts = [];
    let startA = random(360);
    for (let s = 0; s <= 6; s++) {
      let a = startA + s * 22;
      let nr = rad * map(noise(c[0] * 0.01 + s, c[1] * 0.01), 0, 1, 0.8, 1.2);
      let px = c[0] + cos(a) * nr;
      let py = c[1] + sin(a) * nr;
      if (dist(px, py, CX, CY) < R_INNER - 10) {
        arcPts.push([px, py]);
      }
    }
    if (arcPts.length >= 3) {
      brush.set("cpencil", "#fffdf5", 0.42);
      brush.spline(arcPts, 0.45);
    }
  }

  // 2. Curved Overhead Laboratory / Sky Window Surface Reflection Bands
  // Band A: Upper-Left curved meniscus reflection
  for (let r = R_INNER - 88; r <= R_INNER - 24; r += 3.5) {
    let span = map(r, R_INNER - 88, R_INNER - 24, 24, 52);
    let aStart = 222 - span * 0.5 + sin(r * 0.15) * 3;
    let aEnd = 222 + span * 0.5 + cos(r * 0.15) * 3;
    // Interrupt the reflection arc slightly like a segmented window or clinical lamp
    brush.set("pen", "#ffffff", map(r, R_INNER - 88, R_INNER - 24, 0.28, 0.55));
    brush.arc(CX, CY, r, aStart, 219);
    brush.arc(CX, CY, r, 224, aEnd);
  }

  // Secondary faint reflection arc in the lower-left / upper-right meniscus
  for (let r = R_INNER - 48; r <= R_INNER - 16; r += 4.5) {
    brush.set("cpencil", "#e6f5ff", 0.35);
    brush.arc(CX, CY, r, 315, 348);
    brush.arc(CX, CY, r, 112, 138);
  }

  // Soft white water-sheen glints along the reflection bands
  let sheenDots = [];
  for (let i = 0; i < 120; i++) {
    let a = random(195, 250);
    let r = random(R_INNER - 92, R_INNER - 18);
    sheenDots.push([CX + cos(a) * r, CY + sin(a) * r]);
  }
  stippleBatch(sheenDots, "rotring", "#ffffff", 0.45, 0.9);

  // 3. Photosynthetic Oxygen Micro-Bubbles clinging to colonies & water meniscus
  for (let i = 0; i < 42; i++) {
    let a = random(360);
    let d = random(25, R_INNER - 12);
    let bx = CX + cos(a) * d;
    let by = CY + sin(a) * d;
    let br = random(2.0, 5.2);

    brush.set("rotring", "#0b141a", 0.38);
    brush.circle(bx, by, br, 0.05);
    brush.set("pen", "#ffffff", 0.65);
    brush.line(bx - br * 0.35, by - br * 0.35, bx - br * 0.1, by - br * 0.1);
  }
}

