const CX = 600;
const CY = 600;
const SEED = 8472;

// Parametric geometry for one half-sector (strictly mirrored across all 8 axes)
// Local coordinates (u, v): u along lobe ray (0..600), v perpendicular to ray.

function papayaOuterV(t) {
  // t in [0, 1] maps to u in [98, 526]
  if (t <= 0 || t >= 1) return 0;
  let phi = Math.acos(1 - 2 * t); // [0, PI]
  let s = Math.sin(phi);
  // Pyriform papaya silhouette with stem neck, full belly, and Hawaiian crown tip
  let neckPinch = -11 * Math.exp(-Math.pow((t - 0.11) / 0.065, 2));
  let belly = s * (38 + 86 * Math.pow(t, 0.78) - 24 * Math.pow(t, 2.8));
  let crown = 7.5 * Math.exp(-Math.pow((t - 0.955) / 0.032, 2));
  let baseFlare = 24 * Math.pow(1 - t, 7);
  return Math.max(0, belly + neckPinch + crown + baseFlare);
}

function papayaInnerV(t) {
  // t in [0, 1] maps to u in [114, 502] (the cut-fabric fruit window inside the turkey red rim)
  if (t <= 0 || t >= 1) return 0;
  let u = 114 + (502 - 114) * t;
  let tOut = (u - 98) / (526 - 98);
  let outer = papayaOuterV(tOut);
  let rim = 14.5 + 3.5 * Math.pow(Math.sin(Math.PI * t), 0.6);
  let endTaper = Math.sin(Math.PI * t);
  return Math.max(0, (outer - rim) * Math.pow(endTaper, 0.18));
}

function cavityV(s) {
  // s in [0, 1] maps to u in [192, 444] (central seed hollow)
  if (s <= 0 || s >= 1) return 0;
  let phi = Math.acos(1 - 2 * s);
  let sinP = Math.sin(phi);
  let swell = sinP * (22 + 34 * Math.pow(s, 0.72) - 10 * Math.pow(s, 2.4));
  let scallop = 1.8 * Math.sin(s * Math.PI * 9) * sinP;
  return Math.max(0, swell + scallop);
}

function lobeToXY(u, v, k) {
  let ang = k * (Math.PI / 4);
  let ca = Math.cos(ang);
  let sa = Math.sin(ang);
  return [CX + u * ca - v * sa, CY + u * sa + v * ca];
}

// Build closed polygon for the full papaya lobe (uMin..uMax) using vFunc(t)
function buildSymmetricLobePoly(uMin, uMax, vFunc, steps, k, scaleV = 1.0) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let u = uMin + (uMax - uMin) * t;
    let v = vFunc(t) * scaleV;
    pts.push(lobeToXY(u, v, k));
  }
  for (let i = steps - 1; i >= 1; i--) {
    let t = i / steps;
    let u = uMin + (uMax - uMin) * t;
    let v = -vFunc(t) * scaleV;
    pts.push(lobeToXY(u, v, k));
  }
  return pts;
}

// Build flanking Hawaiian scroll-frond polygon in local (u, v) for side sgn (+1 or -1)
function getScrollFrondLocalPts() {
  // Connects to papaya neck/lower belly and arches into the 22.5-deg valley
  return [
    [104, 24],
    [116, 36],
    [132, 51],
    [154, 62],
    [182, 70],
    [212, 77],
    [240, 86],
    [262, 99],
    [274, 113.5], // meets 22.5 deg mirror axis (v = u * tan(22.5) = 0.4142 * u)
    [244, 101.1], // along 22.5 deg axis down to heart cutout top
    [224, 83],    // inner curl of scroll frond around valley cutout
    [202, 69],
    [180, 62],
    [160, 56],
    [144, 46],
    [132, 33],
    [118, 24]
  ];
}

// Build central calyx sector wedge polygon (connects all 8 lobes from r=48 to r=112)
function getCalyxSectorPts(k) {
  let pts = [];
  let steps = 16;
  let a0 = (k - 0.5) * (Math.PI / 4);
  let a1 = (k + 0.5) * (Math.PI / 4);
  // Outer arc from -22.5 to +22.5 around lobe k
  for (let i = 0; i <= steps; i++) {
    let f = i / steps;
    let a = a0 + (a1 - a0) * f;
    let localA = Math.abs(f - 0.5) * 2; // 0 at axis, 1 at valley
    let rOut = 114 + 22 * Math.pow(localA, 1.4);
    pts.push([CX + rOut * Math.cos(a), CY + rOut * Math.sin(a)]);
  }
  // Inner star cutout arc from +22.5 back to -22.5
  for (let i = steps; i >= 0; i--) {
    let f = i / steps;
    let a = a0 + (a1 - a0) * f;
    let localA = Math.abs(f - 0.5) * 2;
    let rIn = 42 + 22 * (1 - Math.pow(localA, 1.3));
    pts.push([CX + rIn * Math.cos(a), CY + rIn * Math.sin(a)]);
  }
  return pts;
}

// Trace any closed polygon with brush.beginShape / brush.vertex / brush.endShape
function traceShape(pts, curvature = 0.25, close = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(close);
}

// Precompute boundary sample points in the fundamental domain for Huygens wavefront echo-quilting
function getMotifWaveSources() {
  let sources = [];
  // Sample for k = -1, 0, 1 so wavefronts across the 0..22.5 deg wedge see neighbor lobes
  for (let k = -1; k <= 1; k++) {
    // 1. Papaya outer contour
    let pSteps = 75;
    for (let i = 0; i <= pSteps; i++) {
      let t = i / pSteps;
      let u = 98 + (526 - 98) * t;
      let v = papayaOuterV(t);
      sources.push(lobeToXY(u, v, k));
      sources.push(lobeToXY(u, -v, k));
    }
    // 2. Flanking scroll frond outer contour
    let frond = getScrollFrondLocalPts();
    for (let i = 0; i < frond.length - 1; i++) {
      let pA = frond[i];
      let pB = frond[i + 1];
      for (let s = 0; s < 4; s++) {
        let f = s / 4;
        let u = pA[0] + (pB[0] - pA[0]) * f;
        let v = pA[1] + (pB[1] - pA[1]) * f;
        sources.push(lobeToXY(u, v, k));
        sources.push(lobeToXY(u, -v, k));
      }
    }
  }
  // Convert to polar relative to (CX, CY)
  return sources.map(pt => {
    let dx = pt[0] - CX;
    let dy = pt[1] - CY;
    return { x: dx, y: dy, r: Math.hypot(dx, dy) };
  });
}

// Compute exact symmetric echo-quilting wave ring at offset distance d
function computeEchoRing(sources, d, angleSteps = 44) {
  let halfWedge = [];
  let maxAlpha = Math.PI / 8;
  for (let i = 0; i <= angleSteps; i++) {
    let alpha = (i / angleSteps) * maxAlpha;
    let ca = Math.cos(alpha);
    let sa = Math.sin(alpha);
    let rMax = 0;
    for (let j = 0; j < sources.length; j++) {
      let s = sources[j];
      // Perpendicular distance from source to ray alpha
      let q = -s.x * sa + s.y * ca;
      if (Math.abs(q) <= d) {
        let p = s.x * ca + s.y * sa;
        let reach = p + Math.sqrt(d * d - q * q);
        if (reach > rMax) rMax = reach;
      }
    }
    halfWedge.push({ alpha, r: rMax });
  }
  // Light 3-tap smoothing along alpha to mimic hand-quilted tension
  let smoothed = halfWedge.map((pt, idx) => {
    let prev = halfWedge[Math.max(0, idx - 1)].r;
    let next = halfWedge[Math.min(halfWedge.length - 1, idx + 1)].r;
    return { alpha: pt.alpha, r: 0.22 * prev + 0.56 * pt.r + 0.22 * next };
  });

  // Expand into all 16 half-wedges (strict D8 symmetry)
  let fullRing = [];
  for (let k = 0; k < 8; k++) {
    let baseAng = k * (Math.PI / 4);
    // Forward 0 .. +22.5 deg
    for (let i = 0; i < smoothed.length; i++) {
      let a = baseAng + smoothed[i].alpha;
      let r = smoothed[i].r;
      fullRing.push([CX + r * Math.cos(a), CY + r * Math.sin(a)]);
    }
    // Mirror +22.5 .. +45 deg
    for (let i = smoothed.length - 2; i >= 1; i--) {
      let a = baseAng + (Math.PI / 4 - smoothed[i].alpha);
      let r = smoothed[i].r;
      fullRing.push([CX + r * Math.cos(a), CY + r * Math.sin(a)]);
    }
  }
  return fullRing;
}

