// Draw tiny pencil stitches and radial fabric puckers along a polyline
function drawPuckeredStitchPath(pts, closed, stitchSpacing, puckerLen, isInnerRim = false) {
  let n = closed ? pts.length : pts.length - 1;
  let distAccum = 0;

  for (let i = 0; i < n; i++) {
    let p0 = pts[i];
    let p1 = pts[(i + 1) % pts.length];
    let dx = p1[0] - p0[0];
    let dy = p1[1] - p0[1];
    let segLen = Math.hypot(dx, dy);
    if (segLen < 0.001) continue;

    let tx = dx / segLen;
    let ty = dy / segLen;
    // Normal vector perpendicular to edge
    let nx = -ty;
    let ny = tx;

    let d = stitchSpacing - distAccum;
    while (d <= segLen) {
      let sx = p0[0] + tx * d;
      let sy = p0[1] + ty * d;

      // 1. Subtle radial pucker crease in cotton & fabric
      brush.set("2H", isInnerRim ? "#7a140d" : "#9c9488", 0.22);
      brush.line(
        sx - nx * puckerLen * 0.85,
        sy - ny * puckerLen * 0.85,
        sx + nx * puckerLen * 1.15,
        sy + ny * puckerLen * 1.15
      );

      // 2. Crisp tiny graphite needle-turn stitch across the seam
      brush.set("HB", isInnerRim ? "#3d120e" : "#45403b", 0.30);
      let sHalf = 2.1;
      brush.line(
        sx - nx * sHalf + tx * 0.9,
        sy - ny * sHalf + ty * 0.9,
        sx + nx * sHalf - tx * 0.9,
        sy + ny * sHalf - ty * 0.9
      );

      d += stitchSpacing;
    }
    distAccum = segLen - (d - stitchSpacing);
  }
}

