function draw() {
  translate(-width / 2, -height / 2);
  background("#f6f2e8");

  // =========================================================================
  // 1. BLEACHED COTTON FIELD: WEAVE, FOLD CREASES & SOFT BATTING TONE
  // =========================================================================
  brush.noStroke();
  brush.fill("#efe9dc", 55);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.15);
  brush.circle(CX, CY, 540, 0.05);
  brush.noFill();

  // Fine woven cotton threads (symmetric orthogonal warp & weft)
  brush.set("2H", "#e3ddd0", 0.16);
  for (let pos = 12; pos < 1200; pos += 16) {
    brush.line(pos, 0, pos, 1200);
    brush.line(0, pos, 1200, pos);
  }

  // Subtle folded-cloth creases along the 8 symmetry axes (kapa kuiki fold lines)
  for (let k = 0; k < 8; k++) {
    let a = k * (Math.PI / 4);
    let ca = Math.cos(a), sa = Math.sin(a);
    brush.set("glaze", "#e5dfd1", 0.65);
    brush.line(CX - 820 * ca, CY - 820 * sa, CX + 820 * ca, CY + 820 * sa);
    brush.set("2H", "#d4cdc0", 0.18);
    brush.line(CX - 820 * ca, CY - 820 * sa, CX + 820 * ca, CY + 820 * sa);
  }

  // =========================================================================
  // 2. CONCENTRIC ECHO-QUILTING LINES ("LIKE WAVES AROUND AN ISLAND")
  // =========================================================================
  let waveSources = getMotifWaveSources();
  let echoStep = 11.5;
  let numEchoRings = 44;

  for (let rIdx = 1; rIdx <= numEchoRings; rIdx++) {
    let d = rIdx * echoStep - 1.5;
    let ringPts = computeEchoRing(waveSources, d, 38);

    // Filter segments that lie inside the 1200x1200 canvas (with small margin)
    // Soft batting dimple shadow along each quilted wave
    brush.set("glaze", "#e3dccd", 0.52);
    traceShape(ringPts, 0.25, true);

    // Primary soft graphite echo-quilting contour line
    let gCol = rIdx % 3 === 0 ? "#5e5951" : "#756f66";
    let gW = rIdx <= 6 ? 0.27 : 0.22;
    brush.set("2H", gCol, gW);
    traceShape(ringPts, 0.25, true);

    // Delicate running-stitch rhythm along the inner 18 echo rings
    if (rIdx <= 18) {
      brush.set("HB", "#544f47", 0.22);
      for (let i = 0; i < ringPts.length; i += 2) {
        let p0 = ringPts[i];
        let p1 = ringPts[(i + 1) % ringPts.length];
        let mx = (p0[0] + p1[0]) * 0.5;
        let my = (p0[1] + p1[1]) * 0.5;
        if (mx > 10 && mx < 1190 && my > 10 && my < 1190) {
          brush.line(
            p0[0] * 0.65 + mx * 0.35,
            p0[1] * 0.65 + my * 0.35,
            mx * 0.35 + p1[0] * 0.65,
            my * 0.35 + p1[1] * 0.65
          );
        }
      }
    }
  }

  // Inner echo-quilting waves inside the central bleached-cotton star cutout (r < 62)
  for (let cRing = 1; cRing <= 4; cRing++) {
    let scale = 1 - cRing * 0.21;
    let cPts = [];
    for (let k = 0; k < 8; k++) {
      let a0 = (k - 0.5) * (Math.PI / 4);
      let a1 = (k + 0.5) * (Math.PI / 4);
      for (let i = 0; i < 12; i++) {
        let f = i / 12;
        let a = a0 + (a1 - a0) * f;
        let localA = Math.abs(f - 0.5) * 2;
        let rIn = (40 + 20 * (1 - Math.pow(localA, 1.3))) * scale;
        cPts.push([CX + rIn * Math.cos(a), CY + rIn * Math.sin(a)]);
      }
    }
    brush.set("glaze", "#e3dccd", 0.4);
    traceShape(cPts, 0.2, true);
    brush.set("2H", "#6b655c", 0.22);
    traceShape(cPts, 0.2, true);
  }

  // =========================================================================
  // 3. TURKEY RED APPLIQUÉ MOTIF (CUT-FABRIC SILHOUETTE)
  // =========================================================================
  let outerPapayaPolys = [];
  let innerPapayaPolys = [];
  let frondPolys = [];
  let calyxPolys = [];

  for (let k = 0; k < 8; k++) {
    outerPapayaPolys.push(buildSymmetricLobePoly(98, 526, papayaOuterV, 64, k, 1.0));
