  brush.fillTexture(0.55, 0.35);
  for (let k = 0; k < 8; k++) {
    traceShape(cavityDeepPolys[k], 0.25, true);
  }
  brush.noFill();

  // 6C. Fibrous orange-coral funiculi (seed stalks) & spongy placental web inside cavity
  for (let i = 1; i <= 18; i++) {
    let s = i / 19;
    let u = 192 + 252 * s;
    let vWall = cavityV(s);
    for (let k = 0; k < 8; k++) {
      for (let sgn of [-1, 1]) {
        let pAxis = lobeToXY(u + (s - 0.5) * 8, sgn * vWall * 0.12, k);
        let pMid = lobeToXY(u, sgn * vWall * 0.58, k);
        let pWall = lobeToXY(u - (s - 0.5) * 6, sgn * vWall * 1.04, k);

        brush.set("glaze", "#b32412", 0.38);
        brush.spline([pAxis, pMid, pWall], 0.4);

        brush.set("silk", "#ff7b3d", 0.36);
        brush.spline([pMid, pWall], 0.35);
      }
    }
  }

  // =========================================================================
  // 7. GLOSSY BLACK SEED CLUSTERS WITH PINPRICK HIGHLIGHTS
  // =========================================================================
  let halfSeeds = generateHalfCavitySeeds();

  // Render seeds tier by tier (0 -> 1 -> 2) so upper seeds overlap lower seeds naturally
  for (let tier = 0; tier <= 2; tier++) {
    let tierSeeds = halfSeeds.filter(sd => sd.tier === tier);

    for (let sd of tierSeeds) {
      let signs = sd.mirror ? [-1, 1] : [1];
      for (let sgn of signs) {
        let u = sd.u;
        let v = sgn * sd.v;
        let r = sd.r;
        let tilt = sgn * sd.tilt;
        let du = Math.cos(tilt) * r * 0.36;
        let dv = Math.sin(tilt) * r * 0.36;

        for (let k = 0; k < 8; k++) {
          // 1. Deep cavity cast shadow underneath each seed
          let shA = lobeToXY(u - du - 1.5, v - dv, k);
          let shB = lobeToXY(u + du - 1.5, v + dv, k);
          brush.set("glaze", "#120102", r * 0.12);
          brush.line(shA[0], shA[1], shB[0], shB[1]);

          // 2. Translucent amber-ruby sarcotesta (gelatinous aril envelope)
          let arA = lobeToXY(u - du * 1.1, v - dv * 1.1 + sgn * 0.9, k);
          let arB = lobeToXY(u + du * 1.1, v + dv * 1.1 + sgn * 0.9, k);
          brush.set("glaze", tier === 0 ? "#8f1b0e" : "#d93b14", r * 0.11);
          brush.line(arA[0], arA[1], arB[0], arB[1]);

          // 3. Plump obsidian-black ovoid seed body
          let pA = lobeToXY(u - du, v - dv, k);
          let pB = lobeToXY(u + du, v + dv, k);
          let bodyCol = tier === 0 ? "#1f1417" : (tier === 1 ? "#150e11" : "#0d090b");
          brush.set("seedBody", bodyCol, r * 0.155);
          brush.line(pA[0], pA[1], pB[0], pB[1]);

          // 4. Warm coral-mahogany subsurface bounce reflection on flesh-facing side
          let bOffsetV = sgn * r * 0.42;
          let bA = lobeToXY(u - du * 0.7, v + bOffsetV - dv * 0.5, k);
          let bMid = lobeToXY(u, v + bOffsetV * 1.15, k);
          let bB = lobeToXY(u + du * 0.7, v + bOffsetV + dv * 0.5, k);
          brush.set("silk", tier === 0 ? "#662014" : "#9c331c", 0.42);
          brush.spline([bA, bMid, bB], 0.45);

          // 5. Cool wet gloss sheen & subtle longitudinal seed ridge
          let gOffsetV = -sgn * r * 0.18;
          let gA = lobeToXY(u - du * 0.65, v + gOffsetV + 0.6, k);
          let gMid = lobeToXY(u + 0.6, v + gOffsetV * 0.5, k);
          let gB = lobeToXY(u + du * 0.65, v + gOffsetV - 0.6, k);
          brush.set("silk", tier === 2 ? "#636978" : "#454852", 0.38);
          brush.spline([gA, gMid, gB], 0.4);

          // 6. Crisp pinprick specular highlight (plus tiny secondary wet glint)
          let hPos = lobeToXY(u + r * 0.16, v - sgn * r * 0.14, k);
          let hPos2 = lobeToXY(u + r * 0.28, v - sgn * r * 0.08, k);
          brush.set("silk", "#ffffff", tier === 2 ? 0.68 : 0.52);
          brush.line(hPos[0] - 0.4, hPos[1] - 0.4, hPos[0] + 0.7, hPos[1] + 0.7);

          if (tier >= 1) {
            brush.set("rotring", "#fff9eb", 0.36);
            brush.line(hPos2[0], hPos2[1], hPos2[0] + 0.35, hPos2[1] + 0.35);
          }
        }
      }
    }
  }

  // Glistening wet mucilage bridges & juicy highlights along the cavity rim
  for (let i = 1; i <= 14; i++) {
    let s = i / 15;
    let u = 192 + 252 * s;
    let v = cavityV(s) * 0.96;
    for (let k = 0; k < 8; k++) {
      for (let sgn of [-1, 1]) {
        let p0 = lobeToXY(u - 3, sgn * v, k);
        let p1 = lobeToXY(u + 3, sgn * (v + 1.2), k);
        brush.set("silk", "#ffe6c2", 0.36);
        brush.line(p0[0], p0[1], p1[0], p1[1]);
      }
    }
  }

  // =========================================================================
  // 8. TINY PENCIL STITCHES PUCKERING ALL APPLIQUÉ EDGES
  // =========================================================================
  // 8A. Crisp fabric seam definition along outer & inner turkey red boundaries
  for (let k = 0; k < 8; k++) {
    brush.set("2H", "#7d0f0a", 0.28);
    traceShape(outerPapayaPolys[k], 0.2, true);
    traceShape(innerPapayaPolys[k], 0.2, true);
    traceShape(calyxPolys[k], 0.15, true);
  }
  for (let fp of frondPolys) {
    brush.set("2H", "#7d0f0a", 0.26);
    traceShape(fp, 0.2, true);
  }

  // 8B. Tiny perpendicular pencil stitches & pucker creases around every appliqué contour
  for (let k = 0; k < 8; k++) {
    drawPuckeredStitchPath(outerPapayaPolys[k], true, 7.5, 4.8, false);
    drawPuckeredStitchPath(innerPapayaPolys[k], true, 7.5, 4.2, true);
  }
  for (let fp of frondPolys) {
    drawPuckeredStitchPath(fp, false, 8.0, 4.2, false);
  }

  // Central star cutout stitched & puckered edge
  let starCutoutPts = [];
  for (let k = 0; k < 8; k++) {
    let a0 = (k - 0.5) * (Math.PI / 4);
    let a1 = (k + 0.5) * (Math.PI / 4);
    for (let i = 0; i < 10; i++) {
      let f = i / 10;
      let a = a0 + (a1 - a0) * f;
      let localA = Math.abs(f - 0.5) * 2;
      let rIn = 42 + 22 * (1 - Math.pow(localA, 1.3));
      starCutoutPts.push([CX + rIn * Math.cos(a), CY + rIn * Math.sin(a)]);
    }
  }
  drawPuckeredStitchPath(starCutoutPts, true, 6.5, 4.0, false);

  noLoop();
}

// Hyperreal Dithered Soda Can & Condensation on Vending-Machine Tray
// Rendered through a strict grid of chunky square marker pixels in p5.brush

const GRID = 120;      // 120 x 120 strict pixel grid
const CELL = 10;       // 10 x 10 canvas units per chunky pixel (1200 x 1200 total)

// Console-style 6-color palette with soft-pastel marker luminosity
const PALETTE = [
  "#181c36", // 0: NAVY (Deep midnight indigo-navy)
  "#eb4b6c", // 1: RED (Cherry soda red with pastel-rose marker warmth)
  "#7883a8", // 2: SILVER_DARK (Cool lavender-slate medium silver)
  "#bdc9e3", // 3: SILVER_LIGHT (Soft pearl-periwinkle light silver)
  "#7ce8fa", // 4: CYAN (Icy pastel electric cyan)
  "#fff7f9"  // 5: WHITE (Crisp warm-pastel chalk white)
];

// Slightly lighter stroke/scanline accents for physical marker layering
const PALETTE_ACCENT = [
  "#23294c", // 0: Lighter navy scanline / marker overlap
  "#f46482", // 1: Luminous cherry marker streak
  "#8894ba", // 2: Mid silver marker streak
  "#d0dbf2", // 3: Bright silver marker streak
  "#a2f1fe", // 4: Bright cyan frost streak
  "#ffffff"  // 5: Pure specular ink
];

// Standard 4x4 Bayer ordered dithering matrix (normalized 0..1)
const BAYER4 = [
  [ 0 / 16,  8 / 16,  2 / 16, 10 / 16],
  [12 / 16,  4 / 16, 14 / 16,  6 / 16],
  [ 3 / 16, 11 / 16,  1 / 16,  9 / 16],
  [15 / 16,  7 / 16, 13 / 16,  5 / 16]
];

let pixelGrid = [];
let activeMask = [];
let droplets = [];
let trayDrops = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4271);
  noiseSeed(4271);

  // Custom square chisel nib added after scaleBrushes for exact pixel control
  brush.add("pixel_nib", {
    type: "custom",
    weight: 2.4,
    scatter: 0.02,
    opacity: 185,
    spacing: 0.22,
    pressure: [1.0, 1.0, 1.0],
    tip: (_m) => {
      _m.rect(-1.2, -1.2, 2.4, 2.4);
    },
    rotate: "none",
    markerTip: false,
    noise: 0.05
  });

  initDroplets();
  computeSceneGrid();
}

function initDroplets() {
  // Curated hero droplets & running drip tracks across the cylinder
  const heroSpecs = [
    // [nx (-0.92..0.92), yCenter (28..88), rx, ry, trailLen]
    [-0.42, 41.0, 2.1, 2.7, 10.0], // Right on primary specular column
    [-0.18, 52.5, 2.4, 3.1, 15.0], // Crossing upper white wave
    [ 0.12, 63.0, 2.3, 3.0, 14.0], // Crossing lower wave into shadow
    [-0.64, 67.5, 2.0, 2.6, 12.0], // Cold cyan left zone drip
    [-0.30, 77.0, 2.5, 3.2, 16.0], // Large lower-left cherry belly bead
    [ 0.38, 46.5, 2.1, 2.8, 11.0], // Deep shadow side bead with bright glint
    [ 0.56, 72.0, 2.2, 2.9, 13.0], // Right bounce-light zone drip
    [-0.05, 35.5, 1.9, 2.4,  6.5], // Upper red logo zone bead
    [-0.52, 28.2, 1.8, 2.2,  0.0], // Silver shoulder bead
    [ 0.22, 29.0, 1.8, 2.2,  0.0], // Right silver shoulder bead
    [-0.75, 49.0, 1.8, 2.4,  8.0], // Far left frost bead
    [ 0.74, 55.5, 1.9, 2.5,  9.0], // Far right rim-lit bead
    [-0.12, 83.5, 2.2, 2.9, 10.0], // Near bottom taper
    [ 0.28, 84.5, 2.0, 2.6,  7.0], // Lower right taper bead
    // Hanging droplets on the bottom aluminium rim
    [-0.35, 93.8, 1.7, 2.4,  4.0],
    [ 0.04, 95.0, 1.9, 2.6,  5.0],
    [ 0.44, 93.5, 1.6, 2.2,  3.5]
  ];

  for (let s of heroSpecs) {
    droplets.push({
      nx: s[0],
      y: s[1],
      rx: s[2],
      ry: s[3],
      trail: s[4]
    });
  }

  // Additional medium & small condensation beads scattered across the can
  for (let i = 0; i < 42; i++) {
    let nx = random(-0.88, 0.88);
    let y = random(26.5, 89.0);
    // Avoid overlapping hero droplets too closely
    let tooClose = false;
    for (let d of droplets) {
      if (abs(nx - d.nx) * 21.5 < d.rx + 2.2 && abs(y - d.y) < d.ry + 2.8) {
        tooClose = true;
        break;
      }
    }
    if (!tooClose) {
      let isMed = random() < 0.45;
      droplets.push({
        nx: nx,
        y: y,
        rx: isMed ? random(1.3, 1.75) : random(0.85, 1.2),
        ry: isMed ? random(1.6, 2.2) : random(1.0, 1.45),
        trail: isMed && random() < 0.35 ? random(4.0, 8.0) : 0
      });
    }
  }

  // Stray water beads sitting on the metallic vending-machine tray
  trayDrops = [
    { x: 35.5, y: 95.5, rx: 2.2, ry: 1.4 },
    { x: 42.0, y: 100.2, rx: 1.8, ry: 1.2 },
    { x: 88.5, y: 96.8, rx: 2.4, ry: 1.5 },
    { x: 81.0, y: 100.8, rx: 1.7, ry: 1.2 },
    { x: 54.0, y: 101.5, rx: 2.0, ry: 1.2 }
  ];
}

// Helper: sample a color ramp [c0, c1, ...] at parameter t in [0, 1] using Bayer 4x4 dithering
function ditherRamp(ramp, t, gx, gy, bayerBias = 0) {
  let tc = constrain(t, 0, 0.9999);
  let scaled = tc * (ramp.length - 1);
  let idx = Math.floor(scaled);
  let frac = scaled - idx;
  let threshold = BAYER4[((gy % 4) + 4) % 4][((gx % 4) + 4) % 4];
  threshold = constrain(threshold + bayerBias, 0.05, 0.95);
  return frac > threshold ? ramp[idx + 1] : ramp[idx];
}

function computeSceneGrid() {
  // Initialize grid to 0 (NAVY) and activeMask to false
  for (let gy = 0; gy < GRID; gy++) {
    pixelGrid[gy] = new Array(GRID).fill(0);
    activeMask[gy] = new Array(GRID).fill(false);
  }

  // Off-centre placement on the 120x120 field (shifted slightly right and down)
  const canCX = 64.5;
  const lidCY = 23.5;
  const neckTopY = 23.5;
  const shoulderBotY = 31.0;
  const bodyBotY = 84.5;
  const baseBotY = 89.8;
  const R_top = 18.2;
  const R_body = 21.5;
  const R_base = 17.6;
  const kEll = 0.35; // Perspective ellipse squash factor

  for (let gy = 0; gy < GRID; gy++) {
    for (let gx = 0; gx < GRID; gx++) {
      let cx = gx + 0.5;
      let cy = gy + 0.5;

      // ---------------------------------------------------------
      // 1. CHECK SODA CAN SILHOUETTE & 3D SURFACE
      // ---------------------------------------------------------
      let inCan = false;
      let canColor = 0;

      // A. Top Lid & Seamed Rim Ellipse
      let ldx = (cx - canCX) / R_top;
      let ldy = (cy - lidCY) / (R_top * kEll);
      let lDist = Math.sqrt(ldx * ldx + ldy * ldy);

      if (lDist <= 1.04) {
        inCan = true;
        canColor = shadeCanLid(cx, cy, canCX, lidCY, ldx, ldy, lDist, gx, gy);
      } else {
        // B. Cylinder Body, Tapered Neck & Tapered Base Heel
        // Estimate vertical cross-section center y0 that projects to cy
        let yEst = cy - R_body * kEll * 0.65;
        for (let iter = 0; iter < 3; iter++) {
          let rHere = getCanRadius(yEst, neckTopY, shoulderBotY, bodyBotY, baseBotY, R_top, R_body, R_base);
          let nxTest = (cx - canCX) / rHere;
          let nzTest = Math.sqrt(Math.max(0, 1 - nxTest * nxTest));
          yEst = cy - rHere * kEll * nzTest;
        }

        if (yEst >= neckTopY && yEst <= baseBotY + 0.6) {
          let R = getCanRadius(yEst, neckTopY, shoulderBotY, bodyBotY, baseBotY, R_top, R_body, R_base);
          let nx = (cx - canCX) / R;
          if (Math.abs(nx) <= 1.0) {
            inCan = true;
            let nz = Math.sqrt(Math.max(0, 1 - nx * nx));
            let ySurf = cy - R * kEll * nz;
            canColor = shadeCanBody(cx, cy, canCX, nx, nz, ySurf, R, gx, gy, neckTopY, shoulderBotY, bodyBotY, baseBotY);
          }
        }
      }

      if (inCan) {
        pixelGrid[gy][gx] = canColor;
        activeMask[gy][gx] = true;
        continue;
      }

      // ---------------------------------------------------------
      // 2. CHECK VENDING-MACHINE TRAY & RECESSED CHUTE
      // ---------------------------------------------------------
      let trayInfo = shadeVendingTray(cx, cy, canCX, gx, gy);
      if (trayInfo.active) {
        pixelGrid[gy][gx] = trayInfo.color;
        activeMask[gy][gx] = true;
      }
    }
  }
}

function getCanRadius(y, neckTopY, shoulderBotY, bodyBotY, baseBotY, R_top, R_body, R_base) {
  if (y <= neckTopY) return R_top;
  if (y < shoulderBotY) {
    let t = (y - neckTopY) / (shoulderBotY - neckTopY);
    // Smooth S-curve shoulder flare
    let s = t * t * (3 - 2 * t);
    return R_top + (R_body - R_top) * s;
  }
  if (y <= bodyBotY) return R_body;
  if (y <= baseBotY) {
    let t = (y - bodyBotY) / (baseBotY - bodyBotY);
    let s = t * t;
    return R_body + (R_base - R_body) * s;
  }
  return R_base;
}

function shadeCanLid(cx, cy, canCX, lidCY, ldx, ldy, lDist, gx, gy) {
  // 1. Rolled Outer Chime (Top Seam Rim)
  if (lDist >= 0.89) {
    let rimPos = (lDist - 0.89) / 0.15; // 0 (inner edge) to 1 (outer edge)
    // Rim catches intense upper-left cyan/white light and lower-left front glint
    let light = 0.55 - 0.35 * ldx - 0.25 * ldy + 0.35 * Math.sin(rimPos * Math.PI);
    // Front edge highlight along bottom of ellipse (ldy > 0)
    if (ldy > 0.2 && ldx > -0.6 && ldx < 0.3 && rimPos > 0.2 && rimPos < 0.85) {
      light += 0.38;
    }
    const rimRamp = [0, 2, 3, 4, 5];
    return ditherRamp(rimRamp, light, gx, gy);
  }

  // 2. Deep Recessed Countersink Groove
  if (lDist >= 0.81) {
    // Upper-left of groove is in deep rim shadow; lower-right catches bounce
    let grooveLight = 0.22 + 0.35 * ldx + 0.30 * ldy;
    const grooveRamp = [0, 0, 2, 3, 4];
    return ditherRamp(grooveRamp, grooveLight, gx, gy);
  }

  // 3. Pull-Tab Assembly (Rivet + Ring + Lifted Tab Glint)
  // Central Rivet at (canCX, lidCY + 0.4)
  let rvx = cx - canCX;
  let rvy = (cy - (lidCY + 0.4)) / 0.55;
  let rvDist = Math.sqrt(rvx * rvx + rvy * rvy);
  if (rvDist < 1.85) {
    if (rvx < 0.2 && rvy < 0.2) return 5; // Crisp WHITE rivet glint
    if (rvDist < 1.2) return 4;           // CYAN core
    return 0;                             // Dark navy collar around rivet
  }

  // Pull-tab rotated coordinates (extending toward upper-right at -22 deg)
  let tx = (cx - (canCX + 2.8));
  let ty = (cy - (lidCY - 0.3)) / 0.48;
  let ang = -22 * Math.PI / 180;
  let ux = tx * Math.cos(ang) - ty * Math.sin(ang);
  let uy = tx * Math.sin(ang) + ty * Math.cos(ang);

  // Pull-tab outer rounded rectangle: ux in [-3.2, 5.6], uy in [-3.0, 3.0]
  if (ux >= -3.0 && ux <= 5.6 && Math.abs(uy) <= 3.1) {
    // Finger hole cutout in the right half of the tab
    let hx = (ux - 2.2) / 2.1;
    let hy = uy / 1.85;
    let hDist = Math.sqrt(hx * hx + hy * hy);

    // Shadow cast underneath the pull-tab onto the lid
    if (ux > 4.8 || Math.abs(uy) > 2.5) {
      return 0; // Crisp dark navy drop-shadow under lifted tab
    }

    if (hDist > 0.85) {
      // On the stamped metal of the pull-tab!
      // Create the iconic razor-sharp PULL-TAB GLINT along the upper bridge
      if (uy < -0.4 && ux > -2.2 && ux < 4.2) {
        return (gx + gy) % 2 === 0 || uy < -1.1 ? 5 : 4; // Crisp WHITE + CYAN glint
      }
      if (ux > -1.8 && ux < 0.4 && Math.abs(uy) <= 1.2) {
        return 5; // Central tab bridge glint
      }
      let tabLight = 0.65 - 0.15 * uy - 0.05 * ux;
      return ditherRamp([2, 3, 4, 5], tabLight, gx, gy);
    } else if (hDist > 0.65) {
      // Inner bevel of the finger hole
      return uy > 0 ? 5 : 0;
    }
  }

  // 4. Drink-Opening Score Line (Lower-Left Oval on Lid)
  let sx = (cx - (canCX - 4.2)) / 5.2;
  let sy = (cy - (lidCY + 1.3)) / 2.1;
  let sDist = Math.sqrt(sx * sx + sy * sy);
  if (sDist >= 0.82 && sDist <= 1.08) {
    // Score groove + adjacent bevel glint
    return sy > 0.2 ? 4 : 0;
  }

  // 5. Flat Lid Panel with Anisotropic Conical Brushed-Metal Reflection
  let phi = Math.atan2(ldy, ldx);
  let fan = Math.pow(Math.abs(Math.cos(phi * 2 + 0.65)), 1.6);
  let lidLight = 0.34 + 0.44 * fan - 0.14 * ldx + 0.10 * ldy;

  // Tiny water beads sitting on the flat lid
  let lidBead1 = Math.hypot(cx - (canCX - 9.5), (cy - (lidCY - 0.8)) / 0.5);
  if (lidBead1 < 1.8) return cx < canCX - 9.6 ? 5 : (cy > lidCY - 0.5 ? 0 : 4);
  let lidBead2 = Math.hypot(cx - (canCX + 8.5), (cy - (lidCY + 2.1)) / 0.5);
  if (lidBead2 < 1.6) return cx < canCX + 8.4 ? 5 : 0;

  return ditherRamp([0, 2, 3, 4, 5], lidLight, gx, gy);
}

function shadeCanBody(cx, cy, canCX, nx, nz, ySurf, R, gx, gy, neckTopY, shoulderBotY, bodyBotY, baseBotY) {
  // Determine surface material zone:
  // 1) Unpainted silver neck flange (ySurf < 26.2)
  // 2) Unpainted silver bottom heel & rim (ySurf > 86.2)
  // 3) Painted cherry-red body with white/silver wave graphic & logo
  let isSilverNeck = ySurf < 26.3;
  let isSilverBase = ySurf > 86.4;

  // Vertical surface normal tilt (upward on shoulder, downward on base taper)
  let ny = 0;
  if (ySurf < shoulderBotY) {
    ny = -0.45 * (1 - (ySurf - neckTopY) / (shoulderBotY - neckTopY));
  } else if (ySurf > bodyBotY) {
    ny = 0.50 * ((ySurf - bodyBotY) / (baseBotY - bodyBotY));
  }

  // ---------------------------------------------------------
  // CYLINDRICAL LIGHTING MODEL
  // ---------------------------------------------------------
  // Primary tall specular column at nx = -0.42
  let specDist = Math.abs(nx - (-0.42));
  let primarySpec = Math.exp(- (specDist * specDist) / (2 * 0.11 * 0.11));
  let wideLight = Math.exp(- Math.pow(nx - (-0.36), 2) / (2 * 0.38 * 0.38));

  // Secondary cold cyan strip reflection at nx = -0.76
  let cyanStrip = Math.exp(- Math.pow(nx - (-0.76), 2) / (2 * 0.08 * 0.08));

  // Core shadow on the right-center (nx around +0.32)
  let coreShadow = Math.exp(- Math.pow(nx - 0.32, 2) / (2 * 0.28 * 0.28));

  // Right-edge metallic tray bounce light (nx around +0.82)
  let rightBounce = Math.exp(- Math.pow(nx - 0.82, 2) / (2 * 0.12 * 0.12));

  // Extreme silhouette edge darkening (Fresnel rim)
  let edgeDark = Math.pow(Math.abs(nx), 6.0);

  // Upward shoulder catches extra overhead cyan/white light
  let shoulderBoost = ny < 0 ? -ny * 0.55 : -ny * 0.35;

  // ---------------------------------------------------------
  // CHECK CONDENSATION WET TRAILS (Vertical Drip Tracks)
  // ---------------------------------------------------------
  let inWetTrail = false;
  let trailEdge = 0;
  for (let d of droplets) {
    if (d.trail > 0) {
      let dX = canCX + d.nx * R;
      let dY = d.y + R * 0.35 * Math.sqrt(Math.max(0, 1 - d.nx * d.nx));
      if (cy < dY - d.ry * 0.5 && cy > dY - d.ry - d.trail) {
        let waveOffset = 0.35 * Math.sin(cy * 0.6 + d.y);
        let dxTrail = Math.abs(cx - (dX + waveOffset));
        let trailHalfW = 0.75 * (1 - 0.35 * ((dY - cy) / (d.trail + d.ry)));
        if (dxTrail <= trailHalfW) {
          inWetTrail = true;
          trailEdge = (cx - (dX + waveOffset)) / trailHalfW;
          break;
        }
      }
    }
  }

  // ---------------------------------------------------------
  // CHECK 3D CONDENSATION DROPLETS (Beads & Cast Shadows)
  // ---------------------------------------------------------
  let dropShadow = 0;
  for (let d of droplets) {
    let rAtD = 21.5;
    let dX = canCX + d.nx * rAtD;
    let dNz = Math.sqrt(Math.max(0, 1 - d.nx * d.nx));
    let dY = d.y + rAtD * 0.35 * dNz;

    // Foreshorten horizontal droplet width slightly near cylinder edges
    let rxEff = d.rx * (0.55 + 0.45 * dNz);
    let ryEff = d.ry;

    let ux = (cx - dX) / rxEff;
    let uy = (cy - dY) / ryEff;
    // Teardrop deformation: slightly narrower at top (uy < 0), plumper at bottom (uy > 0)
    let tearScale = 1.0 - 0.22 * constrain(uy, -1, 1);
    let uxTear = ux * tearScale;
    let distSq = uxTear * uxTear + uy * uy;

    if (distSq <= 1.0) {
      // Inside a condensation water bead!
      // 1. Pinpoint specular glint at upper-left core
      if (uxTear >= -0.62 && uxTear <= 0.12 && uy >= -0.65 && uy <= -0.02) {
        return 5; // Pure WHITE glint
      }
      // 2. Immediate cyan corona around the white glint
      if (uxTear >= -0.75 && uxTear <= 0.30 && uy >= -0.78 && uy <= 0.18 && distSq < 0.72) {
        return 4; // Icy CYAN
      }
      // 3. Dark upper refractive rim (water lens inverting dark upper surroundings)
      if (uy < -0.35 || distSq > 0.82 && uy < 0.15) {
        return nx < -0.2 ? 2 : 0; // Dark SILVER or NAVY rim
      }
      // 4. Lower-right caustic belly (focused light through water drop)
      if (uy > 0.18 && uxTear > -0.35) {
        let caustic = 0.65 + 0.35 * uy + 0.25 * primarySpec;
        if (isSilverNeck || isSilverBase) {
          return ditherRamp([3, 4, 5], caustic, gx, gy);
        }
        return ditherRamp([1, 3, 4, 5], caustic, gx, gy);
      }
      // 5. Mid droplet body
      return isSilverNeck || isSilverBase ? 2 : (nx > 0.2 ? 0 : 1);
    }

    // Crescent cast shadow directly below the droplet (uy in [1.0, 1.55])
    let sx = (cx - (dX + 0.35)) / (rxEff * 0.92);
    let sy = (cy - (dY + ryEff * 0.95)) / (ryEff * 0.55);
    if (sx * sx + sy * sy <= 1.0 && sy > 0) {
      dropShadow = 0.48;
    }
  }

  // ---------------------------------------------------------
  // CHECK GRAPHIC WAVE RIBBON & EMBOSSED LOGO ON CYLINDER
  // ---------------------------------------------------------
  let theta = Math.asin(constrain(nx, -1, 1)); // Cylindrical angle [-pi/2, pi/2]
  let isWhiteGraphic = false;
  let isSilverTrim = false;
  let isGraphicShadow = false;

  if (!isSilverNeck && !isSilverBase) {
    // Classic sweeping dynamic double-wave ribbon wrapping around the cylinder
    let waveCenter = 57.5 - 8.5 * Math.sin(theta * 1.45 + 0.3) - 3.2 * theta;
    let waveDist = ySurf - waveCenter;

    if (waveDist >= -2.4 && waveDist <= 2.4) {
      isWhiteGraphic = true;
    } else if (waveDist > 2.4 && waveDist <= 3.3) {
      isGraphicShadow = true; // Crisp dark shadow edge under main wave
    } else if (waveDist >= 4.2 && waveDist <= 5.6) {
      isSilverTrim = true;    // Secondary silver/cyan pinstripe wave
    }

    // Bold geometric soda brand emblem / script blocks above the wave
    let logoY = ySurf - (42.5 - 3.5 * Math.sin(theta * 1.2 + 0.2));
    if (logoY >= -4.2 && logoY <= 4.2 && theta > -1.05 && theta < 0.95) {
      // Create stepped typographic letterform bars in cylindrical space
      let uChar = (theta + 1.0) * 11.5;
      let charIdx = Math.floor(uChar);
      let charFrac = uChar - charIdx;
      // Skewed italic letter strokes
      let uSkew = charFrac + (logoY * 0.08);
      if (charIdx >= 1 && charIdx <= 18 && charIdx !== 6 && charIdx !== 13) {
        let inStroke = (uSkew > 0.18 && uSkew < 0.78) &&
                       (Math.abs(logoY) > 1.2 || (charIdx % 2 === 0) || uSkew < 0.45);
        // Capital initial letter C / S flourish
        if (charIdx === 1 || charIdx === 2) {
          inStroke = Math.abs(logoY) < 4.0 && (Math.abs(logoY) > 2.1 || uSkew < 0.55);
        }
        if (inStroke) {
          isWhiteGraphic = true;
        } else if (uSkew >= 0.78 && uSkew <= 0.95 && logoY > -3.0) {
          isGraphicShadow = true;
        }
      }
    }

    // Small crisp pixel specification ticks near bottom left ("355mL" badge)
    if (ySurf >= 77.5 && ySurf <= 80.5 && theta >= -0.85 && theta <= -0.35) {
      let badgeU = Math.floor((theta + 0.85) * 24);
      if (badgeU % 2 === 0 && Math.floor(ySurf) % 2 === 0) {
        isSilverTrim = true;
      }
    }
  }

  // ---------------------------------------------------------
  // COMPUTE FINAL SURFACE SHADING & DITHER RAMP SELECTION
  // ---------------------------------------------------------
  // Fine micro-frost noise (tiny 1-pixel condensation mist on cold aluminium)
  let frostHash = ((gx * 73 + gy * 151) % 97) / 97.0;
  let frostBias = 0;
  if (!inWetTrail && dropShadow === 0) {
    if (frostHash > 0.91 && wideLight > 0.25) frostBias = 0.18;
    else if (frostHash < 0.07) frostBias = -0.14;
  }

  // Wet trail modifies surface: glossy wet streak with a bright edge
  if (inWetTrail) {
    frostBias = trailEdge < -0.1 ? 0.22 : -0.18;
  }

  // 1. Silver Neck or Silver Base Rim Shading
  if (isSilverNeck || isSilverBase) {
    let metalLum = 0.30 +
      0.42 * wideLight +
      0.48 * primarySpec +
      0.28 * cyanStrip +
      0.24 * rightBounce -
      0.32 * coreShadow -
      0.45 * edgeDark +
      shoulderBoost -
      dropShadow +
      frostBias;

    // Extra bright bottom chime lip right at the base seam
    if (isSilverBase && ySurf > 88.2 && ySurf < 89.4 && nx > -0.65 && nx < 0.25) {
      metalLum += 0.32;
    }
    const silverRamp = [0, 2, 3, 4, 5];
    return ditherRamp(silverRamp, metalLum, gx, gy);
  }

  // 2. White Wave / Brand Graphic Shading
  if (isWhiteGraphic) {
    let whiteLum = 0.38 +
      0.40 * wideLight +
      0.45 * primarySpec +
      0.25 * cyanStrip +
      0.22 * rightBounce -
      0.38 * coreShadow -
      0.45 * edgeDark -
      dropShadow +
      frostBias;
    const whiteRamp = [0, 2, 3, 4, 5];
    return ditherRamp(whiteRamp, whiteLum, gx, gy);
  }

  // 3. Silver/Cyan Secondary Wave Trim
  if (isSilverTrim) {
    let trimLum = 0.28 +
      0.38 * wideLight +
      0.45 * primarySpec +
      0.35 * cyanStrip +
      0.20 * rightBounce -
      0.35 * coreShadow -
      dropShadow;
    const trimRamp = [0, 2, 4, 3, 5];
    return ditherRamp(trimRamp, trimLum, gx, gy);
  }

  // 4. Cherry-Red Aluminium Body Shading
  let redLum = 0.34 +
    0.34 * wideLight +
    0.52 * primarySpec +
    0.20 * cyanStrip +
    0.18 * rightBounce -
    0.36 * coreShadow -
    0.50 * edgeDark +
    shoulderBoost -
    dropShadow -
    (isGraphicShadow ? 0.32 : 0) +
    frostBias;

  // Choose ramp based on lighting zone so cold cyan frost & cherry red harmonize
  if (cyanStrip > 0.35 && primarySpec < 0.3) {
    // Grazing cold cyan frost zone on the left
    const frostRedRamp = [0, 1, 2, 4, 5];
    return ditherRamp(frostRedRamp, redLum + 0.08, gx, gy);
  } else if (rightBounce > 0.32 && nx > 0.55) {
    // Cool metallic bounce reflection on the right rim
    const bounceRedRamp = [0, 1, 2, 3, 4];
    return ditherRamp(bounceRedRamp, redLum + 0.12, gx, gy);
  } else {
    // Main cherry-red body to pastel-pink/silver/cyan/white specular highlight
    const cherryRamp = [0, 0, 1, 1, 3, 4, 5];
    return ditherRamp(cherryRamp, redLum, gx, gy);
  }
}

function shadeVendingTray(cx, cy, canCX, gx, gy) {
  // Off-centre recessed vending machine tray & chute framing the lower half
  // 1. Recessed Dark Delivery Chute Behind the Can (gy: 66..84)
  if (cy >= 66.0 && cy < 84.0) {
    let halfW = 35.5 + (cy - 66.0) * 0.25;
    let dx = cx - canCX;
    if (Math.abs(dx) <= halfW) {
      // Side bevel frames of the recessed chute
      if (Math.abs(dx) > halfW - 2.5) {
        let frameLum = dx < 0 ? 0.35 : 0.62; // Right inner wall catches left light
        return { active: true, color: ditherRamp([0, 2, 3, 4], frameLum, gx, gy) };
      }
      // Top cold LED light leak inside the chute ceiling (gy: 66..71)
      let chuteLum = 0.08;
      if (cy < 71.5) {
        chuteLum = 0.52 * (1 - (cy - 66.0) / 5.5) * Math.exp(- (dx * dx) / 700);
        return { active: true, color: ditherRamp([0, 2, 4, 5], chuteLum, gx, gy) };
      }
      // Horizontal metallic delivery flap louvers
      if (Math.floor(cy) % 4 === 0 && Math.abs(dx) < halfW - 5) {
        chuteLum = 0.22 + 0.12 * Math.exp(- Math.pow(dx + 10, 2) / 400);
      }
      return { active: true, color: ditherRamp([0, 0, 2, 4], chuteLum, gx, gy) };
    }
  }

  // 2. Sloped Brushed-Steel Tray Floor (gy: 84..103.5)
  if (cy >= 84.0 && cy < 103.5) {
    let tY = (cy - 84.0) / 19.5; // 0 at back, 1 at front lip
    let halfW = 38.0 + tY * 8.5; // Perspective flare toward viewer
    let dx = cx - canCX;

    if (Math.abs(dx) <= halfW) {
      // Raised angled side rims of the tray
      if (Math.abs(dx) > halfW - 3.2) {
        let rimLight = dx < 0 ? 0.58 : 0.42;
        if (Math.abs(dx) > halfW - 1.2) rimLight -= 0.28;
        return { active: true, color: ditherRamp([0, 2, 3, 4, 5], rimLight, gx, gy) };
      }

      // Check stray water droplets on the tray floor
      for (let td of trayDrops) {
        let ux = (cx - td.x) / td.rx;
        let uy = (cy - td.y) / td.ry;
        let d2 = ux * ux + uy * uy;
        if (d2 <= 1.0) {
          if (ux < 0.0 && uy < 0.0) return { active: true, color: 5 };
          if (d2 < 0.65) return { active: true, color: 4 };
          return { active: true, color: 0 };
        }
        if (ux * ux + Math.pow(uy - 0.85, 2) <= 0.85) {
          return { active: true, color: 0 };
        }
      }

      // Check Cold Condensation Puddle pooled around the base of the can
      let px = (cx - (canCX - 1.5)) / 24.5;
      let py = (cy - 93.8) / 6.2;
      // Organic wavy puddle contour
      let puddleAngle = Math.atan2(py, px);
      let puddleRad = 1.0 + 0.12 * Math.sin(puddleAngle * 3 + 0.5) + 0.08 * Math.cos(puddleAngle * 5);
      let pDist = Math.sqrt(px * px + py * py) / puddleRad;

      // Direct contact shadow right under the can base
      let contactDist = Math.hypot((cx - canCX) / 18.8, (cy - 90.2) / 5.4);
      if (contactDist < 1.08) {
        return { active: true, color: 0 }; // Deep NAVY contact occlusion
      }

      if (pDist <= 1.0) {
        // Crisp bright meniscus rim at the edge of the water puddle
        if (pDist > 0.86) {
          let meniscus = (py > 0 || px < -0.2) ? 0.82 : 0.35;
          return { active: true, color: ditherRamp([0, 2, 4, 5], meniscus, gx, gy) };
        }
        // Mirror reflection of the cherry-red can & cyan specular column inside the puddle!
        let rxNorm = (cx - canCX) / 20.5;
        if (Math.abs(rxNorm) < 1.0) {
          let isSpecRefl = Math.abs(rxNorm - (-0.40)) < 0.18;
          let isCyanRefl = Math.abs(rxNorm - (-0.74)) < 0.14;
          // Ripple distortion on the puddle surface
          let ripple = Math.sin(cy * 2.4 + cx * 0.35) * 0.14;
          if (isSpecRefl) {
            return { active: true, color: ditherRamp([2, 3, 4, 5], 0.72 + ripple, gx, gy) };
          }
          if (isCyanRefl) {
            return { active: true, color: ditherRamp([0, 2, 4, 5], 0.62 + ripple, gx, gy) };
          }
          // Reflected cherry-red cylinder in the dark water
          let redRefl = 0.48 - 0.25 * rxNorm + ripple;
          return { active: true, color: ditherRamp([0, 0, 1, 1, 2, 4], redRefl, gx, gy) };
        }
        return { active: true, color: ditherRamp([0, 2, 4], 0.45, gx, gy) };
      }

      // Brushed-Steel Tray Floor Outside the Puddle
      let floorLum = 0.26 + 0.24 * tY - 0.12 * (dx / halfW);
      // Soft diffused red bounce on the tray metal near the can
      if (Math.abs(dx) < 19.0 && cy < 101.0) {
        let bounceT = (1 - Math.abs(dx) / 19.0) * (1 - (cy - 94.0) / 8.0);
        if (bounceT > 0.15) {
          return { active: true, color: ditherRamp([0, 1, 2, 3], floorLum + bounceT * 0.35, gx, gy) };
        }
      }
      // Stamped perspective drainage ribs on the steel tray bed
      let ribX = Math.abs((dx + 30) % 12 - 6);
      if (ribX < 1.1 && cy > 87.0 && cy < 101.0 && Math.abs(dx) > 21.0) {
        floorLum += (dx % 12 < 6) ? 0.24 : -0.18;
      }

      return { active: true, color: ditherRamp([0, 2, 3, 4], floorLum, gx, gy) };
    }
  }

  // 3. Front Bevelled Metallic Tray Lip / Guard Bar (gy: 103.5..110.5)
  if (cy >= 103.5 && cy <= 110.5) {
    let halfW = 46.5 - (cy > 108.5 ? (cy - 108.5) * 2.0 : 0);
    let dx = cx - canCX;
    if (Math.abs(dx) <= halfW) {
      // Top upward-facing bevel of the front bar (gy: 103.5..105.6) catches bright light
      if (cy < 105.6) {
        let lipSpec = 0.62 + 0.32 * Math.exp(- Math.pow(dx + 9.0, 2) / 280) - 0.20 * Math.pow(dx / halfW, 2);
        return { active: true, color: ditherRamp([2, 3, 4, 5], lipSpec, gx, gy) };
      }
      // Vertical front face of the guard bar stepping down into dark navy shadow
      let faceT = (cy - 105.6) / 4.9;
      let faceLum = 0.42 * (1 - faceT) + 0.12 * Math.exp(- Math.pow(dx + 8.0, 2) / 350);
      // Corner rivets on the front tray bar
      if (Math.abs(Math.abs(dx) - 39.0) < 1.6 && Math.abs(cy - 107.8) < 1.3) {
        return { active: true, color: cy < 107.8 ? 4 : 0 };
      }
      return { active: true, color: ditherRamp([0, 0, 2, 3], faceLum, gx, gy) };
    }
  }

  return { active: false, color: 0 };
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // ---------------------------------------------------------
  // 1. DARK NAVY FIELD WITH FAINT SCANLINE RHYTHM
  // ---------------------------------------------------------
  background("#14172d");

  // Base dark navy wash across canvas
  brush.noStroke();
  brush.wash(PALETTE[0], 245);
  brush.rect(0, 0, width, height);
  brush.noWash();

  // Faint scanline rhythm of slightly lighter navy rows across the entire field
  for (let gy = 0; gy < GRID; gy++) {
    let y = gy * CELL;
    if (gy % 2 === 0) {
      // Slightly lighter navy scanline row
      brush.noStroke();
      brush.wash("#202547", 190);
      brush.rect(0, y + 1.0, width, CELL - 2.0);
      brush.noWash();

      brush.set("marker", "#252b52", 0.55);
      brush.line(4, y + CELL * 0.5, width - 4, y + CELL * 0.5);
    } else {
      // Deep velvet navy row texture
      brush.set("marker", "#151830", 0.5);
      brush.line(4, y + CELL * 0.5, width - 4, y + CELL * 0.5);
    }
  }

  // Subtle vertical pixel-grid groove lines on the navy field so the strict grid is felt
  brush.set("rotring", "#121528", 0.35);
  for (let gx = 0; gx <= GRID; gx++) {
    let x = gx * CELL;
    brush.line(x, 0, x, height);
  }

  // ---------------------------------------------------------
  // 2. RENDER CHUNKY SQUARE MARKER PIXELS (BATCHED BY PALETTE)
  // ---------------------------------------------------------
  // Draw each of the 6 console colors in batches for crisp square geometry + marker grain
  const pad = 0.65; // Crisp micro-groove around every 10x10 chunky pixel square
  const sqSize = CELL - pad * 2;

  for (let cIdx = 0; cIdx < PALETTE.length; cIdx++) {
    const baseHex = PALETTE[cIdx];
    const accentHex = PALETTE_ACCENT[cIdx];

    // Pass A: Crisp square marker body via brush.wash + brush.rect
    brush.noStroke();
    brush.wash(baseHex, 246);
    for (let gy = 0; gy < GRID; gy++) {
      for (let gx = 0; gx < GRID; gx++) {
        if (activeMask[gy][gx] && pixelGrid[gy][gx] === cIdx) {
          brush.rect(gx * CELL + pad, gy * CELL + pad, sqSize, sqSize);
        }
      }
    }
    brush.noWash();

    // Pass B: Physical square-nib marker stroke inside every pixel + scanline modulation
    for (let gy = 0; gy < GRID; gy++) {
      let isLightScanRow = (gy % 2 === 0);
      // Alternate marker ink tone slightly on even rows to preserve the faint scanline rhythm
      brush.set("pixel_nib", isLightScanRow ? accentHex : baseHex, 1.0);

      for (let gx = 0; gx < GRID; gx++) {
        if (activeMask[gy][gx] && pixelGrid[gy][gx] === cIdx) {
          let px = gx * CELL;
          let py = gy * CELL;
          // Chisel marker pass across the top half of the pixel square
          brush.line(px + 2.2, py + 3.3, px + CELL - 2.2, py + 3.3);
        }
      }

      // Second marker stroke across the bottom half of the pixel square for rich felt saturation
      brush.set("marker", baseHex, 0.48);
      for (let gx = 0; gx < GRID; gx++) {
        if (activeMask[gy][gx] && pixelGrid[gy][gx] === cIdx) {
          let px = gx * CELL;
          let py = gy * CELL;
          brush.line(px + 1.8, py + 6.9, px + CELL - 1.8, py + 6.9);
        }
      }
    }
  }

  // ---------------------------------------------------------
  // 3. CRISP SPECULAR INK DEFINERS ON GLINTS & HARD STEPPED EDGES
  // ---------------------------------------------------------
  // Reinforce the pure WHITE and CYAN pixels (pull-tab glint, water bead pinpoints)
  // with crisp square marker edges so they pop with hyperreal luminosity
  brush.set("rotring", PALETTE[5], 0.55);
  for (let gy = 0; gy < GRID; gy++) {
    for (let gx = 0; gx < GRID; gx++) {
      if (activeMask[gy][gx] && pixelGrid[gy][gx] === 5) {
        let px = gx * CELL + 1.2;
        let py = gy * CELL + 1.2;
        let s = CELL - 2.4;
        brush.line(px, py, px + s, py);
        brush.line(px, py + s * 0.5, px + s, py + s * 0.5);
      }
    }
  }

  noLoop();
}

// Hyperrealism × Vorticism: Pneumatic Jackhammer Biting into Asphalt
// Hard graphite (2H, HB, 2B), stiff technical pen (rotring), oil smears,
// and knife-sharp pastel watercolour shards (slate grey, burnt sienna, acid yellow ochre).

let ORIGIN;
let THETA = 60; // Main diagonal axis of the jackhammer (no horizontals/verticals)
let U_DIR, V_DIR;
let FAULTS = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  ORIGIN = { x: 558, y: 558 };
  V_DIR = { x: cos(THETA), y: sin(THETA) };         // Down-right along shaft (60°)
  U_DIR = { x: cos(THETA - 90), y: sin(THETA - 90) }; // Up-right perpendicular (-30°)

  initVorticistFaults();
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. Archival paper ground & Vorticist tectonic construction rays
  drawPaperGround();

  // 2. Background & midground flat watercolour shards (slate grey, burnt sienna, acid yellow ochre)
  drawVorticistWatercolorShards();

  // 3. Kinetic geometric plane hatching behind the tool
  drawBackgroundKineticPlanes();

  // 4. Shattered asphalt impact crater & tilted tarmac slabs (lower-right diagonal bed)
  drawAsphaltCraterAndSlabs();

  // 5. Pneumatic Jackhammer: air hose, T-handle, tie-rods, cylinder, exhaust boss, fronthead, latch, hex shaft
  drawPneumaticJackhammer();

  // 6. Worker's gloved knuckles gripping both T-handles with forensic anatomical & leather detail
  drawWorkerGlovedKnuckles();

  // 7. Forensic surface incidents: black compressor oil smears, bare steel scuffs, vibration ghosts
  drawForensicOilAndScuffs();

  // 8. Flying polyhedral chips of tarmac, aggregate shrapnel & ballistic trajectories
  drawFlyingTarmacChips();

  // 9. Razor-sharp Vorticist fracture lines & foreground shrapnel planes
  drawForegroundVorticistFractures();

  noLoop();
}

// ============================================================================
// COORDINATE TRANSFORMS & GEOMETRIC POLYGON CLIPPING / HATCHING ENGINE
// ============================================================================

function toWorld(u, v, shearU = 0, shearV = 0) {
  let uu = u + shearU;
  let vv = v + shearV;
  return [
    ORIGIN.x + uu * U_DIR.x + vv * V_DIR.x,
    ORIGIN.y + uu * U_DIR.y + vv * V_DIR.y
  ];
}

function mapUVPoly(uvPts, shearU = 0, shearV = 0) {
  let out = [];
  for (let i = 0; i < uvPts.length; i++) {
    out.push(toWorld(uvPts[i][0], uvPts[i][1], shearU, shearV));
  }
  return out;
}

function initVorticistFaults() {
  // Knife-sharp diagonal fault lines slicing across the sheet (no 0° or 90° angles)
  let defs = [
    { x: 560, y: 490, ang: 24,  shear: 4.5, dAng: 28 },
    { x: 640, y: 690, ang: -33, shear: -4.0, dAng: -32 },
    { x: 470, y: 340, ang: -26, shear: 3.5, dAng: 24 },
    { x: 745, y: 880, ang: 41,  shear: -5.0, dAng: -26 },
    { x: 590, y: 580, ang: 63,  shear: 2.5, dAng: 19 },
    { x: 410, y: 250, ang: 16,  shear: -3.0, dAng: -22 },
    { x: 785, y: 950, ang: -52, shear: 4.0, dAng: 35 }
  ];
  for (let d of defs) {
    let rad = d.ang * Math.PI / 180;
    let dx = Math.cos(rad), dy = Math.sin(rad);
    FAULTS.push({
      px: d.x, py: d.y,
      dx: dx, dy: dy,
      nx: -dy, ny: dx,
      ang: d.ang,
      shear: d.shear,
      dAng: d.dAng
    });
  }
}

// Sutherland-Hodgman half-plane polygon split: returns [posPoly, negPoly]
function splitPolyByLine(pts, px, py, nx, ny) {
  if (!pts || pts.length < 3) return [[], []];
  let pos = [], neg = [];
  let n = pts.length;
  for (let i = 0; i < n; i++) {
    let A = pts[i];
    let B = pts[(i + 1) % n];
    let dA = (A[0] - px) * nx + (A[1] - py) * ny;
    let dB = (B[0] - px) * nx + (B[1] - py) * ny;

    if (dA >= 0) pos.push(A);
    if (dA <= 0) neg.push(A);

    if ((dA > 0 && dB < 0) || (dA < 0 && dB > 0)) {
      let t = dA / (dA - dB);
      let I = [A[0] + t * (B[0] - A[0]), A[1] + t * (B[1] - A[1])];
      pos.push(I);
      neg.push(I);
    }
  }
  return [pos.length >= 3 ? pos : [], neg.length >= 3 ? neg : []];
}

// Recursively fracture a polygon by a subset of Vorticist fault lines
function fracturePoly(pts, faultIndices, applyShear = false) {
  let cells = [{ pts: pts, dAng: 0, parity: 0 }];
  for (let idx of faultIndices) {
    let f = FAULTS[idx];
    let next = [];
    for (let c of cells) {
      let [p1, p2] = splitPolyByLine(c.pts, f.px, f.py, f.nx, f.ny);
      if (p1.length >= 3 && p2.length >= 3) {
        let shiftedP1 = p1;
        if (applyShear) {
          shiftedP1 = p1.map(pt => [pt[0] + f.dx * f.shear, pt[1] + f.dy * f.shear]);
        }
        next.push({ pts: shiftedP1, dAng: c.dAng + f.dAng, parity: c.parity + 1 });
        next.push({ pts: p2, dAng: c.dAng, parity: c.parity });
      } else if (p1.length >= 3) {
        next.push(c);
      } else if (p2.length >= 3) {
        next.push(c);
      }
    }
    cells = next;
  }
  return cells;
}

// Precision scanline clipper for stiff, knife-sharp parallel hatching inside any polygon
function hatchPoly(pts, spacing, angleDeg, brushName, col, weight, opts = {}) {
  if (!pts || pts.length < 3) return;
  spacing = Math.max(spacing, 1.8);

  let rad = angleDeg * Math.PI / 180;
  let dx = Math.cos(rad), dy = Math.sin(rad);
  let nx = -dy, ny = dx;

  let dMin = Infinity, dMax = -Infinity;
  for (let i = 0; i < pts.length; i++) {
    let d = pts[i][0] * nx + pts[i][1] * ny;
    if (d < dMin) dMin = d;
    if (d > dMax) dMax = d;
  }

  let span = dMax - dMin;
  if (span <= 0.5) return;

  brush.set(brushName, col, weight);

  let startOffset = opts.offset !== undefined ? opts.offset : spacing * 0.45;
  let skipProb = opts.skipProb || 0;
  let inset = opts.inset || 0;

  for (let d = dMin + startOffset; d <= dMax - inset; d += spacing) {
    if (skipProb > 0 && random() < skipProb) continue;

    // Collect intersections with polygon edges
    let tVals = [];
    let n = pts.length;
    for (let i = 0; i < n; i++) {
      let A = pts[i];
      let B = pts[(i + 1) % n];
      let dA = A[0] * nx + A[1] * ny;
      let dB = B[0] * nx + B[1] * ny;
      if ((dA <= d && dB > d) || (dB <= d && dA > d)) {
        let u = (d - dA) / (dB - dA);
        let ix = A[0] + u * (B[0] - A[0]);
        let iy = A[1] + u * (B[1] - A[1]);
        tVals.push(ix * dx + iy * dy);
      }
    }

    if (tVals.length < 2) continue;
    tVals.sort((a, b) => a - b);

    for (let k = 0; k + 1 < tVals.length; k += 2) {
      let t0 = tVals[k] + inset;
      let t1 = tVals[k + 1] - inset;
      if (t1 - t0 > 0.8) {
        let x0 = d * nx + t0 * dx;
        let y0 = d * ny + t0 * dy;
        let x1 = d * nx + t1 * dx;
        let y1 = d * ny + t1 * dy;
        brush.line(x0, y0, x1, y1);
      }
    }
  }

  if (opts.crossAngle !== undefined) {
    let cSpace = opts.crossSpacing || spacing * 1.25;
    let cBrush = opts.crossBrush || brushName;
    let cCol = opts.crossCol || col;
    let cWeight = opts.crossWeight || weight * 0.9;
    hatchPoly(pts, cSpace, opts.crossAngle, cBrush, cCol, cWeight, { inset: inset });
  }

  if (opts.outline) {
    drawPolyOutline(
      pts,
      opts.outlineBrush || "rotring",
      opts.outlineCol || col,
      opts.outlineWeight || weight * 1.05
    );
  }
}

function drawPolyOutline(pts, brushName, col, weight) {
  if (!pts || pts.length < 2) return;
  brush.set(brushName, col, weight);
  for (let i = 0; i < pts.length; i++) {
    let A = pts[i];
    let B = pts[(i + 1) % pts.length];
    brush.line(A[0], A[1], B[0], B[1]);
  }
}

function fillWatercolorBatch(polys, col, opacity, bleed = 0.015, tex = 0.38, border = 0.48) {
  brush.noStroke();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "in");
  brush.fillTexture(tex, border);
  for (let pts of polys) {
    if (!pts || pts.length < 3) continue;
    brush.beginShape(0);
    for (let p of pts) {
      brush.vertex(p[0], p[1]);
    }
    brush.endShape(true);
  }
  brush.noFill();
}

function washPolyBatch(polys, col, opacity) {
  brush.noStroke();
  brush.noHatch();
  brush.wash(col, opacity);
  for (let pts of polys) {
    if (!pts || pts.length < 3) continue;
    brush.beginShape(0);
    for (let p of pts) {
      brush.vertex(p[0], p[1]);
    }
    brush.endShape(true);
  }
  brush.noWash();
}

