function drawAggregateInCleavage(poly, count) {
  // Compute bounding box of cleavage face and scatter sharp crushed-granite aggregate polygons
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (let p of poly) {
    if (p[0] < minX) minX = p[0];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[1] > maxY) maxY = p[1];
  }
  let aggCols = ["#e3d598", "#d4927a", "#b8c3cc", "#eae4d7"];
  for (let i = 0; i < count; i++) {
    let t = (i + 0.5) / count;
    let cx = lerp(poly[0][0], poly[1][0], t) + random(-8, 8);
    let cy = lerp(poly[0][1], poly[1][1], t) + random(6, 26);
    let r = random(3.5, 8.5);
    let a0 = random(360);
    let stone = [
      [cx + cos(a0) * r, cy + sin(a0) * r],
      [cx + cos(a0 + 95) * r * 0.8, cy + sin(a0 + 95) * r * 0.8],
      [cx + cos(a0 + 195) * r * 1.1, cy + sin(a0 + 195) * r * 1.1],
      [cx + cos(a0 + 280) * r * 0.7, cy + sin(a0 + 280) * r * 0.7]
    ];
    washPolyBatch([stone], aggCols[i % aggCols.length], 215);
    drawPolyOutline(stone, "rotring", "#111317", 0.32);
  }
}

function drawTarmacFissures() {
  let crackStarts = [
    [-65, 430, -145, 7],
    [-140, 410, -165, 8],
    [65, 430, -25, 7],
    [150, 405, -12, 8],
    [-35, 515, 135, 6],
    [45, 520, 42, 6]
  ];
  for (let cs of crackStarts) {
    let u = cs[0], v = cs[1], ang = cs[2], steps = cs[3];
    for (let s = 0; s < steps; s++) {
      let len = random(24, 46);
      let nu = u + cos(ang) * len;
      let nv = v + sin(ang) * len;
      let p0 = toWorld(u, v);
      let p1 = toWorld(nu, nv);
      brush.set("rotring", "#0c0e12", map(s, 0, steps, 0.85, 0.28));
      brush.line(p0[0], p0[1], p1[0], p1[1]);
      // Bright edge chip next to fissure
      brush.set("2H", "#ebe4d6", 0.28);
      brush.line(p0[0] + 2, p0[1] - 1.5, p1[0] + 2, p1[1] - 1.5);
      u = nu;
      v = nv;
      ang += random(-32, 32);
    }
  }
}

