    { u0: -1.00, u1: -0.72, wash: "#9aa7b5", op: 215, sp: 4.2, ang: 28,  br: "HB", col: "#323942", w: 0.32, cross: false },
    { u0: -0.72, u1: -0.38, wash: "#b8c3ce", op: 215, sp: 5.2, ang: -35, br: "2H", col: "#3d4652", w: 0.28, cross: false },
    { u0: -0.38, u1: -0.10, wash: "#f7f5ef", op: 240, sp: 14.0, ang: 60, br: "2H", col: "#858f9c", w: 0.22, cross: false },
    { u0: -0.10, u1:  0.20, wash: "#d5dde5", op: 220, sp: 6.0, ang: 42,  br: "2H", col: "#454e59", w: 0.28, cross: false },
    { u0:  0.20, u1:  0.52, wash: "#7a8694", op: 225, sp: 3.6, ang: -28, br: "HB", col: "#252b33", w: 0.35, cross: true, cAng: 48 },
    { u0:  0.52, u1:  0.82, wash: "#3e4652", op: 235, sp: 2.5, ang: 32,  br: "rotring", col: "#14181e", w: 0.40, cross: true, cAng: -44 },
    { u0:  0.82, u1:  1.00, wash: "#c78d75", op: 215, sp: 3.8, ang: -52, br: "HB", col: "#2c333d", w: 0.34, cross: false }
  ];

  for (let s of strips) {
    let quadUV = [
      [uCenter + s.u0 * rTop, vTop],
      [uCenter + s.u1 * rTop, vTop],
      [uCenter + s.u1 * rBot, vBot],
      [uCenter + s.u0 * rBot, vBot]
    ];
    let quadW = mapUVPoly(quadUV);
    washPolyBatch([quadW], s.wash, s.op);

    // Fracture cylinder strip across the Vorticist fault lines so hatching changes direction per plane
    let cells = fracturePoly(quadW, [0, 1, 2, 4], false);
    for (let c of cells) {
      let hAng = s.ang + baseAngOffset + c.dAng;
      hatchPoly(c.pts, s.sp, hAng, s.br, s.col, s.w, {
        crossAngle: s.cross ? (s.cAng + baseAngOffset + c.dAng) : undefined,
        crossSpacing: s.sp * 1.18,
        crossBrush: "2B",
        crossCol: "#181c22",
        crossWeight: s.w * 0.95,
        outline: c.parity > 0,
        outlineBrush: "2H",
        outlineCol: "#2e3540",
        outlineWeight: 0.26
      });
    }
  }

  // Crisp outer contour and top/bottom machined bevel lines
  let outUV = [
    [uCenter - rTop, vTop],
    [uCenter + rTop, vTop],
    [uCenter + rBot, vBot],
    [uCenter - rBot, vBot]
  ];
  drawPolyOutline(mapUVPoly(outUV), "rotring", "#14181e", 0.52);
}

// Renders a 3-faced hexagonal nut or collar in (u, v) coordinates
function drawHexBlock(uCenter, vTop, vBot, radius, isDark = false) {
  let faces = [
    { u0: -1.0, u1: -0.35, wash: isDark ? "#768290" : "#9ba7b5", sp: 3.6, ang: 24, col: "#262c34", cross: false },
    { u0: -0.35, u1: 0.35, wash: isDark ? "#d8dfe6" : "#f5f2eb", sp: 7.5, ang: -32, col: "#4a535e", cross: false },
    { u0:  0.35, u1: 1.0,  wash: isDark ? "#323942" : "#49525e", sp: 2.5, ang: 48, col: "#14181e", cross: true }
  ];
  for (let f of faces) {
    let p = mapUVPoly([
      [uCenter + f.u0 * radius, vTop],
      [uCenter + f.u1 * radius, vTop],
      [uCenter + f.u1 * radius, vBot],
      [uCenter + f.u0 * radius, vBot]
    ]);
    washPolyBatch([p], f.wash, 235);
    hatchPoly(p, f.sp, f.ang, "rotring", f.col, 0.34, {
      crossAngle: f.cross ? -38 : undefined,
      crossSpacing: f.sp * 1.2,
      outline: true,
      outlineBrush: "rotring",
      outlineCol: "#14171c",
      outlineWeight: 0.48
    });
  }
}

function drawPneumaticJackhammer() {
  // --- A. BRAIDED HIGH-PRESSURE AIR HOSE & SWIVEL INLET (v = -590 to -415) ---
  let hoseSegs = [
    { u0: -105, v0: -575, u1: -68, v1: -525, r: 17 },
    { u0: -68,  v0: -525, u1: -36, v1: -475, r: 17 },
    { u0: -36,  v0: -475, u1: -12, v1: -430, r: 18 }
  ];
  for (let hs of hoseSegs) {
    let hPoly = mapUVPoly([
      [hs.u0 - hs.r, hs.v0], [hs.u0 + hs.r, hs.v0],
      [hs.u1 + hs.r, hs.v1], [hs.u1 - hs.r, hs.v1]
    ]);
    washPolyBatch([hPoly], "#39404a", 230);
    // Braided cross-hatch texture on high-pressure hose
    hatchPoly(hPoly, 3.2, 18, "rotring", "#161a20", 0.35, {
      crossAngle: -42,
      crossSpacing: 3.2,
      outline: true,
      outlineCol: "#111419",
      outlineWeight: 0.48
