  }
  // Swivel hex nut & brass crimp ferrule at air inlet
  drawHexBlock(-10, -442, -412, 24, false);

  // --- B. TOP T-HANDLE BAR & THROTTLE VALVE HEAD (v = -412 to -345) ---
  // Left & Right steel grip bars extending from central crown (u = -235 to +235)
  let handleIntervals = [
    [-235, -195], // Left outer end-cap
    [-95, -52],   // Left inner neck
    [52, 95],     // Right inner neck
    [195, 235]    // Right outer end-cap
  ];
  for (let iv of handleIntervals) {
    let u0 = iv[0], u1 = iv[1];
    let topStrip = mapUVPoly([[u0, -402], [u1, -402], [u1, -390], [u0, -390]]);
    let midStrip = mapUVPoly([[u0, -390], [u1, -390], [u1, -378], [u0, -378]]);
