    washPolyBatch([topStrip], "#e8e4da", 235);
    washPolyBatch([midStrip], "#8c98a6", 230);
    washPolyBatch([botStrip], "#2d333c", 240);
    hatchPoly(topStrip, 5.0, -30, "2H", "#454e59", 0.28, { outline: true, outlineCol: "#1a1e24", outlineWeight: 0.42 });
    hatchPoly(midStrip, 3.4, 25, "HB", "#22272f", 0.34, { outline: true, outlineCol: "#1a1e24", outlineWeight: 0.42 });
    hatchPoly(botStrip, 2.4, -45, "rotring", "#111419", 0.40, { crossAngle: 35, outline: true, outlineCol: "#111419", outlineWeight: 0.48 });
  }

  // Squeeze throttle trigger lever under the right handle bar
  let throttlePoly = mapUVPoly([[62, -364], [190, -352], [184, -338], [58, -350]]);
  washPolyBatch([throttlePoly], "#55606e", 230);
  hatchPoly(throttlePoly, 3.0, 40, "rotring", "#181c22", 0.36, { outline: true, outlineWeight: 0.48 });

  // Central T-handle valve crown casting
  drawSteelCylinderSection(-415, -365, 56, 62, 12, 0);
  drawSteelCylinderSection(-365, -330, 66, 60, -15, 0);

  // --- C. MAIN CYLINDER BLOCK, STEPPED FORGINGS & COOLING RIBS (v = -330 to -50) ---
  drawSteelCylinderSection(-330, -275, 58, 58, 0, 0);    // Upper valve chest
  drawSteelCylinderSection(-275, -260, 64, 64, 22, 0);   // Upper retaining flange
  drawSteelCylinderSection(-260, -165, 54, 54, -10, 0);  // Main piston cylinder
  drawSteelCylinderSection(-165, -150, 60, 56, 18, 0);   // Mid reinforcement ring
  drawSteelCylinderSection(-150, -55,  52, 50, 5, 0);    // Lower anvil block housing
  drawSteelCylinderSection(-55,  -38,  62, 58, -20, 0);  // Fronthead bolster flange

  // Cast-iron Exhaust Deflector Boss on right flank of cylinder (u = +48 to +92, v = -255 to -175)
  let exhFront = mapUVPoly([[48, -255], [86, -245], [86, -180], [48, -170]]);
  let exhSide  = mapUVPoly([[86, -245], [102, -235], [102, -190], [86, -180]]);
  washPolyBatch([exhFront], "#7c8896", 235);
  washPolyBatch([exhSide], "#2e3540", 240);
  hatchPoly(exhFront, 3.4, -25, "HB", "#222730", 0.34, { crossAngle: 55, outline: true, outlineCol: "#14181e", outlineWeight: 0.50 });
  hatchPoly(exhSide, 2.3, 38, "rotring", "#12151a", 0.40, { crossAngle: -42, outline: true, outlineCol: "#12151a", outlineWeight: 0.52 });

  // 3 recessed rectangular exhaust ports in the boss
  for (let vp = -238; vp <= -196; vp += 20) {
    let slot = mapUVPoly([[56, vp], [80, vp + 4], [80, vp + 13], [56, vp + 9]]);
    washPolyBatch([slot], "#101317", 250);
    drawPolyOutline(slot, "rotring", "#0b0d10", 0.52);
  }

  // --- D. TWIN SIDE TIE-RODS (LONG TENSION BOLTS, u = -74 and u = +74) ---
  for (let side of [-1, 1]) {
    let uRod = side * 74;
    // Upper lug & hex nut
    drawHexBlock(uRod, -365, -342, 18, side === 1);
    // Exposed upper bolt threads
    for (let vt = -382; vt < -365; vt += 4.5) {
      let p0 = toWorld(uRod - 9, vt);
      let p1 = toWorld(uRod + 9, vt + 2);
      brush.set("rotring", "#1a1e24", 0.38);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
    // Long tension rod shaft (v = -342 to -35)
    drawSteelCylinderSection(-342, -35, 9.5, 9.5, side * 18, uRod);
    // Lower bolster lug & heavy clamping hex nut
    drawHexBlock(uRod, -35, -8, 19, side === 1);
    // Lower lock nut
    drawHexBlock(uRod, -8, 12, 16, !side);
    // Exposed lower bolt threads
    for (let vt = 12; vt <= 30; vt += 4.5) {
      let p0 = toWorld(uRod - 8, vt);
      let p1 = toWorld(uRod + 8, vt + 2);
      brush.set("rotring", "#1a1e24", 0.38);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
