  drawSteelCylinderSection(-38, 35, 48, 42, -8, 0);
  drawSteelCylinderSection(35, 95, 40, 35, 16, 0);
  drawSteelCylinderSection(95, 140, 35, 31, -14, 0);
  drawHexBlock(0, 140, 158, 34, false); // Chuck nose ring

  // Forged Retainer Latch / Stirrup on right side of fronthead (u = +34 to +82, v = +12 to +172)
  let latchPivot = mapUVPoly([[36, 5], [76, 15], [76, 52], [36, 48]]);
  washPolyBatch([latchPivot], "#626e7c", 235);
  hatchPoly(latchPivot, 3.0, -35, "rotring", "#1c2026", 0.38, { crossAngle: 45, outline: true, outlineWeight: 0.50 });

  // Coiled retainer spring rings (v = 52 to 92)
  for (let vs = 54; vs <= 88; vs += 8.5) {
    let coil = mapUVPoly([[42, vs], [78, vs + 3], [78, vs + 8], [42, vs + 5]]);
    washPolyBatch([coil], "#d0d8e0", 230);
    hatchPoly(coil, 2.5, 25, "rotring", "#181c22", 0.38, { outline: true, outlineWeight: 0.45 });
  }

  // Forged stirrup bail looping down around the hex shaft collar
  let bailArm = mapUVPoly([[54, 88], [74, 92], [58, 192], [28, 198], [28, 178], [44, 174]]);
  washPolyBatch([bailArm], "#47515e", 240);
  hatchPoly(bailArm, 2.8, 52, "rotring", "#14181e", 0.38, {
    crossAngle: -28,
    outline: true,
    outlineCol: "#0f1217",
    outlineWeight: 0.55
  });

  // --- F. THE HEXAGONAL STEEL SHAFT / MOIL POINT CHISEL (v = +158 to +475) ---
  // Forged upset collar at v = 166..190
  drawHexBlock(0, 166, 190, 31, false);
  // Short neck above collar
  drawSteelCylinderSection(158, 166, 22, 22, 0, 0);

  // Main 38mm Hexagonal Tool-Steel Shaft (v = 190 to 388, radius = 22)
  // Three razor-sharp longitudinal hexagonal faces: Left, Center (Specular), Right (Core Shadow + Bounce)
  let vS0 = 190, vS1 = 388, rHex = 22;
  let hexFaces = [
    // Left oblique face: mid-slate steel with tight machining hatching
    {
      u0: -rHex, u1: -rHex * 0.34,
      wash: "#95a2b0", sp: 3.4, ang: 26, br: "HB", col: "#252b34", w: 0.34, cross: true, cAng: -52
    },
    // Center flat face: blinding polished tool steel catching hard top-left light
    {
      u0: -rHex * 0.34, u1: rHex * 0.34,
      wash: "#f9f7f1", sp: 9.5, ang: -30, br: "2H", col: "#6c7682", w: 0.24, cross: false
    },
    // Right oblique face: deep core shadow with warm sienna reflection near the bottom
    {
      u0: rHex * 0.34, u1: rHex,
      wash: "#363e4a", sp: 2.3, ang: -42, br: "rotring", col: "#12151a", w: 0.40, cross: true, cAng: 38
    }
  ];

  for (let hf of hexFaces) {
    let fPoly = mapUVPoly([
      [hf.u0, vS0], [hf.u1, vS0],
      [hf.u1, vS1], [hf.u0, vS1]
    ]);
    washPolyBatch([fPoly], hf.wash, 242);

    // Slice the hexagonal shaft across the Vorticist fault planes!
    let cells = fracturePoly(fPoly, [1, 3, 4, 6], false);
    for (let c of cells) {
      hatchPoly(c.pts, hf.sp, hf.ang + c.dAng, hf.br, hf.col, hf.w, {
        crossAngle: hf.cross ? (hf.cAng + c.dAng) : undefined,
        crossSpacing: hf.sp * 1.15,
        crossBrush: "2B",
        crossCol: "#161a20",
        outline: true,
        outlineBrush: "rotring",
        outlineCol: "#14181e",
        outlineWeight: 0.45
      });
