  }

  // Pyramidal Moil-Point Tip biting into the asphalt (v = 388 to 475)
  let tipLeft   = mapUVPoly([[-rHex, 388], [-rHex * 0.34, 388], [-2, 472], [-6, 468]]);
  let tipCenter = mapUVPoly([[-rHex * 0.34, 388], [rHex * 0.34, 388], [2, 472], [-2, 472]]);
  let tipRight  = mapUVPoly([[rHex * 0.34, 388], [rHex, 388], [6, 468], [2, 472]]);

  washPolyBatch([tipLeft], "#7e8b99", 240);
