  hatchPoly(tipRight, 2.0, -38, "rotring", "#0e1116", 0.42, { crossAngle: 42, outline: true, outlineWeight: 0.55 });

  // Pulverized rock-dust shock cone at exact point of bite (v = 435..475)
  let dustCone = mapUVPoly([[-38, 445], [0, 415], [38, 445], [14, 480], [-14, 480]]);
  fillWatercolorBatch([dustCone], "#f4efe4", 185, 0.02, 0.45, 0.5);
  hatchPoly(dustCone, 3.8, -62, "2H", "#8a8478", 0.28);
}

// ============================================================================
// 6. WORKER'S GLOVED KNUCKLES (FORENSIC ANATOMICAL & LEATHER DETAIL)
