function drawWorkerGlovedKnuckles() {
  // Both hands grip the T-handles tightly:
  // Left Hand: u from -198 to -88 (fingers curled over handle at v = -418 to -352)
  // Right Hand: u from +88 to +198 (fingers curled over handle at v = -418 to -352)
  drawSingleGlovedHand(-1, -196, -90);
  drawSingleGlovedHand(1, 90, 196);
}

function drawSingleGlovedHand(side, uMin, uMax) {
  // Four fingers (Index closest to center column, Little finger on outer grip)
  let fingerCount = 4;
  let totalSpan = uMax - uMin;
  let fWidth = totalSpan / fingerCount;

  // 1. Heavy canvas/leather safety cuff & dorsal metacarpal plane (v = -485 to -415)
  let uOuter = side < 0 ? uMin - 18 : uMax + 18;
  let uInner = side < 0 ? uMax + 6  : uMin - 6;
  let cuffU0 = Math.min(uOuter, uInner);
  let cuffU1 = Math.max(uOuter, uInner);

  let cuffPoly = mapUVPoly([
    [cuffU0 - side * 14, -495],
    [cuffU1 - side * 8,  -488],
    [uMax, -416],
    [uMin, -416]
  ]);
  washPolyBatch([cuffPoly], "#d8ccb8", 235);
  let cuffCells = fracturePoly(cuffPoly, [2, 5], false);
  for (let c of cuffCells) {
    hatchPoly(c.pts, 4.2, (side < 0 ? 32 : -44) + c.dAng, "HB", "#4a433b", 0.34, {
      crossAngle: (side < 0 ? -38 : 28) + c.dAng,
      crossSpacing: 6.0,
      outline: true,
      outlineBrush: "rotring",
      outlineCol: "#26221e",
      outlineWeight: 0.45
    });
  }

  // Leather knuckle reinforcement strap across the back of the hand (v = -432 to -412)
  let strapPoly = mapUVPoly([
    [uMin - 4, -434],
    [uMax + 4, -432],
    [uMax + 2, -412],
    [uMin - 2, -414]
  ]);
  washPolyBatch([strapPoly], "#bfa98e", 240);
  hatchPoly(strapPoly, 3.5, side * 25, "HB", "#3b322b", 0.34, {
    outline: true,
    outlineBrush: "rotring",
    outlineCol: "#1e1916",
    outlineWeight: 0.48
  });

  // 2. Four Individual Gloved Fingers & Knuckles
  for (let i = 0; i < fingerCount; i++) {
    // Arch the knuckles anatomically: middle & index knuckles project slightly higher
    let archV = (i === 1 || i === 2) ? -6 : (i === 0 ? -2 : 3);
    let fu0 = uMin + i * fWidth + 1.2;
    let fu1 = uMin + (i + 1) * fWidth - 1.2;
    let fuMid = (fu0 + fu1) * 0.5;
    let bevelW = (fu1 - fu0) * 0.28;

    let vKnuckleTop = -416 + archV;
    let vKnuckleCrown = -398 + archV;
    let vProximalMid = -374 + archV;
    let vPIPJoint = -352 + archV;
    let vTuckBot = -338 + archV;

    // --- A. MCP Knuckle Crown (3 polyhedral facets: Left Bevel, Central Crown, Right Shadow Bevel) ---
    let kLeft = mapUVPoly([
      [fu0, vKnuckleTop], [fu0 + bevelW, vKnuckleTop - 2],
      [fu0 + bevelW, vKnuckleCrown], [fu0, vKnuckleCrown + 2]
    ]);
    let kCenter = mapUVPoly([
      [fu0 + bevelW, vKnuckleTop - 2], [fu1 - bevelW, vKnuckleTop - 2],
      [fu1 - bevelW, vKnuckleCrown], [fu0 + bevelW, vKnuckleCrown]
    ]);
    let kRight = mapUVPoly([
      [fu1 - bevelW, vKnuckleTop - 2], [fu1, vKnuckleTop],
      [fu1, vKnuckleCrown + 2], [fu1 - bevelW, vKnuckleCrown]
    ]);

    washPolyBatch([kLeft], "#cbbba4", 240);
    washPolyBatch([kCenter], "#f6f1e6", 248); // Scuffed bright leather crown
    washPolyBatch([kRight], "#7d6e5d", 242);

    hatchPoly(kLeft, 3.2, 42, "HB", "#3d342c", 0.32, { outline: true, outlineCol: "#221d18", outlineWeight: 0.42 });
    hatchPoly(kCenter, 7.5, -24, "2H", "#7a6e60", 0.24, { outline: true, outlineCol: "#221d18", outlineWeight: 0.42 });
    hatchPoly(kRight, 2.5, -48, "rotring", "#1e1915", 0.38, { crossAngle: 32, outline: true, outlineCol: "#181411", outlineWeight: 0.46 });

    // --- B. Proximal Phalanx (Sloping down over the grip bar, split into 2 taut leather crease facets) ---
    let pUpperLeft = mapUVPoly([[fu0, vKnuckleCrown + 2], [fuMid + 2, vKnuckleCrown], [fuMid, vProximalMid], [fu0, vProximalMid + 2]]);
    let pUpperRight = mapUVPoly([[fuMid + 2, vKnuckleCrown], [fu1, vKnuckleCrown + 2], [fu1, vProximalMid + 2], [fuMid, vProximalMid]]);

    washPolyBatch([pUpperLeft], "#dfd3c0", 242);
    washPolyBatch([pUpperRight], "#8f7e6a", 242);

    hatchPoly(pUpperLeft, 3.8, -18 + i * 7, "HB", "#383028", 0.32, {
      crossAngle: 58,
      crossSpacing: 6.2,
      outline: true,
      outlineCol: "#1e1915",
      outlineWeight: 0.44
    });
    hatchPoly(pUpperRight, 2.6, 46 - i * 5, "rotring", "#1f1a16", 0.38, {
      crossAngle: -34,
      crossSpacing: 3.4,
      outline: true,
      outlineCol: "#181411",
      outlineWeight: 0.46
    });

    // Lower proximal segment approaching PIP joint
    let pLowerLeft = mapUVPoly([[fu0, vProximalMid + 2], [fuMid, vProximalMid], [fuMid - 1, vPIPJoint], [fu0 + 1, vPIPJoint + 2]]);
    let pLowerRight = mapUVPoly([[fuMid, vProximalMid], [fu1, vProximalMid + 2], [fu1 - 1, vPIPJoint + 2], [fuMid - 1, vPIPJoint]]);

    washPolyBatch([pLowerLeft], "#b8a792", 242);
    washPolyBatch([pLowerRight], "#5e5144", 245);

    hatchPoly(pLowerLeft, 3.0, 28, "HB", "#2b241e", 0.35, {
      crossAngle: -45,
      crossSpacing: 4.5,
      outline: true,
      outlineCol: "#1a1512",
      outlineWeight: 0.45
    });
    hatchPoly(pLowerRight, 2.2, -52, "rotring", "#16120f", 0.40, {
      crossAngle: 28,
      crossSpacing: 2.8,
      outline: true,
      outlineCol: "#120f0c",
      outlineWeight: 0.48
    });

    // --- C. PIP Knuckle Ridge & Curled Middle Phalanx tucking under the handle bar ---
    let pipTuck = mapUVPoly([
      [fu0 + 1, vPIPJoint + 2], [fu1 - 1, vPIPJoint + 2],
      [fu1 - 3, vTuckBot], [fu0 + 3, vTuckBot]
    ]);
    washPolyBatch([pipTuck], "#383029", 248);
    hatchPoly(pipTuck, 2.0, -30, "rotring", "#120f0c", 0.44, {
      crossAngle: 50,
      crossSpacing: 2.4,
      outline: true,
      outlineCol: "#0d0b09",
      outlineWeight: 0.52
    });

    // --- D. Forensic Leather Details: Tension Creases, Saddle Stitching & Grease Smudges ---
    // Sharp leather tension folds across each knuckle joint
    let c1A = toWorld(fu0 + 2, vKnuckleCrown + 1);
    let c1B = toWorld(fu1 - 2, vKnuckleCrown - 1);
    let c2A = toWorld(fu0 + 2, vProximalMid + 1);
    let c2B = toWorld(fu1 - 2, vProximalMid - 1);
    brush.set("rotring", "#16120f", 0.52);
    brush.line(c1A[0], c1A[1], c1B[0], c1B[1]);
    brush.line(c2A[0], c2A[1], c2B[0], c2B[1]);

    // Scuffed white highlight along crease ridge
    brush.set("rotring", "#faf6ee", 0.38);
    brush.line(c1A[0], c1A[1] - 1.5, c1B[0], c1B[1] - 1.5);

    // Double-row saddle stitching along finger seam
    brush.set("rotring", "#241e19", 0.34);
    for (let vs = vKnuckleTop + 3; vs < vPIPJoint; vs += 6.5) {
      let st0 = toWorld(fu0 + 2.2, vs);
      let st1 = toWorld(fu0 + 2.2, vs + 3.2);
      brush.line(st0[0], st0[1], st1[0], st1[1]);
    }

    // Deep inter-digital valley shadow between adjacent fingers
