// Control points for the main specular ridge (Curve B) of the grand piano lid corner
const LID_CTRL = [
  [-120, 912],
  [-20, 895],
  [210, 870],
  [440, 836],
  [650, 792],
  [785, 748],
  [850, 706], // Primary corner apex (Cold White Glint zone)
  [902, 632],
  [948, 500],
  [998, 290],
  [1055, -40],
  [1095, -180]
];

// Catmull-Rom interpolation helper
function catmullRom(p0, p1, p2, p3, t) {
  const t2 = t * t;
  const t3 = t2 * t;
  return 0.5 * (
    (2 * p1) +
    (-p0 + p2) * t +
    (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 +
    (-p0 + 3 * p1 - 3 * p2 + p3) * t3
  );
}

// Evaluate position and normal along the grand piano lid edge
// t in [0, 1], bevelShift: < 0 is inward on lid surface, 0 is main ridge, > 0 is outer bevel/rim
function evalLidCurve(t, bevelShift = 0) {
  const n = LID_CTRL.length - 3;
  const u = constrain(t, 0, 0.999999) * n;
  const idx = Math.floor(u);
  const frac = u - idx;

  const p0 = LID_CTRL[idx];
  const p1 = LID_CTRL[idx + 1];
  const p2 = LID_CTRL[idx + 2];
  const p3 = LID_CTRL[idx + 3];

  const x = catmullRom(p0[0], p1[0], p2[0], p3[0], frac);
  const y = catmullRom(p0[1], p1[1], p2[1], p3[1], frac);

  // Tangent via small finite difference
  const eps = 0.002;
  const u2 = constrain(t + eps, 0, 0.999999) * n;
  const idx2 = Math.floor(u2);
  const frac2 = u2 - idx2;
  const q0 = LID_CTRL[idx2];
  const q1 = LID_CTRL[idx2 + 1];
  const q2 = LID_CTRL[idx2 + 2];
  const q3 = LID_CTRL[idx2 + 3];
  const x2 = catmullRom(q0[0], q1[0], q2[0], q3[0], frac2);
  const y2 = catmullRom(q0[1], q1[1], q2[1], q3[1], frac2);

  let tx = x2 - x;
  let ty = y2 - y;
  const len = Math.hypot(tx, ty) || 1;
  tx /= len;
  ty /= len;

  // Outward normal (pointing down-right, away from lid interior)
  const nx = ty;
  const ny = -tx;

  // Foreshortening swell around the dramatic corner apex (t ~ 0.665)
  const cornerSwelling = 1.0 + 0.36 * Math.exp(-Math.pow((t - 0.665) / 0.115, 2));
  const shift = bevelShift * cornerSwelling;

  return {
    x: x + nx * shift,
    y: y + ny * shift,
    tx,
    ty,
    nx,
    ny,
    angle: atan2(ty, tx),
    normalAngle: atan2(ny, nx)
  };
}

// Conchoidal surface warp function: maps (t along edge, depth into lid) to canvas (x, y)
// Simulates the subtle hand-rubbed lacquer undulation and volcanic-glass distortion
function evalMirrorPoint(t, depth, conchoidalAmp = 1.0) {
  const base = evalLidCurve(t, 0);
  // Conchoidal wave ripples radiating from the corner apex (t ~ 0.665)
  const distFromCorner = t - 0.665;
  const radial = Math.hypot(distFromCorner * 900, depth);
  const ripple1 = Math.sin(radial * 0.045 - distFromCorner * 9.0) * 8.5 * conchoidalAmp;
  const ripple2 = Math.cos(radial * 0.11 + depth * 0.03) * 3.2 * conchoidalAmp;
  const shear = Math.sin(depth * 0.018 + t * 7.0) * (depth * 0.09) * conchoidalAmp;

  // Inward direction into the lid mirror is -nx, -ny, skewed slightly toward vertical for reflections
  const mixNx = lerp(-base.nx, -0.18, constrain(depth / 520, 0, 0.72));
  const mixNy = lerp(-base.ny, -0.98, constrain(depth / 520, 0, 0.72));
  const mLen = Math.hypot(mixNx, mixNy) || 1;

  const px = base.x + (mixNx / mLen) * depth + base.tx * (shear + ripple1) + base.nx * ripple2;
  const py = base.y + (mixNy / mLen) * depth + base.ty * (shear + ripple1) + base.ny * ripple2;
  return { x: px, y: py, base };
}

