    opacity: 55,
    spacing: 0.15,
    pressure: [0.0, 1.0, 0.0],
    rotate: "natural",
    noise: 0.15
  });

  // Custom vector field following conchoidal curves around the piano lid corner
  brush.addField("conchoidal", (t, field) => {
    const cols = field.length;
    const rows = field[0].length;
    const apexX = 850;
    const apexY = 706;
    for (let c = 0; c < cols; c++) {
      for (let r = 0; r < rows; r++) {
        const x = (c / (cols - 1)) * 1200;
        const y = (r / (rows - 1)) * 1200;
        const dx = x - apexX;
        const dy = y - apexY;
        const dist = Math.hypot(dx, dy) + 1;
        // Conchoidal shell-like tangential angle with subtle wave
        const baseAng = degrees(Math.atan2(dy, dx)) + 90;
        const wave = Math.sin(dist * 0.025 + (dx - dy) * 0.008) * 18;
        field[c][r] = baseAng + wave;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.abyss);

  // 1. Deep Ground & Atmospheric Washes
  renderDeepGroundWashes();

  // 2. Layered Charcoal Mass in Ivory Black & Blue-Black
  renderCharcoalMassFoundation();

  // 3. Warped Window Reflection in Muted Earth Tones (Dissolving into Velvety Darkness)
  renderWarpedWindowReflection();

  // 4. Warped Reflection of the Pianist's Hands & Ghostly Keys
  renderPianistHandsReflection();

  // 5. Dissolve Reflections into Velvety Charcoal Darkness
  renderVelvetyDissolvePasses();

  // 6. Beveled Lid Rim & Conchoidal Obsidian Fractures
  renderBeveledRimAndConchoidalFractures();

  // 7. The Cold White Glint Carrying the Drama (plus Micro-Polish Halo)
  renderColdWhiteGlint();

  // 8. Surface Micro-Reality: Fingerprint Smudges & Tiny Dust Motes
  renderFingerprintSmudges();
  renderDustMotesAndLint();

  noLoop();
}

