// LAYER 1: DEEP GROUND & ATMOSPHERIC WASHES
// =============================================================================
function renderDeepGroundWashes() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Deep ivory-black base across entire canvas
  brush.wash(PAL.ivoryBlack1, 240);
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noWash();

  // Subtle watercolor bleed reservoirs for blue-black lacquer depth & warm reflection glow
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.65, 0.25);

  // Batch 1: Deep blue-black atmospheric pool across upper lid and corner
  brush.fill(PAL.blueBlack2, 130);
  drawLidRegionPolygon(0.0, 1.0, -45, 780);
  brush.circle(760, 520, 420, 0.25);

  // Batch 2: Muted earth-tone reservoir where window & hands reflect
  brush.fill(PAL.umberDeep, 115);
  brush.circle(560, 590, 310, 0.3);
  brush.circle(430, 710, 240, 0.3);

  // Batch 3: Cold slate undertone around the corner apex
  brush.fill(PAL.slateShadow, 85);
  brush.circle(830, 680, 190, 0.25);

  // Batch 4: Abyssal shadow beneath the piano lid edge
  brush.fill(PAL.abyss, 210);
  drawExteriorShadowPolygon(36);

  brush.noFill();
}

// Helper to draw a closed polygon strip between two bevel offsets or depths
function drawLidRegionPolygon(tStart, tEnd, shiftNear, depthFar) {
  const steps = 28;
  brush.beginShape(0.15);
  for (let i = 0; i <= steps; i++) {
    const t = lerp(tStart, tEnd, i / steps);
    const p = evalLidCurve(t, shiftNear);
    brush.vertex(p.x, p.y);
  }
  for (let i = steps; i >= 0; i--) {
    const t = lerp(tStart, tEnd, i / steps);
    const p = evalMirrorPoint(t, depthFar, 0.4);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
}

// Helper to draw the dark abyss outside/below the piano lid corner
function drawExteriorShadowPolygon(shiftStart) {
  const steps = 32;
  brush.beginShape(0.05);
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const p = evalLidCurve(t, shiftStart);
    brush.vertex(p.x, p.y);
  }
  brush.vertex(1240, -60);
  brush.vertex(1240, 1240);
  brush.vertex(-60, 1240);
  brush.endShape(true);
}

// =============================================================================
// LAYER 2: DEEP LAYERED CHARCOAL MASS (IVORY BLACK & BLUE-BLACK)
// =============================================================================
function renderCharcoalMassFoundation() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();

  // Pass 1: Dense blue-black charcoal masses across the upper and right lid surface
  const blueMassZones = [
    { t0: 0.35, t1: 0.96, d0: 40, d1: 680, col: PAL.blueBlack1, str: 0.85 },
    { t0: 0.50, t1: 0.88, d0: 15, d1: 420, col: PAL.blueBlack2, str: 0.75 },
    { t0: 0.05, t1: 0.65, d0: 260, d1: 850, col: PAL.blueBlack1, str: 0.90 }
  ];

  for (const z of blueMassZones) {
    brush.mass("charcoal", z.col, {
      precision: 0.65,
      strength: z.str,
      gradient: 0.45,
      outline: false
    });
    drawMirrorPatch(z.t0, z.t1, z.d0, z.d1, 14);
  }

  // Pass 2: Deep ivory-black charcoal masses anchoring the upper-left abyss and lower-right void
  const ivoryMassZones = [
    { t0: 0.0, t1: 0.55, d0: 320, d1: 980, col: PAL.ivoryBlack1, str: 0.92 },
    { t0: 0.0, t1: 0.35, d0: 60, d1: 540, col: PAL.ivoryBlack2, str: 0.78 },
    { t0: 0.62, t1: 1.0, d0: 220, d1: 760, col: PAL.ivoryBlack1, str: 0.88 }
  ];

  for (const z of ivoryMassZones) {
    brush.mass("charcoal", z.col, {
      precision: 0.7,
      strength: z.str,
      gradient: 0.5,
      outline: false
    });
    drawMirrorPatch(z.t0, z.t1, z.d0, z.d1, 14);
  }
  brush.noMass();

  // Pass 3: Exterior abyss charcoal hatching & velvet strokes below the lid
  brush.hatchStyle("charcoal", PAL.abyss, 1.4);
  brush.hatch(7, -32, { rand: 0.08, continuous: true, gradient: 0.3 });
  brush.noStroke();
  drawExteriorShadowPolygon(40);
  brush.noHatch();

  // Pass 4: Conchoidal vector field charcoal striations across the entire lid surface
  brush.field("conchoidal");
  for (let i = 0; i < 420; i++) {
    const t = random(0.02, 0.96);
    const depth = random(15, 860);
    const pt = evalMirrorPoint(t, depth, 0.6);
    if (pt.x < -30 || pt.x > 1230 || pt.y < -30 || pt.y > 1230) continue;

    // Alternate between ivory black, blue-black, and deep slate charcoal
    let col = PAL.ivoryBlack1;
    const r = random();
    if (r < 0.38) col = PAL.blueBlack1;
    else if (r < 0.68) col = PAL.blueBlack2;
    else if (r < 0.85) col = PAL.ivoryBlack2;

    const w = map(depth, 15, 860, 0.75, 1.65) * random(0.7, 1.25);
    const len = random(65, 190);
    brush.set("velvet_charcoal", col, w);
    brush.flowLine(pt.x, pt.y, len, pt.base.angle + random(-14, 14));
  }
  brush.noField();
}

function drawMirrorPatch(t0, t1, d0, d1, steps = 12) {
  brush.beginShape(0.2);
  for (let i = 0; i <= steps; i++) {
    const t = lerp(t0, t1, i / steps);
    const p = evalMirrorPoint(t, d0, 0.5);
    brush.vertex(p.x, p.y);
  }
  for (let i = steps; i >= 0; i--) {
    const t = lerp(t0, t1, i / steps);
    const p = evalMirrorPoint(t, d1, 0.5);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
}

// =============================================================================
// LAYER 3: WARPED WINDOW REFLECTION IN MUTED EARTH TONES
// =============================================================================
function renderWarpedWindowReflection() {
  // The window reflection sits in t in [0.46, 0.79], depth in [8, 430]
  // Crisp near depth = 8..130, dissolving into velvety darkness for depth > 220
  const cols = [
    { u0: 0.475, u1: 0.565 },
    { u0: 0.580, u1: 0.668 },
    { u0: 0.683, u1: 0.768 }
  ];
  const rows = [
    { d0: 10, d1: 98, toneIdx: 0 },   // Crisp lower panes right near the lid edge
    { d0: 112, d1: 225, toneIdx: 1 }, // Mid panes
    { d0: 242, d1: 385, toneIdx: 2 }  // Upper panes dissolving into darkness
  ];

  // 3A. Soft watercolor/wash under-glow for each warped window pane
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.55, 0.2);

  for (let c = 0; c < cols.length; c++) {
    for (let r = 0; r < rows.length; r++) {
      const colSpan = cols[c];
      const rowSpan = rows[r];

      // Panes closer to the corner (c == 2, r == 0) are brightest & coolest
      let fillCol = PAL.umberMid;
      let alpha = 95;
      if (r === 0 && c === 2) {
        fillCol = PAL.parchment;
        alpha = 135;
      } else if (r === 0 && c === 1) {
        fillCol = PAL.sandstone;
        alpha = 115;
      } else if (r === 0 && c === 0) {
        fillCol = PAL.taupeWarm;
        alpha = 95;
      } else if (r === 1 && c === 2) {
        fillCol = PAL.taupeWarm;
        alpha = 85;
      } else if (r === 1 && c === 1) {
        fillCol = PAL.ochreEarth;
        alpha = 75;
      } else if (r === 1 && c === 0) {
        fillCol = PAL.siennaMuted;
        alpha = 65;
      } else {
        fillCol = PAL.umberDark;
        alpha = 48;
      }

      brush.fill(fillCol, alpha);
      drawWarpedPanePolygon(colSpan.u0, colSpan.u1, rowSpan.d0, rowSpan.d1, 1.15);
    }
  }
  brush.noFill();

  // 3B. Dry-media cpencil & charcoal tonal build-up inside the panes (crisp near edge, fading up)
  for (let c = 0; c < cols.length; c++) {
    for (let r = 0; r < rows.length; r++) {
      const colSpan = cols[c];
      const rowSpan = rows[r];
      const subSteps = r === 0 ? 28 : r === 1 ? 22 : 14;

      for (let s = 0; s < subSteps; s++) {
        const v = s / (subSteps - 1);
        const d = lerp(rowSpan.d0, rowSpan.d1, v);
        // Global fade as depth increases
        const fade = constrain(map(d, 10, 380, 1.0, 0.05), 0.05, 1.0);
        if (random() > fade + 0.15) continue;

        // Pick muted earth tone based on distance to the corner glint
        let strokeCol = PAL.ochreEarth;
        if (d < 55 && c === 2) strokeCol = random() < 0.45 ? PAL.coldGlint1 : PAL.boneLight;
        else if (d < 95 && c >= 1) strokeCol = random() < 0.5 ? PAL.parchment : PAL.sandstone;
        else if (d < 165) strokeCol = random() < 0.5 ? PAL.taupeWarm : PAL.ochreEarth;
        else if (d < 260) strokeCol = random() < 0.5 ? PAL.siennaMuted : PAL.umberMid;
        else strokeCol = PAL.umberDark;

        const pts = [];
        const segs = 10;
        for (let k = 0; k <= segs; k++) {
          const u = lerp(colSpan.u0 + 0.004, colSpan.u1 - 0.004, k / segs);
          // Conchoidal step displacement
          const stepWarp = Math.sin(u * 42 + d * 0.09) * 3.5;
          const p = evalMirrorPoint(u, d + stepWarp, 1.25);
          pts.push([p.x, p.y, fade * random(0.6, 1.15)]);
        }

        const brName = d < 90 ? "cpencil" : "charcoal";
        const w = map(d, 10, 380, 0.55, 1.35);
        brush.set(brName, strokeCol, w);
        brush.spline(pts, 0.35);
      }
    }
  }

  // 3C. Crisp Conchoidal Window Mullions (Dark Obsidian Bars Crossing the Reflection)
  const mullionUs = [0.472, 0.572, 0.675, 0.772];
  for (const mu of mullionUs) {
    for (let pass = 0; pass < 3; pass++) {
      const pts = [];
      const steps = 24;
      for (let i = 0; i <= steps; i++) {
        const d = lerp(6, 370, i / steps);
        const offsetU = (pass - 1) * 0.0022;
        const conchoidalBend = Math.sin(d * 0.055 + mu * 18) * 0.0045;
        const p = evalMirrorPoint(mu + offsetU + conchoidalBend, d, 1.25);
        const pressure = map(d, 6, 370, 1.1, 0.3);
        pts.push([p.x, p.y, pressure]);
      }
      brush.set("2B", pass === 1 ? PAL.abyss : PAL.blueBlack1, pass === 1 ? 1.15 : 0.85);
      brush.spline(pts, 0.4);
    }

    // Lifted razor highlight immediately kissing the edge of each mullion near the lid rim
    const hiPts = [];
    for (let i = 0; i <= 14; i++) {
      const d = lerp(8, 145, i / 14);
      const p = evalMirrorPoint(mu + 0.0048, d, 1.25);
      hiPts.push([p.x, p.y, map(d, 8, 145, 1.0, 0.05)]);
    }
    const hiCol = mu > 0.65 ? PAL.coldGlint1 : PAL.parchment;
    brush.set("obsidian_razor", hiCol, 0.85);
    brush.spline(hiPts, 0.35);
  }

  // Horizontal transom bars with conchoidal fracture steps
  const transomDepths = [104, 232];
  for (const td of transomDepths) {
    for (let pass = -1; pass <= 1; pass++) {
      const pts = [];
      const steps = 22;
      for (let i = 0; i <= steps; i++) {
        const u = lerp(0.465, 0.778, i / steps);
        const p = evalMirrorPoint(u, td + pass * 3.5, 1.3);
        pts.push([p.x, p.y, 0.9]);
      }
      brush.set("charcoal", pass === 0 ? PAL.abyss : PAL.ivoryBlack2, 0.95);
      brush.spline(pts, 0.35);
    }
    // Crisp lower edge highlight on the lower transom
    if (td < 150) {
      const hiPts = [];
      for (let i = 0; i <= 18; i++) {
        const u = lerp(0.475, 0.768, i / 18);
        const p = evalMirrorPoint(u, td - 5.5, 1.3);
        hiPts.push([p.x, p.y, map(u, 0.475, 0.768, 0.4, 1.0)]);
      }
      brush.set("obsidian_razor", PAL.boneLight, 0.75);
      brush.spline(hiPts, 0.35);
    }
  }
}

function drawWarpedPanePolygon(u0, u1, d0, d1, warpAmp) {
  const steps = 10;
  brush.beginShape(0.2);
  for (let i = 0; i <= steps; i++) {
    const u = lerp(u0, u1, i / steps);
    const p = evalMirrorPoint(u, d0, warpAmp);
    brush.vertex(p.x, p.y);
  }
  for (let i = 0; i <= steps; i++) {
    const d = lerp(d0, d1, i / steps);
    const p = evalMirrorPoint(u1, d, warpAmp);
    brush.vertex(p.x, p.y);
  }
  for (let i = steps; i >= 0; i--) {
    const u = lerp(u0, u1, i / steps);
    const p = evalMirrorPoint(u, d1, warpAmp);
    brush.vertex(p.x, p.y);
  }
  for (let i = steps; i >= 0; i--) {
    const d = lerp(d0, d1, i / steps);
    const p = evalMirrorPoint(u0, d, warpAmp);
    brush.vertex(p.x, p.y);
  }
  brush.endShape(true);
}

// =============================================================================
// LAYER 4: WARPED REFLECTION OF PIANIST'S HANDS & GHOSTLY KEYS
// =============================================================================
function renderPianistHandsReflection() {
  // Reflected along the lid edge in t in [0.14, 0.49], depth in [6, 235]
  // Includes:
  // 1. Ghostly warped reflection of ivory & ebony keys right along the lower mirror edge
  // 2. Left hand (t ~ 0.17..0.30) and Right hand (t ~ 0.32..0.47) with articulated fingers,
  //    knuckles, tendons, and warm earth-tone chiaroscuro dissolving into the dark mirror.

  // 4A. Ghostly Piano Keys Reflection near the Lid Rim (t in [0.12, 0.50], depth in [4, 34])
  const numKeys = 22;
  for (let k = 0; k < numKeys; k++) {
    const u0 = lerp(0.12, 0.495, k / numKeys);
    const u1 = lerp(0.12, 0.495, (k + 0.78) / numKeys);
    const isBrightKey = k > 6 && k < 19;
    const keyCol = isBrightKey
      ? (k % 2 === 0 ? PAL.taupeWarm : PAL.ochreEarth)
      : PAL.umberMid;

    // Subtle key reflection sliver
    const pts = [];
    for (let s = 0; s <= 4; s++) {
      const u = lerp(u0, u1, s / 4);
      const p = evalMirrorPoint(u, 11 + (k % 3) * 2.5, 0.9);
      pts.push([p.x, p.y, 0.85]);
    }
    brush.set("cpencil", keyCol, 0.85);
    brush.spline(pts, 0.25);

    // Key tip glint right at the bevel transition
    if (isBrightKey && random() < 0.8) {
      const pA = evalMirrorPoint(u0, 6, 0.8);
      const pB = evalMirrorPoint(u1, 6, 0.8);
      brush.set("obsidian_razor", PAL.parchment, 0.65);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }

    // Ebony key reflection gap on standard 7-key pattern
    const note = k % 7;
    if (note === 0 || note === 1 || note === 3 || note === 4 || note === 5) {
      const eu = lerp(u0, u1, 0.85);
      const eTop = evalMirrorPoint(eu, 26, 0.9);
      const eBot = evalMirrorPoint(eu, 12, 0.9);
      brush.set("2B", PAL.abyss, 1.1);
      brush.line(eTop.x, eTop.y, eBot.x, eBot.y);
    }
  }

  // 4B. Sculpt the Right Hand (Closer to the window light, t in [0.32, 0.465])
  renderHandReflection({
    tCenter: 0.392,
    tSpan: 0.125,
    wristDepth: 195,
    knuckleDepth: 96,
    tipDepth: 16,
    isRightHand: true,
    brightness: 1.0
  });

  // 4C. Sculpt the Left Hand (Slightly deeper in warm umber shadow, t in [0.175, 0.305])
  renderHandReflection({
    tCenter: 0.242,
    tSpan: 0.115,
    wristDepth: 180,
    knuckleDepth: 88,
    tipDepth: 18,
    isRightHand: false,
    brightness: 0.76
  });
}

function renderHandReflection(cfg) {
  const { tCenter, tSpan, wristDepth, knuckleDepth, tipDepth, isRightHand, brightness } = cfg;
  const tStart = tCenter - tSpan * 0.5;
  const tEnd = tCenter + tSpan * 0.5;

  // 1. Soft warm umber/sienna under-wash for the dorsum of the hand & wrist
  brush.noStroke();
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.6, 0.2);
  brush.fill(brightness > 0.85 ? PAL.siennaMuted : PAL.umberMid, 95);

  const wristPt = evalMirrorPoint(tCenter + (isRightHand ? 0.015 : -0.015), wristDepth, 1.0);
  const kLeft = evalMirrorPoint(tStart, knuckleDepth + 12, 1.0);
  const kMid = evalMirrorPoint(tCenter, knuckleDepth - 8, 1.0);
  const kRight = evalMirrorPoint(tEnd, knuckleDepth + 8, 1.0);
  const fLeft = evalMirrorPoint(tStart + 0.008, tipDepth + 22, 1.0);
  const fRight = evalMirrorPoint(tEnd - 0.008, tipDepth + 18, 1.0);

  brush.beginShape(0.35);
  brush.vertex(wristPt.x - 32, wristPt.y);
  brush.vertex(kLeft.x, kLeft.y);
  brush.vertex(fLeft.x, fLeft.y);
  brush.vertex(fRight.x, fRight.y);
  brush.vertex(kRight.x, kRight.y);
  brush.vertex(wristPt.x + 32, wristPt.y);
  brush.endShape(true);
  brush.noFill();

  // 2. Dorsal hand plane: layered dry cpencil & charcoal shading following the metacarpal arch
  for (let i = 0; i < 36; i++) {
    const v = i / 35;
    const d = lerp(knuckleDepth - 6, wristDepth + 25, v);
    const fade = map(v, 0, 1, 1.0, 0.08);
    const widthFactor = sin(v * 140 + 20) * 0.48 + 0.52;
    const u0 = tCenter - tSpan * 0.44 * widthFactor;
    const u1 = tCenter + tSpan * 0.44 * widthFactor;

    let col = PAL.umberDark;
    if (v < 0.28) col = brightness > 0.85 ? PAL.sandstone : PAL.taupeWarm;
    else if (v < 0.55) col = brightness > 0.85 ? PAL.ochreEarth : PAL.siennaMuted;
    else if (v < 0.8) col = PAL.umberMid;

    const pts = [];
    for (let s = 0; s <= 6; s++) {
      const u = lerp(u0, u1, s / 6);
      const arch = Math.sin((s / 6) * Math.PI) * 10;
      const p = evalMirrorPoint(u, d - arch, 1.15);
      pts.push([p.x, p.y, fade * (s >= 2 && s <= 5 ? 1.1 : 0.5)]);
    }
    brush.set("cpencil", col, map(v, 0, 1, 0.65, 1.15));
    brush.spline(pts, 0.4);
  }

  // 3. Five Articulated Fingers curving down toward the lid bevel edge
  // Finger definitions: [relative u offset (-0.5..0.5), knuckle depth offset, tip depth, finger thickness]
  const fingerSpecs = isRightHand
    ? [
        { uOff: -0.44, kOff: 18, tDepth: 34, thick: 0.95, isThumb: true },  // Thumb
        { uOff: -0.22, kOff: -4, tDepth: 15, thick: 0.90, isThumb: false }, // Index
        { uOff: -0.02, kOff: -9, tDepth: 11, thick: 0.95, isThumb: false }, // Middle
        { uOff:  0.19, kOff: -4, tDepth: 16, thick: 0.88, isThumb: false }, // Ring
        { uOff:  0.39, kOff:  8, tDepth: 26, thick: 0.76, isThumb: false }  // Pinky
      ]
    : [
        { uOff: -0.40, kOff:  9, tDepth: 28, thick: 0.76, isThumb: false }, // Pinky
        { uOff: -0.20, kOff: -3, tDepth: 18, thick: 0.88, isThumb: false }, // Ring
        { uOff:  0.01, kOff: -8, tDepth: 13, thick: 0.95, isThumb: false }, // Middle
        { uOff:  0.22, kOff: -3, tDepth: 16, thick: 0.90, isThumb: false }, // Index
        { uOff:  0.44, kOff: 16, tDepth: 32, thick: 0.95, isThumb: true }   // Thumb
      ];

  for (let f = 0; f < fingerSpecs.length; f++) {
    const spec = fingerSpecs[f];
    const uBase = tCenter + spec.uOff * tSpan;
    const uTip = uBase + (spec.isThumb ? (isRightHand ? 0.014 : -0.014) : (spec.uOff * 0.012));
    const dKnuckle = knuckleDepth + spec.kOff;
    const dProxJoint = lerp(dKnuckle, spec.tDepth, 0.48);
    const dDistJoint = lerp(dKnuckle, spec.tDepth, 0.78);
    const dTip = spec.tDepth;

    // 3a. Dark inter-digital shadow valley on the shadow side (left side) of each finger
    const shadowPts = [];
    for (let s = 0; s <= 10; s++) {
      const frac = s / 10;
      const u = lerp(uBase - 0.0085, uTip - 0.007, frac);
      const d = lerp(dKnuckle + 14, dTip, frac);
      const p = evalMirrorPoint(u, d, 1.15);
      shadowPts.push([p.x, p.y, 1.0]);
    }
    brush.set("2B", PAL.abyss, 1.05 * spec.thick);
    brush.spline(shadowPts, 0.45);

    // 3b. Warm midtone & lit ridge along the phalanges (right side faces the window reflection!)
    for (let strand = -2; strand <= 2; strand++) {
      const uShift = strand * 0.0022 * spec.thick;
      const pts = [];
      for (let s = 0; s <= 12; s++) {
        const frac = s / 12;
        const u = lerp(uBase, uTip, frac) + uShift;
        const d = lerp(dKnuckle, dTip, frac);
        // Phalanx curvature (arches between joints)
        const jointWave = Math.sin(frac * Math.PI * 2.2) * 0.0018;
        const p = evalMirrorPoint(u + jointWave, d, 1.15);
        pts.push([p.x, p.y, 0.85]);
      }

      let col = PAL.umberMid;
      if (strand === 2) col = brightness > 0.85 ? PAL.parchment : PAL.sandstone;
      else if (strand === 1) col = brightness > 0.85 ? PAL.sandstone : PAL.taupeWarm;
      else if (strand === 0) col = brightness > 0.85 ? PAL.taupeWarm : PAL.ochreEarth;
      else if (strand === -1) col = PAL.siennaMuted;

      brush.set("cpencil", col, 0.58 * spec.thick);
      brush.spline(pts, 0.45);
    }

    // 3c. Knuckle & PIP/DIP joint highlights (lifted bone/parchment crescents)
    const joints = [
      { d: dKnuckle, w: 0.0065, col: brightness > 0.85 ? PAL.boneLight : PAL.parchment },
      { d: dProxJoint, w: 0.0052, col: brightness > 0.85 ? PAL.parchment : PAL.sandstone },
      { d: dDistJoint, w: 0.0040, col: PAL.taupeWarm }
    ];
    for (const j of joints) {
      const jFrac = map(j.d, dKnuckle, dTip, 0, 1);
      const ju = lerp(uBase, uTip, jFrac) + 0.0015;
      const p1 = evalMirrorPoint(ju - j.w, j.d + 2, 1.15);
      const p2 = evalMirrorPoint(ju, j.d - 3, 1.15);
      const p3 = evalMirrorPoint(ju + j.w, j.d + 1, 1.15);
      brush.set("obsidian_shard", j.col, 0.72 * spec.thick);
      brush.spline([[p1.x, p1.y, 0.4], [p2.x, p2.y, 1.1], [p3.x, p3.y, 0.5]], 0.5);
    }

    // 3d. Delicate fingernail reflection glint right near the lid edge
    const nailP1 = evalMirrorPoint(uTip - 0.0028, dTip + 3, 1.1);
    const nailP2 = evalMirrorPoint(uTip + 0.001, dTip - 1, 1.1);
    const nailP3 = evalMirrorPoint(uTip + 0.0038, dTip + 2.5, 1.1);
    brush.set("obsidian_razor", brightness > 0.85 ? PAL.boneLight : PAL.parchment, 0.85);
    brush.spline([[nailP1.x, nailP1.y, 0.5], [nailP2.x, nailP2.y, 1.2], [nailP3.x, nailP3.y, 0.5]], 0.5);

    // 3e. Subtle tendon line extending from the knuckle toward the wrist
    const tendStart = evalMirrorPoint(uBase + 0.0015, dKnuckle + 4, 1.1);
    const tendMid = evalMirrorPoint(lerp(uBase, tCenter, 0.35), lerp(dKnuckle, wristDepth, 0.45), 1.1);
    const tendEnd = evalMirrorPoint(lerp(uBase, tCenter, 0.65), lerp(dKnuckle, wristDepth, 0.82), 1.1);
    brush.set("HB", brightness > 0.85 ? PAL.sandstone : PAL.ochreEarth, 0.5);
    brush.spline([[tendStart.x, tendStart.y, 0.9], [tendMid.x, tendMid.y, 0.6], [tendEnd.x, tendEnd.y, 0.1]], 0.35);
  }
}

// =============================================================================
// LAYER 5: VELVETY CHARCOAL DISSOLVE PASSES
// =============================================================================
function renderVelvetyDissolvePasses() {
  // Reflections are crisp near the edge and dissolve into velvety darkness further inward.
  // We lay down feathered charcoal & velvet_charcoal passes across the upper transition zone
  // (depth 150..520) and across the deep left/top void.
  brush.field("conchoidal");

  for (let i = 0; i < 310; i++) {
    const t = random(0.05, 0.92);
    // Concentrate in the transition zone (depth 140..480)
    const depth = random(135, 540);
    const pt = evalMirrorPoint(t, depth, 0.85);

    // Choose deep ivory-black or blue-black
    const isBlueZone = t > 0.52;
    let col = isBlueZone
      ? (random() < 0.6 ? PAL.blueBlack1 : PAL.blueBlack2)
      : (random() < 0.65 ? PAL.ivoryBlack1 : PAL.ivoryBlack2);

    const w = map(depth, 135, 540, 0.45, 1.45);
    const len = map(depth, 135, 540, 45, 145);
    brush.set("velvet_charcoal", col, w);
    brush.flowLine(pt.x, pt.y, len, pt.base.angle + random(-18, 18));
  }
  brush.noField();

  // Horizontal/conchoidal charcoal smudge splines that veil the upper reflection edges
  for (let band = 0; band < 28; band++) {
    const d = lerp(165, 440, band / 27) + random(-10, 10);
    const t0 = random(0.10, 0.32);
    const t1 = random(0.68, 0.88);
    const pts = [];
    const steps = 14;
    for (let s = 0; s <= steps; s++) {
      const t = lerp(t0, t1, s / steps);
      const p = evalMirrorPoint(t, d + Math.sin(t * 25 + band) * 8, 1.1);
      pts.push([p.x, p.y, random(0.4, 1.0)]);
    }
    const col = band % 2 === 0 ? PAL.ivoryBlack1 : PAL.blueBlack1;
    brush.set("charcoal", col, map(d, 165, 440, 0.6, 1.35));
    brush.spline(pts, 0.4);
  }
}

// =============================================================================
// LAYER 6: BEVELED RIM & CONCHOIDAL OBSIDIAN FRACTURES
// =============================================================================
function renderBeveledRimAndConchoidalFractures() {
  // The grand piano lid edge has a sculptural, multi-planed bevel:
  // - bevelShift -42 to 0: Upper bevel roll where surface reflections compress & fracture
  // - bevelShift 0 to +28: Bullnose lacquered face
  // - bevelShift +28 to +44: Lower rim lip & deep shadow cutoff

  // 6A. Deep obsidian shadow core along the bullnose and lower lip
  const coreBands = [
    { shift: -18, col: PAL.blueBlack1, w: 1.4, br: "charcoal" },
    { shift: -4,  col: PAL.abyss,      w: 1.8, br: "charcoal" },
    { shift: 6,   col: PAL.abyss,      w: 2.1, br: "velvet_charcoal" },
    { shift: 16,  col: PAL.ivoryBlack2,w: 1.5, br: "charcoal" },
    { shift: 26,  col: PAL.abyss,      w: 2.2, br: "charcoal" },
    { shift: 36,  col: PAL.abyss,      w: 2.6, br: "velvet_charcoal" }
  ];

  for (const b of coreBands) {
    const pts = [];
    const steps = 42;
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const p = evalLidCurve(t, b.shift);
      pts.push([p.x, p.y, 1.0]);
    }
    brush.set(b.br, b.col, b.w);
    brush.spline(pts, 0.45);
  }

  // 6B. Anamorphic Stretched Reflections Wrapped Across the Bevel (-38 to +22)
  // Both the pianist's hands (t in [0.16, 0.48]) and the window panes (t in [0.48, 0.78])
  // stretch into razor-thin stepped ribbons along the bevel curve!
  for (let r = 0; r < 58; r++) {
    const t0 = random(0.14, 0.84);
    const span = random(0.025, 0.095);
    const t1 = constrain(t0 + span, 0.15, 0.90);
    const shift = random(-38, 22);

    // Determine color based on zone along the lid edge
    const tMid = (t0 + t1) * 0.5;
    let col = PAL.umberMid;
    let br = "obsidian_shard";
    let w = random(0.45, 0.95);

    if (tMid > 0.61 && tMid < 0.73) {
      // Corner apex zone: icy slate to cold white
      col = random() < 0.55 ? PAL.coldGlint1 : PAL.iceMist;
      br = "obsidian_razor";
      w = random(0.55, 1.15);
    } else if (tMid >= 0.47 && tMid <= 0.80) {
      // Window bevel reflection zone: warm parchment, bone, sandstone
      const p = random();
      col = p < 0.35 ? PAL.boneLight : p < 0.7 ? PAL.parchment : PAL.taupeWarm;
      br = random() < 0.6 ? "obsidian_razor" : "obsidian_shard";
    } else if (tMid >= 0.16 && tMid < 0.47) {
      // Hand & keys bevel reflection zone: warm ochre, sienna, sandstone
      const p = random();
      col = p < 0.3 ? PAL.parchment : p < 0.65 ? PAL.taupeWarm : PAL.ochreEarth;
    } else {
      col = PAL.slateShadow;
      w *= 0.7;
    }

    const pts = [];
    const steps = 10;
    for (let s = 0; s <= steps; s++) {
      const frac = s / steps;
      const t = lerp(t0, t1, frac);
      // Conchoidal step offset along the ribbon
      const stepOffset = Math.sin(frac * Math.PI * 2 + r) * 2.4;
      const p = evalLidCurve(t, shift + stepOffset);
      const pressure = Math.sin(frac * Math.PI) * 1.15;
      pts.push([p.x, p.y, pressure]);
    }
    brush.set(br, col, w);
    brush.spline(pts, 0.45);
  }

  // 6C. Conchoidal Obsidian Fractures (Nested Shell-Like Curves Breaking the Reflections)
  // Each conchoidal fracture pairs an abyss-black micro-cliff with a lifted, razor-thin highlight
  const numFractures = 46;
  for (let f = 0; f < numFractures; f++) {
    // Cluster fractures along the corner and reflection zones
    const tCenter = random(0.18, 0.86);
    const tHalf = random(0.018, 0.068);
    const depthStart = random(-28, 85);
    const archHeight = random(14, 48) * (random() < 0.5 ? 1 : -1);

    const shadowPts = [];
    const highlightPts = [];
    const steps = 12;

    for (let s = 0; s <= steps; s++) {
      const frac = s / steps;
      const u = lerp(tCenter - tHalf, tCenter + tHalf, frac);
      // Shell-like parabolic/sinusoidal conchoidal curve with a sharp stepped break near 0.65
      const shellCurve = Math.sin(frac * Math.PI) * archHeight;
      const stepBreak = frac > 0.62 && frac < 0.68 ? 4.5 : 0;
      const d = depthStart + shellCurve + stepBreak;

      const pShadow = d >= 0
        ? evalMirrorPoint(u, d, 1.2)
        : evalLidCurve(u, d);
      const pHi = d >= 0
        ? evalMirrorPoint(u, d - 2.2, 1.2)
        : evalLidCurve(u, d - 1.8);

      const taper = Math.sin(frac * Math.PI);
      shadowPts.push([pShadow.x, pShadow.y, taper * 1.1]);
      highlightPts.push([pHi.x, pHi.y, taper * 1.2]);
    }

    // Draw dark obsidian fracture line
    brush.set("2B", PAL.abyss, random(0.55, 0.95));
    brush.spline(shadowPts, 0.45);

    // Draw lifted razor-thin highlight along the fracture crest
    let hiCol = PAL.taupeWarm;
    if (tCenter > 0.60 && tCenter < 0.74 && depthStart < 45) {
      hiCol = random() < 0.6 ? PAL.coldGlint2 : PAL.coldGlint1;
    } else if (tCenter > 0.46 && tCenter < 0.79 && depthStart < 75) {
      hiCol = random() < 0.5 ? PAL.boneLight : PAL.parchment;
    } else if (depthStart < 35) {
      hiCol = PAL.sandstone;
    } else {
      hiCol = PAL.ochreEarth;
    }

    brush.set("obsidian_razor", hiCol, random(0.55, 1.05));
    brush.spline(highlightPts, 0.45);
  }

  // 6D. Continuous Razor Rim Highlights along the Upper & Lower Bevel Crests
  // Upper bevel crest (shift ~ -36)
  drawSteppedBevelHighlight(0.12, 0.88, -36, 14, PAL.parchment, PAL.coldGlint1);
  // Primary bullnose ridge (shift ~ 0)
  drawSteppedBevelHighlight(0.08, 0.92, 0, 18, PAL.boneLight, PAL.pureWhite);
  // Lower rim lip (shift ~ +24)
  drawSteppedBevelHighlight(0.18, 0.84, 24, 12, PAL.ochreEarth, PAL.iceMist);
}

function drawSteppedBevelHighlight(tStart, tEnd, baseShift, segments, warmCol, coldCol) {
  for (let seg = 0; seg < segments; seg++) {
    const u0 = lerp(tStart, tEnd, seg / segments);
    const u1 = lerp(tStart, tEnd, (seg + 0.86) / segments);
    const uMid = (u0 + u1) * 0.5;

    // Proximity to the dramatic corner apex (t = 0.665)
    const cornerProx = Math.exp(-Math.pow((uMid - 0.665) / 0.11, 2));
    const shiftStep = (seg % 3 - 1) * 1.6;

    const pts = [];
    const steps = 8;
    for (let i = 0; i <= steps; i++) {
      const frac = i / steps;
      const t = lerp(u0, u1, frac);
      const p = evalLidCurve(t, baseShift + shiftStep);
      const pressure = Math.sin(frac * Math.PI) * lerp(0.55, 1.35, cornerProx);
      pts.push([p.x, p.y, pressure]);
    }

    let col = warmCol;
    if (cornerProx > 0.65) col = coldCol;
    else if (cornerProx > 0.32) col = PAL.boneLight;

    brush.set("obsidian_razor", col, lerp(0.5, 1.15, cornerProx));
    brush.spline(pts, 0.4);
  }
}

// =============================================================================
// LAYER 7: THE COLD WHITE GLINT CARRYING THE DRAMA
// =============================================================================
function renderColdWhiteGlint() {
  // Corner apex at t = 0.665 -> approx (846, 708)
  const apex = evalLidCurve(0.665, 0);

  // 7A. Cold atmospheric halo around the specular glint
  brush.noStroke();
  brush.fillBleed(0.4, "out");
  brush.fillTexture(0.45, 0.15);

  brush.fill(PAL.slateShadow, 95);
  brush.circle(apex.x - 8, apex.y - 6, 115, 0.2);

  brush.fill(PAL.iceSlate, 75);
  brush.circle(apex.x - 4, apex.y - 3, 62, 0.18);

  brush.fill(PAL.coldGlint1, 85);
  brush.circle(apex.x, apex.y, 28, 0.15);
  brush.noFill();

  // 7B. Hyperreal Spiderweb Polishing Micro-Scratches Concentric Around the Glint
  // On real black piano lacquer, microscopic circular buffing swirls catch the light around any bright specular!
  for (let i = 0; i < 95; i++) {
    const rad = random(14, 135);
    const startAng = random(0, 360);
    const arcSpan = random(18, 58);

    // Only draw where the arc stays on the lid or bevel (not deep into the exterior void)
    const midAng = startAng + arcSpan * 0.5;
    const mx = apex.x + cos(midAng) * rad;
    const my = apex.y + sin(midAng) * rad;
    if (mx > 955 || my > 790) continue;

    const prox = map(rad, 14, 135, 1.0, 0.15);
    const col = rad < 45 ? PAL.coldGlint2 : rad < 85 ? PAL.iceMist : PAL.iceSlate;
    brush.set("micro_polish", col, map(rad, 14, 135, 0.95, 0.35) * random(0.7, 1.2));
    brush.arc(apex.x + random(-3, 3), apex.y + random(-3, 3), rad, startAng, startAng + arcSpan);
  }

  // 7C. Conchoidal Specular Shards Approaching the Core Glint
  const shardConfigs = [
    { t0: 0.615, t1: 0.715, shift: 0,    w: 1.55, col: PAL.pureWhite },
    { t0: 0.632, t1: 0.698, shift: -1.8, w: 1.85, col: PAL.pureWhite },
    { t0: 0.642, t1: 0.688, shift: 1.6,  w: 1.65, col: PAL.pureWhite },
    { t0: 0.595, t1: 0.655, shift: -12,  w: 1.15, col: PAL.coldGlint2 },
    { t0: 0.672, t1: 0.735, shift: -9,   w: 1.10, col: PAL.coldGlint2 },
    { t0: 0.625, t1: 0.695, shift: 11,   w: 0.95, col: PAL.coldGlint1 },
    { t0: 0.638, t1: 0.682, shift: -24,  w: 0.90, col: PAL.coldGlint1 }
  ];

  for (const sc of shardConfigs) {
    const pts = [];
    const steps = 14;
    for (let i = 0; i <= steps; i++) {
      const frac = i / steps;
      const t = lerp(sc.t0, sc.t1, frac);
      const p = evalLidCurve(t, sc.shift + Math.sin(frac * Math.PI * 2) * 0.9);
      const pressure = Math.pow(Math.sin(frac * Math.PI), 0.75) * 1.4;
      pts.push([p.x, p.y, pressure]);
    }
    brush.set("obsidian_razor", sc.col, sc.w);
    brush.spline(pts, 0.45);
  }

  // 7D. The Blinding Cold White Core Specular (Stepped Obsidian Diamond Edge)
  brush.noStroke();
  brush.wash(PAL.pureWhite, 245);
  // Crisp elongated specular core hugging the corner tangent
  brush.beginShape(0.2);
  const c0 = evalLidCurve(0.648, -0.5);
  const c1 = evalLidCurve(0.665, -4.2);
  const c2 = evalLidCurve(0.682, -0.5);
  const c3 = evalLidCurve(0.665, 3.8);
  brush.vertex(c0.x, c0.y);
  brush.vertex(c1.x, c1.y);
  brush.vertex(c2.x, c2.y);
  brush.vertex(c3.x, c3.y);
  brush.endShape(true);
  brush.noWash();

  // Secondary stepped pure-white core highlight on the upper bevel ridge
  brush.wash(PAL.pureWhite, 220);
  brush.beginShape(0.2);
  const u0 = evalLidCurve(0.654, -12.5);
  const u1 = evalLidCurve(0.667, -15.0);
  const u2 = evalLidCurve(0.679, -12.5);
  const u3 = evalLidCurve(0.667, -10.2);
  brush.vertex(u0.x, u0.y);
  brush.vertex(u1.x, u1.y);
  brush.vertex(u2.x, u2.y);
  brush.vertex(u3.x, u3.y);
  brush.endShape(true);
  brush.noWash();

  // 7E. Razor-thin optical diffraction filaments radiating from the cold white glint
  const rayAngles = [apex.angle, apex.angle + 180, apex.normalAngle, apex.normalAngle + 180, -38, 142, 52, -128];
  for (let i = 0; i < rayAngles.length; i++) {
    const ang = rayAngles[i];
    const isPrimary = i < 4;
    const len = isPrimary ? random(42, 72) : random(18, 34);
    const x1 = apex.x + cos(ang) * 2;
    const y1 = apex.y + sin(ang) * 2;
    const xm = apex.x + cos(ang) * (len * 0.45);
    const ym = apex.y + sin(ang) * (len * 0.45);
    const x2 = apex.x + cos(ang) * len;
    const y2 = apex.y + sin(ang) * len;

    brush.set("obsidian_razor", isPrimary ? PAL.pureWhite : PAL.coldGlint1, isPrimary ? 0.85 : 0.45);
    brush.spline([[x1, y1, 1.2], [xm, ym, 0.55], [x2, y2, 0.02]], 0.2);
  }
}

// =============================================================================
// LAYER 8A: SURFACE MICRO-REALITY — FINGERPRINT SMUDGES
// =============================================================================
function renderFingerprintSmudges() {
  // Fingerprint smudges sit physically on the glossy surface near the corner where the lid is lifted:
  // 1. Primary thumbprint smudge crossing the edge of the window reflection
  // 2. Index finger smudge slightly higher up
  // 3. Faint side-smudge near the hand reflection zone
  const smudges = [
    { x: 748, y: 668, rx: 20, ry: 30, angle: -26, strength: 1.0 },
    { x: 792, y: 622, rx: 16, ry: 24, angle: -18, strength: 0.82 },
    { x: 688, y: 712, rx: 15, ry: 22, angle: -35, strength: 0.75 },
    { x: 598, y: 748, rx: 18, ry: 25, angle: -42, strength: 0.65 }
  ];

  for (const sm of smudges) {
    push();
    translate(sm.x, sm.y);
    rotate(sm.angle);

    // Subtle matte oil-film haze that slightly scatters the mirror contrast
    brush.noStroke();
    brush.fillBleed(0.18, "out");
    brush.fillTexture(0.75, 0.15);
    brush.fill(PAL.taupeWarm, 18 * sm.strength);
    brush.circle(0, 0, sm.rx * 0.95, 0.35);
    brush.noFill();

    // Concentric whorl & loop skin ridges drawn with broken micro-stipple arcs
    const numRidges = 22;
    for (let r = 2; r <= numRidges; r++) {
      const frac = r / numRidges;
      const a = sm.rx * frac;
      const b = sm.ry * frac;

      // Draw 2 to 3 broken segments per ridge oval to emulate realistic skin contact
      const segments = 3;
      for (let seg = 0; seg < segments; seg++) {
        if (random() < 0.22) continue;
        const th0 = seg * 120 + random(-18, 18);
        const th1 = th0 + random(48, 88);
        const pts = [];
        const steps = 7;

        for (let s = 0; s <= steps; s++) {
          const th = lerp(th0, th1, s / steps);
          // Whorl pinch distortion near center
          const px = cos(th) * a + sin(th * 2) * 0.8;
          const py = sin(th) * b;
          const p = Math.sin((s / steps) * Math.PI) * sm.strength;
          pts.push([px, py, p]);
        }

        const ridgeCol = random() < 0.55 ? PAL.sandstone : PAL.ochreEarth;
        brush.set("skin_ridge", ridgeCol, random(0.65, 1.15) * sm.strength);
        brush.spline(pts, 0.45);
      }
    }

    // Faint oily drag tail from lifting fingers off the lacquer
    for (let d = 0; d < 8; d++) {
      const ox = random(-sm.rx * 0.6, sm.rx * 0.6);
      const oy = sm.ry * 0.5 + random(0, 14);
      brush.set("skin_ridge", PAL.ochreEarth, 0.55 * sm.strength);
      brush.line(ox, oy, ox + random(-4, 4), oy + random(8, 22));
    }

    pop();
  }
}

// =============================================================================
// LAYER 8B: SURFACE MICRO-REALITY — TINY DUST MOTES & MICRO-LINT
// =============================================================================
function renderDustMotesAndLint() {
  // Dust sits on the top surface of the piano lid (t in [0.02, 0.96], depth in [-25, 850]).
  // Motes in the lit reflection zone and near the cold glint glow crisply;
  // motes across the dark charcoal field are subtle dim flecks that anchor the flat surface plane.

  const totalMotes = 340;
  for (let i = 0; i < totalMotes; i++) {
    // Bias distribution slightly toward the reflection and corner zones while keeping coverage across the lid
    const u = random() < 0.62 ? random(0.22, 0.84) : random(0.03, 0.95);
    const d = random() < 0.68 ? random(-22, 320) : random(280, 860);

    const pt = d >= 0 ? evalMirrorPoint(u, d, 0.3) : evalLidCurve(u, d);
    if (pt.x < 12 || pt.x > 1188 || pt.y < 12 || pt.y > 1188) continue;

    // Proximity to the cold glint (846, 708) and window reflection
    const distGlint = Math.hypot(pt.x - 846, pt.y - 708);
    const inWindowZone = u > 0.46 && u < 0.78 && d > -15 && d < 260;
    const inHandZone = u > 0.16 && u < 0.46 && d > -15 && d < 180;

    let moteCol = PAL.ochreEarth;
    let weight = random(0.35, 0.85);

    if (distGlint < 110) {
      moteCol = random() < 0.65 ? PAL.pureWhite : PAL.coldGlint1;
      weight = random(0.55, 1.25);
    } else if (inWindowZone) {
      moteCol = random() < 0.5 ? PAL.boneLight : PAL.parchment;
      weight = random(0.45, 1.05);
    } else if (inHandZone) {
      moteCol = random() < 0.5 ? PAL.parchment : PAL.sandstone;
      weight = random(0.4, 0.9);
    } else {
      moteCol = random() < 0.5 ? PAL.taupeWarm : PAL.siennaMuted;
      weight = random(0.3, 0.68);
    }

    // Draw pinpoint dust mote (and its faint twin reflection 2-3px deeper in the thick clear lacquer coat!)
    const len = random(0.6, 2.0);
    const ang = random(0, 360);
    brush.set("obsidian_razor", moteCol, weight);
    brush.line(
      pt.x,
      pt.y,
      pt.x + cos(ang) * len,
      pt.y + sin(ang) * len
    );

    // Double-surface lacquer reflection of the brightest dust specs
    if ((distGlint < 150 || inWindowZone) && random() < 0.42) {
      const twinShift = map(d, -20, 260, 2.2, 3.8);
      brush.set("skin_ridge", PAL.ochreEarth, weight * 0.65);
      brush.line(
        pt.x + 1.2,
        pt.y + twinShift,
        pt.x + 1.2 + cos(ang) * len,
        pt.y + twinShift + sin(ang) * len
      );
    }
  }

  // Tiny curved lint fibers sitting on the lacquer surface (22 delicate hair-like squiggles)
  for (let l = 0; l < 24; l++) {
    const u = random(0.20, 0.82);
    const d = random(-15, 310);
    const pt = d >= 0 ? evalMirrorPoint(u, d, 0.2) : evalLidCurve(u, d);

    const distGlint = Math.hypot(pt.x - 846, pt.y - 708);
    const col = distGlint < 130
      ? PAL.coldGlint2
      : (u > 0.46 && d < 220 ? PAL.boneLight : PAL.taupeWarm);

    const a1 = random(0, 360);
    const a2 = a1 + random(-65, 65);
    const segLen = random(2.2, 5.2);
    const p1 = [pt.x, pt.y, 0.4];
    const p2 = [pt.x + cos(a1) * segLen, pt.y + sin(a1) * segLen, 1.0];
    const p3 = [p2[0] + cos(a2) * segLen, p2[1] + sin(a2) * segLen, 0.3];

    brush.set("obsidian_razor", col, random(0.45, 0.78));
    brush.spline([p1, p2, p3], 0.6);
  }
}

// Hyperreal Steam Locomotive Driving Wheel & Connecting Rod
// Rendered as a Toned Prussian Cyan Silent Film Frame with Lifted Steam Plumes

const PAL = {
  // Deepest carbon & Prussian blacks (film border, abyssal crevices, grease core)
  voidBlack: "#060c10",
  filmBlack: "#0a141b",
  abyssCyan: "#0e1d27",
  darkPrussian: "#142834",
  charcoalCyan: "#1c3544",

  // Toned Prussian cyan midtones
  prussianDeep: "#254454",
  prussianMid: "#315566",
  prussianSlate: "#416778",
  prussianMist: "#567b8a",
  prussianPale: "#73939f",
  prussianLight: "#93adb5",

  // Muted earth tones (grease, brass bearings, oxidized oil, warm nitrate paper undertone)
  darkUmber: "#23211d",
  greaseEarth: "#38352e",
  oiledBronze: "#504b3f",
  mutedEarth: "#686253",
  brassOchre: "#837b67",
  warmTaupe: "#9e9683",
  parchmentGrey: "#b7b1a0",

  // Compressed & slightly bleached silent-film highlights (steel rims, lifted steam)
  bleachedLow: "#b2bdbc",
  bleachedMid: "#c7d0cc",
  bleachedHigh: "#dae0da",
  bleachedPeak: "#eaece4"
};

// Math helpers in degrees (independent of p5 angleMode state)
function dCos(deg) {
  return Math.cos((deg * Math.PI) / 180);
}
function dSin(deg) {
  return Math.sin((deg * Math.PI) / 180);
}

// Helper to draw a closed or open polygon using brush.beginShape
function drawShapePoly(pts, curvature = 0, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// Helper to transform local (s, n) coordinates along a rod axis into canvas (x, y)
// s: distance from origin (ox, oy) along unit vector (ux, uy)
// n: perpendicular offset along (-uy, ux)
function rodPt(ox, oy, ux, uy, s, n) {
  return [ox + s * ux - n * uy, oy + s * uy + n * ux];
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1927);
  noiseSeed(1927);

  // Custom brushes scaled for 1200x1200 hyperreal detail & charcoal texture
  brush.add("soft_charcoal", {
    type: "default",
    weight: 16,
    scatter: 1.6,
    sharpness: 0.14,
    grain: 0.85,
    opacity: 26,
    spacing: 0.25,
    pressure: [0.4, 1.0, 0.3],
    noise: 0.8
  });

  brush.add("fine_graphite", {
    type: "default",
    weight: 0.9,
    scatter: 0.06,
    sharpness: 0.82,
    grain: 0.45,
    opacity: 145,
    spacing: 0.12,
    pressure: [0.7, 1.0, 0.7],
    noise: 0.35
  });

  brush.add("micro_etch", {
    type: "default",
    weight: 0.45,
    scatter: 0.03,
    sharpness: 0.92,
    grain: 0.3,
    opacity: 165,
    spacing: 0.1,
    pressure: [0.8, 1.0, 0.8],
    noise: 0.2
  });

  brush.add("grease_impasto", {
    type: "default",
    weight: 4.2,
    scatter: 0.4,
    sharpness: 0.35,
    grain: 0.75,
    opacity: 95,
    spacing: 0.2,
    pressure: [0.6, 1.2, 0.4],
    noise: 0.9
  });

  brush.add("steam_lift", {
    type: "default",
    weight: 26,
    scatter: 2.4,
    sharpness: 0.06,
    grain: 0.7,
    opacity: 19,
    spacing: 0.28,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.6
  });

  brush.add("film_scratch", {
    type: "default",
    weight: 0.42,
    scatter: 0.01,
    sharpness: 0.96,
    grain: 0.25,
    opacity: 135,
    spacing: 0.08,
    pressure: [0.5, 1.0, 0.5],
    noise: 0.15
  });

  // Custom turbulent upward-drifting vector field for lifted steam plumes
  brush.addField("steam_turbulence", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        let swirl =
          -28 +
          38 * Math.sin(nx * 5.2 - ny * 4.1) +
          24 * Math.cos(nx * 9.0 + ny * 6.5);
        field[col][row] = swirl;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Bleached, warm-toned silver-gelatin paper/nitrate base
  background(PAL.bleachedMid);

  // Clip all locomotive rendering to the silent film aperture
  const GATE = [84, 20, 1184, 1180];
  brush.clip(GATE);

  // 1. Base Toned Prussian Cyan & Muted Earth Film Washes
  renderBaseFilmWashes();

  // 2. Recessed Locomotive Frame, Boiler Skirt, Splasher Arch, Springs & Brake Rigging
  const wheelCx = 620;
  const wheelCy = 560;
  const crankAng = 55;
  const crankDist = 210;
  const crankX = wheelCx + crankDist * dCos(crankAng); // ~740.4
  const crankY = wheelCy + crankDist * dSin(crankAng); // ~732.0

  renderLocomotiveUnderframe(wheelCx, wheelCy);

  // 3. Steel Rail, Fishplate, Sleepers & Crushed Ballast
  renderRailAndBallast(wheelCx);

  // 4. The Great Driving Wheel (Spokes, Crescent Counterweight, Rim, Steel Tire, Hub & Axle)
  renderDrivingWheel(wheelCx, wheelCy, crankX, crankY, crankAng);

  // 5. Horizontal Coupling Rod (Side Rod) & Articulated Knuckle Joint
  renderCouplingRod(crankX, crankY);

  // 6. Main Connecting Rod, Fluted Shaft, Big-End Strap, Brasses, Wedge & Oil Cups
  renderMainConnectingRod(crankX, crankY);

  // 7. Walschaerts Eccentric Crank Arm & Eccentric Rod
  renderEccentricGear(crankX, crankY);

  // 8. Lifted Steam Plumes & Specular Halation
  renderLiftedSteamPlumes(wheelCx, wheelCy, crankX, crankY);

  // 9. Flickering Silent Film Vignette, Celluloid Scratches & Dust Specks
  renderFilmArtifacts();

  brush.noClip();

  // 10. Silent Film Frame Line & Sliver of the Sprocket Edge along the Left Side
  renderSprocketFrameBorder();

  noLoop();
}

