// =============================================================================
// 2. LOCOMOTIVE UNDERFRAME, SPLASHER ARCH, LEAF SPRINGS & BRAKE RIGGING
// =============================================================================
function renderLocomotiveUnderframe(cx, cy) {
  // Heavy dark frame plates in background
  brush.noStroke();
  brush.wash(PAL.abyssCyan, 210);
  drawShapePoly([
    [84, 20],
    [1184, 20],
    [1184, 490],
    [1040, 520],
    [620, 310],
    [190, 510],
    [84, 490]
  ]);
  brush.noWash();

  // Cross-hatched cast-iron frame texture in upper corners
  brush.hatchStyle("2B", PAL.darkPrussian, 0.8);
  brush.hatch(9, 35, { rand: 0.08 });
  brush.noStroke();
  brush.rect(84, 20, 1100, 340, "corner");
  brush.hatch(11, -55, { rand: 0.08 });
  brush.rect(84, 20, 1100, 280, "corner");
  brush.noHatch();

  // Vertical boiler throat & frame plate seams with rivet rows
  const seamXs = [235, 445, 825, 1035];
  for (let sx of seamXs) {
    brush.set("charcoal", PAL.voidBlack, 1.1);
    brush.line(sx, 20, sx, 350);
    brush.set("fine_graphite", PAL.prussianPale, 0.7);
    brush.line(sx + 2.5, 20, sx + 2.5, 350);

    for (let ry = 42; ry < 320; ry += 26) {
      drawRivet(sx - 14, ry, 5.2, true);
      drawRivet(sx + 16, ry, 5.2, true);
    }
  }

  // Horizontal heavy frame girder above the wheel
  brush.noStroke();
  brush.wash(PAL.charcoalCyan, 190);
  brush.rect(84, 115, 1100, 54, "corner");
  brush.noWash();

  brush.set("fine_graphite", PAL.bleachedLow, 0.9);
  brush.line(84, 115, 1184, 115);
  brush.set("charcoal", PAL.voidBlack, 1.2);
  brush.line(84, 169, 1184, 169);

  for (let rx = 110; rx < 1170; rx += 32) {
    drawRivet(rx, 130, 5.5, true);
    drawRivet(rx + 16, 154, 5.5, false);
  }

  // Leaf Spring Pack behind upper wheel / splasher (x = 470..770, y = 175..285)
  const spLeft = 475;
  const spRight = 765;
  const numLeaves = 9;
  for (let i = 0; i < numLeaves; i++) {
    let inset = i * 11;
    let yTop = 182 + i * 7.5;
    let lx = spLeft + inset;
    let rx = spRight - inset;
    let midY = yTop + 14;

    brush.set("charcoal", PAL.voidBlack, 1.1);
    brush.spline(
      [
        [lx, yTop],
        [cx, midY],
        [rx, yTop]
      ],
      0.35
    );
    brush.set("fine_graphite", i < 3 ? PAL.bleachedLow : PAL.prussianMist, 0.75);
    brush.spline(
      [
        [lx, yTop - 2],
        [cx, midY - 2],
        [rx, yTop - 2]
      ],
      0.35
    );
  }

  // Central Forged Spring Buckle clamping the leaves
  brush.noStroke();
  brush.wash(PAL.darkUmber, 220);
  brush.rect(cx - 28, 174, 56, 86, "corner");
  brush.noWash();
  brush.set("fine_graphite", PAL.bleachedMid, 0.9);
  brush.rect(cx - 28, 174, 56, 86, "corner");
  drawHexBolt(cx, 200, 9, false);
  drawHexBolt(cx, 236, 9, true);

  // Curved Wheel Splasher / Arch hugging top of wheel (R = 502 to 548, angle 198 to 342)
  const spR1 = 502;
  const spR2 = 546;
  let archPts = [];
  for (let a = 196; a <= 344; a += 4) {
    archPts.push([cx + spR1 * dCos(a), cy + spR1 * dSin(a)]);
  }
  for (let a = 344; a >= 196; a -= 4) {
    archPts.push([cx + spR2 * dCos(a), cy + spR2 * dSin(a)]);
  }
  brush.noStroke();
  brush.wash(PAL.prussianDeep, 215);
  drawShapePoly(archPts, 0.1, true);
  brush.noWash();

  // Splasher arch tonal beading & rivets
  brush.set("charcoal", PAL.voidBlack, 1.4);
  brush.arc(cx, cy, spR1, 196, 344);
  brush.arc(cx, cy, spR2, 196, 344);

  brush.set("fine_graphite", PAL.bleachedMid, 1.0);
  brush.arc(cx, cy, spR1 + 3, 200, 325);
  brush.set("fine_graphite", PAL.warmTaupe, 0.8);
  brush.arc(cx, cy, spR2 - 3, 205, 335);

  for (let a = 200; a <= 340; a += 4.5) {
    let rx = cx + (spR1 + 22) * dCos(a);
    let ry = cy + (spR1 + 22) * dSin(a);
    drawRivet(rx, ry, 5.0, a < 295);
  }

  // Left-side Cast-Iron Brake Shoe & Forged Hanger Lever (hugging left wheel tire at 152..194 deg)
  let brakePts = [];
  for (let a = 154; a <= 194; a += 4) {
    brakePts.push([cx + 488 * dCos(a), cy + 488 * dSin(a)]);
  }
  for (let a = 194; a >= 154; a -= 4) {
    brakePts.push([cx + 528 * dCos(a), cy + 528 * dSin(a)]);
  }
  brush.noStroke();
  brush.wash(PAL.darkUmber, 235);
  drawShapePoly(brakePts, 0.1, true);
  brush.noWash();

  brush.set("fine_graphite", PAL.bleachedLow, 0.9);
  brush.arc(cx, cy, 490, 154, 194);
  brush.set("charcoal", PAL.voidBlack, 1.3);
  brush.arc(cx, cy, 528, 154, 194);

  // Brake hanger vertical lever & heavy clevis pins
  let bhX1 = cx + 525 * dCos(196);
  let bhY1 = cy + 525 * dSin(196);
  let bhX2 = cx + 515 * dCos(154);
  let bhY2 = cy + 515 * dSin(154);
  brush.set("grease_impasto", PAL.voidBlack, 1.8);
  brush.line(bhX1 - 8, bhY1 - 90, bhX2 - 6, bhY2 + 65);
  brush.set("fine_graphite", PAL.bleachedMid, 0.95);
  brush.line(bhX1 - 12, bhY1 - 90, bhX2 - 10, bhY2 + 65);

  drawHexBolt(bhX1 - 6, bhY1 - 65, 11, true);
  drawHexBolt((bhX1 + bhX2) * 0.5 - 6, (bhY1 + bhY2) * 0.5, 13, true);
  drawHexBolt(bhX2 - 5, bhY2 + 35, 10, true);
}

// =============================================================================
// 3. STEEL RAIL, FISHPLATE, SLEEPERS & CRUSHED BALLAST
// =============================================================================
function renderRailAndBallast(wheelCx) {
  const railTop = 1045;
  const railHeadBot = 1064;
  const railWebBot = 1098;
  const railFootBot = 1114;

  // Crushed stone ballast & timber sleepers bed
  brush.noStroke();
  brush.wash(PAL.abyssCyan, 230);
  brush.rect(84, railFootBot - 4, 1100, 1180 - railFootBot + 4, "corner");
  brush.noWash();

  // Ballast stones & oily cinder texture
  for (let i = 0; i < 160; i++) {
    let bx = random(90, 1175);
    let by = random(railFootBot + 2, 1174);
    let bw = random(8, 24);
    let bh = random(5, 14);
    let col =
      random() < 0.35
        ? PAL.voidBlack
        : random() < 0.65
          ? PAL.darkUmber
          : PAL.prussianMid;
    brush.set("charcoal", col, random(0.6, 1.3));
    brush.line(bx, by, bx + bw, by + random(-4, 4));
    if (random() < 0.35) {
      brush.set("fine_graphite", PAL.bleachedLow, 0.55);
      brush.line(bx, by - 1, bx + bw * 0.6, by - 1);
    }
  }

  // Rail Web (recessed dark channel) & Rail Foot
  brush.noStroke();
  brush.wash(PAL.voidBlack, 240);
  brush.rect(84, railHeadBot, 1100, railWebBot - railHeadBot, "corner");
  brush.wash(PAL.greaseEarth, 210);
  brush.rect(84, railWebBot, 1100, railFootBot - railWebBot, "corner");

  // Rail Head (polished steel table)
  brush.wash(PAL.prussianSlate, 210);
  brush.rect(84, railTop, 1100, railHeadBot - railTop, "corner");
  brush.noWash();

  // Bright bleached specular reflection along top surface of steel rail
  for (let yOff = 0; yOff <= 6; yOff += 1.5) {
    let col = yOff < 3 ? PAL.bleachedPeak : PAL.bleachedMid;
    brush.set("fine_graphite", col, 0.9);
    brush.line(84, railTop + yOff, 1184, railTop + yOff);
  }

  // Lower rail head shadow & rail foot edge highlights
  brush.set("charcoal", PAL.voidBlack, 1.4);
  brush.line(84, railHeadBot, 1184, railHeadBot);
  brush.line(84, railFootBot, 1184, railFootBot);
  brush.set("fine_graphite", PAL.warmTaupe, 0.8);
  brush.line(84, railWebBot, 1184, railWebBot);

  // Heavy Bolted Fishplate (Joint Bar) on the rail web at x = 250..465
  brush.noStroke();
  brush.wash(PAL.oiledBronze, 215);
  brush.rect(250, railHeadBot + 3, 215, 30, "corner");
  brush.noWash();
  brush.set("fine_graphite", PAL.bleachedLow, 0.85);
  brush.rect(250, railHeadBot + 3, 215, 30, "corner");
  for (let bx of [278, 330, 385, 437]) {
    drawHexBolt(bx, railHeadBot + 18, 8.5, false);
  }

  // Cast-iron Rail Chairs & Spikes along the rail foot
  for (let cxPos of [175, 535, 745, 980, 1135]) {
    brush.noStroke();
    brush.wash(PAL.darkUmber, 235);
    brush.rect(cxPos - 26, railWebBot - 6, 52, 26, "corner");
    brush.noWash();
    brush.set("fine_graphite", PAL.parchmentGrey, 0.7);
    brush.line(cxPos - 26, railWebBot - 6, cxPos + 26, railWebBot - 6);
    drawRivet(cxPos - 16, railFootBot - 4, 5.5, true);
    drawRivet(cxPos + 16, railFootBot - 4, 5.5, true);
  }

  // Intense crushing contact shadow where wheel tread meets rail at wheelCx
  brush.set("charcoal", PAL.voidBlack, 2.2);
  brush.line(wheelCx - 85, railTop + 1, wheelCx + 85, railTop + 1);
  brush.line(wheelCx - 55, railTop + 3, wheelCx + 55, railTop + 3);
}

// =============================================================================
// 4. THE GREAT DRIVING WHEEL (SPOKES, COUNTERWEIGHT, RIM, TIRE & HUB)
// =============================================================================
function renderDrivingWheel(cx, cy, crankX, crankY, crankAng) {
  const R_flange = 485;
  const R_tread = 468;
  const R_seam = 442;
  const R_tireLip = 424;
  const R_rimInner = 390;

  // Deep shadow inside the wheel openings (between spokes)
  brush.noStroke();
  brush.wash(PAL.voidBlack, 155);
  brush.circle(cx, cy, R_rimInner + 6, 0.02);
  brush.noWash();

  // --- A. 20 Tapered Cast-Steel Spokes ---
  const numSpokes = 20;
  for (let i = 0; i < numSpokes; i++) {
    let ang = i * (360 / numSpokes);
    let ux = dCos(ang);
    let uy = dSin(ang);

    // Spokes from R = 120 to R = 392
    let rStart = 120;
    let rEnd = R_rimInner + 4;
    let wStart = 15.5;
    let wEnd = 11.0;

    let p1 = rodPt(cx, cy, ux, uy, rStart, -wStart);
    let p2 = rodPt(cx, cy, ux, uy, rEnd - 24, -wEnd);
    let p2Flare = rodPt(cx, cy, ux, uy, rEnd, -wEnd * 1.9);
    let p3Flare = rodPt(cx, cy, ux, uy, rEnd, wEnd * 1.9);
    let p3 = rodPt(cx, cy, ux, uy, rEnd - 24, wEnd);
    let p4 = rodPt(cx, cy, ux, uy, rStart, wStart);

    // Base fill of spoke
    brush.noStroke();
    brush.wash(PAL.darkPrussian, 235);
    drawShapePoly([p1, p2, p2Flare, p3Flare, p3, p4], 0.15, true);
    brush.noWash();

    // Cylindrical 3D shading along each spoke
    let lightDot = dCos(ang - 225); // upper-left directional lighting
    let litCol = lightDot > 0 ? PAL.bleachedLow : PAL.prussianMist;
    let midCol = lightDot > 0 ? PAL.prussianSlate : PAL.prussianDeep;

    // Longitudinal charcoal/graphite modeling strokes
    for (let frac = -0.85; frac <= 0.85; frac += 0.28) {
      let spA = rodPt(cx, cy, ux, uy, rStart + 10, frac * wStart);
      let spB = rodPt(cx, cy, ux, uy, rEnd - 10, frac * wEnd);
      if (frac < -0.3) {
        brush.set("fine_graphite", litCol, 0.85);
      } else if (frac < 0.25) {
        brush.set("fine_graphite", midCol, 0.9);
      } else if (frac < 0.6) {
        brush.set("fine_graphite", PAL.greaseEarth, 0.9);
      } else {
        brush.set("charcoal", PAL.voidBlack, 1.0);
      }
      brush.line(spA[0], spA[1], spB[0], spB[1]);
    }

    // Flared root fillet highlights where spoke joins inner rim
    brush.set("fine_graphite", litCol, 0.75);
    brush.spline([p1, p2, p2Flare], 0.4);
    brush.set("charcoal", PAL.voidBlack, 0.95);
    brush.spline([p4, p3, p3Flare], 0.4);
  }

  // --- B. Solid Crescent Counterweight (192° to 282°, opposite Crank Pin) ---
  const cwStart = 192;
  const cwEnd = 282;
  const cwInnerR = 232;
  const cwOuterR = R_rimInner + 3;

  let cwPts = [];
  for (let a = cwStart; a <= cwEnd; a += 3) {
    // Taper inner radius slightly near the crescent tips
    let edgeFactor = Math.sin(((a - cwStart) / (cwEnd - cwStart)) * Math.PI);
    let rIn = cwInnerR + (1 - edgeFactor) * 48;
    cwPts.push([cx + rIn * dCos(a), cy + rIn * dSin(a)]);
  }
  for (let a = cwEnd; a >= cwStart; a -= 3) {
    cwPts.push([cx + cwOuterR * dCos(a), cy + cwOuterR * dSin(a)]);
  }

  brush.noStroke();
  brush.wash(PAL.charcoalCyan, 245);
  drawShapePoly(cwPts, 0.15, true);
  brush.noWash();

  // Concentric charcoal & graphite tonal arcs across the counterweight mass
  for (let r = cwInnerR + 4; r <= cwOuterR - 2; r += 3.2) {
    let t = (r - cwInnerR) / (cwOuterR - cwInnerR);
    let spanTrim = (1 - Math.sin(Math.min(1, t * 2.2) * (Math.PI / 2))) * 22;
    let a1 = cwStart + spanTrim;
    let a2 = cwEnd - spanTrim;
    if (a2 <= a1 + 4) continue;

    let col;
    if (t < 0.08) col = PAL.bleachedHigh;
    else if (t < 0.22) col = PAL.prussianLight;
    else if (t < 0.55) col = PAL.prussianMid;
    else if (t < 0.82) col = PAL.greaseEarth;
    else col = PAL.darkPrussian;

    brush.set(t < 0.15 ? "fine_graphite" : "charcoal", col, 0.9);
    brush.arc(cx, cy, r, a1, a2);
  }

  // Hatching across counterweight for cast-iron foundry texture
  brush.hatchStyle("2H", PAL.abyssCyan, 0.65);
  brush.hatch(7, 42, { rand: 0.06 });
  brush.noStroke();
  drawShapePoly(cwPts, 0.1, true);
  brush.noHatch();

  // 5 Recessed Lead-Fill Plugs & Centrifugal Grease Streaks on Counterweight
  for (let a of [210, 223, 237, 251, 264]) {
    let px = cx + 318 * dCos(a);
    let py = cy + 318 * dSin(a);
    drawRivet(px, py, 12, true);
    drawRivet(px, py, 4.5, false);

    // Radial centrifugal oil/soot streaks flung toward rim
    brush.set("grease_impasto", PAL.darkUmber, 0.75);
    brush.line(
      cx + 330 * dCos(a),
      cy + 330 * dSin(a),
      cx + 388 * dCos(a + 1),
      cy + 388 * dSin(a + 1)
    );
  }

  // --- C. Wheel Rim, Tire Retaining Ring, Machined Steel Tire & Outer Flange ---
  // Base concentric bands
  drawRingWash(cx, cy, R_rimInner, R_tireLip, PAL.darkPrussian, 240);
  drawRingWash(cx, cy, R_tireLip, R_seam, PAL.greaseEarth, 225);
  drawRingWash(cx, cy, R_seam, R_tread, PAL.prussianMid, 230);
  drawRingWash(cx, cy, R_tread, R_flange, PAL.abyssCyan, 245);

  // Angular metallic specular modulation around the 360° Steel Tire & Rim
  // Upper-left (190..265°) and lower-right (10..75°) catch bleached silent-film sheen
  const numSectors = 36;
  for (let s = 0; s < numSectors; s++) {
    let a1 = s * 10;
    let a2 = a1 + 10.5;
    let aMid = a1 + 5;

    // Specular factor: two opposing metallic reflection lobes on turned steel
    let spec1 = Math.max(0, dCos(aMid - 225));
    let spec2 = Math.max(0, dCos(aMid - 38)) * 0.82;
    let spec = Math.max(spec1, spec2);

    let tireCol =
      spec > 0.78
        ? PAL.bleachedPeak
        : spec > 0.52
          ? PAL.bleachedMid
          : spec > 0.28
            ? PAL.prussianLight
            : spec > 0.1
              ? PAL.prussianSlate
              : PAL.darkPrussian;

    let rimCol =
      spec > 0.7
        ? PAL.warmTaupe
        : spec > 0.35
          ? PAL.prussianMid
          : PAL.abyssCyan;

    // Turned steel tire lathe lines
    for (let r = R_seam + 2; r <= R_tread - 2; r += 3.2) {
      brush.set("fine_graphite", tireCol, 0.9);
      brush.arc(cx, cy, r, a1, a2);
    }

    // Inner cast rim shading
    for (let r = R_rimInner + 3; r <= R_tireLip - 2; r += 4.0) {
      brush.set("charcoal", rimCol, 0.85);
      brush.arc(cx, cy, r, a1, a2);
    }

    // Outer flange bevel highlight
    if (spec > 0.35) {
      brush.set(
        "fine_graphite",
        spec > 0.7 ? PAL.bleachedPeak : PAL.bleachedLow,
        0.95
      );
      brush.arc(cx, cy, R_tread + 3, a1, a2);
      brush.arc(cx, cy, R_flange - 2, a1, a2);
    }
  }

  // Crisp structural boundary circles of the wheel rim & tire
  brush.set("charcoal", PAL.voidBlack, 1.5);
  brush.circle(cx, cy, R_rimInner, 0.008);
  brush.circle(cx, cy, R_tireLip, 0.008);
  brush.circle(cx, cy, R_seam, 0.008);
  brush.circle(cx, cy, R_tread, 0.008);
  brush.circle(cx, cy, R_flange, 0.008);

  brush.set("fine_graphite", PAL.bleachedHigh, 0.85);
  brush.arc(cx, cy, R_rimInner + 2.5, 185, 290);
  brush.arc(cx, cy, R_rimInner + 2.5, 5, 85);

  // 36 Tire-Retaining Lip Rivets around R = 433
  for (let a = 0; a < 360; a += 10) {
    let rx = cx + 433 * dCos(a);
    let ry = cy + 433 * dSin(a);
    let isLit = dCos(a - 225) > -0.2 || dCos(a - 38) > 0.2;
    drawRivet(rx, ry, 4.8, isLit);
  }

  // 3 White/Ochre Railroad Shop Tire-Slip Alignment Stripes across rim-to-tire seam
  for (let slipAng of [162, 248, 322]) {
    for (let off = -2.5; off <= 2.5; off += 1.2) {
      let x1 = cx + (R_rimInner + 14) * dCos(slipAng) - off * dSin(slipAng);
      let y1 = cy + (R_rimInner + 14) * dSin(slipAng) + off * dCos(slipAng);
      let x2 = cx + (R_tread - 4) * dCos(slipAng) - off * dSin(slipAng);
      let y2 = cy + (R_tread - 4) * dSin(slipAng) + off * dCos(slipAng);
      brush.set("fine_graphite", PAL.bleachedHigh, 0.8);
      brush.line(x1, y1, x2, y2);
    }
  }

  // --- D. Massive Central Cast-Iron Wheel Boss (Axle Hub + Crank Pin Boss) ---
  const rHub = 142;
  const rCrankBoss = 114;
  let bossPts = buildPeanutBoss(
    cx,
    cy,
    rHub,
    crankX,
    crankY,
    rCrankBoss,
    crankAng
  );
  let bossInnerPts = buildPeanutBoss(
    cx,
    cy,
    rHub - 16,
    crankX,
    crankY,
    rCrankBoss - 15,
    crankAng
  );

  // Cast shadow of central wheel boss onto spokes
  let bossShadowPts = bossPts.map((p) => [p[0] + 10, p[1] + 14]);
  brush.noStroke();
  brush.wash(PAL.voidBlack, 185);
  drawShapePoly(bossShadowPts, 0.15, true);

  // Outer boss flange fill
  brush.wash(PAL.prussianDeep, 245);
  drawShapePoly(bossPts, 0.15, true);

  // Recessed inner boss face fill
  brush.wash(PAL.charcoalCyan, 245);
  drawShapePoly(bossInnerPts, 0.15, true);
  brush.noWash();

  // Cross-hatched cast-iron grain & grease patina on wheel boss
  brush.hatchStyle("2B", PAL.abyssCyan, 0.75);
  brush.hatch(6, 28, { rand: 0.07 });
  brush.noStroke();
  drawShapePoly(bossInnerPts, 0.15, true);
  brush.hatchStyle("fine_graphite", PAL.greaseEarth, 0.65);
  brush.hatch(8, -52, { rand: 0.08 });
  drawShapePoly(bossInnerPts, 0.15, true);
  brush.noHatch();

  // Boss contour rims & bleached upper-left bevel highlights
  brush.set("charcoal", PAL.voidBlack, 1.6);
  drawShapePoly(bossPts, 0.15, true);
  drawShapePoly(bossInnerPts, 0.15, true);

  brush.set("fine_graphite", PAL.bleachedHigh, 1.1);
  brush.arc(cx, cy, rHub - 2, 155, 315);
  brush.arc(cx, cy, rHub - 15, 160, 310);

  // --- E. Main Pressed Steel Axle End at (cx, cy) ---
  const rAxleCollar = 96;
  const rAxleEnd = 78;

  brush.noStroke();
  brush.wash(PAL.darkUmber, 240);
  brush.circle(cx, cy, rAxleCollar, 0.01);
  brush.wash(PAL.prussianSlate, 235);
  brush.circle(cx, cy, rAxleEnd, 0.01);
  brush.noWash();

  // Concentric lathe turning rings on steel axle face
  for (let r = 18; r <= rAxleEnd - 2; r += 3.0) {
    let col =
      r > rAxleEnd - 10
        ? PAL.bleachedHigh
        : r % 9 < 3
          ? PAL.bleachedLow
          : r % 9 < 6
            ? PAL.prussianMid
            : PAL.mutedEarth;
    brush.set("fine_graphite", col, 0.8);
    brush.circle(cx, cy, r, 0.005);
  }

  // Specular flare across axle face
  for (let r = 20; r <= rAxleEnd - 4; r += 2.5) {
    brush.set("fine_graphite", PAL.bleachedPeak, 0.85);
    brush.arc(cx, cy, r, 200, 255);
    brush.arc(cx, cy, r, 20, 68);
  }

  // Rectangular Steel Keyway driven into axle perimeter at -65 deg
  let kwUx = dCos(-65);
  let kwUy = dSin(-65);
  let kwPts = [
    rodPt(cx, cy, kwUx, kwUy, rAxleEnd - 14, -13),
    rodPt(cx, cy, kwUx, kwUy, rAxleEnd + 12, -13),
    rodPt(cx, cy, kwUx, kwUy, rAxleEnd + 12, 13),
    rodPt(cx, cy, kwUx, kwUy, rAxleEnd - 14, 13)
  ];
  brush.noStroke();
  brush.wash(PAL.oiledBronze, 240);
  drawShapePoly(kwPts, 0, true);
  brush.noWash();
  brush.set("charcoal", PAL.voidBlack, 1.1);
  drawShapePoly(kwPts, 0, true);
  brush.set("fine_graphite", PAL.bleachedHigh, 0.85);
  brush.line(kwPts[0][0], kwPts[0][1], kwPts[1][0], kwPts[1][1]);

  // Central Conical Lathe Center Dimple & Weeping Grease Trail
  brush.noStroke();
  brush.wash(PAL.voidBlack, 250);
  brush.circle(cx, cy, 15, 0.02);
  brush.noWash();
  brush.set("fine_graphite", PAL.bleachedHigh, 0.9);
  brush.arc(cx, cy, 15, 25, 195);

  // Dark viscous axle grease weeping down from lathe center & axle collar
  for (let gx = -18; gx <= 18; gx += 4.5) {
    let len = random(45, 115);
    brush.set("grease_impasto", PAL.voidBlack, random(0.7, 1.3));
    brush.line(cx + gx, cy + 12, cx + gx + random(-4, 4), cy + 12 + len);
  }
}

// Helper to build smooth tangent peanut contour around wheel hub and crank boss
function buildPeanutBoss(x1, y1, r1, x2, y2, r2, ang) {
  let pts = [];
  for (let a = ang + 72; a <= ang + 288; a += 6) {
    pts.push([x1 + r1 * dCos(a), y1 + r1 * dSin(a)]);
  }
  for (let a = ang - 72; a <= ang + 72; a += 6) {
    pts.push([x2 + r2 * dCos(a), y2 + r2 * dSin(a)]);
  }
  return pts;
}

// Helper to draw an annular ring wash using polygon vertices
function drawRingWash(cx, cy, rIn, rOut, col, alpha) {
  let pts = [];
  for (let a = 0; a <= 360; a += 6) {
    pts.push([cx + rIn * dCos(a), cy + rIn * dSin(a)]);
  }
  for (let a = 360; a >= 0; a -= 6) {
    pts.push([cx + rOut * dCos(a), cy + rOut * dSin(a)]);
  }
  brush.noStroke();
  brush.wash(col, alpha);
  drawShapePoly(pts, 0, true);
  brush.noWash();
}

// =============================================================================
// 5. HORIZONTAL COUPLING ROD (SIDE ROD) & KNUCKLE JOINT
// =============================================================================
function renderCouplingRod(crankX, crankY) {
  const rodY = crankY;
  const hHalf = 40; // total height 80px
  const fluteHalf = 24;

  // Cast shadow of horizontal coupling rod onto lower wheel spokes & rim
  brush.noStroke();
  brush.wash(PAL.voidBlack, 185);
  brush.rect(84, rodY - hHalf + 12, 1100, hHalf * 2 + 6, "corner");

  // Main horizontal coupling rod body (x = 84 to 1184)
  brush.wash(PAL.prussianDeep, 245);
  brush.rect(84, rodY - hHalf, 1100, hHalf * 2, "corner");

  // Recessed I-beam fluted channel (left segment x=84..635, right segment x=1015..1184)
  brush.wash(PAL.abyssCyan, 235);
  brush.rect(84, rodY - fluteHalf, 550, fluteHalf * 2, "corner");
  brush.rect(1015, rodY - fluteHalf, 170, fluteHalf * 2, "corner");
  brush.noWash();

  // Horizontal metallic shading along Top Flange, Flute Web & Bottom Flange
  for (let dy = -hHalf; dy <= hHalf; dy += 2.2) {
    let col;
    let br = "fine_graphite";
    if (dy < -fluteHalf) {
      // Top flange: bright bleached steel highlight
      col = dy < -hHalf + 6 ? PAL.bleachedPeak : PAL.bleachedMid;
    } else if (dy < -fluteHalf + 7) {
      // Undercut shadow beneath top flange
      col = PAL.voidBlack;
      br = "charcoal";
    } else if (dy < fluteHalf - 6) {
      // Concave oiled flute web grading from Prussian slate to muted earth
      let f = (dy + fluteHalf) / (fluteHalf * 2);
      col =
        f < 0.4
          ? PAL.prussianMid
          : f < 0.75
            ? PAL.mutedEarth
            : PAL.prussianLight;
    } else if (dy < fluteHalf + 3) {
      // Bottom flute lip catching sky reflection
      col = PAL.bleachedLow;
    } else {
      // Bottom flange in shadow
      col = dy > hHalf - 6 ? PAL.voidBlack : PAL.darkPrussian;
      br = "charcoal";
    }

    brush.set(br, col, 0.85);
    brush.line(84, rodY + dy, 640, rodY + dy);
    brush.line(1010, rodY + dy, 1184, rodY + dy);
  }

  // Solid Coupling Rod Boss & Forged Knuckle Clevis Block (x = 640 to 1015)
  brush.noStroke();
  brush.wash(PAL.prussianMid, 240);
  brush.rect(640, rodY - hHalf - 6, 375, (hHalf + 6) * 2, "corner");
  brush.noWash();

  for (let dy = -hHalf - 6; dy <= hHalf + 6; dy += 2.5) {
    let col =
      dy < -hHalf + 4
        ? PAL.bleachedHigh
        : dy < 0
          ? PAL.prussianSlate
          : dy < hHalf - 6
            ? PAL.oiledBronze
            : PAL.voidBlack;
    brush.set("fine_graphite", col, 0.85);
    brush.line(640, rodY + dy, 1015, rodY + dy);
  }

  // Articulated Knuckle Joint at x = 960, y = rodY
  const knX = 960;
  // Vertical fork seam
  brush.set("charcoal", PAL.voidBlack, 1.5);
  brush.line(knX - 38, rodY - hHalf - 6, knX - 38, rodY + hHalf + 6);
  brush.line(knX + 42, rodY - hHalf - 6, knX + 42, rodY + hHalf + 6);
  brush.set("fine_graphite", PAL.bleachedHigh, 0.85);
  brush.line(knX - 35, rodY - hHalf - 6, knX - 35, rodY + hHalf + 6);

  // Knuckle Pin Boss, Hex Locknut & Heavy Split Cotter Key
  brush.noStroke();
  brush.wash(PAL.darkUmber, 245);
  brush.circle(knX, rodY, 34, 0.01);
  brush.noWash();
  brush.set("fine_graphite", PAL.bleachedMid, 1.0);
  brush.arc(knX, rodY, 34, 185, 330);
  brush.set("charcoal", PAL.voidBlack, 1.3);
  brush.arc(knX, rodY, 34, 5, 180);
  drawHexBolt(knX, rodY, 21, true);

  // Machined Lubricating Oil Cup on top of Knuckle Joint
  drawOilCup(knX, rodY - hHalf - 6, 26, 28);

  // Dark grease streaks weeping from Knuckle Joint
  for (let gx = -22; gx <= 24; gx += 5) {
    brush.set("grease_impasto", PAL.voidBlack, 0.95);
    brush.line(
      knX + gx,
      rodY + 18,
      knX + gx + random(-3, 3),
      rodY + hHalf + random(6, 22)
    );
  }
}

// =============================================================================
// 6. MAIN CONNECTING ROD, FLUTED SHAFT & BIG-END ASSEMBLY
// =============================================================================
function renderMainConnectingRod(crankX, crankY) {
  // Main Connecting Rod runs from Piston Crosshead (70, 385) to Crank Pin (crankX, crankY)
  const startX = 70;
  const startY = 385;
  const dx = crankX - startX;
  const dy = crankY - startY;
  const rodLen = Math.hypot(dx, dy);
  // Unit vector pointing from Crank Pin back up-left toward Crosshead
  const ux = -dx / rodLen;
  const uy = -dy / rodLen;
  // Note: with rodPt(crankX, crankY, ux, uy, s, n):
  // s > 0 moves up-left along the rod toward (70, 385)
  // n > 0 points UP-RIGHT (top lit edge of the rod!)
  // n < 0 points DOWN-LEFT (bottom shadow edge of the rod!)

  // --- A. Cast Shadow of Main Rod & Big End onto Wheel & Coupling Rod ---
  let shadowPts = [
    rodPt(crankX + 14, crankY + 18, ux, uy, -98, 86),
    rodPt(crankX + 14, crankY + 18, ux, uy, 148, 86),
    rodPt(crankX + 14, crankY + 18, ux, uy, rodLen + 20, 46),
    rodPt(crankX + 14, crankY + 18, ux, uy, rodLen + 20, -46),
    rodPt(crankX + 14, crankY + 18, ux, uy, 148, -86),
    rodPt(crankX + 14, crankY + 18, ux, uy, -98, -86)
  ];
  brush.noStroke();
  brush.wash(PAL.voidBlack, 195);
  drawShapePoly(shadowPts, 0.05, true);
  brush.noWash();

  // --- B. Tapered Fluted I-Beam Shaft of Main Rod (s = 138 to rodLen + 20) ---
  const sButt = 138;
  const sEnd = rodLen + 25;
  const hButt = 62;
  const hEnd = 44;

  let shaftPts = [
    rodPt(crankX, crankY, ux, uy, sButt, hButt),
    rodPt(crankX, crankY, ux, uy, sEnd, hEnd),
    rodPt(crankX, crankY, ux, uy, sEnd, -hEnd),
    rodPt(crankX, crankY, ux, uy, sButt, -hButt)
  ];
  brush.noStroke();
  brush.wash(PAL.prussianDeep, 248);
  drawShapePoly(shaftPts, 0, true);
  brush.noWash();

  // Longitudinal hyperreal metallic shading across the tapered I-beam shaft
  // nFrac in [+1.0 (top lit edge) .. -1.0 (bottom shadow edge)]
  const numStrips = 44;
  for (let i = 0; i <= numStrips; i++) {
    let nFrac = 1.0 - (2.0 * i) / numStrips;
    let pA = rodPt(crankX, crankY, ux, uy, sButt, nFrac * hButt);
    let pB = rodPt(crankX, crankY, ux, uy, sEnd, nFrac * hEnd);

    let col;
    let br = "fine_graphite";
    let wt = 0.95;

    if (nFrac > 0.62) {
      // Top Flange: intense bleached highlight bevel
      col =
        nFrac > 0.84
          ? PAL.bleachedPeak
          : nFrac > 0.72
            ? PAL.bleachedHigh
            : PAL.bleachedMid;
      wt = 1.05;
    } else if (nFrac > 0.48) {
      // Sharp undercut shadow beneath Top Flange
      col = PAL.voidBlack;
      br = "charcoal";
      wt = 1.15;
    } else if (nFrac > -0.45) {
      // Recessed Flute Channel: Prussian slate grading to warm oiled earth & sky reflection
      let fluteT = (0.48 - nFrac) / 0.93; // 0 at top of flute, 1 at bottom of flute
      if (fluteT < 0.25) col = PAL.darkPrussian;
      else if (fluteT < 0.5) col = PAL.prussianMid;
      else if (fluteT < 0.75) col = PAL.mutedEarth;
      else col = PAL.prussianLight;
    } else if (nFrac > -0.62) {
      // Upper lip of Bottom Flange catching bright reflection
      col = nFrac > -0.54 ? PAL.bleachedHigh : PAL.bleachedLow;
    } else {
      // Bottom Flange face & underside shadow
      col =
        nFrac > -0.82
          ? PAL.prussianDeep
          : nFrac > -0.92
            ? PAL.darkUmber
            : PAL.voidBlack;
      if (nFrac < -0.85) br = "charcoal";
    }

    brush.set(br, col, wt);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // Semicircular Flute Termination Cove at sButt = 148
  let covePts = [];
  for (let a = -90; a <= 90; a += 12) {
    let cs = sButt + 22 - 22 * dCos(a);
    let cn = 30 * dSin(a);
    covePts.push(rodPt(crankX, crankY, ux, uy, cs, cn));
  }
  brush.set("charcoal", PAL.voidBlack, 1.3);
  brush.spline(covePts, 0.4);

  // Longitudinal grease & cylinder oil streaks blown back along the flute
  for (let k = 0; k < 22; k++) {
    let s1 = random(165, rodLen - 40);
    let s2 = s1 - random(35, 110);
    let nf = random(-0.42, 0.42);
    let g1 = rodPt(crankX, crankY, ux, uy, s1, nf * 50);
    let g2 = rodPt(crankX, crankY, ux, uy, s2, nf * 54 - random(0, 6));
    brush.set(
      "grease_impasto",
      random() < 0.5 ? PAL.darkUmber : PAL.abyssCyan,
      random(0.5, 1.0)
    );
    brush.line(g1[0], g1[1], g2[0], g2[1]);
  }

  // --- C. Forged Big-End U-Strap & Brass Bearing Block (s = -96 to +142, n = -82 to +82) ---
  const sMin = -96;
  const sMax = 142;
  const nStrap = 82;
  const nInner = 56;

  let strapOuter = [
    rodPt(crankX, crankY, ux, uy, sMax, nStrap),
    rodPt(crankX, crankY, ux, uy, sMin + 14, nStrap),
    rodPt(crankX, crankY, ux, uy, sMin, nStrap - 14),
    rodPt(crankX, crankY, ux, uy, sMin, -nStrap + 14),
    rodPt(crankX, crankY, ux, uy, sMin + 14, -nStrap),
    rodPt(crankX, crankY, ux, uy, sMax, -nStrap)
  ];

  brush.noStroke();
  brush.wash(PAL.prussianSlate, 248);
  drawShapePoly(strapOuter, 0.05, true);
  brush.noWash();

  // Machined steel shading on the Big-End Strap
  for (let nf = -nStrap; nf <= nStrap; nf += 2.6) {
    let pA = rodPt(crankX, crankY, ux, uy, sMin + 6, nf);
    let pB = rodPt(crankX, crankY, ux, uy, sMax, nf);
    let col =
      nf > nStrap - 8
        ? PAL.bleachedPeak
        : nf > nInner
          ? PAL.bleachedLow
          : nf > 0
            ? PAL.prussianMid
            : nf > -nInner
              ? PAL.oiledBronze
              : nf > -nStrap + 8
                ? PAL.darkPrussian
                : PAL.voidBlack;
    brush.set("fine_graphite", col, 0.9);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // Two-Piece Bronze/Brass Crankpin Bearing Block inside the Strap (s = -60 to +58, n = -56 to +56)
  let brassBox = [
    rodPt(crankX, crankY, ux, uy, 58, nInner),
    rodPt(crankX, crankY, ux, uy, -60, nInner),
    rodPt(crankX, crankY, ux, uy, -60, -nInner),
    rodPt(crankX, crankY, ux, uy, 58, -nInner)
  ];
  brush.noStroke();
  brush.wash(PAL.brassOchre, 240);
  drawShapePoly(brassBox, 0, true);
  brush.noWash();

  // Muted earth & warm bronze hatching on bearing brasses
  for (let nf = -nInner + 2; nf <= nInner - 2; nf += 2.5) {
    let pA = rodPt(crankX, crankY, ux, uy, -58, nf);
    let pB = rodPt(crankX, crankY, ux, uy, 56, nf);
    let col =
      nf > 22
        ? PAL.parchmentGrey
        : nf > -15
          ? PAL.brassOchre
          : nf > -38
            ? PAL.oiledBronze
            : PAL.darkUmber;
    brush.set("fine_graphite", col, 0.85);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // Split seam between front and rear bearing brasses at s = 0
  let seamTop = rodPt(crankX, crankY, ux, uy, 0, nInner);
  let seamBot = rodPt(crankX, crankY, ux, uy, 0, -nInner);
  brush.set("charcoal", PAL.voidBlack, 1.4);
  brush.line(seamTop[0], seamTop[1], seamBot[0], seamBot[1]);
  brush.set("fine_graphite", PAL.bleachedHigh, 0.8);
  brush.line(seamTop[0] + 2, seamTop[1] + 1, seamBot[0] + 2, seamBot[1] + 1);

  // Crisp outlines of Brass Box & Strap
  brush.set("charcoal", PAL.voidBlack, 1.5);
  drawShapePoly(brassBox, 0, true);
  drawShapePoly(strapOuter, 0.05, true);

  // --- D. Tapered Adjusting Wedge / Cotter Key & Twin Strap Clamping Bolts ---
  // Tall Tapered Steel Cotter Key passing through s = 72..88, protruding top & bottom
  let cotterPts = [
    rodPt(crankX, crankY, ux, uy, 89, nStrap + 54),
    rodPt(crankX, crankY, ux, uy, 70, nStrap + 54),
    rodPt(crankX, crankY, ux, uy, 74, -nStrap - 38),
    rodPt(crankX, crankY, ux, uy, 87, -nStrap - 38)
  ];
  brush.noStroke();
  brush.wash(PAL.prussianSlate, 245);
  drawShapePoly(cotterPts, 0, true);
  brush.noWash();
  brush.set("charcoal", PAL.voidBlack, 1.2);
  drawShapePoly(cotterPts, 0, true);
  brush.set("fine_graphite", PAL.bleachedPeak, 0.95);
  brush.line(cotterPts[0][0], cotterPts[0][1], cotterPts[3][0], cotterPts[3][1]);

  // Cotter locking set-screws
  let cs1 = rodPt(crankX, crankY, ux, uy, 80, nStrap + 26);
  let cs2 = rodPt(crankX, crankY, ux, uy, 80, 0);
  drawHexBolt(cs1[0], cs1[1], 7.5, true);
  drawHexBolt(cs2[0], cs2[1], 8.5, false);

  // Two Massive Vertical Strap Clamping Bolts at s = 104 and s = 128
  for (let sb of [104, 128]) {
    let bTop = rodPt(crankX, crankY, ux, uy, sb, nStrap + 18);
    let bBot = rodPt(crankX, crankY, ux, uy, sb, -nStrap - 18);
    let sTop = rodPt(crankX, crankY, ux, uy, sb, nStrap);
    let sBot = rodPt(crankX, crankY, ux, uy, sb, -nStrap);

    // Bolt shaft line across strap
    brush.set("charcoal", PAL.voidBlack, 1.1);
    brush.line(sTop[0], sTop[1], sBot[0], sBot[1]);
    brush.set("fine_graphite", PAL.bleachedLow, 0.75);
    brush.line(sTop[0] + 3, sTop[1] + 1, sBot[0] + 3, sBot[1] + 1);

    // Castellated top nut & bottom bolt head
    drawHexBolt(bTop[0], bTop[1], 11, true);
    drawHexBolt(bBot[0], bBot[1], 10, false);
  }

  // --- E. Twin Machined Brass Oil Cups on top of the Big End ---
  for (let sCup of [-26, 26]) {
    let cupBase = rodPt(crankX, crankY, ux, uy, sCup, nStrap);
    let cupTop = rodPt(crankX, crankY, ux, uy, sCup, nStrap + 38);
    drawAngledOilCup(cupBase[0], cupBase[1], cupTop[0], cupTop[1], ux, uy, 17);

    // Viscous dark oil trails weeping down from each oil cup across strap & brasses
    for (let k = -6; k <= 6; k += 3) {
      let wStart = rodPt(crankX, crankY, ux, uy, sCup + k, nStrap - 2);
      brush.set("grease_impasto", PAL.voidBlack, random(0.6, 1.1));
      brush.line(
        wStart[0],
        wStart[1],
        wStart[0] + random(-5, 5),
        wStart[1] + random(45, 115)
      );
    }
  }
}

// =============================================================================
// 7. WALSCHAERTS ECCENTRIC CRANK ARM & ECCENTRIC ROD
// =============================================================================
function renderEccentricGear(crankX, crankY) {
  // Eccentric pin center offset down-left from main Crank Pin
  const eccX = crankX - 118;
  const eccY = crankY + 96;

  // --- A. Slender Eccentric Rod running from (eccX, eccY) back to Valve Link at (84, 575) ---
  const vX = 84;
  const vY = 575;
  const edx = eccX - vX;
  const edy = eccY - vY;
  const eLen = Math.hypot(edx, edy);
  const eux = -edx / eLen;
  const euy = -edy / eLen;

  let eRodPts = [
    rodPt(eccX, eccY, eux, euy, 0, 17),
    rodPt(eccX, eccY, eux, euy, eLen, 13),
    rodPt(eccX, eccY, eux, euy, eLen, -13),
    rodPt(eccX, eccY, eux, euy, 0, -17)
  ];

  // Shadow of Eccentric Rod
  let eShadow = eRodPts.map((p) => [p[0] + 8, p[1] + 10]);
  brush.noStroke();
  brush.wash(PAL.voidBlack, 175);
  drawShapePoly(eShadow, 0, true);

  brush.wash(PAL.prussianDeep, 240);
  drawShapePoly(eRodPts, 0, true);
  brush.noWash();

  for (let nf = -15; nf <= 15; nf += 2.5) {
    let pA = rodPt(eccX, eccY, eux, euy, 18, nf);
    let pB = rodPt(eccX, eccY, eux, euy, eLen, nf * 0.78);
    let col =
      nf > 9
        ? PAL.bleachedHigh
        : nf > 0
          ? PAL.prussianSlate
          : nf > -9
            ? PAL.mutedEarth
            : PAL.voidBlack;
    brush.set("fine_graphite", col, 0.85);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // --- B. Forged Eccentric Crank Arm clamping onto Main Crank Pin (crankX, crankY) to (eccX, eccY) ---
  const cdx = eccX - crankX;
  const cdy = eccY - crankY;
  const cLen = Math.hypot(cdx, cdy);
  const cux = cdx / cLen;
  const cuy = cdy / cLen;

  // Build contour around Crank Pin Eye (R=48) and Eccentric Pin Eye (R=30)
  let armPts = buildPeanutBoss(crankX, crankY, 48, eccX, eccY, 30, 140);
  let armShadow = armPts.map((p) => [p[0] + 9, p[1] + 12]);

  brush.noStroke();
  brush.wash(PAL.voidBlack, 195);
  drawShapePoly(armShadow, 0.15, true);

  brush.wash(PAL.prussianSlate, 248);
  drawShapePoly(armPts, 0.15, true);
  brush.noWash();

  // Recessed web inside the Eccentric Crank Arm
  for (let nf = -18; nf <= 18; nf += 2.5) {
    let p1 = rodPt(crankX, crankY, cux, cuy, 36, nf);
    let p2 = rodPt(crankX, crankY, cux, cuy, cLen - 24, nf * 0.75);
    let col =
      nf < -10
        ? PAL.bleachedPeak
        : nf < 0
          ? PAL.bleachedLow
          : nf < 10
            ? PAL.oiledBronze
            : PAL.darkPrussian;
    brush.set("fine_graphite", col, 0.9);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  brush.set("charcoal", PAL.voidBlack, 1.5);
  drawShapePoly(armPts, 0.15, true);

  // Main Crank Pin Center Cap, 3 Locking Bolts & Central Grease Nipple
  brush.noStroke();
  brush.wash(PAL.darkUmber, 245);
  brush.circle(crankX, crankY, 35, 0.01);
  brush.noWash();
  brush.set("fine_graphite", PAL.bleachedPeak, 1.0);
  brush.arc(crankX, crankY, 35, 190, 325);
  brush.set("charcoal", PAL.voidBlack, 1.3);
  brush.arc(crankX, crankY, 35, 10, 185);

  for (let a of [30, 150, 270]) {
    drawHexBolt(crankX + 20 * dCos(a), crankY + 20 * dSin(a), 6.5, false);
  }
  drawHexBolt(crankX, crankY, 9.5, true);

  // Eccentric Pin Joint & Pinch Bolt at (eccX, eccY)
  brush.noStroke();
  brush.wash(PAL.darkUmber, 240);
  brush.circle(eccX, eccY, 22, 0.01);
  brush.noWash();
  drawHexBolt(eccX, eccY, 13, true);
}

// =============================================================================
// 8. LIFTED STEAM PLUMES & SPECULAR HALATION (DREAMY, NOSTALGIC MOOD)
// =============================================================================
function renderLiftedSteamPlumes(cx, cy, crankX, crankY) {
  // 1. Translucent Watercolor Steam Billows (soft edges, lifted charcoal look)
  brush.noStroke();
  brush.noHatch();
  brush.fillBleed(0.48, "out");
  brush.fillTexture(0.55, 0.25);

  // Outer pale Prussian-mist steam envelope
  brush.fill(PAL.bleachedLow, 68);
  // Plume A: Lower-left cylinder cock exhaust surging across wheel rim & lower spokes
  drawShapePoly(
    [
      [84, 710],
      [230, 620],
      [460, 650],
      [620, 780],
      [580, 990],
      [350, 1110],
      [84, 1140]
    ],
    0.45,
    true
  );
  // Plume B: Trailing steam cloud along rail & behind knuckle joint
  drawShapePoly(
    [
      [680, 880],
      [940, 810],
      [1184, 760],
      [1184, 1130],
      [740, 1120]
    ],
    0.45,
    true
  );
  // Plume C: Upper-left piston crosshead vapor wisp
  drawShapePoly(
    [
      [84, 240],
      [320, 280],
      [430, 410],
      [250, 490],
      [84, 470]
    ],
    0.45,
    true
  );

  // Brighter bleached inner steam cores
  brush.fill(PAL.bleachedHigh, 82);
  drawShapePoly(
    [
      [84, 780],
      [210, 710],
      [410, 740],
      [490, 870],
      [390, 1020],
      [84, 1060]
    ],
    0.45,
    true
  );
  drawShapePoly(
    [
      [820, 920],
      [1040, 860],
      [1184, 830],
      [1184, 1070],
      [860, 1060]
    ],
    0.45,
    true
  );
  drawShapePoly(
    [
      [84, 290],
      [240, 320],
      [310, 400],
      [170, 440],
      [84, 420]
    ],
    0.45,
    true
  );

  // Intense bleached highlight core at lower-left exhaust nozzle
  brush.fill(PAL.bleachedPeak, 95);
  drawShapePoly(
    [
      [84, 840],
      [195, 790],
      [330, 830],
      [310, 960],
      [84, 1010]
    ],
    0.45,
    true
  );

  brush.noFill();

  // 2. Vector-Field Lifted Steam Gestures (kneaded-eraser & vapor turbulence)
  brush.field("steam_turbulence");

  // Lower-left main steam plume flowLines
  for (let i = 0; i < 165; i++) {
    let sx = random(84, 560);
    let sy = random(650, 1110);
    // Concentrate density toward lower-left core
    let distCore = Math.hypot(sx - 210, sy - 890);
    if (distCore > 380 && random() < 0.65) continue;

    let col =
      distCore < 150
        ? PAL.bleachedPeak
        : distCore < 260
          ? PAL.bleachedHigh
          : PAL.bleachedLow;
    let br = random() < 0.6 ? "steam_lift" : "soft_charcoal";
    brush.set(br, col, random(0.7, 1.5));
    brush.flowLine(sx, sy, random(55, 165), random(-35, 15));
  }

  // Lower-right trailing rail steam flowLines
  for (let i = 0; i < 95; i++) {
    let sx = random(720, 1160);
    let sy = random(820, 1100);
    let col = random() < 0.45 ? PAL.bleachedHigh : PAL.bleachedLow;
    brush.set(
      random() < 0.65 ? "steam_lift" : "soft_charcoal",
      col,
      random(0.6, 1.3)
    );
    brush.flowLine(sx, sy, random(50, 140), random(-25, 20));
  }

  // Upper-left crosshead steam wisps
  for (let i = 0; i < 65; i++) {
    let sx = random(84, 380);
    let sy = random(260, 470);
    let col = random() < 0.5 ? PAL.bleachedHigh : PAL.prussianLight;
    brush.set("steam_lift", col, random(0.6, 1.2));
    brush.flowLine(sx, sy, random(45, 120), random(-20, 25));
  }

  brush.noField();

  // 3. Re-assert faint ghosted mechanical contours peeking through the thinner steam edges
  brush.set("fine_graphite", PAL.prussianSlate, 0.65);
  brush.arc(cx, cy, 468, 108, 162);
  brush.arc(cx, cy, 485, 112, 158);
}

// =============================================================================
// 9. SILENT FILM VIGNETTE, VERTICAL SCRATCHES & DUST SPECKS
// =============================================================================
function renderFilmArtifacts() {
  // --- A. Flickering Uneven Silent Film Vignette darkening the corners ---
  brush.noStroke();
  brush.fillBleed(0.45, "in");
  brush.fillTexture(0.75, 0.4);

  // Four uneven corner shadow polygons batched in dark Prussian charcoal
  brush.fill(PAL.abyssCyan, 155);
  // Top-Left corner
  drawShapePoly([
    [84, 20],
    [520, 20],
    [310, 140],
    [160, 310],
    [84, 520]
  ]);
  // Top-Right corner (extra deep flicker)
  drawShapePoly([
    [620, 20],
    [1184, 20],
    [1184, 580],
    [1050, 320],
    [890, 150]
  ]);
  // Bottom-Right corner
  drawShapePoly([
    [1184, 780],
    [1184, 1180],
    [760, 1180],
    [980, 1060],
    [1110, 930]
  ]);
  // Bottom-Left corner
  drawShapePoly([
    [84, 880],
    [180, 1040],
    [380, 1180],
    [84, 1180]
  ]);

  // Second tighter pass of carbon-black corner vignette
  brush.fill(PAL.voidBlack, 165);
  drawShapePoly([
    [84, 20],
    [340, 20],
    [170, 150],
    [84, 340]
  ]);
  drawShapePoly([
    [840, 20],
    [1184, 20],
    [1184, 390],
    [1040, 170]
  ]);
  drawShapePoly([
    [1184, 920],
    [1184, 1180],
    [920, 1180],
    [1090, 1070]
  ]);
  drawShapePoly([
    [84, 1010],
    [240, 1180],
    [84, 1180]
  ]);
  brush.noFill();

  // Charcoal dry-media vignette sweeps along top, bottom & right frame edges
  for (let i = 0; i < 75; i++) {
    let isTop = i < 30;
    let x1 = random(84, 1184);
    let y1 = isTop ? random(20, 95) : random(1110, 1180);
    brush.set(
      "soft_charcoal",
      random() < 0.5 ? PAL.voidBlack : PAL.abyssCyan,
      random(0.8, 1.6)
    );
    brush.line(x1, y1, x1 + random(-140, 140), y1 + random(-25, 25));
  }

  // --- B. Fine Vertical Celluloid Projection Scratches ---
  // Continuous & broken vertical scratches (both dark emulsion & bleached base lines)
  const numScratches = 42;
  for (let i = 0; i < numScratches; i++) {
    let sx = random(96, 1172);
    let isLight = random() < 0.42;
    let col = isLight
      ? random() < 0.5
        ? PAL.bleachedPeak
        : PAL.bleachedMid
      : random() < 0.6
        ? PAL.voidBlack
        : PAL.darkPrussian;

    let wt = random(0.35, 0.85);
    brush.set("film_scratch", col, wt);

    // Each scratch consists of 1 to 4 vertical segments with slight lateral drift
    let curY = random(20, 240);
    while (curY < 1160) {
      let segLen = random(140, 520);
      let nextY = Math.min(1180, curY + segLen);
      let drift = random(-2.2, 2.2);
      brush. spline(
        [
          [sx, curY],
          [sx + drift * 0.5, (curY + nextY) * 0.5],
          [sx + drift, nextY]
        ],
        0.2
      );
      sx += drift;
      curY = nextY + random(18, 140);
    }
  }

  // --- C. Dust Specks, Nitrate Mottling & Projector Gate Hairs ---
  // Spray stipple across gate
  for (let i = 0; i < 35; i++) {
    let dx = random(100, 1165);
    let dy = random(35, 1165);
    brush.set(
      "spray",
      random() < 0.55 ? PAL.voidBlack : PAL.bleachedHigh,
      random(0.4, 0.9)
    );
    brush.line(dx, dy, dx + random(-18, 18), dy + random(-18, 18));
  }

  // Tiny individual dust specks, pinholes & lint fibers
  for (let i = 0; i < 110; i++) {
    let px = random(92, 1175);
    let py = random(28, 1172);
    let isPinhole = random() < 0.32;
    brush.set(
      "micro_etch",
      isPinhole ? PAL.bleachedPeak : PAL.voidBlack,
      random(0.5, 1.2)
    );
    if (random() < 0.78) {
      // Tiny speck
      brush.line(px, py, px + random(-2.5, 2.5), py + random(-2.5, 2.5));
    } else {
      // Tiny curved lint fiber
      brush.spline(
        [
          [px, py],
          [px + random(-7, 7), py + random(-7, 7)],
          [px + random(-12, 12), py + random(-12, 12)]
        ],
        0.6
      );
    }
  }
}

// =============================================================================
// 10. SILENT FILM FRAME LINE & SLIVER OF THE SPROCKET EDGE (LEFT SIDE)
// =============================================================================
function renderSprocketFrameBorder() {
  // Solid black celluloid film strip along the left edge (x = 0..84)
  // plus thin black frame lines at top (y = 0..20), bottom (y = 1180..1200), right (x = 1184..1200)
  brush.noStroke();
  brush.wash(PAL.voidBlack, 252);
  brush.rect(0, 0, 86, 1200, "corner");
  brush.rect(84, 0, 1116, 22, "corner");
  brush.rect(84, 1178, 1116, 22, "corner");
  brush.rect(1182, 0, 18, 1200, "corner");
  brush.noWash();

  // Textured charcoal & vertical transport wear along the black celluloid border
  for (let i = 0; i < 45; i++) {
    let bx = random(4, 82);
    let col =
      random() < 0.65
        ? PAL.filmBlack
        : random() < 0.85
          ? PAL.darkPrussian
          : PAL.greaseEarth;
    brush.set("fine_graphite", col, random(0.5, 1.1));
    brush.line(bx, 0, bx + random(-1.5, 1.5), 1200);
  }

  // Crisp yet slightly halated optical-gate Frame Line boundary
  brush.set("charcoal", PAL.voidBlack, 1.8);
  brush.line(85, 18, 85, 1182);
  brush.line(84, 20, 1184, 20);
  brush.line(84, 1180, 1184, 1180);
  brush.line(1184, 20, 1184, 1180);

  // Subtle silver halide edge fogging just inside the left frame line (x = 86..91)
  brush.set("soft_charcoal", PAL.voidBlack, 0.9);
  brush.line(87, 22, 87, 1178);

  // Thin dark separation line between sprocket track and sound/frame rebate at x = 68
  brush.set("micro_etch", PAL.prussianMid, 0.6);
  brush.line(68, 0, 68, 1200);

  // 4 Kodak-standard 35mm Silent Film Sprocket Perforations cropped along the left edge (x = 0..42)
  // Plus partial perforations at the very top and bottom
  const perfCentersY = [-45, 195, 435, 675, 915, 1155];
  const perfHalfH = 48;
  const perfRightX = 42;

  for (let cyPerf of perfCentersY) {
    let yTop = cyPerf - perfHalfH;
    let yBot = cyPerf + perfHalfH;
    let rCorner = 12;

    // Rounded-right-edge polygon for the sliver of sprocket perforation
    let perfPts = [
      [0, yTop],
      [perfRightX - rCorner, yTop],
      [perfRightX - 3, yTop + 3],
      [perfRightX, yTop + rCorner],
      [perfRightX, yBot - rCorner],
      [perfRightX - 3, yBot - 3],
      [perfRightX - rCorner, yBot],
      [0, yBot]
    ];

    // Bleached light-table / projector glow inside perforation
    brush.noStroke();
    brush.wash(PAL.bleachedHigh, 248);
    drawShapePoly(perfPts, 0.15, true);
    brush.noWash();

    // Slight warm parchment vignette inside perforation edge
    for (let k = 1; k <= 4; k++) {
      brush.set(
        "fine_graphite",
        k < 3 ? PAL.parchmentGrey : PAL.bleachedPeak,
        0.75
      );
      brush.line(
        perfRightX - k * 2,
        yTop + rCorner,
        perfRightX - k * 2,
        yBot - rCorner
      );
    }

    // Dark inner celluloid thickness bevel & mechanical sprocket-tooth wear at corners
    brush.set("charcoal", PAL.voidBlack, 1.25);
    drawShapePoly(perfPts, 0.15, false);

    // Subtle halation / light bleed around the sprocket hole onto the black celluloid
    brush.set("fine_graphite", PAL.prussianMist, 0.65);
    brush.line(perfRightX + 3, yTop + 8, perfRightX + 3, yBot - 8);
    brush.set("micro_etch", PAL.bleachedLow, 0.55);
    brush.line(0, yTop - 2, perfRightX - 8, yTop - 2);
    brush.line(0, yBot + 2, perfRightX - 8, yBot + 2);
  }
}

// =============================================================================
// MECHANICAL DETAIL HELPERS (RIVETS, HEX BOLTS, OIL CUPS)
// =============================================================================
function drawRivet(x, y, r, isLit = true) {
  // 1. Vertical oil/soot weep streak beneath rivet
  brush.set("fine_graphite", PAL.abyssCyan, 0.65);
  brush.line(x, y + r, x + random(-1.5, 1.5), y + r * random(2.2, 4.2));

  // 2. Dark cast shadow crescent under bottom-right
  brush.set("charcoal", PAL.voidBlack, 1.0);
  brush.arc(x + 1, y + 1.5, r * 1.05, 10, 175);

  // 3. Rivet dome body
  brush.noStroke();
  brush.wash(isLit ? PAL.prussianMid : PAL.darkPrussian, 235);
  brush.circle(x, y, r, 0.02);
  brush.noWash();

  // 4. Specular highlight crescent on upper-left dome
  brush.set(
    "micro_etch",
    isLit ? PAL.bleachedPeak : PAL.prussianLight,
    0.85
  );
  brush.arc(x, y, r * 0.72, 195, 320);
}

function drawHexBolt(x, y, r, hasCotter = false) {
  // Washer shadow & ring
  brush.noStroke();
  brush.wash(PAL.voidBlack, 220);
  brush.circle(x + 2, y + 2.5, r * 1.25, 0.02);
  brush.wash(PAL.oiledBronze, 235);
  brush.circle(x, y, r * 1.15, 0.02);

  // Hexagonal nut body
  let hexPts = [];
  for (let a = 0; a < 360; a += 60) {
    hexPts.push([x + r * dCos(a + 15), y + r * dSin(a + 15)]);
  }
  brush.wash(PAL.prussianSlate, 245);
  drawShapePoly(hexPts, 0, true);
  brush.noWash();

  // Lit top flats & dark bottom flats of hex nut
  brush.set("fine_graphite", PAL.bleachedPeak, 0.9);
  brush.line(hexPts[3][0], hexPts[3][1], hexPts[4][0], hexPts[4][1]);
  brush.line(hexPts[4][0], hexPts[4][1], hexPts[5][0], hexPts[5][1]);

  brush.set("charcoal", PAL.voidBlack, 1.0);
  brush.line(hexPts[0][0], hexPts[0][1], hexPts[1][0], hexPts[1][1]);
  brush.line(hexPts[1][0], hexPts[1][1], hexPts[2][0], hexPts[2][1]);

  // Central threaded bolt stud
  brush.noStroke();
  brush.wash(PAL.darkUmber, 245);
  brush.circle(x, y, r * 0.52, 0.01);
  brush.noWash();
  brush.set("micro_etch", PAL.bleachedHigh, 0.8);
  brush.arc(x, y, r * 0.52, 195, 325);

  // Split cotter pin passing through bolt crown
  if (hasCotter) {
    brush.set("fine_graphite", PAL.bleachedPeak, 0.9);
    brush.line(x - r * 0.95, y - r * 0.35, x + r * 0.95, y + r * 0.35);
    brush.set("micro_etch", PAL.voidBlack, 0.7);
    brush.line(x - r * 0.95, y - r * 0.35 + 1.5, x + r * 0.95, y + r * 0.35 + 1.5);
  }
}

function drawOilCup(x, yBase, w, h) {
  let left = x - w * 0.5;
  // Brass cup body
  brush.noStroke();
  brush.wash(PAL.brassOchre, 240);
  brush.rect(left, yBase - h, w, h, "corner");
  brush.noWash();

  // Vertical metallic sheen on oil cup
  for (let dx = -w * 0.45; dx <= w * 0.45; dx += 2.2) {
    let col =
      dx < -w * 0.15
        ? PAL.bleachedHigh
        : dx < w * 0.15
          ? PAL.brassOchre
          : PAL.darkUmber;
    brush.set("fine_graphite", col, 0.8);
    brush.line(x + dx, yBase - h, x + dx, yBase);
  }

  // Knurled cap & filler plug
  brush.set("charcoal", PAL.voidBlack, 1.1);
  brush.rect(left - 2, yBase - h - 5, w + 4, 5, "corner");
  brush.rect(left, yBase - h, w, h, "corner");
  brush.set("fine_graphite", PAL.bleachedPeak, 0.9);
  brush.line(left - 2, yBase - h - 5, left + w + 2, yBase - h - 5);
  brush.line(x - 4, yBase - h - 10, x + 4, yBase - h - 10);
}

function drawAngledOilCup(bx, by, tx, ty, ux, uy, halfW) {
  let p1 = [bx - halfW * ux, by - halfW * uy];
  let p2 = [bx + halfW * ux, by + halfW * uy];
  let p3 = [tx + halfW * ux, ty + halfW * uy];
  let p4 = [tx - halfW * ux, ty - halfW * uy];

  brush.noStroke();
  brush.wash(PAL.brassOchre, 245);
  drawShapePoly([p1, p2, p3, p4], 0, true);
  brush.noWash();

  // Cylindrical brass shading lines
  for (let f = -0.85; f <= 0.85; f += 0.25) {
    let sx = bx + f * halfW * ux;
    let sy = by + f * halfW * uy;
    let ex = tx + f * halfW * ux;
    let ey = ty + f * halfW * uy;
    let col =
      f > 0.35
        ? PAL.bleachedPeak
        : f > -0.2
          ? PAL.brassOchre
          : PAL.darkUmber;
    brush.set("fine_graphite", col, 0.85);
    brush.line(sx, sy, ex, ey);
  }

  brush.set("charcoal", PAL.voidBlack, 1.15);
  drawShapePoly([p1, p2, p3, p4], 0, true);
  brush.set("fine_graphite", PAL.bleachedPeak, 1.0);
  brush.line(p4[0], p4[1], p3[0], p3[1]);
}

