// =============================================================================
// GEOMETRY & DRAWING HELPERS
// =============================================================================

function polyWash(pts, col, opacity = 255) {
  if (!pts || pts.length < 3) return;
  let p = new brush.Polygon(pts);
  p.wash(col, opacity);
}

function polyDraw(pts, brushName, col, weight = 1) {
  if (!pts || pts.length < 3) return;
  brush.set(brushName, col, weight);
  let p = new brush.Polygon(pts);
  p.draw(brushName, col, weight);
}

function polyHatch(pts, brushName, col, weight, dist, angle, opts = {}) {
  if (!pts || pts.length < 3) return;
  brush.hatchStyle(brushName, col, weight);
  let p = new brush.Polygon(pts);
  p.hatch(dist, angle, opts);
  brush.noHatch();
}

function mirrorPt(x, y, side) {
  return [600 + side * (x - 600), y];
}

function evalBezier4(p0, p1, p2, p3, p4, t) {
  let u = 1 - t;
  let b0 = u * u * u * u;
  let b1 = 4 * u * u * u * t;
  let b2 = 6 * u * u * t * t;
  let b3 = 4 * u * t * t * t;
  let b4 = t * t * t * t;
  return [
    b0 * p0[0] + b1 * p1[0] + b2 * p2[0] + b3 * p3[0] + b4 * p4[0],
    b0 * p0[1] + b1 * p1[1] + b2 * p2[1] + b3 * p3[1] + b4 * p4[1]
  ];
}

function evalBezier3(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let b0 = u * u * u;
  let b1 = 3 * u * u * t;
  let b2 = 3 * u * t * t;
  let b3 = t * t * t;
  return [
    b0 * p0[0] + b1 * p1[0] + b2 * p2[0] + b3 * p3[0],
    b0 * p0[1] + b1 * p1[1] + b2 * p2[1] + b3 * p3[1]
  ];
}

