  for (let y = 36; y <= 1164; y += 18) {
    brush.line(36, y, 1164, y);
  }

  // Outer woodblock key-line frame
  let m1 = 28;
  let m2 = 42;
  let m3 = 52;

  // Gold & peach inner rules
  brush.set("denseMarker", PAL.peach, 0.9);
  brush.noFill();
  brush.noWash();
  brush.rect(m2, m2, 1200 - m2 * 2, 1200 - m2 * 2, "corner");

  brush.set("keyLine", PAL.lacquer, 1.3);
  brush.rect(m1, m1, 1200 - m1 * 2, 1200 - m1 * 2, "corner");
  brush.set("keyLine", PAL.lacquer, 0.85);
  brush.rect(m3, m3, 1200 - m3 * 2, 1200 - m3 * 2, "corner");

  // Symmetrical Nianhua corner fretwork (Huiwen) & emerald-gold corner studs
  const corners = [
    [-1, -1],
    [1, -1],
    [-1, 1],
    [1, 1]
  ];
  for (let [sx, sy] of corners) {
    let cx = 600 + sx * (600 - m3);
    let cy = 600 + sy * (600 - m3);
    let ix = -sx;
    let iy = -sy;

    // Corner square plaque
    let plaque = [
      [cx, cy],
      [cx + ix * 56, cy],
      [cx + ix * 56, cy + iy * 56],
      [cx, cy + iy * 56]
    ];
    polyWash(plaque, PAL.lacquer, 250);

    let innerPlaque = [
      [cx + ix * 8, cy + iy * 8],
      [cx + ix * 48, cy + iy * 8],
      [cx + ix * 48, cy + iy * 48],
      [cx + ix * 8, cy + iy * 48]
    ];
    polyWash(innerPlaque, PAL.emerald, 245);
    polyDraw(innerPlaque, "finePen", PAL.lemon, 0.8);

    // Corner auspicious diamond
    let dia = [
      [cx + ix * 28, cy + iy * 13],
      [cx + ix * 43, cy + iy * 28],
      [cx + ix * 28, cy + iy * 43],
      [cx + ix * 13, cy + iy * 28]
    ];
    polyWash(dia, PAL.lemon, 250);
    polyDraw(dia, "finePen", PAL.lacquer, 0.85);

    // Fretwork extensions along frame
    brush.set("keyLine", PAL.lacquer, 0.9);
    for (let k = 1; k <= 3; k++) {
      let d = 56 + k * 18;
      brush.line(cx + ix * d, cy, cx + ix * d, cy + iy * 14);
      brush.line(cx, cy + iy * d, cx + ix * 14, cy + iy * d);
    }
    brush.set("finePen", PAL.lemon, 0.7);
    brush.circle(cx + ix * 28, cy + iy * 28, 4.5, 0.05);
  }
}

