function drawBackgroundWaterWaves() {
  // Subtle circular auspicious ring in peach/vermilion/gold behind the koi and bowl
  brush.set("finePen", PAL.peach, 0.65);
  brush.arc(600, 520, 445, 195, 345);
  brush.arc(600, 520, 453, 193, 347);
