  brush.arc(600, 520, 449, 198, 342);

  // Mirrored curling water ribbons (Langhua) around the koi tails and bowl sides
  for (let side of [-1, 1]) {
    drawCurlWave(side, 945, 715, 115, 210, 1.0);
    drawCurlWave(side, 1020, 620, 90, 185, 0.85);
    drawCurlWave(side, 880, 465, 85, 155, 0.78);
    drawCurlWave(side, 745, 355, 75, 165, 0.72);
  }
}

function drawCurlWave(side, baseX, baseY, len, startAng, sc) {
  let pts = [];
  let innerPts = [];
  let steps = 22;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let ang = startAng + t * 145;
    let r = len * (1 - t * 0.55);
    let x = baseX + cos(ang) * r * 0.85;
    let y = baseY + sin(ang) * r * 0.65;
    pts.push(mirrorPt(x, y, side));
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let ang = startAng + t * 145;
    let r = len * (1 - t * 0.55) - (1 - t) * 18 * sc - 3;
    let x = baseX + cos(ang) * r * 0.85;
    let y = baseY + sin(ang) * r * 0.65 + (1 - t) * 8;
    innerPts.push(mirrorPt(x, y, side));
  }
  let poly = pts.concat(innerPts);
  polyWash(poly, PAL.peachLight, 235);

  // Striation lines inside wave ribbon
  brush.set("finePen", PAL.peachDeep, 0.55);
  let midCurve = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let ang = startAng + t * 145;
    let r = len * (1 - t * 0.55) - (1 - t) * 9 * sc - 1.5;
    let x = baseX + cos(ang) * r * 0.85;
    let y = baseY + sin(ang) * r * 0.65 + (1 - t) * 4;
    let mp = mirrorPt(x, y, side);
    midCurve.push([mp[0], mp[1], 0.8]);
  }
  brush.spline(midCurve, 0.5);

  // Crisp woodblock black outline + white crest tip
  polyDraw(poly, "keyLine", PAL.lacquer, 0.75);
  let tip = pts[pts.length - 1];
  let tipPoly = [];
  for (let a = 0; a < 360; a += 30) {
    tipPoly.push([tip[0] + cos(a) * 8 * sc, tip[1] + sin(a) * 8 * sc]);
  }
  polyWash(tipPoly, PAL.porcelain, 250);
  polyDraw(tipPoly, "keyLine", PAL.lacquer, 0.75);
}

// =============================================================================
// 3 & 8. HYPERREAL EMERALD MANDARIN LEAVES
// =============================================================================

function drawSingleLeaf(cx, cy, angleDeg, len, wid, flipCurvature = 1, brightSide = 1) {
  let steps = 24;
  let upperEdge = [];
  let lowerEdge = [];
  let spinePts = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    // Natural pointed citrus leaf profile with slightly winged petiole base
    let profile = sin(pow(t, 0.78) * 180) * (1 - 0.18 * t);
    let bend = sin(t * 180) * 14 * flipCurvature;
    let lx = t * len;
    let ly = bend;

    let halfW = (wid / 2) * profile;

    // Rotate around (cx, cy)
    let ca = cos(angleDeg);
    let sa = sin(angleDeg);

    let sx = cx + lx * ca - ly * sa;
    let sy = cy + lx * sa + ly * ca;
    spinePts.push([sx, sy]);

    let ux = cx + lx * ca - (ly - halfW) * sa;
    let uy = cy + lx * sa + (ly - halfW) * ca;
    upperEdge.push([ux, uy]);

    let bx = cx + lx * ca - (ly + halfW) * sa;
    let by = cy + lx * sa + (ly + halfW) * ca;
    lowerEdge.push([bx, by]);
  }

  let fullPoly = upperEdge.concat(lowerEdge.slice().reverse());
  let topHalfPoly = upperEdge.concat(spinePts.slice().reverse());
  let botHalfPoly = spinePts.concat(lowerEdge.slice().reverse());

  // Dense opaque emerald fills (two-tone across midrib for 3D leaf camber)
  polyWash(fullPoly, PAL.emeraldDark, 255);
  polyWash(
    brightSide > 0 ? topHalfPoly : botHalfPoly,
    PAL.emerald,
    250
  );

  // Subtle gradation hatching & glossy highlight patch on the convex half
  let litPoly = brightSide > 0 ? topHalfPoly : botHalfPoly;
  let shadePoly = brightSide > 0 ? botHalfPoly : topHalfPoly;
  polyHatch(litPoly, "cpencil", PAL.emeraldBright, 0.85, 3.2, angleDeg + 35, { rand: 0.04 });
  polyHatch(shadePoly, "cpencil", PAL.emeraldDark, 0.85, 3.5, angleDeg - 35, { rand: 0.04 });

  // Specular waxy sheen strip along mid-blade
  let sheenPts = [];
  for (let i = 5; i <= 16; i++) {
    let p1 = spinePts[i];
    let p2 = brightSide > 0 ? upperEdge[i] : lowerEdge[i];
    sheenPts.push([
      lerp(p1[0], p2[0], 0.35),
      lerp(p1[1], p2[1], 0.35)
    ]);
  }
  for (let i = 16; i >= 5; i--) {
    let p1 = spinePts[i];
    let p2 = brightSide > 0 ? upperEdge[i] : lowerEdge[i];
    sheenPts.push([
      lerp(p1[0], p2[0], 0.65),
      lerp(p1[1], p2[1], 0.65)
    ]);
  }
  polyWash(sheenPts, PAL.emeraldLight, 185);

  // Lateral veins (secondary venation curving toward leaf tip)
  for (let i = 3; i <= steps - 3; i += 2) {
    let t = i / steps;
    let iTip = min(steps - 1, i + 3);
    let sp = spinePts[i];
    let up = upperEdge[iTip];
    let lo = lowerEdge[iTip];

    let midU = [
      lerp(sp[0], up[0], 0.55),
      lerp(sp[1], up[1], 0.55)
    ];
    let endU = [
      lerp(sp[0], up[0], 0.88),
      lerp(sp[1], up[1], 0.88)
    ];
    let midL = [
      lerp(sp[0], lo[0], 0.55),
      lerp(sp[1], lo[1], 0.55)
    ];
    let endL = [
      lerp(sp[0], lo[0], 0.88),
      lerp(sp[1], lo[1], 0.88)
    ];

    brush.set("finePen", PAL.emeraldLight, 0.55);
    brush.spline([
      [sp[0], sp[1], 0.9],
      [midU[0], midU[1], 0.7],
      [endU[0], endU[1], 0.3]
    ], 0.4);
    brush.spline([
      [sp[0], sp[1], 0.9],
      [midL[0], midL[1], 0.7],
      [endL[0], endL[1], 0.3]
    ], 0.4);

    brush.set("finePen", PAL.lacquer, 0.45);
    brush.spline([
      [sp[0], sp[1], 0.8],
      [midU[0], midU[1], 0.6],
      [endU[0], endU[1], 0.2]
    ], 0.4);
  }

  // Central midrib in lemon-emerald + lacquer key line
  let spineSpline = spinePts.map((p, idx) => [p[0], p[1], 1.1 - 0.6 * (idx / steps)]);
  brush.set("finePen", PAL.lemon, 0.9);
  brush.spline(spineSpline, 0.4);
  brush.set("finePen", PAL.lacquer, 0.55);
  brush.spline(spineSpline, 0.4);

  // Firm black woodblock contour around leaf
  polyDraw(fullPoly, "keyLine", PAL.lacquer, 0.95);
}

