// =============================================================================
// 4. TWO FAT ARCHING KOI (HYPERREAL SCALES, FINS, BARBELS, NIANHUA KEY LINES)
// =============================================================================

function getKoiSpineFrame(t, side) {
  // Degree-4 Bezier spine for the right koi (mirrored for left koi via side = -1)
  const P0 = [656, 286]; // Snout tip facing inward toward center
  const P1 = [755, 110]; // High dorsal arch
  const P2 = [1085, 195]; // Wide outer muscular sweep
  const P3 = [1065, 495]; // Lower body curve
  const P4 = [940, 622]; // Caudal peduncle (tail base)

  let ptR = evalBezier4(P0, P1, P2, P3, P4, t);
  let dt = 0.004;
  let t0 = max(0, t - dt);
  let t1 = min(1, t + dt);
  let pA = evalBezier4(P0, P1, P2, P3, P4, t0);
  let pB = evalBezier4(P0, P1, P2, P3, P4, t1);

  let pt = mirrorPt(ptR[0], ptR[1], side);
  let mA = mirrorPt(pA[0], pA[1], side);
  let mB = mirrorPt(pB[0], pB[1], side);

  let dx = mB[0] - mA[0];
  let dy = mB[1] - mA[1];
  let len = sqrt(dx * dx + dy * dy) || 1;
  let tx = dx / len;
  let ty = dy / len;

  // Normal pointing toward the OUTER (dorsal) arch of the koi
  // For right koi (side = 1), tangent goes up-right then down, so outer dorsal normal is (ty * side, -tx * side)
  let nxOuter = ty * side;
  let nyOuter = -tx * side;

  // Plump, fat koi radius profile along spine parameter t
  let girth;
  if (t < 0.14) {
    // Snout to gill cover
    let u = t / 0.14;
    girth = 18 + 56 * pow(sin(u * 90), 0.78);
  } else if (t < 0.42) {
    // Gill cover to fattest belly
    let u = (t - 0.14) / 0.28;
    girth = 74 + 13 * sin(u * 180);
  } else {
    // Mid-body tapering to muscular tail peduncle
    let u = (t - 0.42) / 0.58;
    girth = 74 * pow(1 - u, 0.85) + 24 * pow(u, 0.85) + 7 * sin(u * 180);
  }

  // Belly (inner curve) is slightly fuller than dorsal (outer curve)
  let rDorsal = girth * 0.94;
  let rVentral = girth * 1.12;

  return {
    x: pt[0],
    y: pt[1],
    tx,
    ty,
    nx: nxOuter,
    ny: nyOuter,
    rDorsal,
    rVentral,
    girth
  };
}

function getKoiSurfacePoint(t, v, side) {
  // v in [-1, 1]: v = +1 is outer dorsal ridge, v = -1 is inner ventral belly
  let f = getKoiSpineFrame(t, side);
  let r = v >= 0 ? f.rDorsal * v : f.rVentral * v;
  return [f.x + f.nx * r, f.y + f.ny * r];
}

function drawRayedFin(basePts, outerPts, side, finStyle = "pectoral") {
  let fullPoly = basePts.concat(outerPts.slice().reverse());

  // Translucent-looking opaque Nianhua fin wash: peach pink base with vermilion & lemon glow
  polyWash(fullPoly, PAL.peachLight, 245);

  // Inner warm vermilion-peach blush near fin root
  let rootBlush = [];
  let n = min(basePts.length, outerPts.length);
  for (let i = 0; i < n; i++) {
    rootBlush.push(basePts[i]);
  }
  for (let i = n - 1; i >= 0; i--) {
    rootBlush.push([
      lerp(basePts[i][0], outerPts[i][0], 0.48),
      lerp(basePts[i][1], outerPts[i][1], 0.48)
    ]);
  }
  polyWash(rootBlush, PAL.peach, 225);

  let deepRoot = [];
  for (let i = 0; i < n; i++) deepRoot.push(basePts[i]);
  for (let i = n - 1; i >= 0; i--) {
    deepRoot.push([
      lerp(basePts[i][0], outerPts[i][0], 0.24),
      lerp(basePts[i][1], outerPts[i][1], 0.24)
    ]);
  }
  polyWash(deepRoot, PAL.vermilion, 210);

  // Fin rays (cartilage bones radiating from base to scalloped margin)
  let rayCount = outerPts.length;
  for (let i = 0; i < rayCount; i++) {
    let bIdx = floor(map(i, 0, rayCount - 1, 0, basePts.length - 1));
    let b = basePts[bIdx];
    let o = outerPts[i];
    let mid = [
      lerp(b[0], o[0], 0.55) + sin(i * 35) * 3 * side,
      lerp(b[1], o[1], 0.55) + cos(i * 35) * 3
    ];

    // Lemon-gold highlight ray + fine lacquer ink ray line
    if (i % 2 === 0) {
      brush.set("finePen", PAL.lemon, 0.75);
      brush.spline([[b[0], b[1], 0.9], [mid[0], mid[1], 0.7], [o[0], o[1], 0.4]], 0.4);
    }
    brush.set("finePen", PAL.peachDeep, 0.55);
    brush.spline([[b[0], b[1], 0.8], [mid[0], mid[1], 0.6], [o[0], o[1], 0.3]], 0.4);

    if (i % 3 === 0 || i === 0 || i === rayCount - 1) {
      brush.set("finePen", PAL.lacquer, 0.55);
      brush.spline([[b[0], b[1], 0.95], [mid[0], mid[1], 0.7], [o[0], o[1], 0.4]], 0.4);
    }
  }

  // Leading spine reinforcement
  if (basePts.length > 0 && outerPts.length > 0) {
    let b0 = basePts[0];
    let o0 = outerPts[0];
    brush.set("keyLine", PAL.lemon, 1.4);
    brush.line(b0[0], b0[1], o0[0], o0[1]);
    brush.set("keyLine", PAL.lacquer, 1.1);
    brush.line(b0[0], b0[1], o0[0], o0[1]);
  }

  // Firm woodblock contour around fin
  polyDraw(fullPoly, "keyLine", PAL.lacquer, 0.9);
}

function drawSymmetricalKoi(side) {
  // ---- A. UNDER-BODY FINS (Ventral, Anal, Pectoral, Dorsal, Caudal Tail) ----

  // 1. Huge Flowing Bifurcated Caudal Fin (Tail)
  let tailBase = [];
  let tailOuter = [];
  let fTail = getKoiSpineFrame(0.97, side);
  for (let i = 0; i <= 28; i++) {
    let u = i / 28; // 0 = dorsal lobe tip, 0.5 = central fork notch, 1 = ventral lobe tip
    let vBase = lerp(0.85, -0.85, u);
    tailBase.push(getKoiSurfacePoint(0.96, vBase, side));

    // Twin sweeping lobes with central V-notch and delicate scallops
    let lobeEnv = 1 - 0.52 * exp(-pow((u - 0.48) / 0.16, 2));
    let scallop = 1 + 0.045 * sin(u * 28 * 180);
    let rayLen = (155 * lobeEnv * scallop);

    let spreadAngle = lerp(-52, 62, u) * side;
    let dirX = -fTail.tx * cos(spreadAngle) - fTail.ty * sin(spreadAngle);
    let dirY = -fTail.ty * cos(spreadAngle) + fTail.tx * sin(spreadAngle);

    let bp = tailBase[i];
    // Add graceful upward curl at lobe tips
    let curlY = -18 * pow(abs(u - 0.5) * 2, 2);
    tailOuter.push([
      bp[0] + dirX * rayLen,
      bp[1] + dirY * rayLen + curlY
    ]);
  }
  drawRayedFin(tailBase, tailOuter, side, "caudal");

  // 2. Outer Pectoral Fin (sweeping outward from behind gill cover)
  let pecOuterBase = [];
  let pecOuterMargin = [];
  for (let i = 0; i <= 14; i++) {
    let u = i / 14;
    let t = lerp(0.16, 0.30, u);
    let bp = getKoiSurfacePoint(t, lerp(0.55, 0.78, u), side);
    let f = getKoiSpineFrame(t, side);
    pecOuterBase.push(bp);

    let profile = sin(pow(u, 0.65) * 170) * (1 + 0.05 * sin(u * 14 * 180));
    let len = 98 * profile + 18;
    let ang = lerp(-18, 45, u) * side;
    let dx = f.nx * cos(ang) - f.ny * sin(ang);
    let dy = f.ny * cos(ang) + f.nx * cos(ang);
    pecOuterMargin.push([
      bp[0] + (f.nx * 0.85 - f.tx * 0.45 * u) * len,
      bp[1] + (f.ny * 0.85 - f.ty * 0.45 * u) * len
    ]);
  }
  drawRayedFin(pecOuterBase, pecOuterMargin, side, "pectoral");

  // 3. Inner Ventral Pectoral Fin (fanning inward toward center)
  let pecInnerBase = [];
  let pecInnerMargin = [];
  for (let i = 0; i <= 16; i++) {
    let u = i / 16;
    let t = lerp(0.17, 0.33, u);
    let bp = getKoiSurfacePoint(t, lerp(-0.55, -0.88, u), side);
    let f = getKoiSpineFrame(t, side);
    pecInnerBase.push(bp);

    let profile = sin(pow(u, 0.7) * 172) * (1 + 0.05 * sin(u * 16 * 180));
    let len = 112 * profile + 16;
    pecInnerMargin.push([
      bp[0] + (-f.nx * 0.92 - f.tx * 0.38 * u) * len,
      bp[1] + (-f.ny * 0.92 - f.ty * 0.38 * u) * len
    ]);
  }
  drawRayedFin(pecInnerBase, pecInnerMargin, side, "pectoral");

  // 4. Ventral Pelvic & Anal Fins along inner belly arch
  let pelvBase = [];
  let pelvMargin = [];
  for (let i = 0; i <= 12; i++) {
    let u = i / 12;
    let t = lerp(0.48, 0.64, u);
    let bp = getKoiSurfacePoint(t, -0.86, side);
    let f = getKoiSpineFrame(t, side);
    pelvBase.push(bp);
    let len = 68 * sin(pow(u, 0.75) * 170) + 10;
    pelvMargin.push([
      bp[0] + (-f.nx * 0.82 - f.tx * 0.52) * len,
      bp[1] + (-f.ny * 0.82 - f.ty * 0.52) * len
    ]);
  }
  drawRayedFin(pelvBase, pelvMargin, side, "pelvic");

  // ---- B. PLUMP KOI BODY SILHOUETTE BASE ----
  let bodyDorsal = [];
  let bodyVentral = [];
  let bodySteps = 44;
  for (let i = 0; i <= bodySteps; i++) {
    let t = i / bodySteps;
    bodyDorsal.push(getKoiSurfacePoint(t, 1.0, side));
    bodyVentral.push(getKoiSurfacePoint(t, -1.0, side));
  }
  let bodyPoly = bodyDorsal.concat(bodyVentral.slice().reverse());
  polyWash(bodyPoly, PAL.vermilion, 255);

  // ---- C. HYPERREAL IMBRICATED SCALES (Drawn tail-to-head so each overlaps the next!) ----
  // Rows from t = 0.96 (tail peduncle) down to t = 0.165 (posterior edge of gill plate)
  const numRows = 28;
  const colsPerRow = 11;

  for (let rIdx = numRows; rIdx >= 0; rIdx--) {
    let uRow = rIdx / numRows;
    let tCenter = lerp(0.165, 0.96, uRow);
    let dtScale = 0.044 * (0.82 + 0.35 * sin(uRow * 180));

    // Draw outer lateral scales first, then central spine scales last so crown scales sit on top
    let colOrder = [];
    for (let c = 0; c < colsPerRow; c++) colOrder.push(c);
    colOrder.sort((a, b) => abs(b - (colsPerRow - 1) / 2) - abs(a - (colsPerRow - 1) / 2));

    for (let c of colOrder) {
      let stagger = (rIdx % 2 === 0 ? 0 : 0.5);
      let normC = (c + stagger) / colsPerRow; // 0..1 across girth
      if (normC < 0.02 || normC > 0.98) continue;

      // Cylindrical projection: map normC through sin(theta) so edge scales foreshorten naturally!
      let theta = lerp(-82, 82, normC);
      let vCenter = sin(theta);
      let vHalfSpan = cos(theta) * (1.85 / colsPerRow);

      // Scale polygon in (t, v) space: rounded posterior cycloid margin pointing toward tail (t + dtScale)
      let scalePts = [];
      let arcSteps = 10;
      // Anterior root tucked under previous row
      scalePts.push(getKoiSurfacePoint(max(0.14, tCenter - dtScale * 0.45), vCenter - vHalfSpan * 0.85, side));
      for (let k = 0; k <= arcSteps; k++) {
        let ang = lerp(-90, 90, k / arcSteps);
        let tPt = tCenter + cos(ang) * dtScale * 0.95;
        let vPt = vCenter + sin(ang) * vHalfSpan * 1.08;
        scalePts.push(getKoiSurfacePoint(min(0.985, tPt), constrain(vPt, -0.99, 0.99), side));
      }
      scalePts.push(getKoiSurfacePoint(max(0.14, tCenter - dtScale * 0.45), vCenter + vHalfSpan * 0.85, side));

      // Determine scale coloration: auspicious Nianhua red-gold-peach-black calico & 3D cylindrical lighting
      // Light comes from top-center, so dorsal/upper flank is glowing lemon-gold & vermilion, belly is peach/shadow
      let isBlackSpot =
        (uRow > 0.22 && uRow < 0.34 && vCenter > -0.15 && vCenter < 0.45) ||
        (uRow > 0.56 && uRow < 0.68 && vCenter > -0.35 && vCenter < 0.25) ||
        (uRow > 0.80 && uRow < 0.88 && abs(vCenter) < 0.32);

      let isGoldPatch =
        (uRow > 0.05 && uRow < 0.20 && abs(vCenter) < 0.48) ||
        (uRow > 0.38 && uRow < 0.54 && vCenter > -0.25 && vCenter < 0.55);

      let baseCol, rimCol, innerCol;
      if (isBlackSpot) {
        baseCol = PAL.lacquer;
        innerCol = PAL.lacquerSoft;
        rimCol = PAL.gold;
      } else if (isGoldPatch || abs(vCenter) < 0.18) {
        baseCol = PAL.gold;
        innerCol = PAL.vermilionLight;
        rimCol = PAL.lemonBright;
      } else if (vCenter < -0.52) {
        // Ventral belly scales: creamy porcelain & peach pink
        baseCol = PAL.peach;
        innerCol = PAL.peachDeep;
        rimCol = PAL.porcelain;
      } else if (vCenter > 0.48) {
        // Deep dorsal vermilion
        baseCol = PAL.vermilionDark;
        innerCol = PAL.cinnabarDeep;
        rimCol = PAL.peach;
      } else {
        // Main vibrant vermilion flank
        baseCol = PAL.vermilion;
        innerCol = PAL.cinnabar;
        rimCol = PAL.lemon;
      }

      // 1. Scale solid base
      polyWash(scalePts, baseCol, 250);

      // 2. Darker anterior pocket shadow (under the overlapping scale in front)
      let antPts = [
        scalePts[0],
        getKoiSurfacePoint(tCenter + dtScale * 0.28, vCenter - vHalfSpan * 0.65, side),
        getKoiSurfacePoint(tCenter + dtScale * 0.42, vCenter, side),
        getKoiSurfacePoint(tCenter + dtScale * 0.28, vCenter + vHalfSpan * 0.65, side),
        scalePts[scalePts.length - 1]
      ];
      polyWash(antPts, innerCol, 220);

      // 3. Glowing crescent highlight along posterior exposed rim of scale
      let pTip1 = getKoiSurfacePoint(tCenter + dtScale * 0.55, vCenter - vHalfSpan * 0.65, side);
      let pTip2 = getKoiSurfacePoint(tCenter + dtScale * 0.84, vCenter, side);
      let pTip3 = getKoiSurfacePoint(tCenter + dtScale * 0.55, vCenter + vHalfSpan * 0.65, side);
      brush.set("finePen", rimCol, 0.75);
      brush.spline([
        [pTip1[0], pTip1[1], 0.5],
        [pTip2[0], pTip2[1], 1.1],
        [pTip3[0], pTip3[1], 0.5]
      ], 0.5);

      // 4. Fine woodblock key-line contour around each scale
      polyDraw(scalePts, "finePen", PAL.lacquer, 0.62);
    }
  }

  // ---- D. LONG UNDULATING DORSAL FIN ALONG THE OUTER BACK ARCH ----
  // Mounted along the ridge (v ≈ 0.35 to 0.95) from t = 0.26 to t = 0.78
  let dorsalBase = [];
  let dorsalMargin = [];
  let dSteps = 22;
  for (let i = 0; i <= dSteps; i++) {
    let u = i / dSteps;
    let t = lerp(0.27, 0.79, u);
    let bp = getKoiSurfacePoint(t, 0.38, side);
    let f = getKoiSpineFrame(t, side);
    dorsalBase.push(bp);

    let wave = sin(u * 360) * 10;
    let height = (72 * sin(pow(u, 0.65) * 168) + 22) * (1 + 0.04 * sin(u * 20 * 180));
    dorsalMargin.push([
      bp[0] + (f.nx * 0.95 - f.tx * 0.28) * height + f.tx * wave,
      bp[1] + (f.ny * 0.95 - f.ty * 0.28) * height + f.ty * wave
    ]);
  }
  drawRayedFin(dorsalBase, dorsalMargin, side, "dorsal");

  // ---- E. SCULPTED KOI HEAD, OPERCULUM (GILL PLATES), EYE, MOUTH & BARBELS ----
  drawKoiHeadAndDetails(side);

  // ---- F. BOLD WOODBLOCK KEY-LINE CONTOUR REINFORCEMENT ON BODY ----
  let dorsalSpline = bodyDorsal.map(p => [p[0], p[1], 1.1]);
  let ventralSpline = bodyVentral.map(p => [p[0], p[1], 1.1]);
  brush.set("keyLine", PAL.lacquer, 1.15);
  brush.spline(dorsalSpline, 0.45);
  brush.spline(ventralSpline, 0.45);
}

function drawKoiHeadAndDetails(side) {
  // Head shell from t = 0 (snout) to t = 0.175 (gill cover margin)
  let headPts = [];
  for (let i = 0; i <= 14; i++) {
    let t = lerp(0, 0.17, i / 14);
    headPts.push(getKoiSurfacePoint(t, 1.0, side));
  }
  // Curved operculum (gill cover posterior border)
  for (let i = 10; i >= -10; i--) {
    let v = i / 10;
    let tGill = 0.17 + 0.032 * (1 - v * v);
    headPts.push(getKoiSurfacePoint(tGill, v, side));
  }
  for (let i = 14; i >= 0; i--) {
    let t = lerp(0, 0.17, i / 14);
    headPts.push(getKoiSurfacePoint(t, -1.0, side));
  }

  polyWash(headPts, PAL.vermilion, 255);

  // Golden-peach cheek & crown bony plates on head
  let crownPts = [];
  for (let i = 0; i <= 12; i++) {
    let ang = i * 30;
    let t = 0.085 + cos(ang) * 0.055;
    let v = 0.05 + sin(ang) * 0.52;
    crownPts.push(getKoiSurfacePoint(max(0.01, t), v, side));
  }
  polyWash(crownPts, PAL.peach, 235);

  // Auspicious Kohaku / Nianhua red-and-gold forehead medallion on the koi crown
  let foreheadPts = [];
  for (let i = 0; i <= 12; i++) {
    let ang = i * 30;
    let t = 0.075 + cos(ang) * 0.038;
    let v = 0.02 + sin(ang) * 0.34;
    foreheadPts.push(getKoiSurfacePoint(max(0.015, t), v, side));
  }
  polyWash(foreheadPts, PAL.lemon, 245);
  polyDraw(foreheadPts, "finePen", PAL.vermilion, 0.7);

  // Pre-operculum & operculum gill plate ridges with gold sheen
  let gillArc1 = [];
  let gillArc2 = [];
  for (let i = -8; i <= 8; i++) {
    let v = i / 10;
    let p1 = getKoiSurfacePoint(0.135 + 0.024 * (1 - v * v), v, side);
    let p2 = getKoiSurfacePoint(0.17 + 0.032 * (1 - v * v), v, side);
    gillArc1.push([p1[0], p1[1], 0.9]);
    gillArc2.push([p2[0], p2[1], 1.1]);
  }
  brush.set("keyLine", PAL.lemon, 1.3);
  brush.spline(gillArc1, 0.45);
  brush.spline(gillArc2, 0.45);
  brush.set("keyLine", PAL.lacquer, 0.95);
  brush.spline(gillArc1, 0.45);
  brush.spline(gillArc2, 0.45);

  // Plump upper lip & snout at t = 0
  let lipPts = [];
  for (let i = -8; i <= 8; i++) {
    let v = i / 8;
    let p = getKoiSurfacePoint(0.012 * (1 - 0.5 * v * v), v * 0.95, side);
    lipPts.push(p);
  }
  for (let i = 8; i >= -8; i--) {
    let v = i / 8;
    let p = getKoiSurfacePoint(0.032, v * 0.85, side);
    lipPts.push(p);
  }
  polyWash(lipPts, PAL.peachLight, 250);
  polyDraw(lipPts, "keyLine", PAL.lacquer, 0.95);

  // Two pairs of flowing sensory barbels (whiskers) curling gracefully
  let snoutOuter = getKoiSurfacePoint(0.018, 0.68, side);
  let snoutInner = getKoiSurfacePoint(0.018, -0.68, side);
  let fSnout = getKoiSpineFrame(0.01, side);

  // Long outer barbel
  let b1 = [
    [snoutOuter[0], snoutOuter[1], 1.2],
    [snoutOuter[0] + (fSnout.tx * 28 + fSnout.nx * 36), snoutOuter[1] + (fSnout.ty * 28 + fSnout.ny * 36), 1.0],
    [snoutOuter[0] + (fSnout.tx * 68 + fSnout.nx * 22), snoutOuter[1] + (fSnout.ty * 68 + fSnout.ny * 22), 0.7],
    [snoutOuter[0] + (fSnout.tx * 92 - fSnout.nx * 14), snoutOuter[1] + (fSnout.ty * 92 - fSnout.ny * 14), 0.3]
  ];
  // Long inner barbel curling toward center pearl
  let b2 = [
    [snoutInner[0], snoutInner[1], 1.2],
    [snoutInner[0] + (fSnout.tx * 34 - fSnout.nx * 32), snoutInner[1] + (fSnout.ty * 34 - fSnout.ny * 32), 1.0],
    [snoutInner[0] + (fSnout.tx * 58 - fSnout.nx * 68), snoutInner[1] + (fSnout.ty * 58 - fSnout.ny * 68), 0.7],
    [snoutInner[0] + (fSnout.tx * 35 - fSnout.nx * 96), snoutInner[1] + (fSnout.ty * 35 - fSnout.ny * 96), 0.3]
  ];

  for (let barb of [b1, b2]) {
    brush.set("keyLine", PAL.lacquer, 1.9);
    brush.spline(barb, 0.55);
    brush.set("keyLine", PAL.lemon, 1.15);
    brush.spline(barb, 0.55);
  }

  // Hyperreal Glossy Koi Eye (positioned at t = 0.068, v = 0.42)
  let eyePos = getKoiSurfacePoint(0.068, 0.44, side);
  let ex = eyePos[0];
  let ey = eyePos[1];

  let sclera = [];
  let iris = [];
  let pupil = [];
  let spec = [];
  for (let a = 0; a < 360; a += 24) {
    sclera.push([ex + cos(a) * 14.5, ey + sin(a) * 13.5]);
    iris.push([ex + cos(a) * 11, ey + sin(a) * 10.5]);
    pupil.push([ex + cos(a) * 6.8, ey + sin(a) * 6.8]);
    spec.push([ex - 3.5 * side + cos(a) * 3.2, ey - 3.5 + sin(a) * 3.2]);
  }
  polyWash(sclera, PAL.porcelain, 255);
  polyWash(iris, PAL.lemon, 255);
  polyDraw(iris, "finePen", PAL.vermilion, 0.8);
  polyWash(pupil, PAL.lacquer, 255);
  polyWash(spec, PAL.white, 255);
  polyDraw(sclera, "keyLine", PAL.lacquer, 1.05);

  // Head contour outline
  polyDraw(headPts, "keyLine", PAL.lacquer, 1.05);
}

