// 5. CENTRAL WATER INTERACTION & AUSPICIOUS PEARL BETWEEN THE KOI
// =============================================================================

function drawCentralWaterInteraction() {
  // Symmetrical water splash ribbons rising between the two koi snouts at (600, 325)
  for (let side of [-1, 1]) {
    drawCurlWave(side, 635, 395, 78, 225, 0.82);
    drawCurlWave(side, 645, 255, 64, 135, 0.72);
  }

  // Auspicious radiant water-pearl orb suspended between the two koi mouths at (600, 315)
  let cx = 600;
  let cy = 315;
  let r = 28;

  // Radiant halo rings around the central orb
  brush.set("finePen", PAL.lemon, 0.8);
  brush.circle(cx, cy, r + 10, 0.04);
  brush.set("finePen", PAL.peachLight, 0.65);
  brush.circle(cx, cy, r + 18, 0.04);

  drawHyperrealMandarinOrOrb(cx, cy, r, true);
}

// =============================================================================
// 6. HEAPED PYRAMID OF GLOSSY MANDARINS (HYPERREAL DIMPLED RIND & SPECULAR SHEEN)
// =============================================================================

function drawHyperrealMandarin(cx, cy, rx, ry, stemSide = 0, hasCalyx = true) {
  // Slightly oblate, plump tangerine silhouette with subtle top stem dimple
  let silPts = [];
  let steps = 36;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    // Slight indentation at top (-90 deg) where calyx sits, and plump cheeks
    let topIndent = exp(-pow(((a - 270 + 540) % 360 - 180) / 28, 2)) * 0.06;
    let lobe = 1 - topIndent + 0.025 * cos(a * 2);
    silPts.push([
      cx + cos(a) * rx * lobe,
      cy + sin(a) * ry * lobe
    ]);
  }

  // 1. Deep vermilion-crimson shadow base wash
  polyWash(silPts, PAL.vermilionDark, 255);

  // 2. Concentric spherical gradation layers shifted toward top-center-left light source
  let lightShiftX = (cx < 600 ? 0.16 : cx > 600 ? -0.16 : 0.0) * rx;
  let lightShiftY = -0.22 * ry;

  const layers = [
    { scaleX: 0.93, scaleY: 0.91, ox: lightShiftX * 0.25, oy: lightShiftY * 0.25, col: PAL.cinnabar, op: 250 },
    { scaleX: 0.84, scaleY: 0.81, ox: lightShiftX * 0.55, oy: lightShiftY * 0.55, col: PAL.vermilion, op: 250 },
    { scaleX: 0.71, scaleY: 0.68, ox: lightShiftX * 0.85, oy: lightShiftY * 0.85, col: PAL.tangerine, op: 245 },
    { scaleX: 0.54, scaleY: 0.50, ox: lightShiftX * 1.15, oy: lightShiftY * 1.15, col: PAL.gold, op: 235 },
    { scaleX: 0.35, scaleY: 0.31, ox: lightShiftX * 1.38, oy: lightShiftY * 1.38, col: PAL.lemon, op: 235 }
  ];

  for (let L of layers) {
    let lPts = [];
    for (let i = 0; i < 24; i++) {
      let a = (i / 24) * 360;
      lPts.push([
        cx + L.ox + cos(a) * rx * L.scaleX,
        cy + L.oy + sin(a) * ry * L.scaleY
      ]);
    }
    polyWash(lPts, L.col, L.op);
  }

  // 3. Peach-pink reflected bounce light crescent along the bottom rim of each mandarin
  let bouncePts = [];
  for (let a = 25; a <= 155; a += 13) {
    bouncePts.push([cx + cos(a) * rx * 0.92, cy + sin(a) * ry * 0.92]);
  }
  for (let a = 155; a >= 25; a -= 13) {
    bouncePts.push([cx + cos(a) * rx * 0.76, cy + sin(a) * ry * 0.74]);
  }
  polyWash(bouncePts, PAL.peach, 195);

  // 4. Subtle segment crease contour lines radiating from stem dimple
  let stemX = cx + stemSide * rx * 0.12;
  let stemY = cy - ry * 0.56;
  brush.set("finePen", PAL.vermilionDark, 0.45);
  for (let k = -3; k <= 3; k++) {
    let a = -90 + k * 24;
    let p1 = [stemX + cos(a) * 8, stemY + sin(a) * 6, 0.8];
    let p2 = [stemX + cos(a) * rx * 0.42, stemY + sin(a) * ry * 0.35, 0.5];
    let p3 = [cx + cos(a) * rx * 0.78, cy + sin(a) * ry * 0.65, 0.2];
    brush.spline([p1, p2, p3], 0.45);
  }

  // 5. HYPERREAL DIMPLED RIND (Hundreds of oil-gland pores mapped across 3D sphere!)
  let hx = cx + lightShiftX * 1.45;
  let hy = cy + lightShiftY * 1.45;

  // Deterministic Fibonacci-spiral distribution on the disk so pores are organic and uniform
  let numPores = floor((rx * ry) / 22);
  for (let i = 0; i < numPores; i++) {
    let rNorm = sqrt((i + 0.5) / numPores) * 0.94;
    let theta = i * 137.508; // Golden angle in degrees
    // Foreshorten radially near edge of sphere
    let px = cx + cos(theta) * rx * rNorm;
    let py = cy + sin(theta) * ry * rNorm;

    let dHighlight = dist(px, py, hx, hy) / rx;

    if (dHighlight < 0.34) {
      // Glossy specular zone: bright white & lemon-yellow micro-crescent rings around oil glands!
      brush.set("rindPore", PAL.lemonBright, 0.75);
      brush.arc(px, py, 2.2, 200, 350);
      brush.set("rindPore", PAL.tangerine, 0.6);
      brush.arc(px, py, 1.8, 20, 160);
    } else if (dHighlight < 0.72) {
      // Midtone tangerine/vermilion zone: dark crimson pore dot + golden lower rim
      brush.set("rindPore", PAL.vermilionDark, 0.72);
      brush.line(px - 1.1, py, px + 1.1, py + 0.4);
      if (i % 2 === 0) {
        brush.set("rindPore", PAL.lemon, 0.55);
        brush.line(px - 0.8, py + 1.2, px + 0.9, py + 1.2);
      }
    } else {
      // Deep shadow zone: rich lacquer-vermilion dimples
      brush.set("rindPore", PAL.lacquerSoft, 0.65);
      brush.line(px - 1.0, py - 0.3, px + 1.0, py + 0.3);
    }
  }

  // 6. Waxy Specular Highlight Window (broken into bumpy rind sparkles along its edge!)
  let specPoly = [];
  for (let a = 0; a < 360; a += 30) {
    let jitter = 1 + 0.14 * sin(a * 5);
    specPoly.push([
      hx + cos(a) * rx * 0.16 * jitter,
      hy + sin(a) * ry * 0.11 * jitter
    ]);
  }
  polyWash(specPoly, PAL.lemonBright, 240);

  let coreSpec = [];
  for (let a = 0; a < 360; a += 36) {
    coreSpec.push([
      hx + cos(a) * rx * 0.08,
      hy + sin(a) * ry * 0.055
    ]);
  }
  polyWash(coreSpec, PAL.white, 255);

  // Sparkling pinpoint oil-gland reflections ringing the main specular highlight
  brush.set("finePen", PAL.white, 0.95);
  for (let a = 0; a < 360; a += 28) {
    let sx = hx + cos(a) * rx * 0.22;
    let sy = hy + sin(a) * ry * 0.15;
    brush.line(sx - 1.2, sy, sx + 1.2, sy);
  }

  // 7. Emerald & Gold Star Calyx (Stem button) in top dimple
  if (hasCalyx) {
    let calPts = [];
    for (let i = 0; i < 10; i++) {
      let a = i * 36;
      let rad = i % 2 === 0 ? 13 : 6;
      calPts.push([stemX + cos(a) * rad, stemY + sin(a) * rad * 0.68]);
    }
    polyWash(calPts, PAL.emerald, 255);
    polyDraw(calPts, "finePen", PAL.lacquer, 0.75);

    let buttonPts = [];
    for (let a = 0; a < 360; a += 45) {
      buttonPts.push([stemX + cos(a) * 4.5, stemY + sin(a) * 3.5]);
    }
    polyWash(buttonPts, PAL.lemon, 250);
    polyDraw(buttonPts, "finePen", PAL.lacquer, 0.65);
  }

  // 8. Firm lacquer-black woodblock contour line
  polyDraw(silPts, "keyLine", PAL.lacquer, 1.05);
}

