// =============================================================================
// 7. HEAPED PORCELAIN TREASURE BOWL (HYPERREAL GLAZE, NIANHUA MOTIFS & RIM)
// =============================================================================

function getBowlHalfWidth(y) {
  // Bowl extends from y = 788 (flared rim) to y = 1042 (footed base)
  if (y < 804) {
    // Flared everted lip
    let u = (y - 788) / 16;
    return lerp(308, 294, u);
  } else if (y < 996) {
    // Generous rounded porcelain belly
    let u = (y - 804) / 192;
    return 294 * pow(cos(u * 76), 0.58) + 22 * (1 - u);
  } else {
    // Straight/slightly flared foot ring (圈足)
    let u = (y - 996) / 46;
    return lerp(136, 144, sin(u * 90));
  }
}

function drawPorcelainBowl() {
  const yTop = 788;
  const yFootTop = 996;
  const yBot = 1044;

  // 1. Cast shadow under the bowl foot in deep cinnabar-lacquer
  let footShadow = [];
  for (let a = 0; a < 360; a += 15) {
    footShadow.push([600 + cos(a) * 165, 1046 + sin(a) * 18]);
  }
  polyWash(footShadow, PAL.vermilionDark, 235);

  // 2. Main Porcelain Bowl Body Silhouette
  let leftEdge = [];
  let rightEdge = [];
  for (let y = yTop; y <= yBot; y += 6) {
    let hw = getBowlHalfWidth(y);
    // Curved bottom edge of the foot ring
    leftEdge.push([600 - hw, y]);
    rightEdge.push([600 + hw, y]);
  }
  // Curved bottom arc of foot
  let botArc = [];
  let hwBot = getBowlHalfWidth(yBot);
  for (let i = -10; i <= 10; i++) {
    let u = i / 10;
    botArc.push([600 + u * hwBot, yBot + (1 - u * u) * 14]);
  }
  // Top rim dips slightly in center perspective
  let topArc = [];
  let hwTop = getBowlHalfWidth(yTop);
  for (let i = 12; i >= -12; i--) {
    let u = i / 12;
    topArc.push([600 + u * hwTop, yTop + (1 - u * u) * 16]);
  }

  let bowlPoly = leftEdge.concat(botArc).concat(rightEdge.slice().reverse()).concat(topArc);
  polyWash(bowlPoly, PAL.porcelain, 255);

  // 3. Subtle 3D cylindrical porcelain shading (warm peach-cream shadow on left & right flanks and under lip)
  for (let side of [-1, 1]) {
    let flankShade = [];
    let deepFlank = [];
    for (let y = yTop + 14; y <= yFootTop; y += 8) {
      let hw = getBowlHalfWidth(y);
      flankShade.push([600 + side * hw, y]);
      deepFlank.push([600 + side * hw, y]);
    }
    for (let y = yFootTop; y >= yTop + 14; y -= 8) {
      let hw = getBowlHalfWidth(y);
      flankShade.push([600 + side * hw * 0.62, y + 6]);
      deepFlank.push([600 + side * hw * 0.82, y + 3]);
    }
    polyWash(flankShade, PAL.porcelainMid, 225);
    polyWash(deepFlank, PAL.porcelainShadow, 210);
  }

  // Under-lip shadow band & foot-ring groove
  let drawBand = (y1, y2, col, op = 250) => {
    let bPts = [];
    let hw1 = getBowlHalfWidth(y1);
    let hw2 = getBowlHalfWidth(y2);
    let sag1 = y1 < 950 ? 16 : 12;
    let sag2 = y2 < 950 ? 16 : 12;
    for (let i = -16; i <= 16; i++) {
      let u = i / 16;
      bPts.push([600 + u * hw1, y1 + (1 - u * u) * sag1]);
    }
    for (let i = 16; i >= -16; i--) {
      let u = i / 16;
      bPts.push([600 + u * hw2, y2 + (1 - u * u) * sag2]);
    }
    polyWash(bPts, col, op);
    return bPts;
  };

  // Gold & Emerald & Vermilion decorative bands on the porcelain bowl
  let lipBand = drawBand(788, 806, PAL.lemon, 250);
  polyDraw(lipBand, "keyLine", PAL.lacquer, 0.9);

  let upperFretBand = drawBand(806, 834, PAL.emerald, 245);
  polyDraw(upperFretBand, "keyLine", PAL.lacquer, 0.85);

  // Key-fret / Ruyi auspicious pattern along the emerald upper band (foreshortened along cylinder!)
  let nFrets = 11;
  for (let i = -nFrets; i <= nFrets; i++) {
    let u = i / (nFrets + 1);
    let theta = u * 80;
    let xProj = sin(theta);
    let scaleW = cos(theta);
    let hw = getBowlHalfWidth(820);
    let cx = 600 + xProj * hw;
    let cy = 820 + (1 - xProj * xProj) * 15;
    let rw = 10 * scaleW;
    let rh = 7;

    let dmd = [
      [cx, cy - rh],
      [cx + rw, cy],
      [cx, cy + rh],
      [cx - rw, cy]
    ];
    polyWash(dmd, i % 2 === 0 ? PAL.lemon : PAL.peachLight, 245);
    polyDraw(dmd, "finePen", PAL.lacquer, 0.65);
  }

  // Lower lotus-petal band above the foot ring
  let lowerBand = drawBand(966, 996, PAL.vermilion, 245);
  polyDraw(lowerBand, "keyLine", PAL.lacquer, 0.85);

  let nPetals = 9;
  for (let i = -nPetals; i <= nPetals; i++) {
    let u = i / (nPetals + 0.8);
    let theta = u * 78;
    let xProj = sin(theta);
    let scaleW = cos(theta);
    let hwTopP = getBowlHalfWidth(964);
    let hwBotP = getBowlHalfWidth(995);
    let xTop = 600 + xProj * hwTopP;
    let yTopP = 964 + (1 - xProj * xProj) * 14;
    let xBot = 600 + xProj * hwBotP;
    let yBotP = 995 + (1 - xProj * xProj) * 13;
    let pw = 14 * scaleW;

    let petal = [
      [xBot - pw * 0.7, yBotP],
      [xTop - pw, yTopP + 8],
      [xTop, yTopP - 6],
      [xTop + pw, yTopP + 8],
      [xBot + pw * 0.7, yBotP]
    ];
    polyWash(petal, i % 2 === 0 ? PAL.peachLight : PAL.lemon, 245);
    polyDraw(petal, "finePen", PAL.lacquer, 0.7);
  }

  // Foot ring decoration (Gold & Emerald stripes)
  let footGold = drawBand(996, 1012, PAL.gold, 250);
  polyDraw(footGold, "finePen", PAL.lacquer, 0.8);
  let footEm = drawBand(1026, 1042, PAL.emeraldDark, 250);
  polyDraw(footEm, "finePen", PAL.lacquer, 0.8);

  // Central Auspicious Medallion (Bats / Peony / Longevity emblem) & Symmetrical Floral Scrolls on Bowl Belly
  drawBowlCenterMedallionAndScrolls();

  // 4. Hyperreal Ceramic Specular Glaze Highlight Strip on the curved porcelain belly!
  for (let side of [-1, 1]) {
    let glazePts = [];
    for (let y = 838; y <= 958; y += 10) {
      let hw = getBowlHalfWidth(y);
      glazePts.push([600 + side * hw * 0.42, y + 11]);
    }
    for (let y = 958; y >= 838; y -= 10) {
      let hw = getBowlHalfWidth(y);
      glazePts.push([600 + side * hw * 0.50, y + 9]);
    }
    polyWash(glazePts, PAL.white, 225);
  }

  // 5. Crisp Woodblock Key-Line Outline around entire Porcelain Bowl
  polyDraw(bowlPoly, "keyLine", PAL.lacquer, 1.25);
}

