// 8B. HYPERREAL WATER DROPLETS (ON KOI, MANDARINS, LEAVES & IN THE AIR)
// =============================================================================

function drawHyperrealWaterDroplet(x, y, r, angleDeg = -90, isTeardrop = true, onSurface = "red") {
  let pts = [];
  let steps = 20;
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);

  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    // Teardrop elongation along angleDeg
    let stretch = isTeardrop && cos(a) > 0 ? 1 + 0.65 * pow(cos(a), 2) : 1.0;
    let taper = isTeardrop && cos(a) > 0 ? 1 - 0.38 * pow(cos(a), 1.5) : 1.0;
    let lx = cos(a) * r * stretch;
    let ly = sin(a) * r * taper;
    pts.push([x + lx * ca - ly * sa, y + lx * sa + ly * ca]);
  }

  // 1. Cast shadow beneath droplet
  let shPts = pts.map(p => [p[0] + 2.5, p[1] + 3.5]);
  polyWash(shPts, onSurface === "leaf" ? PAL.emeraldDark : PAL.vermilionDark, 215);

  // 2. Refracted interior body color
  let bodyCol =
    onSurface === "leaf"
      ? PAL.emerald
      : onSurface === "bowl"
      ? PAL.porcelainMid
      : PAL.vermilion;
  polyWash(pts, bodyCol, 245);

  // 3. Internal caustic glow on the bottom/opposite side of the droplet
  let causticPts = [];
  for (let a = 20; a <= 160; a += 20) {
    causticPts.push([x + cos(a) * r * 0.78, y + sin(a) * r * 0.78]);
  }
  for (let a = 160; a >= 20; a -= 20) {
    causticPts.push([x + cos(a) * r * 0.38, y + sin(a) * r * 0.35]);
  }
  polyWash(
    causticPts,
    onSurface === "leaf" ? PAL.emeraldLight : PAL.lemon,
    235
  );

  // 4. Dark refractive cap on top-facing side
  let capPts = [];
  for (let a = 200; a <= 340; a += 20) {
    capPts.push([x + cos(a) * r * 0.82, y + sin(a) * r * 0.82]);
  }
  for (let a = 340; a >= 200; a -= 20) {
    capPts.push([x + cos(a) * r * 0.42, y + sin(a) * r * 0.42]);
  }
  polyWash(
    capPts,
    onSurface === "leaf" ? PAL.emeraldDark : PAL.cinnabarDeep,
    220
  );

  // 5. Crisp pure white specular highlight dot + secondary reflection dot
  let specPts = [];
  let sx = x - r * 0.28;
  let sy = y - r * 0.32;
  let sr = max(2.2, r * 0.28);
  for (let a = 0; a < 360; a += 45) {
    specPts.push([sx + cos(a) * sr, sy + sin(a) * sr * 0.8]);
  }
  polyWash(specPts, PAL.white, 255);

  // 6. Firm lacquer-black key line around droplet
  polyDraw(pts, "finePen", PAL.lacquer, 0.75);
}

