// Head coordinate system parameters
const HEAD_CX = 590;
const HEAD_CY = 395;
const HEAD_TILT = -4.5; // degrees

// Scene storage for batched fills, ghost contours, and primary contours
let fillBatches = {};
let contourPaths = []; // { pts, closed, weight, brushName, ghostTag, isFine, inkCol }
let dropletList = [];  // { x, y, rx, ry, angle, colKey, ghostTag, hasHighlight }

function headPt(u, v) {
  let rad = HEAD_TILT * Math.PI / 180;
  let c = Math.cos(rad);
  let s = Math.sin(rad);
  return [
    HEAD_CX + u * c - v * s,
    HEAD_CY + u * s + v * c
  ];
}

function registerFill(colKey, pts, opacity = 115, curvature = 0.18, misregScale = 1.0) {
  if (!fillBatches[colKey]) fillBatches[colKey] = [];
  fillBatches[colKey].push({
    pts,
    opacity,
    curvature,
    dx: 7.5 * misregScale + random(-2.2, 2.2),
    dy: -6.0 * misregScale + random(-2.2, 2.2)
  });
}

function registerContour(pts, opts = {}) {
  contourPaths.push({
    pts,
    closed: opts.closed || false,
    weight: opts.weight || 0.55,
    brushName: opts.brushName || "roto_marker",
    ghostTag: opts.ghostTag || "body",
    wobbleAmp: opts.wobbleAmp !== undefined ? opts.wobbleAmp : 1.85,
    wobbleStep: opts.wobbleStep || 11,
    inkCol: opts.inkCol || PALETTE.inkBlack,
    skipGhost: opts.skipGhost || false
  });
}

function registerShape(colKey, pts, opts = {}) {
  if (colKey) {
    registerFill(
      colKey,
      pts,
      opts.opacity !== undefined ? opts.opacity : 120,
      opts.curvature !== undefined ? opts.curvature : 0.2,
      opts.misregScale !== undefined ? opts.misregScale : 1.0
    );
  }
  if (!opts.noContour) {
    registerContour(pts, opts);
  }
}

// Subdivide a path and inject coherent hand-traced rotoscope wobble
function makeWobblePts(pts, closed, stepLen, amp, seedOffset = 0) {
  if (!pts || pts.length < 2) return pts;
  let src = closed ? [...pts, pts[0]] : pts;
  let out = [];
  let accumDist = 0;

  for (let i = 0; i < src.length - 1; i++) {
    let p0 = src[i];
    let p1 = src[i + 1];
    let dx = p1[0] - p0[0];
    let dy = p1[1] - p0[1];
    let segLen = Math.hypot(dx, dy);
    if (segLen < 0.5) continue;

    let steps = Math.max(1, Math.ceil(segLen / stepLen));
    let nx = -dy / segLen;
    let ny = dx / segLen;

    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let x = p0[0] + dx * t;
      let y = p0[1] + dy * t;
      let d = accumDist + segLen * t;

      let n1 = noise(x * 0.018 + seedOffset, y * 0.018 + seedOffset, d * 0.03) - 0.5;
      let n2 = noise(d * 0.12 + seedOffset * 3.1, i * 0.37) - 0.5;
      let disp = (n1 * 1.65 + n2 * 0.85) * amp;
      let along = (noise(y * 0.025 + seedOffset, x * 0.025) - 0.5) * amp * 0.45;

      out.push([x + nx * disp + (dx / segLen) * along, y + ny * disp + (dy / segLen) * along]);
    }
    accumDist += segLen;
  }

  let last = src[src.length - 1];
  let nLast = (noise(last[0] * 0.02 + seedOffset, last[1] * 0.02) - 0.5) * amp;
  out.push([last[0] + nLast, last[1] - nLast]);
  return out;
}

// Compute the offset position of the previous rotoscope frame (t - 1)
function ghostTransformPoint(pt, tag) {
  let x = pt[0];
  let y = pt[1];
  if (tag === "body") {
    // Swimmer was lower in the pool 1/24s ago and slightly tilted
    return [x - 8.5, y + 14.5];
  } else if (tag === "splash") {
    // Flying water sheets and droplets were closer to the face/impact center
    let cx = 585, cy = 540;
    return [cx + (x - cx) * 0.955 - 5.5, cy + (y - cy) * 0.955 + 15.0];
  } else if (tag === "ripple") {
    // Pool ripples were slightly smaller ellipses 1/24s ago
    let cx = 585, cy = 795;
    return [cx + (x - cx) * 0.965 - 4.0, cy + (y - cy) * 0.965 + 7.5];
  }
  return [x - 7.0, y + 11.0];
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);

  // Custom felt-tip rotoscope marker brush
  brush.add("roto_marker", {
    type: "default",
    weight: 1.05,
    scatter: 0.06,
    sharpness: 0.82,
    grain: 0.88,
    opacity: 225,
    spacing: 0.14,
    pressure: [0.88, 1.18, 0.85],
    noise: 0.65
  });

  // Fine trembling technical ink pen for hyperreal wet details
  brush.add("roto_fine", {
    type: "default",
    weight: 0.52,
    scatter: 0.04,
    sharpness: 0.9,
    grain: 0.92,
    opacity: 235,
    spacing: 0.12,
    pressure: [0.75, 1.1, 0.7],
    noise: 0.75
  });

  randomSeed(4219);
  noiseSeed(4219);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.ground);

  // Build the entire hyperreal rotoscoped scene geometry
  buildPoolBackgroundAndCaustics();
  buildSubmergedTorsoAndShoulders();
  buildNeckAndThroat();
  buildFaceAndAnatomy();
  buildSwimCapAndWetHair();
  buildGogglesAndEyes();
  buildWaterSheetingAndCurtains();
  buildSurfaceRipplesAndFoamCollar();
  buildObsessiveDroplets();

  // PASS 1: Luminous Flat Misregistered Watercolour Fills (batched by color for performance)
  renderWatercolourBatches();

  // PASS 2: Subtle Dry-Media / Marker Tonal Accent Streaks
  renderMarkerAccents();

  // PASS 3: Faint Offset Ghost Contours (Previous Rotoscope Frame t - 1)
  renderGhostContours();

  // PASS 4: Primary Wobbling Black Marker Contours (Current Frame t)
  renderPrimaryContours();

  // PASS 5: Fine Framing Border & Film Cel Registration Marks
  renderRotoscopeCelFrame();

  noLoop();
}

// ============================================================================
// 1. POOL WATER, REFRACTION BANDS & CELLULAR CAUSTICS
// ============================================================================
function buildPoolBackgroundAndCaustics() {
  // Large interlocking pool zones in turquoise, cerulean, and chlorine green
  registerFill("turquoise", [
    [35, 35], [1165, 35], [1165, 1165], [35, 1165]
  ], 95, 0.05, 0.6);

  // Upper pool diagonal refraction swells
  let swellBands = [
    { col: "cerulean", y0: 45, y1: 230, amp: 28, op: 110 },
    { col: "chlorine", y0: 190, y1: 420, amp: 35, op: 105 },
    { col: "deepPool", y0: 360, y1: 620, amp: 40, op: 105 },
    { col: "ceruleanLight", y0: 550, y1: 790, amp: 32, op: 95 },
    { col: "chlorine", y0: 740, y1: 980, amp: 36, op: 115 },
    { col: "deepPool", y0: 930, y1: 1160, amp: 25, op: 125 }
  ];

  for (let b = 0; b < swellBands.length; b++) {
    let sb = swellBands[b];
    let pts = [];
    for (let x = 40; x <= 1160; x += 70) {
      let y = sb.y0 + Math.sin(x * 0.008 + b * 1.4) * sb.amp + (noise(x * 0.005, b) - 0.5) * 35;
      pts.push([x, y]);
    }
    for (let x = 1160; x >= 40; x -= 70) {
      let y = sb.y1 + Math.cos(x * 0.007 + b * 1.9) * sb.amp + (noise(x * 0.005, b + 5) - 0.5) * 35;
      pts.push([x, y]);
    }
    registerFill(sb.col, pts, sb.op, 0.25, 1.15);
  }

  // Cellular refraction caustics across the upper/outer turquoise water
  for (let row = 0; row < 10; row++) {
    for (let col = 0; col < 11; col++) {
      let cx = 85 + col * 102 + (row % 2) * 48 + random(-22, 22);
      let cy = 75 + row * 104 + random(-20, 20);

      // Keep clear of the core face & torso silhouette
      let dHead = Math.hypot((cx - 585) * 1.1, (cy - 440) * 0.9);
      let dTorso = Math.hypot((cx - 585) * 0.72, (cy - 790) * 1.2);
      if (dHead < 275 || dTorso < 260) continue;

      let rx = random(32, 62);
      let ry = random(16, 32);
      let tilt = (cx - 600) * 0.025 + random(-12, 12);
      let cellPts = [];
      let innerPts = [];
      let nVerts = 10;

      for (let k = 0; k < nVerts; k++) {
        let ang = (k / nVerts) * Math.PI * 2;
        let rMod = 0.82 + 0.35 * noise(cx * 0.02 + Math.cos(ang), cy * 0.02 + Math.sin(ang));
        let px = Math.cos(ang) * rx * rMod;
        let py = Math.sin(ang) * ry * rMod;
        let rot = tilt * Math.PI / 180;
        let wx = cx + px * Math.cos(rot) - py * Math.sin(rot);
        let wy = cy + px * Math.sin(rot) + py * Math.cos(rot);
        cellPts.push([wx, wy]);
        innerPts.push([
          cx + (wx - cx) * 0.62,
          cy + (wy - cy) * 0.62
        ]);
      }

      let colKey = (row + col) % 3 === 0 ? "chlorinePale" : ((row + col) % 2 === 0 ? "ceruleanLight" : "deepPool");
      registerShape(colKey, cellPts, {
        closed: true,
        opacity: 85,
        weight: 0.36,
        brushName: "roto_fine",
        ghostTag: "ripple",
        wobbleAmp: 1.5
      });

      // Inner refraction ring
      if (random() < 0.65) {
        registerContour(innerPts, {
          closed: true,
          weight: 0.26,
          brushName: "roto_fine",
          ghostTag: "ripple",
          wobbleAmp: 1.2
        });
      }
    }
  }
}

