    weight: 0.62,
    brushName: "roto_marker",
    ghostTag: "ripple",
    wobbleAmp: 2.1
  });

  // Lace-like foam holes & aeration bubbles across the surging water collar
  for (let i = 0; i < 42; i++) {
    let u = random(-455, 455);
    let v = random(375, 485);
    let r = random(7, 22);
    let bubblePts = [];
    for (let k = 0; k < 8; k++) {
      let a = (k / 8) * Math.PI * 2;
      bubblePts.push(headPt(u + Math.cos(a) * r * 1.25, v + Math.sin(a) * r * 0.72));
    }
    let col = i % 3 === 0 ? "cerulean" : (i % 2 === 0 ? "chlorine" : "foamCream");
    registerShape(col, bubblePts, {
      closed: true,
      opacity: 110,
      weight: 0.34,
      brushName: "roto_fine",
      ghostTag: "splash",
      wobbleAmp: 1.2
    });
  }

  // Concentric Elliptical Refraction Ripples radiating across the pool
  let rippleCenterX = 588;
  let rippleCenterY = 815;

  for (let ring = 0; ring < 14; ring++) {
    let rx = 250 + ring * 44;
    let ry = 88 + ring * 21;

    // Draw 3–4 segmented undulating arcs per elliptical ring
    let nArcs = 4;
    for (let aIdx = 0; aIdx < nArcs; aIdx++) {
      let aStart = (aIdx / nArcs) * Math.PI * 2 + ring * 0.23;
      let aEnd = aStart + (Math.PI * 2 / nArcs) * random(0.68, 0.88);

      let arcPts = [];
      let ribbonPts = [];
      let steps = 22;

      for (let s = 0; s <= steps; s++) {
        let t = s / steps;
        let ang = aStart + (aEnd - aStart) * t;
        let waveMod = Math.sin(ang * 7 + ring * 1.4) * (5 + ring * 0.6);
        let x = rippleCenterX + Math.cos(ang) * (rx + waveMod);
        let y = rippleCenterY + Math.sin(ang) * (ry + waveMod * 0.45);

        // Clip inside canvas margins and avoid overlapping the upper head
        if (x < 45 || x > 1155 || y < 55 || y > 1155) continue;
        if (Math.hypot(x - 585, y - 395) < 235) continue;

        arcPts.push([x, y]);
        let thick = (10 + (ring % 3) * 5) * Math.sin(t * Math.PI);
        ribbonPts.unshift([x, y + thick]);
      }

      if (arcPts.length > 4) {
        if ((ring + aIdx) % 2 === 0) {
          let fullRibbon = [...arcPts, ...ribbonPts];
          let rCol = ring % 3 === 0 ? "foamCream" : (ring % 2 === 0 ? "chlorinePale" : "ceruleanLight");
          registerShape(rCol, fullRibbon, {
            closed: true,
            opacity: 105,
            weight: 0.46,
            brushName: "roto_fine",
            ghostTag: "ripple",
            wobbleAmp: 1.85
          });
        } else {
          registerContour(arcPts, {
            closed: false,
            weight: ring % 2 === 0 ? 0.56 : 0.36,
            brushName: ring % 2 === 0 ? "roto_marker" : "roto_fine",
            ghostTag: "ripple",
            wobbleAmp: 1.9
          });
        }
      }
    }
  }
}

// ============================================================================
// 9. OBSESSIVE HYPERREAL WATER DROPLETS (AIRBORNE & SKIN-CLINGING)
// ============================================================================
function buildObsessiveDroplets() {
  // 1. Airborne parabolic droplet arcs bursting outward from head, goggles, and shoulders
  for (let i = 0; i < 165; i++) {
    let side = i % 2 === 0 ? -1 : 1;
    let t = random(0.05, 1.0);
    let band = i % 4;
    let u, v, ang;

    if (band === 0) {
      // Spraying off the swim cap & goggles
      u = side * (135 + t * 290 + random(-25, 25));
      v = -165 + t * t * 340 + random(-35, 35);
      ang = side * (15 + t * 55);
    } else if (band === 1) {
      // Spraying off cheekbones & water curtains
      u = side * (175 + t * 330 + random(-25, 25));
      v = 25 + t * t * 380 + random(-30, 30);
      ang = side * (35 + t * 45);
    } else if (band === 2) {
      // Rising above the crown of the head
      u = random(-260, 260);
      v = -235 - random(10, 130) + Math.pow(u / 220, 2) * 85;
      ang = (u / 260) * 45;
    } else {
      // Churning up from the shoulder foam collar
      u = side * random(120, 490);
      v = random(270, 520);
      ang = side * random(10, 65);
    }

    let p = headPt(u, v);
    if (p[0] < 45 || p[0] > 1155 || p[1] < 45 || p[1] > 1155) continue;

    let rx = random(3.5, 13.5);
    let ry = rx * random(0.52, 0.85);
    let colKey = i % 3 === 0 ? "foamCream" : (i % 2 === 0 ? "chlorinePale" : "ceruleanLight");

    dropletList.push({
      x: p[0],
      y: p[1],
      rx,
      ry,
      angle: ang + HEAD_TILT,
      colKey: rx > 5.5 ? colKey : null, // Fill medium/large droplets, contour all of them
      ghostTag: "splash",
      hasHighlight: rx > 6.5
    });
  }

  // 2. Skin-clinging water beads across forehead, cheeks, nose bridge, chin, neck, cap, and shoulders
  let skinZones = [
    // Swim cap beads
    { uMin: -120, uMax: 120, vMin: -195, vMax: -75, count: 36, col: "foamCream" },
    // Goggle frame & lens beads
    { uMin: -145, uMax: 145, vMin: -42, vMax: 28, count: 28, col: "chlorinePale" },
    // Cheekbones & nose bridge
    { uMin: -148, uMax: 148, vMin: 28, vMax: 135, count: 44, col: "foamCream" },
    // Chin & jaw
    { uMin: -95, uMax: 95, vMin: 175, vMax: 238, count: 20, col: "foamCream" },
    // Neck, clavicles & deltoids
    { uMin: -395, uMax: 395, vMin: 255, vMax: 410, count: 62, col: "chlorinePale" }
  ];

  for (let z of skinZones) {
    for (let k = 0; k < z.count; k++) {
      let u = random(z.uMin, z.uMax);
      let v = random(z.vMin, z.vMax);
      // Avoid placing skin beads directly inside the dark open mouth cavity
      if (Math.abs(u) < 48 && v > 115 && v < 166) continue;

      let p = headPt(u, v);
      let rx = random(2.8, 7.8);
      let ry = rx * random(0.65, 0.95);
      dropletList.push({
        x: p[0],
        y: p[1],
        rx,
        ry,
        angle: random(-25, 25),
        colKey: rx > 5.0 ? z.col : null,
        ghostTag: "body",
        hasHighlight: rx > 5.2
      });
    }
  }

  // Convert filled droplets into batched watercolour polygons as well
  for (let d of dropletList) {
    if (d.colKey) {
      let pts = [];
      let n = 8;
      let rad = d.angle * Math.PI / 180;
      for (let k = 0; k < n; k++) {
        let a = (k / n) * Math.PI * 2;
        // Slight teardrop pinch at one end
        let pinch = k === 0 ? 1.35 : 1.0;
        let px = Math.cos(a) * d.rx * pinch;
        let py = Math.sin(a) * d.ry;
        pts.push([
          d.x + px * Math.cos(rad) - py * Math.sin(rad),
          d.y + px * Math.sin(rad) + py * Math.cos(rad)
        ]);
      }
      registerFill(d.colKey, pts, 145, 0.25, 0.65);
    }
  }
}

