function renderWatercolourBatches() {
  brush.noStroke();
  brush.noHatch();
  brush.noField();

  // Order from background pool colors to skin/cap midtones to bright specular water highlights
  const drawOrder = [
    "turquoise",
    "cerulean",
    "deepPool",
    "chlorine",
    "ceruleanLight",
    "submergedSkin",
    "fleshPale",
    "fleshWarm",
    "earthOchre",
    "earthTerra",
    "capOchre",
    "capShadow",
    "goggleFrame",
    "goggleStrap",
    "lensAmber",
    "earthUmber",
    "chlorinePale",
    "foamCream"
  ];

  for (let colKey of drawOrder) {
    let batch = fillBatches[colKey];
    if (!batch || batch.length === 0) continue;

    let hexCol = PALETTE[colKey];
    brush.fillBleed(0.065, "out");
    brush.fillTexture(0.32, 0.22);

    for (let item of batch) {
      if (!item.pts || item.pts.length < 3) continue;
