// ============================================================================
// PASS 3: FAINT SECOND GHOST CONTOUR (PREVIOUS ROTOSCOPE FRAME t - 1)
// ============================================================================
function renderGhostContours() {
  brush.noFill();
  brush.noHatch();
  brush.noField();

  // Trace offset ghost contours for all scene paths
  for (let idx = 0; idx < contourPaths.length; idx++) {
    let item = contourPaths[idx];
    if (item.skipGhost) continue;

    let ghostColor = item.ghostTag === "body" ? PALETTE.ghostWarm : PALETTE.ghostCool;
    let ghostWeight = item.weight * 0.68;
    brush.set("roto_fine", ghostColor, ghostWeight);

    let shiftedPts = item.pts.map(pt => ghostTransformPoint(pt, item.ghostTag));
    let wobbled = makeWobblePts(shiftedPts, item.closed, item.wobbleStep * 1.25, item.wobbleAmp * 1.15, idx * 0.73 + 50);

    if (wobbled.length >= 2) {
      brush.spline(wobbled, 0.35);
    }
  }

  // Ghost outlines for all droplets (shifted to their previous-frame trajectory position)
  brush.set("roto_fine", PALETTE.ghostCool, 0.28);
  for (let i = 0; i < dropletList.length; i++) {
    let d = dropletList[i];
    let gp = ghostTransformPoint([d.x, d.y], d.ghostTag);
    drawWobblyDropletOutline(gp[0], gp[1], d.rx * 0.92, d.ry * 0.92, d.angle, false, i + 500);
  }
}

// ============================================================================
// PASS 4: PRIMARY WOBBLING BLACK MARKER CONTOURS (CURRENT FRAME t)
// ============================================================================
function renderPrimaryContours() {
  brush.noFill();
  brush.noHatch();
  brush.noField();

  for (let idx = 0; idx < contourPaths.length; idx++) {
    let item = contourPaths[idx];
    brush.set(item.brushName, item.inkCol, item.weight);

    let wobbled = makeWobblePts(item.pts, item.closed, item.wobbleStep, item.wobbleAmp, idx * 1.17);
    if (wobbled.length >= 2) {
      brush.spline(wobbled, 0.38);
    }

    // For bold primary contours, add a subtle second overlapping pass on key bends for authentic marker bleed
    if (item.weight >= 0.7 && wobbled.length > 5) {
      brush.set("roto_fine", PALETTE.inkBlack, item.weight * 0.48);
      let sub = wobbled.slice(0, Math.floor(wobbled.length * 0.65));
      brush.spline(sub, 0.35);
    }
  }

  // Primary wobbling black outlines + inner specular crescents for every single droplet
  for (let i = 0; i < dropletList.length; i++) {
    let d = dropletList[i];
    let w = map(d.rx, 2.5, 14, 0.28, 0.56, true);
    brush.set(d.rx > 7 ? "roto_marker" : "roto_fine", PALETTE.inkBlack, w);
    drawWobblyDropletOutline(d.x, d.y, d.rx, d.ry, d.angle, d.hasHighlight, i);
  }
}

function drawWobblyDropletOutline(cx, cy, rx, ry, angleDeg, drawCrescent, seedIdx) {
  let n = 9;
  let rad = angleDeg * Math.PI / 180;
  let pts = [];

  for (let k = 0; k <= n; k++) {
    let a = (k / n) * Math.PI * 2;
    let pinch = (k === 0 || k === n) ? 1.32 : 1.0;
    let jitter = 1.0 + (noise(seedIdx * 0.3, k * 0.7) - 0.5) * 0.28;
    let px = Math.cos(a) * rx * pinch * jitter;
    let py = Math.sin(a) * ry * jitter;
    pts.push([
      cx + px * Math.cos(rad) - py * Math.sin(rad),
      cy + px * Math.sin(rad) + py * Math.cos(rad)
    ]);
  }
  brush.spline(pts, 0.45);

  if (drawCrescent) {
    let cPts = [];
    for (let k = 1; k <= 4; k++) {
      let a = -Math.PI * 0.75 + (k / 5) * Math.PI * 0.85;
      let px = Math.cos(a) * rx * 0.54;
      let py = Math.sin(a) * ry * 0.54;
      cPts.push([
        cx + px * Math.cos(rad) - py * Math.sin(rad),
        cy + px * Math.sin(rad) + py * Math.cos(rad)
      ]);
    }
    brush.set("roto_fine", PALETTE.inkSoft, 0.24);
    brush.spline(cPts, 0.4);
  }
}

