// =============================================================================
// GEOMETRY & CRYSTAL FIELD HELPERS
// =============================================================================

function drawPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function polyArea(pts) {
  if (!pts || pts.length < 3) return 0;
  let a = 0;
  for (let i = 0; i < pts.length; i++) {
    let j = (i + 1) % pts.length;
    a += pts[i][0] * pts[j][1] - pts[j][0] * pts[i][1];
  }
  return abs(a) * 0.5;
}

// Sutherland-Hodgman polygon clipping against a clockwise convex polygon
function clipPolygon(subjectPoly, clipPoly) {
  let outputList = subjectPoly.map(p => [p[0], p[1]]);
  for (let i = 0; i < clipPoly.length; i++) {
    let inputList = outputList;
    outputList = [];
    if (inputList.length === 0) break;

    let A = clipPoly[i];
    let B = clipPoly[(i + 1) % clipPoly.length];
    let ex = B[0] - A[0];
    let ey = B[1] - A[1];

    let isInside = (P) => (ex * (P[1] - A[1]) - ey * (P[0] - A[0])) >= -1e-4;

    let computeIntersection = (S, E) => {
      let dx = E[0] - S[0];
      let dy = E[1] - S[1];
      let denom = ex * dy - ey * dx;
      if (abs(denom) < 1e-7) return [S[0], S[1]];
      let t = (ex * (A[1] - S[1]) - ey * (A[0] - S[0])) / denom;
      return [S[0] + t * dx, S[1] + t * dy];
    };

    let S = inputList[inputList.length - 1];
    for (let j = 0; j < inputList.length; j++) {
      let E = inputList[j];
      if (isInside(E)) {
        if (!isInside(S)) {
          outputList.push(computeIntersection(S, E));
        }
        outputList.push(E);
      } else if (isInside(S)) {
        outputList.push(computeIntersection(S, E));
      }
      S = E;
    }
  }
  // Remove near-duplicate vertices
  let cleaned = [];
  for (let i = 0; i < outputList.length; i++) {
    let p = outputList[i];
    let prev = cleaned.length > 0 ? cleaned[cleaned.length - 1] : outputList[outputList.length - 1];
    if ( cleaned.length === 0 || dist(p[0], p[1], prev[0], prev[1]) > 0.8 ) {
      cleaned.push(p);
    }
  }
  return cleaned;
}

function pointInConvexPoly(x, y, poly) {
  for (let i = 0; i < poly.length; i++) {
    let A = poly[i];
    let B = poly[(i + 1) % poly.length];
    let cross = (B[0] - A[0]) * (y - A[1]) - (B[1] - A[1]) * (x - A[0]);
    if (cross < 0) return false;
  }
  return true;
}

// Convert screen (x, y) to crystal cleavage coordinates (u across planes, v along striations)
function toCrystalCoords(x, y) {
  let dx = x - STONE_CX;
  let dy = y - STONE_CY;
  let u = dx * cosN + dy * sinN;
  let v = dx * cosC + dy * sinC;
  return { u, v };
}

// Convert crystal (u, v) back to screen (x, y)
function toScreenCoords(u, v) {
  return [
    STONE_CX + u * cosN + v * cosC,
    STONE_CY + u * sinN + v * sinC
  ];
}

// Compute effective u coordinate including stepped cleavage fracture offsets
function getEffectiveU(u, v) {
  let stepOffset = 0;
  // Determine which fracture block (u, v) belongs to
  let f0 = FRACTURES[0].v + sin(u * FRACTURES[0].freq * 57.3) * FRACTURES[0].amp;
  let f1 = FRACTURES[1].v + sin((u + 40) * FRACTURES[1].freq * 57.3) * FRACTURES[1].amp;
  let f2 = FRACTURES[2].v + sin((u - 30) * FRACTURES[2].freq * 57.3) * FRACTURES[2].amp;
  let f3 = FRACTURES[3].v + sin((u + 80) * FRACTURES[3].freq * 57.3) * FRACTURES[3].amp;

  if (v < f0) stepOffset = -15;
  else if (v < f1) stepOffset = 9;
  else if (v < f2) stepOffset = -12;
  else if (v < f3) stepOffset = 17;
  else stepOffset = 2;

  // Subtle internal lamellar wave
  let twinWave = sin(v * 1.4 + u * 0.5) * 2.5;
  return u + stepOffset + twinWave;
}

// Evaluate mineral zone from effective u and v
function getLabradoriteZone(u, v) {
  let uEff = getEffectiveU(u, v);
  // Slight organic tapering of the flash band near the top and bottom edges
  let vAtten = map(abs(v), 0, 210, 1.0, 0.85, true);

  if (uEff < -92) {
    return { zone: "smoky_west", uEff, t: map(uEff, -320, -92, 0, 1, true), vAtten };
  } else if (uEff < -58) {
    return { zone: "indigo_border", uEff, t: map(uEff, -92, -58, 0, 1, true), vAtten };
  } else if (uEff < 42) {
    return { zone: "peacock_blue", uEff, t: map(uEff, -58, 42, 0, 1, true), vAtten };
  } else if (uEff < 64) {
    return { zone: "turquoise_bridge", uEff, t: map(uEff, 42, 64, 0, 1, true), vAtten };
  } else if (uEff < 110) {
    return { zone: "gold_band", uEff, t: map(uEff, 64, 110, 0, 1, true), vAtten };
  } else if (uEff < 133) {
    return { zone: "copper_edge", uEff, t: map(uEff, 110, 133, 0, 1, true), vAtten };
  } else if (uEff < 154) {
    return { zone: "extinction_rim", uEff, t: map(uEff, 133, 154, 0, 1, true), vAtten };
  } else {
    return { zone: "smoky_east", uEff, t: map(uEff, 154, 360, 0, 1, true), vAtten };
  }
}

function makeEllipsePoly(cx, cy, rx, ry, rotDeg = 0, steps = 40) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < steps; i++) {
    let ang = (i / steps) * 360;
    let lx = cos(ang) * rx;
    let ly = sin(ang) * ry;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

// =============================================================================
// 1. DARK GREEN JEWELLER'S FELT (Soft Charcoal-Mass Texture)
// =============================================================================

function drawJewellersFelt() {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();

  // Base atmospheric washes for low raking light from upper-left
  const feltBaseZones = [
    { pts: [[0, 0], [1200, 0], [1200, 1200], [0, 1200]], col: "#091914", op: 255 },
    { pts: [[0, 0], [950, 0], [680, 750], [0, 880]], col: "#102820", op: 180 },
    { pts: [[0, 0], [680, 0], [440, 520], [0, 580]], col: "#16352b", op: 150 },
    { pts: [[450, 550], [1200, 320], [1200, 1200], [180, 1200]], col: "#050f0c", op: 190 }
  ];

  for (let z of feltBaseZones) {
    brush.wash(z.col, z.op);
    drawPoly(z.pts, 0);
  }
  brush.noWash();

  // Layered charcoal-mass patches to create soft, tactile wool-felt density
  const feltMassPatches = [
    // Raking light upper-left & mid-left swells
    { cx: 220, cy: 210, rx: 310, ry: 180, rot: -12, col: "#1c4035", str: 0.65, prec: 0.3 },
    { cx: 520, cy: 170, rx: 340, ry: 150, rot: -8,  col: "#16362c", str: 0.6,  prec: 0.35 },
    { cx: 150, cy: 520, rx: 240, ry: 190, rot: -15, col: "#143228", str: 0.6,  prec: 0.3 },
    { cx: 860, cy: 220, rx: 320, ry: 170, rot: -5,  col: "#0f2720", str: 0.55, prec: 0.35 },
    // Midground viridian-forest felt planes
    { cx: 310, cy: 840, rx: 350, ry: 210, rot: -10, col: "#0c211b", str: 0.7,  prec: 0.35 },
    { cx: 640, cy: 960, rx: 400, ry: 220, rot: -6,  col: "#091a15", str: 0.75, prec: 0.3 },
    { cx: 980, cy: 520, rx: 280, ry: 210, rot: -14, col: "#0b1e18", str: 0.65, prec: 0.35 },
    { cx: 1020, cy: 980, rx: 320, ry: 220, rot: -8, col: "#06120e", str: 0.8,  prec: 0.3 },
    // Gentle raking ridge highlights in the felt pad
    { cx: 180, cy: 290, rx: 210, ry: 65,  rot: -18, col: "#234d40", str: 0.45, prec: 0.4 },
    { cx: 480, cy: 195, rx: 240, ry: 55,  rot: -14, col: "#1e4438", str: 0.4,  prec: 0.4 },
    { cx: 210, cy: 760, rx: 220, ry: 60,  rot: -16, col: "#15332a", str: 0.45, prec: 0.4 }
  ];

  for (let p of feltMassPatches) {
    let pts = makeEllipsePoly(p.cx, p.cy, p.rx, p.ry, p.rot, 24);
    brush.mass("charcoal", p.col, {
      precision: p.prec,
      strength: p.str,
      gradient: 0.65,
      outline: false
    });
    drawPoly(pts, 0.2);
  }
  brush.noMass();

  // Subtle diagonal jeweller's pad crease in the upper right and lower left
  brush.field("feltNap");
  const feltColors = ["#071410", "#0c221b", "#133027", "#1b4034", "#245243", "#050d0a"];
  for (let cIdx = 0; cIdx < feltColors.length; cIdx++) {
    let col = feltColors[cIdx];
    brush.set("charcoal", col, 0.55);
    let count = 130;
    for (let i = 0; i < count; i++) {
      let x = random(-40, 1240);
      let y = random(-40, 1240);
      // Weight brighter colors toward upper-left raking light
      let lightBias = (x / 1200) * 0.6 + (y / 1200) * 0.4;
      if ((cIdx === 3 || cIdx === 4) && lightBias > 0.62) continue;
      if (cIdx === 5 && lightBias < 0.35) continue;
      let len = random(35, 95);
      brush.flowLine(x, y, len, random(-22, -6));
    }
  }

  // Fine raking surface fibers catching the low light
  brush.set("2B", "#2d6150", 0.35);
  for (let i = 0; i < 160; i++) {
    let x = random(20, 950);
    let y = random(20, 880);
    if (x + y < 1150) {
      brush.flowLine(x, y, random(18, 45), random(-20, -8));
    }
  }
  brush.noField();
}

