// =============================================================================
// 3. LABRADORITE SLAB: THICK VERTICAL SIDE WALLS & CHAMFER BEVEL
// =============================================================================

function drawSlabSideWalls() {
  brush.noStroke();
  brush.noFill();

  // Four visible front/side vertical facets of the thick slab (from P0->P7->P6->P5->P4)
  const wallLeft = [
    bevelOuterPts[0], bevelOuterPts[7], bottomWallPts[7], bottomWallPts[0]
  ];
  const wallCenter = [
    bevelOuterPts[7], bevelOuterPts[6], bottomWallPts[6], bottomWallPts[7]
  ];
  const wallRight = [
    bevelOuterPts[6], bevelOuterPts[5], bottomWallPts[5], bottomWallPts[6]
  ];
  const wallFarRight = [
    bevelOuterPts[5], bevelOuterPts[4], bottomWallPts[4], bottomWallPts[5]
  ];

  // Opaque mineral base washes for the vertical walls
  brush.wash("#1c2329", 255);
  drawPoly(wallLeft, 0);

  brush.wash("#161d22", 255);
  drawPoly(wallCenter, 0);

  brush.wash("#101519", 255);
  drawPoly(wallRight, 0);

  brush.wash("#0b0f12", 255);
  drawPoly(wallFarRight, 0);
  brush.noWash();

  // Sub-surface labradorescence continuation on the front-center vertical wall!
  // Where the flash band intersects the front edge (x ~ 435 to 615)
  const sideFlashBlue = [
    [435, 663], [528, 659], [534, 738], [440, 741]
  ];
  const sideFlashGold = [
    [524, 659], [558, 658], [564, 736], [530, 738]
  ];
  const sideFlashCopper = [
    [555, 658], [571, 658], [577, 736], [561, 736]
  ];

  brush.wash("#488899", 170);
  drawPoly(sideFlashBlue, 0);
  brush.wash("#7a6832", 150);
  drawPoly(sideFlashGold, 0);
  brush.wash("#6e3520", 150);
  drawPoly(sideFlashCopper, 0);
  brush.noWash();

  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.6, 0.4);
  brush.fill("#00b0ff", 110);
  drawPoly(sideFlashBlue, 0);
  brush.fill("#00e5ff", 75);
  drawPoly([[455, 662], [515, 660], [520, 725], [460, 728]], 0);
  brush.fill("#ffab00", 95);
  drawPoly(sideFlashGold, 0);
  brush.fill("#dd2c00", 95);
  drawPoly(sideFlashCopper, 0);
  brush.noFill();

  // Charcoal & graphite texture on the rough-sawn / semi-polished vertical slab edges
  brush.mass("charcoal", "#12171c", { precision: 0.5, strength: 0.55, gradient: 0.5, outline: false });
  drawPoly(wallLeft, 0);
  brush.mass("charcoal", "#0c1014", { precision: 0.5, strength: 0.65, gradient: 0.5, outline: false });
  drawPoly(wallRight, 0);
  drawPoly(wallFarRight, 0);
  brush.noMass();

  // Horizontal lamellar bedding and cleavage steps on the vertical front walls
  const frontSegments = [
    { pA: bevelOuterPts[0], pB: bevelOuterPts[7], bA: bottomWallPts[0], bB: bottomWallPts[7], shade: "left" },
    { pA: bevelOuterPts[7], pB: bevelOuterPts[6], bA: bottomWallPts[7], bB: bottomWallPts[6], shade: "center" },
    { pA: bevelOuterPts[6], pB: bevelOuterPts[5], bA: bottomWallPts[6], bB: bottomWallPts[5], shade: "right" },
    { pA: bevelOuterPts[5], pB: bevelOuterPts[4], bA: bottomWallPts[5], bB: bottomWallPts[4], shade: "farRight" }
  ];

  for (let seg of frontSegments) {
    // Cleavage striations continuing down the vertical face
    let steps = 38;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let tx = lerp(seg.pA[0], seg.pB[0], t);
      let ty = lerp(seg.pA[1], seg.pB[1], t);
      let bx = lerp(seg.bA[0], seg.bB[0], t) + random(-3, 3);
      let by = lerp(seg.bA[1], seg.bB[1], t);

      let col = "#0d1217";
      let w = random(0.22, 0.42);
      if (seg.shade === "left") {
        col = random() < 0.4 ? "#38434d" : "#151b21";
      } else if (seg.shade === "center") {
        if (tx > 438 && tx < 528) col = random() < 0.55 ? "#29b6f6" : "#072a3a";
        else if (tx >= 528 && tx < 556) col = random() < 0.5 ? "#ffca28" : "#3b2c0c";
        else if (tx >= 556 && tx <= 573) col = random() < 0.5 ? "#ff7043" : "#2e1208";
        else col = random() < 0.35 ? "#2e3842" : "#0e1318";
      } else {
        col = random() < 0.25 ? "#222a32" : "#070a0d";
      }
      brush.set("rotring", col, w);
      brush.line(tx, ty, bx, by);
    }

    // Sub-horizontal lamellar step lines along the vertical edge
    for (let k = 1; k < 8; k++) {
      let vf = k / 8 + random(-0.03, 0.03);
      let x1 = lerp(seg.pA[0], seg.bA[0], vf);
      let y1 = lerp(seg.pA[1], seg.bA[1], vf);
      let x2 = lerp(seg.pB[0], seg.bB[0], vf);
      let y2 = lerp(seg.pB[1], seg.bB[1], vf);
      brush.set("pen", "#090d10", 0.28);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Draw the perimeter chamfer/bevel ring base between bevelOuterPts and topFacePts
  for (let i = 0; i < 8; i++) {
    let j = (i + 1) % 8;
    let quadPts = [topFacePts[i], topFacePts[j], bevelOuterPts[j], bevelOuterPts[i]];
    // Upper-left bevels catch bright raking light; lower-right bevels are dark slate
    let bevelCols = ["#586673", "#687887", "#505d69", "#343e47", "#1e242b", "#242c34", "#2f3942", "#424e59"];
    brush. noStroke();
    brush.wash(bevelCols[i], 255);
    drawPoly(quadPts, 0);
  }
  brush.noWash();
}

// =============================================================================
// 4. LABRADORITE SLAB: OPAQUE UNDERPAINTING
// =============================================================================

function drawSlabUnderpainting() {
  brush.noStroke();
  brush.noFill();

  // Base smoky-grey mineral wash across the entire top polished face
  brush.wash("#283038", 255);
  drawPoly(topFacePts, 0);

  // Build stepped strip underpainting across the crystal coordinate frame
  // Smoky grey regions get cool slate shades; the flash corridor gets a luminous
  // pale mineral ground so subsequent transparent watercolor glazes glow from within!
  const vBlocks = [-220, -118, -42, 36, 108, 220];

  for (let b = 0; b < vBlocks.length - 1; b++) {
    let v0 = vBlocks[b] - 2;
    let v1 = vBlocks[b + 1] + 2;

    // Step through u strips
    for (let u = -340; u < 360; u += 14) {
      let uMid = u + 7;
      let vMid = (v0 + v1) * 0.5;
      let info = getLabradoriteZone(uMid, vMid);

      let col = "#283038";
      let op = 230;

      if (info.zone === "smoky_west") {
        // Cool smoky grey, slightly lighter toward raking light on upper-left
        col = (uMid < -200) ? "#36404a" : "#272f37";
        op = 220;
      } else if (info.zone === "indigo_border") {
        col = "#1c4359";
        op = 235;
      } else if (info.zone === "peacock_blue") {
        // Luminous pale cyan-ice ground for electric peacock watercolor glazes
        let bright = sin(info.t * 180);
        col = bright > 0.55 ? "#d8fbff" : "#9beaf5";
        op = 245;
      } else if (info.zone === "turquoise_bridge") {
        col = "#c8f7dc";
        op = 240;
      } else if (info.zone === "gold_band") {
        // Luminous warm ivory-gold ground for gold watercolor glazes
        col = info.t < 0.55 ? "#fff6c4" : "#ffe699";
        op = 245;
      } else if (info.zone === "copper_edge") {
        // Luminous peach-copper ground for the fiery copper edge
        col = "#ffd5bd";
        op = 240;
      } else if (info.zone === "extinction_rim") {
        col = "#161b20";
        op = 240;
      } else {
        // Smoky grey east
        col = (uMid > 240) ? "#232a31" : "#2c343d";
        op = 225;
      }

      // Construct crystal quad in screen space and clip to topFacePts
      let rawQuad = [
        toScreenCoords(u - 1, v0),
        toScreenCoords(u + 15, v0),
        toScreenCoords(u + 15, v1),
        toScreenCoords(u - 1, v1)
      ];
      let clipped = clipPolygon(rawQuad, topFacePts);
      if (polyArea(clipped) > 12) {
        brush.wash(col, op);
        drawPoly(clipped, 0);
      }
    }
  }
  brush.noWash();
}

// =============================================================================
// 5. LABRADORITE SLAB: TRANSPARENT OVERLAPPING WATERCOLOUR GLAZES
// =============================================================================

function drawSlabWatercolorGlazes() {
  brush.noStroke();
  brush.noWash();

  // We batch watercolor glazes by color family for rich transparent veils and bleeding.
  // First: Broad atmospheric watercolor veils across the smoky grey zones and flash band
  const broadVeils = [
    // Smoky grey west clouds (cool slate, charcoal, ghostly steel-blue)
    { u0: -340, u1: -85,  v0: -210, v1: 20,   col: "#313b45", op: 85, bleed: 0.22 },
    { u0: -320, u1: -95,  v0: -30,  v1: 210,  col: "#20272e", op: 95, bleed: 0.24 },
    { u0: -250, u1: -110, v0: -140, v1: 110,  col: "#283642", op: 75, bleed: 0.20 },
    { u0: -180, u1: -82,  v0: -190, v1: 190,  col: "#192026", op: 90, bleed: 0.18 },

    // Emerging Prussian & deep marine border
    { u0: -102, u1: -45,  v0: -210, v1: 210,  col: "#06344d", op: 105, bleed: 0.22 },
    { u0: -82,  u1: -32,  v0: -180, v1: 185,  col: "#005b7f", op: 95,  bleed: 0.20 },

    // Electric Peacock Blue broad glowing veils
    { u0: -62,  u1: 44,   v0: -210, v1: 210,  col: "#00b0ff", op: 90,  bleed: 0.24 },
    { u0: -48,  u1: 28,   v0: -195, v1: 195,  col: "#00e5ff", op: 85,  bleed: 0.22 },
    { u0: -25,  u1: 48,   v0: -175, v1: 180,  col: "#00838f", op: 75,  bleed: 0.20 },
    { u0: -55,  u1: 10,   v0: -120, v1: 135,  col: "#0077be", op: 80,  bleed: 0.18 },

    // Turquoise-emerald optical bridge
    { u0: 32,   u1: 70,   v0: -205, v1: 205,  col: "#00bfa5", op: 85,  bleed: 0.20 },
    { u0: 45,   u1: 76,   v0: -180, v1: 185,  col: "#aeea00", op: 65,  bleed: 0.18 },

    // Luminous Gold broad veils
    { u0: 58,   u1: 114,  v0: -210, v1: 210,  col: "#ffd600", op: 95,  bleed: 0.20 },
    { u0: 70,   u1: 116,  v0: -190, v1: 190,  col: "#ffab00", op: 90,  bleed: 0.18 },
    { u0: 82,   u1: 118,  v0: -140, v1: 155,  col: "#ff8f00", op: 75,  bleed: 0.16 },

    // Thin Edge of Copper
    { u0: 106,  u1: 136,  v0: -210, v1: 210,  col: "#ff6d00", op: 100, bleed: 0.16 },
    { u0: 114,  u1: 138,  v0: -195, v1: 195,  col: "#dd2c00", op: 95,  bleed: 0.14 },

    // Extinction shadow & Smoky grey east veils
    { u0: 130,  u1: 168,  v0: -210, v1: 210,  col: "#12171c", op: 115, bleed: 0.18 },
    { u0: 148,  u1: 360,  v0: -210, v1: 40,   col: "#262e36", op: 90,  bleed: 0.24 },
    { u0: 150,  u1: 360,  v0: -20,  v1: 210,  col: "#1c2229", op: 100, bleed: 0.24 },
    { u0: 195,  u1: 310,  v0: -140, v1: 130,  col: "#2d3740", op: 75,  bleed: 0.20 }
  ];

  for (let v of broadVeils) {
    let rawPoly = [
      toScreenCoords(v.u0, v.v0),
      toScreenCoords(v.u1, v.v0),
      toScreenCoords(v.u1, v.v1),
      toScreenCoords(v.u0, v.v1)
    ];
    let clipped = clipPolygon(rawPoly, topFacePts);
    if (polyArea(clipped) > 25) {
      brush.fillBleed(v.bleed, "in");
      brush.fillTexture(0.6, 0.38);
      brush.fill(v.col, v.op);
      drawPoly(clipped, 0);
    }
  }

  // Second: Stepped Lamellar Shingles (overlapping crystal plates shifted by fractures)
  // Grouped by color palette for optimal p5.brush watercolor caching and richness
  const vBands = [
    [-205, -118],
    [-118, -42],
    [-42, 36],
    [36, 108],
    [108, 205]
  ];

  let shingleBatches = {};
  let addShingle = (col, op, bleed, poly) => {
    let key = col + "_" + op;
    if (!shingleBatches[key]) shingleBatches[key] = { col, op, bleed, polys: [] };
    shingleBatches[key].polys.push(poly);
  };

  for (let b = 0; b < vBands.length; b++) {
    let vStart = vBands[b][0];
    let vEnd = vBands[b][1];
    let vMid = (vStart + vEnd) * 0.5;

    // Create stepped lamellar ribbons across u
    for (let u = -290; u < 320; u += 11) {
      let info = getLabradoriteZone(u + 5, vMid);
      let w = random(9, 18);
      let dv0 = vStart + random(-6, 8);
      let dv1 = vEnd + random(-8, 6);

      let col = null;
      let op = 75;
      let bleed = 0.12;

      if (info.zone === "smoky_west") {
        if (random() < 0.45) {
          col = random(["#1e242b", "#2c353e", "#39444f", "#232c34"]);
          op = 65;
        }
      } else if (info.zone === "indigo_border") {
        col = random(["#05293d", "#084461", "#006080", "#102838"]);
        op = 90;
      } else if (info.zone === "peacock_blue") {
        col = random(["#00e5ff", "#00b0ff", "#0091ea", "#00bcd4", "#006064", "#1de9b6", "#01579b"]);
        op = floor(random(65, 105));
        bleed = 0.14;
      } else if (info.zone === "turquoise_bridge") {
        col = random(["#00bfa5", "#00e676", "#64dd17", "#1de9b6", "#00acc1"]);
        op = 80;
      } else if (info.zone === "gold_band") {
        col = random(["#ffd600", "#ffab00", "#ffc400", "#ff8f00", "#ffe57f", "#c6a700"]);
        op = floor(random(70, 105));
        bleed = 0.13;
      } else if (info.zone === "copper_edge") {
        col = random(["#ff6d00", "#dd2c00", "#bf360c", "#ff3d00", "#e65100"]);
        op = 95;
        bleed = 0.11;
      } else if (info.zone === "extinction_rim") {
        col = random(["#0f1419", "#171e24", "#241914"]);
        op = 95;
      } else if (info.zone === "smoky_east") {
        if (random() < 0.45) {
          col = random(["#181e24", "#252d36", "#313b45", "#1f262e"]);
          op = 70;
        }
      }

      if (col) {
        let rawQuad = [
          toScreenCoords(u, dv0),
          toScreenCoords(u + w, dv0 + random(-4, 4)),
          toScreenCoords(u + w, dv1 + random(-4, 4)),
          toScreenCoords(u, dv1)
        ];
        let clipped = clipPolygon(rawQuad, topFacePts);
        if (polyArea(clipped) > 15) {
          addShingle(col, op, bleed, clipped);
        }
      }
    }
  }

  // Render all batched watercolor lamellar shingles
  for (let key in shingleBatches) {
    let batch = shingleBatches[key];
    brush.fillBleed(batch.bleed, "in");
    brush.fillTexture(0.65, 0.42);
    brush.fill(batch.col, batch.op);
    for (let poly of batch.polys) {
      drawPoly(poly, 0);
    }
  }
  brush.noFill();

  // Third: Sub-surface glowing heart inside the brightest lamellar plates
  // (Re-injects pure optical brilliance where light hits the exact Bragg angle)
  for (let b = 0; b < vBands.length; b++) {
    let v0 = vBands[b][0] + 6;
    let v1 = vBands[b][1] - 6;
    let vMid = (v0 + v1) * 0.5;
    if (abs(vMid) > 155) continue;

    for (let u = -52; u <= 126; u += 9) {
      let info = getLabradoriteZone(u + 4, vMid);
      if (random() > 0.58) continue;

      let glowCol = null;
      let glowOp = 90;
      if (info.zone === "peacock_blue") {
        glowCol = random() < 0.5 ? "#84ffff" : "#00e5ff";
        glowOp = random(70, 115);
      } else if (info.zone === "turquoise_bridge") {
        glowCol = "#69f0ae";
        glowOp = 75;
      } else if (info.zone === "gold_band") {
        glowCol = random() < 0.5 ? "#fff59d" : "#ffd740";
        glowOp = random(75, 110);
      } else if (info.zone === "copper_edge") {
        glowCol = "#ff8a65";
        glowOp = 85;
      }

      if (glowCol) {
        let subV0 = lerp(v0, v1, random(0.05, 0.35));
        let subV1 = lerp(v0, v1, random(0.65, 0.95));
        let rawSliver = [
          toScreenCoords(u, subV0),
          toScreenCoords(u + random(4, 9), subV0),
          toScreenCoords(u + random(4, 9), subV1),
          toScreenCoords(u, subV1)
        ];
        let clipped = clipPolygon(rawSliver, topFacePts);
        if (polyArea(clipped) > 8) {
          brush.wash(glowCol, glowOp);
          drawPoly(clipped, 0);
        }
      }
    }
  }
  brush.noWash();

  // Final delicate transparent watercolor veil over the flash corridor to unify the inner glow
  let unifyBlue = clipPolygon([
    toScreenCoords(-55, -180),
    toScreenCoords(45, -180),
    toScreenCoords(45, 180),
    toScreenCoords(-55, 180)
  ], topFacePts);
  let unifyGold = clipPolygon([
    toScreenCoords(55, -180),
    toScreenCoords(132, -180),
    toScreenCoords(132, 180),
    toScreenCoords(55, 180)
  ], topFacePts);

  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.45, 0.3);
  brush.fill("#00b8d4", 38);
  drawPoly(unifyBlue, 0);
  brush.fill("#ffab00", 34);
  drawPoly(unifyGold, 0);
  brush.noFill();
}

// =============================================================================
// 6. LABRADORITE SLAB: CLEAVAGE STRIATIONS, FRACTURES & INTERNAL SCHILLER
// =============================================================================

function drawSlabCleavageAndLamellae() {
  brush.noFill();
  brush.noWash();
  brush.noMass();

  // A. Fine Polysynthetic Twinning Striations (the signature parallel ruler-lines of labradorite)
  // Every striation runs along v, steps laterally at the transverse fractures, and adapts its
  // ink/color to the exact optical zone it traverses.
  for (let uBase = -335; uBase <= 345; uBase += 3.2) {
    // Vary spacing slightly like natural crystal twin lamellae
    let u = uBase + (noise(uBase * 0.25) - 0.5) * 2.2;

    // Trace between consecutive transverse fractures
    let vBreaks = [-230, -118, -42, 36, 108, 230];
    for (let b = 0; b < vBreaks.length - 1; b++) {
      let vStart = vBreaks[b];
      let vEnd = vBreaks[b + 1];
      let vMid = (vStart + vEnd) * 0.5;

      // Exact fracture boundary curves
      if (b > 0) {
        let f = FRACTURES[b - 1];
        vStart = f.v + sin(u * f.freq * 57.3) * f.amp;
      }
      if (b < FRACTURES.length) {
        let f = FRACTURES[b];
        vEnd = f.v + sin(u * f.freq * 57.3) * f.amp;
      }

      // Compute slight physical offset of the cleavage striation in this fracture block
      let blockShift = 0;
      if (b === 0) blockShift = -4.5;
      else if (b === 1) blockShift = 2.5;
      else if (b === 2) blockShift = -3.5;
      else if (b === 3) blockShift = 5.0;
      else blockShift = 0.5;

      let uActual = u + blockShift;
      let info = getLabradoriteZone(u, vMid);

      // Clip segment (uActual, vStart) -> (uActual, vEnd) against topFacePts
      let p1 = toScreenCoords(uActual, vStart);
      let p2 = toScreenCoords(uActual, vEnd);

      // Subdivide into smaller chords so we stay strictly inside topFacePts
      let steps = 4;
      for (let s = 0; s < steps; s++) {
        let t0 = s / steps;
        let t1 = (s + 1) / steps;
        let sx0 = lerp(p1[0], p2[0], t0);
        let sy0 = lerp(p1[1], p2[1], t0);
        let sx1 = lerp(p1[0], p2[0], t1);
        let sy1 = lerp(p1[1], p2[1], t1);
        let mx = (sx0 + sx1) * 0.5;
        let my = (sy0 + sy1) * 0.5;

        if (!pointInConvexPoly(mx, my, topFacePts)) continue;
        if (!pointInConvexPoly(sx0, sy0, topFacePts) || !pointInConvexPoly(sx1, sy1, topFacePts)) {
          // Pull endpoints slightly inward toward midpoint if near boundary
          sx0 = lerp(mx, sx0, 0.7);
          sy0 = lerp(my, sy0, 0.7);
          sx1 = lerp(mx, sx1, 0.7);
          sy1 = lerp(my, sy1, 0.7);
          if (!pointInConvexPoly(sx0, sy0, topFacePts) || !pointInConvexPoly(sx1, sy1, topFacePts)) continue;
        }

        // Select pen style & color based on gemological zone
        let col = "#1a2128";
        let weight = 0.24;
        let brushName = "rotring";
        let drawProb = 0.78;

        if (info.zone === "smoky_west") {
          drawProb = 0.62;
          col = random(["#141a20", "#1e262e", "#3d4854", "#4f5d6b"]);
          weight = random(0.18, 0.30);
        } else if (info.zone === "indigo_border") {
          drawProb = 0.85;
          col = random(["#041b29", "#006994", "#29b6f6", "#072f42"]);
          weight = random(0.22, 0.36);
        } else if (info.zone === "peacock_blue") {
          drawProb = 0.92;
          let r = random();
          if (r < 0.35) {
            col = "#b2ffff"; // bright internal cleavage reflection
            weight = random(0.22, 0.38);
          } else if (r < 0.68) {
            col = "#00e5ff";
            weight = random(0.25, 0.42);
          } else {
            col = "#032633"; // sharp dark twin boundary groove
            weight = random(0.20, 0.34);
          }
        } else if (info.zone === "turquoise_bridge") {
          drawProb = 0.88;
          col = random(["#64ffda", "#b9f6ca", "#004d40", "#aeea00"]);
          weight = random(0.22, 0.36);
        } else if (info.zone === "gold_band") {
          drawProb = 0.90;
          let r = random();
          if (r < 0.38) {
            col = "#fff9c4";
            weight = random(0.22, 0.38);
          } else if (r < 0.72) {
            col = "#ffc107";
            weight = random(0.24, 0.40);
          } else {
            col = "#3d2606"; // dark bronze twin line
            weight = random(0.20, 0.32);
          }
        } else if (info.zone === "copper_edge") {
          drawProb = 0.94;
          col = random(["#ffab91", "#ff5722", "#ff3d00", "#2b0d04"]);
          weight = random(0.22, 0.38);
        } else if (info.zone === "extinction_rim") {
          drawProb = 0.80;
          col = random(["#090d11", "#161d24", "#3b2316"]);
          weight = random(0.22, 0.34);
        } else {
          drawProb = 0.60;
          col = random(["#12171c", "#1d242b", "#37424d", "#485461"]);
          weight = random(0.18, 0.28);
        }

        if (random() < drawProb) {
          brush.set(brushName, col, weight);
          brush.line(sx0, sy0, sx1, sy1);
        }
      }
    }
  }

  // B. Oriented Acicular Inclusions (Fine ilmenite/rutile needles at crystallographic angles)
  for (let i = 0; i < 220; i++) {
    let u = random(-280, 290);
    let v = random(-195, 195);
    let pt = toScreenCoords(u, v);
    if (!pointInConvexPoly(pt[0], pt[1], topFacePts)) continue;

    let info = getLabradoriteZone(u, v);
    // Needles orient either along cleavage (63 deg) or secondary twin plane (-12 deg or +118 deg)
    let ang = random() < 0.55 ? CLEAVAGE_ANGLE : (random() < 0.5 ? -12 : 118);
    let len = random(8, 28);
    let x2 = pt[0] + cos(ang) * len;
    let y2 = pt[1] + sin(ang) * len;
    if (!pointInConvexPoly(x2, y2, topFacePts)) continue;

    let col = "#0d1217";
    let w = random(0.18, 0.32);
    if (info.zone === "peacock_blue") {
      col = random() < 0.6 ? "#e0ffff" : "#041c24";
    } else if (info.zone === "gold_band") {
      col = random() < 0.6 ? "#fff8e1" : "#261905";
    } else if (info.zone === "copper_edge") {
      col = random() < 0.6 ? "#ffccbc" : "#240a03";
    } else {
      col = random() < 0.3 ? "#546270" : "#0f1419";
    }

    brush.set("rotring", col, w);
    brush.line(pt[0], pt[1], x2, y2);
  }

  // C. Transverse Stepped Cleavage Fractures & Internal Iridescent Feathers
  for (let fIdx = 0; fIdx < FRACTURES.length; fIdx++) {
    let f = FRACTURES[fIdx];
    let shadowPts = [];
    let lightPts = [];

    for (let u = -330; u <= 340; u += 10) {
      let fv = f.v + sin(u * f.freq * 57.3) * f.amp + (noise(u * 0.05, fIdx) - 0.5) * 6;
      let p = toScreenCoords(u, fv);
      if (pointInConvexPoly(p[0], p[1], topFacePts)) {
        shadowPts.push([p[0], p[1], random(0.4, 1.1)]);
        lightPts.push([p[0] + 1.8, p[1] - 1.8, random(0.3, 0.9)]);

        // Draw delicate internal cleavage "feather" steps along the fracture plane
        if (random() < 0.65) {
          let info = getLabradoriteZone(u, fv);
          let fCol = "#4a5866";
          if (info.zone === "peacock_blue") fCol = "#84ffff";
          else if (info.zone === "gold_band") fCol = "#ffe57f";
          else if (info.zone === "copper_edge") fCol = "#ff9e80";

          brush.set("2H", fCol, 0.25);
          let featherLen = random(6, 18);
          brush.line(
            p[0], p[1],
            p[0] + cos(CLEAVAGE_ANGLE) * featherLen,
            p[1] + sin(CLEAVAGE_ANGLE) * featherLen
          );
        }
      }
    }

    if (shadowPts.length > 3) {
      // Dark internal fracture shadow line
      brush.set("rotring", "#0b1015", 0.42);
      brush.spline(shadowPts, 0.25);
      // Crisp raking light edge catching the stepped cleavage plane
      brush.set("rotring", "#7e93a6", 0.26);
      brush.spline(lightPts, 0.25);
    }
  }
}

// =============================================================================
// 7. LABRADORITE SLAB: CHAMFER HIGHLIGHTS & VITREOUS SURFACE POLISH
// =============================================================================

function drawSlabBevelAndPolish() {
  // Vitreous raking sheen across the flat polished top face
  // (Low-opacity diagonal pencil/marker strokes at the raking light angle ~ -22 deg)
  for (let i = 0; i < 85; i++) {
    let x1 = random(145, 760);
    let y1 = random(280, 635);
    let len = random(35, 110);
    let x2 = x1 + cos(-22) * len;
    let y2 = y1 + sin(-22) * len;
    if (pointInConvexPoly(x1, y1, topFacePts) && pointInConvexPoly(x2, y2, topFacePts)) {
      brush.set("2H", "#d4e6f1", 0.22);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Crisp gemological bevel edges around the polished top face and outer chamfer
  for (let i = 0; i < 8; i++) {
    let j = (i + 1) % 8;
    let A = topFacePts[i];
    let B = topFacePts[j];
    let OA = bevelOuterPts[i];
    let OB = bevelOuterPts[j];

    // Inner bevel ridge (between top face and chamfer)
    let isLitEdge = (i === 0 || i === 1 || i === 2 || i === 6 || i === 7);
    let ridgeCol = isLitEdge ? "#9cb0c2" : "#38434f";
    let ridgeW = isLitEdge ? 0.48 : 0.35;
    brush.set("rotring", ridgeCol, ridgeW);
    brush.line(A[0], A[1], B[0], B[1]);

    // Specular glints on the raking-lit bevel edges
    if (i === 0 || i === 1 || i === 7) {
      brush.set("pen", "#e1f5fe", 0.38);
      let gx1 = lerp(A[0], B[0], 0.15);
      let gy1 = lerp(A[1], B[1], 0.15);
      let gx2 = lerp(A[0], B[0], 0.85);
      let gy2 = lerp(A[1], B[1], 0.85);
      brush.line(gx1, gy1, gx2, gy2);
    }

    // Where the flash band crosses the front bevel (edge 6: P6->P7 and edge 2: P2->P3)
    if (i === 6) {
      // Peacock blue & gold specular along the front polished chamfer ridge
      brush.set("pen", "#80d8ff", 0.52);
      brush.line(lerp(A[0], B[0], 0.18), lerp(A[1], B[1], 0.18), lerp(A[0], B[0], 0.52), lerp(A[1], B[1], 0.52));
      brush.set("pen", "#ffe57f", 0.48);
      brush.line(lerp(A[0], B[0], 0.06), lerp(A[1], B[1], 0.06), lerp(A[0], B[0], 0.18), lerp(A[1], B[1], 0.18));
    }

    // Outer chamfer edge
    brush.set("rotring", "#12181f", 0.42);
    brush.line(OA[0], OA[1], OB[0], OB[1]);

    // Miter facet line at each corner of the chamfer
    brush.set("rotring", isLitEdge ? "#7b8d9e" : "#1c242c", 0.35);
    brush.line(A[0], A[1], OA[0], OA[1]);
  }
}

// =============================================================================
// 8. BRASS JEWELLER'S LOUPE (10x Triplet Magnifier beside the Stone)
// =============================================================================

function drawBrassLoupe() {
  // Loupe geometry in low raking perspective:
  // Main cylindrical lens housing centered at (838, 795), tilted slightly
  // Swivel teardrop cover hinged at (912, 762) and swung open to (1052, 672)

  const lCx = 838;
  const lCy = 795;
  const lRx = 88;
  const lRy = 58;
  const barrelH = 42;

  const hCx = 914;
  const hCy = 758;
  const tCx = 1048;
  const tCy = 678;

  brush.noStroke();
  brush.noFill();

  // --- PART A: FOLDED TEARDROP BRASS COVER (SWUNG OPEN TO THE RIGHT) ---
  // 1. Lower teardrop brass plate & dark interior cavity
  let coverLowerPts = [];
  for (let a = 115; a <= 285; a += 15) {
    coverLowerPts.push([hCx + cos(a) * 44, hCy + 34 + sin(a) * 30]);
  }
  for (let a = -65; a <= 115; a += 12) {
    coverLowerPts.push([tCx + cos(a) * 54, tCy + 34 + sin(a) * 36]);
  }

  // Curved vertical side-wall of the teardrop shroud around the far end
  let shroudWallPts = [];
  for (let a = -55; a <= 105; a += 10) {
    shroudWallPts.push([tCx + cos(a) * 54, tCy + sin(a) * 36]);
  }
  for (let a = 105; a >= -55; a -= 10) {
    shroudWallPts.push([tCx + cos(a) * 54, tCy + 38 + sin(a) * 36]);
  }

  // Upper teardrop brass plate
  let coverUpperPts = [];
  for (let a = 115; a <= 285; a += 15) {
    coverUpperPts.push([hCx + cos(a) * 44, hCy + sin(a) * 30]);
  }
  for (let a = -65; a <= 115; a += 12) {
    coverUpperPts.push([tCx + cos(a) * 54, tCy + sin(a) * 36]);
  }

  // Lanyard bail / small brass ring at the tip of the loupe cover (1098, 668)
  let bailOuter = makeEllipsePoly(1100, 672, 20, 14, -25, 20);
  let bailInner = makeEllipsePoly(1100, 672, 10, 7, -25, 16);

  // Render bail
  brush.wash("#8c6d2e", 255);
  drawPoly(bailOuter, 0.2);
  brush.wash("#071410", 255);
  drawPoly(bailInner, 0.2);

  // Render lower plate & dark interior of the open shroud
  brush.wash("#241a08", 255);
  drawPoly(coverLowerPts, 0.15);

  // Render curved outer brass wall of the shroud
  brush.wash("#6e521f", 255);
  drawPoly(shroudWallPts, 0.1);

  // Vertical metallic reflections on the shroud wall
  for (let i = 0; i < 28; i++) {
    let ang = map(i, 0, 27, -50, 100);
    let x = tCx + cos(ang) * 54;
    let yTop = tCy + sin(ang) * 36;
    let yBot = yTop + 38;
    let col = "#4a3612";
    if (ang > -15 && ang < 25) col = "#e6c770"; // bright brass highlight band
    else if (ang >= 25 && ang < 55) col = "#b58e3e";
    else if (ang < -25) col = "#2b1f09";
    brush.set("rotring", col, 0.55);
    brush.line(x, yTop, x, yBot);
  }

  // Render upper teardrop brass plate
  brush.noStroke();
  brush.wash("#a88438", 255);
  drawPoly(coverUpperPts, 0.15);
  brush.noWash();

  // Watercolor & dry-media metallic shading on the upper teardrop plate
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.5, 0.35);
  brush.fill("#c9a046", 110);
  drawPoly(coverUpperPts, 0.15);

  // Bright raking highlight across the upper-left curve of the teardrop plate
  let plateHighlight = [
    [hCx - 15, hCy - 24],
    [tCx - 10, tCy - 32],
    [tCx + 28, tCy - 12],
    [hCx + 20, hCy - 4]
  ];
  brush.wash("#f2da8a", 180);
  drawPoly(plateHighlight, 0.2);
  brush.wash("#fff8d6", 140);
  drawPoly([
    [hCx - 5, hCy - 20],
    [tCx - 8, tCy - 27],
    [tCx + 10, tCy - 18],
    [hCx + 8, hCy - 10]
  ], 0.2);
  brush.noWash();

  // Darker bronze reflection along the lower-right edge of the teardrop plate
  let plateShadow = [
    [hCx + 10, hCy + 8],
    [tCx + 15, tCy + 6],
    [tCx + 42, tCy + 24],
    [hCx + 25, hCy + 26]
  ];
  brush.fill("#4d3812", 130);
  drawPoly(plateShadow, 0.15);
  brush.noFill();

  // --- PART B: CYLINDRICAL BRASS LENS BARREL ---
  // Cylindrical wall dropping from (lCx, lCy) to (lCx, lCy + barrelH)
  let barrelWallPts = [];
  for (let a = -15; a <= 195; a += 8) {
    barrelWallPts.push([lCx + cos(a) * lRx, lCy + sin(a) * lRy]);
  }
  for (let a = 195; a >= -15; a -= 8) {
    barrelWallPts.push([lCx + cos(a) * lRx, lCy + barrelH + sin(a) * lRy]);
  }

  brush.noStroke();
  brush.wash("#594116", 255);
  drawPoly(barrelWallPts, 0.08);
  brush.noWash();

  // Machined vertical knurling & metallic reflections around the cylindrical barrel
  // Note: the left side (a ~ 135..185) faces the labradorite slab and catches a cool
  // peacock-cyan bounce glint alongside the warm raking light!
  let knurlSteps = 64;
  for (let i = 0; i <= knurlSteps; i++) {
    let a = map(i, 0, knurlSteps, -10, 192);
    let x = lCx + cos(a) * lRx;
    let y1 = lCy + sin(a) * lRy;
    let y2 = y1 + barrelH;

    // Base cylindrical reflection bands
    let col = "#3b2a0d";
    let w = 0.55;
    if (a >= 145 && a <= 178) {
      // Faces the glowing labradorite slab + raking light!
      col = (i % 2 === 0) ? "#64d8cb" : "#d4b459";
      w = 0.6;
    } else if (a >= 110 && a < 145) {
      // Primary bright brass specular zone
      col = (i % 2 === 0) ? "#fff3c4" : "#b8903c";
      w = 0.65;
    } else if (a >= 75 && a < 110) {
      col = (i % 2 === 0) ? "#8c6925" : "#261a07";
      w = 0.55;
    } else if (a >= 30 && a < 75) {
      // Secondary golden reflection band
      col = (i % 2 === 0) ? "#d9b359" : "#5e4517";
      w = 0.55;
    } else {
      col = (i % 2 === 0) ? "#473310" : "#1c1304";
      w = 0.5;
    }

    brush.set("rotring", col, w);
    brush.line(x, y1, x, y2);
  }

  // Top & bottom polished brass rings bordering the knurled grip band
  for (let ringOffset of [0, 7, barrelH - 6, barrelH]) {
    let ringPts = [];
    for (let a = -5; a <= 188; a += 8) {
      ringPts.push([lCx + cos(a) * (lRx + 0.8), lCy + ringOffset + sin(a) * (lRy + 0.5), 0.7]);
    }
    let ringCol = (ringOffset === 7 || ringOffset === barrelH - 6) ? "#241906" : "#dec068";
    brush.set("rotring", ringCol, 0.42);
    brush.spline(ringPts, 0.25);
  }

  // --- PART C: UPPER CONCENTRIC BRASS BEZEL & OPTICAL TRIPLET GLASS LENS ---
  let outerBezel = makeEllipsePoly(lCx, lCy, lRx, lRy, 0, 44);
  let midBezel   = makeEllipsePoly(lCx, lCy, lRx * 0.84, lRy * 0.84, 0, 40);
  let innerRing  = makeEllipsePoly(lCx, lCy + 2, lRx * 0.75, lRy * 0.75, 0, 40);
  let glassPoly  = makeEllipsePoly(lCx, lCy + 3, lRx * 0.71, lRy * 0.71, 0, 40);

  // Brass bezel top ring
  brush.noStroke();
  brush.wash("#9e7b32", 255);
  drawPoly(outerBezel, 0.15);

  // Metallic radial sheen on the brass bezel
  for (let a = 0; a < 360; a += 5) {
    let r1x = lRx * 0.75, r1y = lRy * 0.75;
    let r2x = lRx * 0.99, r2y = lRy * 0.99;
    let x1 = lCx + cos(a) * r1x;
    let y1 = lCy + sin(a) * r1y;
    let x2 = lCx + cos(a) * r2x;
    let y2 = lCy + sin(a) * r2y;

    let col = "#7d5f22";
    if (a > 125 && a < 175) col = "#fff6cc";      // bright raking light
    else if (a >= 175 && a < 215) col = "#80deea"; // cyan bounce from stone!
    else if (a >= 215 && a < 265) col = "#d4af37";
    else if (a >= 305 && a < 350) col = "#ebd282"; // opposite rim reflection
    else if (a >= 25 && a < 95) col = "#3b2b0d";   // dark bronze wave

    brush.set("rotring", col, 0.45);
    brush.line(x1, y1, x2, y2);
  }

  // Dark oxidized inner retaining flange inside the bezel
  brush.noStroke();
  brush.wash("#1b160c", 255);
  drawPoly(midBezel, 0.15);
  brush.wash("#0d1211", 255);
  drawPoly(innerRing, 0.15);

  // --- OPTICAL GLASS LENS (Magnifying the dark green felt + refracted cyan/gold glint) ---
  brush.wash("#0a241d", 255);
  drawPoly(glassPoly, 0.15);
  brush.noWash();

  // Watercolor glazes inside the lens for optical depth & convex refraction
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.45, 0.3);
  brush.fill("#134236", 130);
