const GCX = 716;   // Outer moon gate center X (off-centre)
const GCY = 526;   // Outer moon gate center Y
const GR  = 318;   // Outer moon gate radius

const IGX = 701;   // Inner opening center X (creates 3D architectural reveal)
const IGY = 520;   // Inner opening center Y
const IGR = 304;   // Inner opening radius

async function setup() {
