// Clip a polygon to a circle approximated as an N-gon (Sutherland-Hodgman)
function clipPolyToCircle(pts, cx, cy, r, segs = 56) {
  let poly = pts.map(p => [p[0], p[1]]);
  for (let i = 0; i < segs; i++) {
    let a1 = (i / segs) * 360;
    let a2 = ((i + 1) / segs) * 360;
    let x1 = cx + cos(a1) * r;
    let y1 = cy + sin(a1) * r;
    let x2 = cx + cos(a2) * r;
    let y2 = cy + sin(a2) * r;

    let input = poly;
    poly = [];
    if (input.length === 0) break;

    let nx = -(y2 - y1);
    let ny = (x2 - x1);

    let isInside = (p) => (p[0] - x1) * nx + (p[1] - y1) * ny <= 0;
    let intersect = (p1, p2) => {
      let d1 = (p1[0] - x1) * nx + (p1[1] - y1) * ny;
      let d2 = (p2[0] - x1) * nx + (p2[1] - y1) * ny;
      let t = d1 / (d1 - d2 + 1e-9);
      return [p1[0] + t * (p2[0] - p1[0]), p1[1] + t * (p2[1] - p1[1])];
    };

    for (let j = 0; j < input.length; j++) {
      let curr = input[j];
      let prev = input[(j + input.length - 1) % input.length];
      let cIn = isInside(curr);
      let pIn = isInside(prev);
      if (cIn) {
        if (!pIn) poly.push(intersect(prev, curr));
        poly.push(curr);
      } else if (pIn) {
        poly.push(intersect(prev, curr));
      }
    }
  }
  return poly;
}

function inInnerGate(x, y, margin = 0) {
  return dist(x, y, IGX, IGY) <= IGR - margin;
}

function inOuterGate(x, y, margin = 0) {
  return dist(x, y, GCX, GCY) <= GR - margin;
}

function drawClippedFillPoly(pts, col, alpha, bleed = 0.15, tex = 0.55, border = 0.35, curvature = 0.15) {
  let clipped = clipPolyToCircle(pts, IGX, IGY, IGR);
  if (clipped.length < 3) return;
  brush.noStroke();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let p of clipped) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noFill();
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm chalk-white paper ground
  background("#f5f2eb");

  // =========================================================================
