// SECTION 2B: GREY FLAGSTONE COURTYARD WITH MOSS SEAMS
// ---------------------------------------------------------------------------
function renderFlagstoneCourtyard() {
  // Base courtyard ground wash (deep moss & damp stone earth for the joints)
  drawClippedFillPoly(
    [[395, 495], [1010, 495], [1010, 830], [395, 830]],
    "#3d5e2b", 125, 0.2, 0.65, 0.35, 0.05
  );
  drawClippedFillPoly(
    [[420, 515], [985, 515], [985, 830], [420, 830]],
    "#5b6b6e", 85, 0.25, 0.6, 0.3, 0.05
  );

  // Generate perspective flagstone rows from y = 496 down to 826
  let vpX = 685;
  let vpY = 340;
  let rowYs = [496, 514, 535, 560, 589, 623, 663, 710, 765, 828];

  let stonePalette = [
    "#6e7d85", "#7c8b92", "#617078", "#87959c",
    "#748288", "#586770", "#7f8c8e", "#687880"
  ];

  let allStones = [];

  for (let r = 0; r < rowYs.length - 1; r++) {
    let yTop = rowYs[r];
    let yBot = rowYs[r + 1];
    let gap = map(r, 0, rowYs.length - 2, 1.8, 4.2);

    // Rays in perspective parameter u at reference line y = 700
    let uCur = 320 + (r % 2) * 38;
    while (uCur < 1120) {
      let uStep = random(68, 128);
      let uNext = uCur + uStep;

      let xAtY = (u, y) => vpX + (u - vpX) * ((y - vpY) / (700 - vpY));

      let xTL = xAtY(uCur + gap, yTop + gap * 0.65);
      let xTR = xAtY(uNext - gap, yTop + gap * 0.65);
      let xBR = xAtY(uNext - gap, yBot - gap * 0.65);
      let xBL = xAtY(uCur + gap, yBot - gap * 0.65);

      // Slight organic hand-cut corner irregularity
      let jit = map(r, 0, 8, 0.8, 2.5);
      let pts = [
        [xTL + random(-jit, jit), yTop + gap * 0.65 + random(-jit, jit)],
        [xTR + random(-jit, jit), yTop + gap * 0.65 + random(-jit, jit)],
        [xBR + random(-jit, jit), yBot - gap * 0.65 + random(-jit, jit)],
        [xBL + random(-jit, jit), yBot - gap * 0.65 + random(-jit, jit)]
      ];

      let cx = (pts[0][0] + pts[2][0]) * 0.5;
      let cy = (pts[0][1] + pts[2][1]) * 0.5;

      if (dist(cx, cy, IGX, IGY) < IGR + 45) {
        allStones.push({
          pts,
          cx,
          cy,
          r,
          col: random(stonePalette)
        });
      }
      uCur = uNext;
    }
  }

  // Draw individual flagstone watercolour washes
  for (let st of allStones) {
    drawClippedFillPoly(st.pts, st.col, random(135, 175), 0.11, 0.68, 0.48, 0.06);

    // Golden sunlit reflection on left/mid flagstones, cool shadow on right/under-canopy
    if (st.cx < 720 && random() < 0.65) {
      drawClippedFillPoly(st.pts, "#d9be72", random(38, 68), 0.16, 0.5, 0.25, 0.06);
    } else if (st.cx > 730 || st.cy < 560) {
      drawClippedFillPoly(st.pts, "#3e5263", random(40, 75), 0.14, 0.55, 0.3, 0.06);
    }
  }

  // Crisp stone edges, chiselled texture & vivid moss tufts in flagstone seams
  for (let st of allStones) {
    let clipped = clipPolyToCircle(st.pts, IGX, IGY, IGR - 1);
    if (clipped.length < 3) continue;

    // Dark shadow under bottom/right edge of each flagstone
    brush.set("HB", "#37444a", 0.55);
    for (let i = 0; i < clipped.length; i++) {
      let p1 = clipped[i];
      let p2 = clipped[(i + 1) % clipped.length];
      if (inInnerGate(p1[0], p1[1], 2) && inInnerGate(p2[0], p2[1], 2)) {
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }

    // Subtle stone grain hatching on foreground stones
    if (st.r >= 4 && random() < 0.7) {
      brush.hatchStyle("2H", "#4d5c63", 0.35);
      brush.hatch(random(5, 9), random(-8, 8), { rand: 0.08 });
      brush.noStroke();
      brush.beginShape(0.05);
      for (let p of clipped) brush.vertex(p[0], p[1]);
      brush.endShape(true);
      brush.noHatch();
    }

    // Vivid emerald/chartreuse moss growing in the joints between stones
    for (let i = 0; i < clipped.length; i++) {
      let p1 = clipped[i];
      let p2 = clipped[(i + 1) % clipped.length];
      let steps = floor(dist(p1[0], p1[1], p2[0], p2[1]) / 14);
      for (let s = 0; s <= steps; s++) {
        if (random() < 0.48) {
          let t = s / max(1, steps);
          let mx = lerp(p1[0], p2[0], t) + random(-2, 2);
          let my = lerp(p1[1], p2[1], t) + random(-2, 2);
          if (inInnerGate(mx, my, 3)) {
            let mCol = random(["#3b7d1e", "#58a329", "#78bf36", "#265712"]);
            brush.set("cpencil", mCol, random(0.65, 1.35));
            brush.line(mx, my, mx + random(-4, 4), my + random(-2.5, 2.5));
          }
        }
      }
    }
  }
}

