// ---------------------------------------------------------------------------
// SECTION 2E: FALLEN GINKGO LEAVES ON FLAGSTONES & IN CANOPY
// ---------------------------------------------------------------------------
function drawGinkgoLeaf(x, y, sz, ang, col, isDetailed = true) {
  if (!inInnerGate(x, y, 4)) return;

  // Fan-shaped bilobed ginkgo leaf geometry
  let c = cos(ang);
  let s = sin(ang);
  let rot = (lx, ly) => [x + lx * c - ly * s, y + lx * s + ly * c];

  let pts = [
    rot(0, 0),                           // base of blade
    rot(sz * 0.45, -sz * 0.58),          // left flare
    rot(sz * 0.88, -sz * 0.74),          // outer left tip
    rot(sz * 1.05, -sz * 0.42),          // upper left lobe
    rot(sz * 0.76, -sz * 0.04),          // central bilobed notch!
    rot(sz * 1.05,  sz * 0.40),          // upper right lobe
    rot(sz * 0.86,  sz * 0.72),          // outer right tip
    rot(sz * 0.42,  sz * 0.55)           // right flare
  ];

  drawClippedFillPoly(pts, col, random(185, 235), 0.05, 0.45, 0.35, 0.22);

  if (isDetailed) {
    // Tiny petiole stem & central notch vein
    let pBase = rot(0, 0);
    let pStem = rot(-sz * 0.48, sz * 0.08);
    let pNotch = rot(sz * 0.76, -sz * 0.04);
    let pLobe1 = rot(sz * 0.95, -sz * 0.42);
    let pLobe2 = rot(sz * 0.95,  sz * 0.40);

    brush.set("HB", "#8c5308", 0.38);
    brush.line(pBase[0], pBase[1], pStem[0], pStem[1]);
    brush.line(pBase[0], pBase[1], pNotch[0], pNotch[1]);
    brush.set("2H", "#b8740f", 0.3);
    brush.line(pBase[0], pBase[1], pLobe1[0], pLobe1[1]);
    brush.line(pBase[0], pBase[1], pLobe2[0], pLobe2[1]);
  }
}

