// ---------------------------------------------------------------------------
// SECTION 3: 3D ARCHITECTURAL REVEAL & STONE THRESHOLD SILL OF MOON GATE
// ---------------------------------------------------------------------------
function renderMoonGateReveal() {
  // The crescent reveal between outer circle (GCX, GCY, GR) and inner opening (IGX, IGY, IGR)
  // Upper-right & right plaster reveal (warm reflected garden gold + soft shadow)
  let revealRight = [];
  for (let a = -75; a <= 65; a += 5) {
    revealRight.push([GCX + cos(a) * GR, GCY + sin(a) * GR]);
  }
  for (let a = 65; a >= -75; a -= 5) {
    revealRight.push([IGX + cos(a) * IGR, IGY + sin(a) * IGR]);
  }
  brush.noStroke();
  brush.fill("#ded8ca", 195);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.45, 0.35);
  brush.beginShape(0.05);
  for (let p of revealRight) brush.vertex(p[0], p[1]);
  brush.endShape(true);

  // Warm golden reflected light from the ginkgo canopy onto the right inner reveal
  brush.fill("#ebd9a7", 75);
  brush.fillBleed(0.08, "in");
  brush.beginShape(0.05);
  for (let p of revealRight) brush.vertex(p[0], p[1]);
  brush.endShape(true);

  // Upper-left & top inner arch reveal (in cool shade)
  let revealTop = [];
  for (let a = 165; a <= 285; a += 5) {
    revealTop.push([GCX + cos(a) * GR, GCY + sin(a) * GR]);
  }
  for (let a = 285; a >= 165; a -= 5) {
    revealTop.push([IGX + cos(a) * IGR, IGY + sin(a) * IGR]);
  }
  brush.fill("#c2bcb0", 190);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.5, 0.4);
  brush.beginShape(0.05);
  for (let p of revealTop) brush.vertex(p[0], p[1]);
  brush.endShape(true);

  // Bottom curved grey stone sill / threshold (from angle 55 to 135 degrees)
  let sillPoly = [];
  for (let a = 50; a <= 135; a += 4) {
    sillPoly.push([GCX + cos(a) * GR, GCY + sin(a) * GR]);
  }
  for (let a = 135; a >= 50; a -= 4) {
    sillPoly.push([IGX + cos(a) * IGR, IGY + sin(a) * IGR]);
  }
  brush.fill("#8c9496", 205);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.65, 0.45);
  brush.beginShape(0.05);
  for (let p of sillPoly) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noFill();

  // Radial masonry / radial pencil shading across the inner reveal thickness
  for (let a = 0; a < 360; a += 1.6) {
    let x1 = IGX + cos(a) * IGR;
    let y1 = IGY + sin(a) * IGR;
    let x2 = GCX + cos(a) * GR;
    let y2 = GCY + sin(a) * GR;
    let d = dist(x1, y1, x2, y2);
    if (d > 2) {
      let col = (a > 50 && a < 135) ? "#4f585c" : "#8c8579";
      brush.set("2H", col, 0.42);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Stone block joint lines on the bottom sill + two stray fallen ginkgo leaves resting on the sill!
  for (let a of [68, 86, 104, 121]) {
    let x1 = IGX + cos(a) * IGR;
    let y1 = IGY + sin(a) * IGR;
    let x2 = GCX + cos(a) * GR;
    let y2 = GCY + sin(a) * GR;
    brush.set("2B", "#32383b", 0.75);
    brush.line(x1, y1, x2, y2);
  }

  // Stray golden ginkgo leaves resting right on the worn stone sill of the moon gate
  let sillLeaves = [
    { a: 78,  col: "#ffbf00", rot: 18,  sz: 13 },
    { a: 94,  col: "#ffd629", rot: 145, sz: 14 },
    { a: 97,  col: "#e88500", rot: 210, sz: 12 },
    { a: 112, col: "#ffcc00", rot: -25, sz: 13 }
  ];
  for (let sl of sillLeaves) {
    let lx = lerp(IGX + cos(sl.a) * IGR, GCX + cos(sl.a) * GR, 0.52);
    let ly = lerp(IGY + sin(sl.a) * IGR, GCY + sin(sl.a) * GR, 0.52);
    let c = cos(sl.rot), s = sin(sl.rot);
    let rPt = (px, py) => [lx + px * c - py * s, ly + px * s + py * c];
    let lPts = [
      rPt(0, 0),
      rPt(sl.sz * 0.5, -sl.sz * 0.6),
      rPt(sl.sz * 0.95, -sl.sz * 0.45),
      rPt(sl.sz * 0.72, 0),
      rPt(sl.sz * 0.95, sl.sz * 0.45),
      rPt(sl.sz * 0.5, sl.sz * 0.6)
    ];
    brush.noStroke();
    brush.fill(sl.col, 225);
    brush.fillBleed(0.03, "out");
    brush.beginShape(0.2);
    for (let p of lPts) brush.vertex(p[0], p[1]);
