// ---------------------------------------------------------------------------
// SECTION 4B: WORN EDGE OF THE ROUND MOON GATE OPENING
// ---------------------------------------------------------------------------
function renderWornGateEdge() {
  // 1. Inner rim contour (where inner reveal meets the garden)
  for (let pass = 0; pass < 2; pass++) {
    let pts = [];
    for (let a = 0; a <= 360; a += 3) {
      let rJit = IGR + (noise(a * 0.08, pass * 10) - 0.5) * 2.8;
      pts.push([IGX + cos(a) * rJit, IGY + sin(a) * rJit, random(0.5, 1.0)]);
    }
    brush.set("HB", "#544e46", 0.52);
    brush.spline(pts, 0.25);
  }

  // 2. Outer worn plaster edge of the circular moon gate (GCX, GCY, GR)
  for (let pass = 0; pass < 3; pass++) {
    let pts = [];
    for (let a = 0; a <= 360; a += 2.5) {
      let wear = (noise(a * 0.12, pass * 5 + 20) - 0.45) * 4.5;
      let rJit = GR + wear;
      let pr = map(sin(a + 45), -1, 1, 0.45, 1.15);
      pts.push([GCX + cos(a) * rJit, GCY + sin(a) * rJit, pr]);
    }
    let bName = pass === 0 ? "2B" : (pass === 1 ? "HB" : "2H");
    let bCol  = pass === 0 ? "#4a453e" : (pass === 1 ? "#6e685f" : "#968f84");
    let bW    = pass === 0 ? 0.62 : (pass === 1 ? 0.48 : 0.38);
    brush.set(bName, bCol, bW);
    brush.spline(pts, 0.25);
  }

  // 3. Soft radial bevel shading & chipped limewash flakes along the round edge
  for (let a = 0; a < 360; a += 0.9) {
    let n = noise(a * 0.15, 77);
    let bevelW = map(n, 0, 1, 3, 18);
    if (a > 130 && a < 270) bevelW *= 1.35; // slightly more worn on the left/lower-left rim

    let x1 = GCX + cos(a) * (GR - 0.5);
    let y1 = GCY + sin(a) * (GR - 0.5);
    let x2 = GCX + cos(a) * (GR + bevelW);
    let y2 = GCY + sin(a) * (GR + bevelW);

    brush.set("2H", random(["#b5aea0", "#9e9689", "#c9c3b6"]), random(0.25, 0.45));
    brush.line(x1, y1, x2, y2);
  }

  // 4. Chipped plaster scars around the rim (exposing granular grey-buff mortar beneath)
  let chipAngles = [18, 42, 118, 152, 194, 218, 256, 308, 338];
  for (let ca of chipAngles) {
    let span = random(3.5, 8.5);
    let depth = random(8, 22);
    let chipPts = [];
    for (let a = ca - span; a <= ca + span; a += 1.5) {
      let rIn = GR + random(-1.5, 2.0);
      chipPts.push([GCX + cos(a) * rIn, GCY + sin(a) * rIn]);
    }
    for (let a = ca + span; a >= ca - span; a -= 2.0) {
      let midFactor = 1 - pow((a - ca) / span, 2);
      let rOut = GR + depth * midFactor * random(0.75, 1.25);
      chipPts.push([GCX + cos(a) * rOut, GCY + sin(a) * rOut]);
    }

    // Subtle darker mortar tone inside the plaster chip
    brush.noStroke();
    brush.fill("#cfc8b8", 145);
    brush.fillBleed(0.02, "in");
    brush.beginShape(0.15);
    for (let p of chipPts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
    brush.noFill();

    // Cross-hatched mortar grain & crisp shadow lip of the peeled whitewash
    brush.hatchStyle("HB", "#7d7568", 0.32);
    brush.hatch(3.2, ca + 45, { rand: 0.15 });
    brush.set("2B", "#524b42", 0.48);
    brush.beginShape(0.15);
    for (let p of chipPts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
    brush.noHatch();
  }
}

// ---------------------------------------------------------------------------
// SECTION 4C: METICULOUS HAIRLINE PLASTER CRACKS IN THE FOREGROUND WALL
// ---------------------------------------------------------------------------
function drawPlasterCrack(startX, startY, initAngle, totalSteps, stepLen, weightStart, depth = 0) {
  let pts = [];
  let x = startX;
  let y = startY;
  let ang = initAngle;

  for (let i = 0; i < totalSteps; i++) {
    let t = i / totalSteps;
    let pr = lerp(weightStart, 0.12, pow(t, 0.75));
    pts.push([x, y, pr]);

    // Organic brittle plaster fracture angle wander
    let n = noise(x * 0.018, y * 0.018, depth * 10 + i * 0.15);
    ang += map(n, 0, 1, -24, 24) + random(-9, 9);

    let nx = x + cos(ang) * stepLen * random(0.7, 1.3);
    let ny = y + sin(ang) * stepLen * random(0.7, 1.3);

    // Stop if entering the moon gate or leaving the canvas
    if (inOuterGate(nx, ny, -2) || nx < 6 || nx > 1194 || ny < 6 || ny > 1194) {
      break;
    }

    x = nx;
    y = ny;

    // Spawn secondary & tertiary hairline fissures
    if (depth < 2 && i > 3 && i < totalSteps - 3 && random() < (depth === 0 ? 0.14 : 0.09)) {
      let branchSign = random() < 0.5 ? -1 : 1;
      let branchAng = ang + branchSign * random(22, 54);
      let branchSteps = floor((totalSteps - i) * random(0.38, 0.72));
      drawPlasterCrack(x, y, branchAng, branchSteps, stepLen * 0.82, pr * 0.68, depth + 1);
    }
  }

  if (pts.length < 2) return;

  // 1. Faint pale highlight lip along one edge of the crack (catches raking light)
  brush.set("2H", "#fcfaf5", 0.55);
  for (let i = 0; i < pts.length - 1; i++) {
    brush.line(pts[i][0] + 1.1, pts[i][1] + 0.8, pts[i + 1][0] + 1.1, pts[i + 1][1] + 0.8);
  }

  // 2. Soft graphite shadow halo along key segments of primary cracks
  if (depth === 0) {
    brush.set("2H", "#9e9689", 0.42);
    for (let i = 0; i < pts.length - 1; i += 2) {
      brush.line(pts[i][0] - 0.8, pts[i][1] + 0.8, pts[i + 1][0] - 0.8, pts[i + 1][1] + 0.8);
    }
  }

  // 3. Crisp hairline core fissure
  let crackColor = depth === 0 ? "#3d3831" : (depth === 1 ? "#635c52" : "#877f73");
  brush.set("fissure", crackColor, depth === 0 ? 0.95 : (depth === 1 ? 0.68 : 0.46));
  for (let i = 0; i < pts.length - 1; i++) {
    brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
  }

  // 4. Tiny spalled plaster crumbs at sharp fracture bends
  if (depth <= 1) {
    for (let i = 2; i < pts.length - 2; i += 4) {
      if (random() < 0.45) {
        let px = pts[i][0];
        let py = pts[i][1];
        brush.set("2B", "#4a433b", random(0.35, 0.65));
        brush.line(px - 1.5, py - 1, px + 1.5, py + 1.5);
      }
    }
  }
}

