const SEED = 48291;

// Center of the conical hat (slightly off-center for natural overhead poise)
const CX = 606;
const CY = 594;
const NUM_RINGS = 20;
const NUM_RAFTERS = 16;

// Precomputed ring data and sweat patch definitions
let ringRadii = [];
let sweatPatches = [];
let rimGaps = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Define concentric ring base radii from conical crown to outer rim
  // Stepping down like terraced paddies
  let r = 14;
  for (let k = 0; k < NUM_RINGS; k++) {
    ringRadii.push(r);
    // Step width varies organically like hillside terraces
    let step = map(k, 0, NUM_RINGS - 1, 21, 31) + sin(k * 37) * 2.5;
    r += step;
  }

  // Define sweat-darkened & weathered patches across the hat
  // Concentrated around the inner head-band crown and hand-grip brim zones
  sweatPatches = [
    { r: 115, ang: 0.85, radR: 75, radAng: 0.95, strength: 0.95 },
    { r: 145, ang: 2.35, radR: 85, radAng: 1.10, strength: 0.88 },
    { r: 105, ang: 4.10, radR: 68, radAng: 1.25, strength: 0.82 },
    { r: 160, ang: 5.50, radR: 70, radAng: 0.85, strength: 0.78 },
    { r: 310, ang: 1.15, radR: 95, radAng: 0.55, strength: 0.85 },
    { r: 390, ang: 3.65, radR: 110, radAng: 0.60, strength: 0.90 },
    { r: 465, ang: 0.42, radR: 85, radAng: 0.48, strength: 0.92 },
    { r: 450, ang: 2.75, radR: 90, radAng: 0.45, strength: 0.80 },
    { r: 255, ang: 4.95, radR: 80, radAng: 0.65, strength: 0.72 }
  ];

  // Weathered notches along the outer rim where the hat edge breaks into glimpses of seedlings below
  rimGaps = [
    { ang: 0.72, width: 0.24, depth: 2.2 },
    { ang: 2.48, width: 0.20, depth: 1.7 },
    { ang: 3.88, width: 0.28, depth: 2.5 },
    { ang: 5.42, width: 0.22, depth: 1.8 }
  ];
}

// Compute organic terraced radius and position for ring k at angle theta (in radians)
function getRingPoint(k, theta) {
  let baseR = ringRadii[k];
  let normK = k / (NUM_RINGS - 1);

  // Subtle conical overhead tilt: shifts inner rings slightly toward upper-left
  // creating wider sunlit terraces on the lower-right and steeper steps on the upper-left
  let shiftX = (1 - normK) * -14;
  let shiftY = (1 - normK) * -11;

  // Coherent topographic undulation (shared across adjacent rings like terraced contours)
  let n1 = noise(
    10 + Math.cos(theta) * 1.35 + normK * 1.6,
    10 + Math.sin(theta) * 1.35 + normK * 1.6
  ) - 0.5;
  let n2 = noise(
    30 + Math.cos(theta * 3) * 0.9 + normK * 3.2,
    30 + Math.sin(theta * 3) * 0.9
  ) - 0.5;

  // Subtle polygonization over the 16 radial bamboo rafters
  let rafterWave = Math.cos(theta * NUM_RAFTERS) * (1.2 + normK * 2.2);

  // Outer rim weathering & indentation near rim gaps
  let gapIndent = 0;
  if (k >= NUM_RINGS - 3) {
    for (let g of rimGaps) {
      let dAng = Math.atan2(Math.sin(theta - g.ang), Math.cos(theta - g.ang));
      if (Math.abs(dAng) < g.width) {
        let falloff = Math.cos((dAng / g.width) * (Math.PI / 2));
        let ringFactor = map(k, NUM_RINGS - 4, NUM_RINGS - 1, 0, 1);
        gapIndent -= falloff * falloff * g.depth * 14 * ringFactor;
      }
    }
  }

  let r = baseR + n1 * (10 + normK * 18) + n2 * (4 + normK * 8) + rafterWave + gapIndent;
  let x = CX + shiftX + r * Math.cos(theta);
  let y = CY + shiftY + r * Math.sin(theta);
  return { x, y, r };
}

// Evaluate sweat-darkening intensity (0..1) at polar coordinate (r, theta in radians)
function getSweatStrength(r, theta) {
  let total = 0;
  for (let p of sweatPatches) {
    let dAng = Math.atan2(Math.sin(theta - p.ang), Math.cos(theta - p.ang));
    let dr = (r - p.r) / p.radR;
    let da = dAng / p.radAng;
    let distSq = dr * dr + da * da;
    if (distSq < 1.8) {
      let n = noise(r * 0.025, theta * 3.0 + p.r * 0.1) * 0.45;
      let d = Math.max(0, 1 - Math.sqrt(distSq) + n - 0.2);
      total = Math.max(total, Math.min(1, d * p.strength * 1.25));
    }
  }
  return total;
}

// Check if outer ring segment is broken away into the paddy field below
function isRimBroken(k, theta) {
  if (k < NUM_RINGS - 2) return false;
  for (let g of rimGaps) {
    let dAng = Math.abs(Math.atan2(Math.sin(theta - g.ang), Math.cos(theta - g.ang)));
    let thresh = k === NUM_RINGS - 1 ? g.width * 0.72 : g.width * 0.36;
    if (dAng < thresh && g.depth > (k === NUM_RINGS - 1 ? 1.5 : 2.1)) {
      return true;
    }
  }
  return false;
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm archival cotton rag paper ground with cool mineral undertone
  background("#f2ede2");

  // -------------------------------------------------------------------------
  // 1. FLOODED PADDY BACKGROUND & WATER WASHES (OUTER EDGES & CORNERS)
  // -------------------------------------------------------------------------
  drawFloodedPaddyGround();

  // -------------------------------------------------------------------------
  // 2. BLURRED GLIMPSES OF GREEN SEEDLING ROWS BELOW THE HAT
  // -------------------------------------------------------------------------
  drawSeedlingRowsBelow();

  // -------------------------------------------------------------------------
  // 3. TERRACED HAT RINGS: TRANSLUCENT WATERCOLOR IN JADE, UMBER & SKY SILVER
  // -------------------------------------------------------------------------
  drawTerraceWatercolors();

  // -------------------------------------------------------------------------
  // 4. SWEAT-DARKENED PATCHES: TRANSLUCENT UMBER STAINS & TIDE-LINE RINGS
  // -------------------------------------------------------------------------
  drawSweatPatches();

  // -------------------------------------------------------------------------
  // 5. SUBSURFACE RADIAL BAMBOO RAFTERS & FINE STRAW WEAVE FIBERS
  // -------------------------------------------------------------------------
  drawRadialStrawWeaveAndRafters();

  // -------------------------------------------------------------------------
  // 6. WATER MENISCUS SHIMMER & TERRACE STEP SHADOWS BETWEEN RINGS
  // -------------------------------------------------------------------------
  drawTerraceShadowsAndReflections();

  // -------------------------------------------------------------------------
  // 7. PRECISION PENCIL CONTOURS: EVERY PLAITED BAND & RATTAN STITCHING
  // -------------------------------------------------------------------------
  drawPlaitedBands();

  // -------------------------------------------------------------------------
  // 8. CONICAL APEX ROSETTE (CROWN PEAK)
  // -------------------------------------------------------------------------
  drawConicalApex();

  // -------------------------------------------------------------------------
  // 9. FRAYED STRAW ENDS, SPLINTERS & OVERLAPPING RIM DETAILS
  // -------------------------------------------------------------------------
  drawFrayedStrawEnds();

  noLoop();
}

// ===========================================================================
// 1. FLOODED PADDY GROUND (WET-MUD UMBER, EMERALD WATER, SKY SILVER)
// ===========================================================================
function drawFloodedPaddyGround() {
  brush.noStroke();

  // Group watercolor polygons by color batch for speed and authentic pigment bleed
  let mudPolys = [];
  let deepJadePolys = [];
  let vividJadePolys = [];
  let skySilverPolys = [];

  // Create organic watercolor patches around the outer perimeter (r = 450..820)
  let numPatches = 28;
  for (let i = 0; i < numPatches; i++) {
    let ang1 = (i / numPatches) * TWO_PI;
    let ang2 = ((i + 1.35) / numPatches) * TWO_PI;
    let rInner = 455 + (i % 3) * 22;
    let rOuter = 720 + (i % 2) * 140;

    let pts = [];
    let steps = 5;
    for (let s = 0; s <= steps; s++) {
      let a = lerp(ang1, ang2, s / steps);
      let rr = rInner + (noise(i, s * 0.4) - 0.5) * 45;
      pts.push([CX + rr * Math.cos(a), CY + rr * Math.sin(a)]);
    }
    for (let s = steps; s >= 0; s--) {
      let a = lerp(ang1, ang2, s / steps);
      let rr = rOuter + (noise(i + 20, s * 0.4) - 0.5) * 60;
      pts.push([
        constrain(CX + rr * Math.cos(a), -20, width + 20),
        constrain(CY + rr * Math.sin(a), -20, height + 20)
      ]);
    }

    if (i % 4 === 0) mudPolys.push(pts);
    else if (i % 4 === 1) deepJadePolys.push(pts);
    else if (i % 4 === 2) vividJadePolys.push(pts);
    else skySilverPolys.push(pts);
  }

  // Batch 1: Wet-mud umber base
  brush.fill("#4d3420", 95);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.65, 0.45);
  for (let pts of mudPolys) drawCurvedShape(pts, 0.3);

  // Batch 2: Deep paddy jade water
  brush.fill("#0f6e58", 90);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.6, 0.4);
  for (let pts of deepJadePolys) drawCurvedShape(pts, 0.3);

  // Batch 3: Vivid emerald-jade water
  brush.fill("#1f9975", 82);
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.55, 0.38);
  for (let pts of vividJadePolys) drawCurvedShape(pts, 0.3);

  // Batch 4: Reflected-sky silver-cerulean water sheen
  brush.fill("#8fb8cf", 95);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.5, 0.35);
  for (let pts of skySilverPolys) drawCurvedShape(pts, 0.3);
}

// ===========================================================================
// 2. BLURRED GLIMPSES OF GREEN SEEDLING ROWS BELOW
// ===========================================================================
function drawSeedlingRowsBelow() {
  // Rice paddy rows run along an angle (~26 degrees) across the flooded field below
  let rowAngle = 0.46; // radians
  let cosA = Math.cos(rowAngle);
  let sinA = Math.sin(rowAngle);
  let perpX = -sinA;
  let perpY = cosA;

  // Collect seedling locations outside the hat or inside broken rim gaps
  let tufts = [];
  let rowSpacing = 44;

  for (let rowIdx = -16; rowIdx <= 16; rowIdx++) {
    let rowOffset = rowIdx * rowSpacing;
    for (let u = -780; u <= 780; u += 28) {
      let jitterU = u + random(-6, 6);
      let jitterV = rowOffset + sin(u * 0.25 + rowIdx * 12) * 5 + random(-4, 4);

      let x = CX + jitterU * cosA + jitterV * perpX;
      let y = CY + jitterU * sinA + jitterV * perpY;

      if (x < -15 || x > width + 15 || y < -15 || y > height + 15) continue;

      let dx = x - CX;
      let dy = y - CY;
      let theta = Math.atan2(dy, dx);
      if (theta < 0) theta += TWO_PI;

      let rimPt = getRingPoint(NUM_RINGS - 1, theta);
      let distFromCenter = Math.sqrt(dx * dx + dy * dy);
      let rimDist = Math.sqrt((rimPt.x - CX) ** 2 + (rimPt.y - CY) ** 2);

      // Keep seedlings outside the hat rim or visible through rim gaps
      let broken = isRimBroken(NUM_RINGS - 1, theta);
      let minAllowed = broken ? rimDist - 42 : rimDist - 12;

      if (distFromCenter > minAllowed) {
        tufts.push({ x, y, distFromCenter, rimDist, theta, rowIdx });
      }
    }
  }

  // 2A. Soft watercolor halos for blurred seedling rows & wet mud mounds
  brush.noStroke();
  brush.fill("#168245", 88);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.5, 0.3);
  for (let i = 0; i < tufts.length; i += 2) {
    let t = tufts[i];
    brush.circle(t.x, t.y, random(14, 24), 0.35);
  }

  brush.fill("#48bd52", 75);
  brush.fillBleed(0.4, "out");
  for (let i = 1; i < tufts.length; i += 3) {
    let t = tufts[i];
    brush.circle(t.x + random(-4, 4), t.y + random(-4, 4), random(11, 18), 0.4);
  }

  // 2B. Soft out-of-focus charcoal/pastel under-blur along the seedling rows
  for (let t of tufts) {
    // Mud shadow base & water ripple ring around each emerging seedling cluster
    brush.set("charcoal", "#2b4228", random(0.9, 1.5));
    brush.arc(t.x, t.y, random(10, 18), random(0, 120), random(200, 340));

    brush.set("cpencil", "#9dc2d4", random(0.5, 0.85));
    brush.arc(t.x, t.y, random(14, 24), random(20, 160), random(190, 310));
  }

  // 2C. Vivid green seedling blades (slightly softened with cpencil + HB to suggest depth below hat)
  let bladePalette = ["#0d5e33", "#1b8c42", "#2eb84b", "#6ce053", "#8cf065", "#147558"];
  for (let t of tufts) {
    let numBlades = floor(random(7, 13));
    for (let b = 0; b < numBlades; b++) {
      let bAng = random(0, TWO_PI);
      let bLen = random(14, 34);
      let curveBend = random(-0.45, 0.45);
      let col = bladePalette[b % bladePalette.length];

      // Soft colored pencil outer glow for blurred optical depth
      brush.set("cpencil", col, random(0.65, 1.15));
      let mx = t.x + Math.cos(bAng + curveBend * 0.5) * (bLen * 0.55);
      let my = t.y + Math.sin(bAng + curveBend * 0.5) * (bLen * 0.55);
      let ex = t.x + Math.cos(bAng + curveBend) * bLen;
      let ey = t.y + Math.sin(bAng + curveBend) * bLen;
      brush.spline([
        [t.x + random(-2, 2), t.y + random(-2, 2), 0.9],
        [mx, my, 0.65],
        [ex, ey, 0.15]
      ], 0.45);
    }
    // Bright sunlit chartreuse tip accents
    brush.set("2H", "#a7f57a", 0.45);
    let tipAng = random(0, TWO_PI);
    brush.line(
      t.x,
      t.y,
      t.x + Math.cos(tipAng) * 15,
      t.y + Math.sin(tipAng) * 15
    );
  }
}

// ===========================================================================
// 3. TERRACED HAT RINGS: TRANSLUCENT WATERCOLOR IN JADE, UMBER & SKY SILVER
// ===========================================================================
function drawTerraceWatercolors() {
  brush.noStroke();

  // First, lay a subtle warm straw wash across the entire hat dome so paper & straw glow
  let hatOutline = [];
  let outlineSteps = 48;
  for (let s = 0; s < outlineSteps; s++) {
    let theta = (s / outlineSteps) * TWO_PI;
    let pt = getRingPoint(NUM_RINGS - 1, theta);
    hatOutline.push([pt.x, pt.y]);
  }
  brush.fill("#e3cfa3", 72);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.45, 0.3);
  drawCurvedShape(hatOutline, 0.25);

  // Batch terrace strips by color family to maximize watercolor richness and speed:
  // Families:
  // 0: Pale luminous jade (#49b89f)
  // 1: Saturated paddy jade (#1c8c73)
  // 2: Wet-mud umber (#6e4829)
  // 3: Deep earthen umber (#4f321b)
  // 4: Reflected-sky silver-blue (#9abbd1)
  // 5: Luminous sky-silver highlight (#bfd7e6)
  // 6: Sunlit golden straw ochre (#cfa14e)
  let batches = [[], [], [], [], [], [], []];

  for (let k = 0; k < NUM_RINGS - 1; k++) {
    // Number of angular sectors increases slightly with radius
    let numSectors = k < 5 ? 4 : k < 12 ? 6 : 8;
    for (let s = 0; s < numSectors; s++) {
      let angStart = (s / numSectors) * TWO_PI + (k % 2) * 0.18;
      let angEnd = ((s + 0.96) / numSectors) * TWO_PI + (k % 2) * 0.18;
      let angMid = 0.5 * (angStart + angEnd);

      if (isRimBroken(k + 1, angMid)) continue;

      // Build curved terrace trough polygon between ring k and ring k+1
      // Leaving the upper ~25% of the step for the plaited band, filling the lower ~75% as water trough
      let pts = [];
      let subSteps = 6;
      for (let i = 0; i <= subSteps; i++) {
        let a = lerp(angStart, angEnd, i / subSteps);
        let p0 = getRingPoint(k, a);
        let p1 = getRingPoint(k + 1, a);
        pts.push([lerp(p0.x, p1.x, 0.24), lerp(p0.y, p1.y, 0.24)]);
      }
      for (let i = subSteps; i >= 0; i--) {
        let a = lerp(angStart, angEnd, i / subSteps);
        let p0 = getRingPoint(k, a);
        let p1 = getRingPoint(k + 1, a);
        pts.push([lerp(p0.x, p1.x, 0.94), lerp(p0.y, p1.y, 0.94)]);
      }

      // Choose color based on conical overhead lighting, terrace rhythm, and sweat patches
      let rMid = 0.5 * (ringRadii[k] + ringRadii[k + 1]);
      let sweat = getSweatStrength(rMid, angMid % TWO_PI);

      // Overhead sky light comes from upper-left (angle ~ 3.8 rad)
      let lightFacing = Math.cos(angMid - 3.85); // +1 on upper-left, -1 on lower-right

      let batchIdx;
      if (sweat > 0.58) {
        batchIdx = (k + s) % 2 === 0 ? 3 : 2; // Wet-mud umber in sweat-stained steps
      } else if (lightFacing > 0.35 && (k + s) % 3 === 0) {
        batchIdx = 5; // Bright reflected-sky silver
      } else if (lightFacing > 0.05 && (k + s) % 2 === 0) {
        batchIdx = 0; // Pale luminous jade
      } else if ((k + s) % 4 === 0) {
        batchIdx = 4; // Reflected-sky silver-blue
      } else if ((k + s) % 4 === 1) {
        batchIdx = 1; // Saturated paddy jade
      } else if ((k + s) % 4 === 2) {
        batchIdx = 2; // Wet-mud umber
      } else {
        batchIdx = 6; // Sunlit golden straw
      }

      batches[batchIdx].push(pts);
    }
  }

  const batchConfigs = [
    { col: "#49b89f", alpha: 92, bleed: 0.22 }, // 0: Pale luminous jade
    { col: "#1c8c73", alpha: 88, bleed: 0.24 }, // 1: Saturated paddy jade
    { col: "#6e4829", alpha: 86, bleed: 0.25 }, // 2: Wet-mud umber
    { col: "#4f321b", alpha: 98, bleed: 0.28 }, // 3: Deep earthen umber
    { col: "#8fb5cc", alpha: 95, bleed: 0.20 }, // 4: Reflected-sky silver-blue
    { col: "#c4dceb", alpha: 110, bleed: 0.18 }, // 5: Luminous sky-silver
    { col: "#cfa14e", alpha: 80, bleed: 0.20 }  // 6: Golden straw ochre
  ];

  for (let b = 0; b < batches.length; b++) {
    let cfg = batchConfigs[b];
    brush.fill(cfg.col, cfg.alpha);
    brush.fillBleed(cfg.bleed, "out");
    brush.fillTexture(0.55, 0.42);
    for (let pts of batches[b]) {
      drawCurvedShape(pts, 0.2);
    }
  }
}

// ===========================================================================
// 4. SWEAT-DARKENED PATCHES: TRANSLUCENT STAINS & PRECISION TIDE-LINE CONTOURS
// ===========================================================================
function drawSweatPatches() {
  // 4A. Translucent wet-umber watercolor stains over the sweat-darkened zones
  brush.noStroke();
  let stainPolysOuter = [];
  let stainPolysCore = [];

  for (let p of sweatPatches) {
    let ptsOuter = [];
    let ptsCore = [];
    let steps = 16;
    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * TWO_PI;
      let n = 0.72 + 0.45 * noise(p.r * 0.05 + Math.cos(a) * 1.5, p.ang + Math.sin(a) * 1.5);

      let rrOuter = p.r + Math.cos(a) * p.radR * n;
      let aaOuter = p.ang + Math.sin(a) * p.radAng * n * 0.65;
      ptsOuter.push([CX + rrOuter * Math.cos(aaOuter), CY + rrOuter * Math.sin(aaOuter)]);

      let rrCore = p.r + Math.cos(a) * p.radR * n * 0.58;
      let aaCore = p.ang + Math.sin(a) * p.radAng * n * 0.38;
      ptsCore.push([CX + rrCore * Math.cos(aaCore), CY + rrCore * Math.sin(aaCore)]);
    }
    stainPolysOuter.push(ptsOuter);
    stainPolysCore.push(ptsCore);
  }

  brush.fill("#664225", 68);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.65, 0.55);
  for (let pts of stainPolysOuter) drawCurvedShape(pts, 0.35);

  brush.fill("#3d2412", 74);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.7, 0.6);
  for (let pts of stainPolysCore) drawCurvedShape(pts, 0.35);

  // 4B. Fine pencil tide-line contours tracing the mineral edges of every sweat-darkened patch
  for (let idx = 0; idx < sweatPatches.length; idx++) {
    let p = sweatPatches[idx];
    for (let ringLayer = 0; ringLayer < 3; ringLayer++) {
      let scale = 1.0 - ringLayer * 0.16;
      let col = ringLayer === 0 ? "#3b2615" : ringLayer === 1 ? "#24160b" : "#593b22";
      let w = ringLayer === 0 ? 0.42 : 0.32;
      brush.set("2H", col, w);

      let contourPts = [];
      let steps = 28;
      for (let i = 0; i <= steps; i++) {
        let a = (i / steps) * TWO_PI;
        let n = 0.72 + 0.45 * noise(
          p.r * 0.05 + Math.cos(a) * 1.5 + ringLayer * 0.2,
          p.ang + Math.sin(a) * 1.5 + ringLayer * 0.2
        );
        let rr = constrain(p.r + Math.cos(a) * p.radR * n * scale, 18, 528);
        let aa = p.ang + Math.sin(a) * p.radAng * n * 0.65 * scale;
        let px = CX + rr * Math.cos(aa);
        let py = CY + rr * Math.sin(aa);
        contourPts.push([px, py, 0.4 + 0.4 * sin(i * 35)]);
      }
      brush.spline(contourPts, 0.35);
    }
  }
}

// ===========================================================================
// 5. SUBSURFACE RADIAL BAMBOO RAFTERS & FINE STRAW WEAVE FIBERS
// ===========================================================================
function drawRadialStrawWeaveAndRafters() {
  // 5A. 16 Radial Bamboo Rafters running from crown to rim
  for (let rIdx = 0; rIdx < NUM_RAFTERS; rIdx++) {
    let baseTheta = (rIdx / NUM_RAFTERS) * TWO_PI;
    for (let side of [-1, 1]) {
      let pts = [];
      for (let k = 0; k < NUM_RINGS; k++) {
        let pt = getRingPoint(k, baseTheta);
        let perpX = -Math.sin(baseTheta) * side * 2.2;
        let perpY = Math.cos(baseTheta) * side * 2.2;
        pts.push([pt.x + perpX, pt.y + perpY, 0.45]);
      }
      brush.set("2H", "#4d3926", 0.36);
      brush.spline(pts, 0.2);
    }
  }

  // 5B. Fine radial flattened palm-leaf / straw strips & longitudinal fiber striations
  // Stepping down ring by ring with patient concentric rhythm
  for (let k = 0; k < NUM_RINGS - 1; k++) {
    let rMid = 0.5 * (ringRadii[k] + ringRadii[k + 1]);
    // Number of radial straw strips scales with circumference
    let numStrips = floor(map(k, 0, NUM_RINGS - 2, 36, 220));

    for (let s = 0; s < numStrips; s++) {
      let theta = (s / numStrips) * TWO_PI + (k % 2) * (PI / numStrips);
      if (isRimBroken(k + 1, theta)) continue;

      let pInner = getRingPoint(k, theta);
      let pOuter = getRingPoint(k + 1, theta);

      // Slight shingle overlap angle for each flattened leaf strip
      let thetaNext = theta + (TWO_PI / numStrips) * 0.85;
      let pOuterNext = getRingPoint(k + 1, thetaNext);

      let sweat = getSweatStrength(rMid, theta % TWO_PI);

      // Primary straw strip edge contour
      let edgeCol = sweat > 0.55 ? "#382414" : (s % 3 === 0 ? "#5e462d" : "#806443");
      let edgeWeight = sweat > 0.55 ? 0.38 : 0.28;
      brush.set("2H", edgeCol, edgeWeight);

      let x1 = lerp(pInner.x, pOuter.x, 0.18);
      let y1 = lerp(pInner.y, pOuter.y, 0.18);
      let x2 = lerp(pInner.x, pOuter.x, 0.96);
      let y2 = lerp(pInner.y, pOuter.y, 0.96);
      brush.line(x1, y1, x2, y2);

      // Diagonal shingle overlap crease
      if (s % 2 === 0) {
        brush.set("2H", sweat > 0.5 ? "#2e1d10" : "#9c7c52", 0.24);
        brush.line(
          lerp(pInner.x, pOuter.x, 0.22),
          lerp(pInner.y, pOuter.y, 0.22),
          lerp(pInner.x, pOuterNext.x, 0.92),
          lerp(pInner.y, pOuterNext.y, 0.92)
        );
      }

      // Extra sweat-darkened cross-weave graphite shading inside stained patches
      if (sweat > 0.48) {
        brush.set("HB", "#2b1b0e", 0.32 * sweat);
        let xm1 = lerp(pInner.x, pOuter.x, 0.45);
        let ym1 = lerp(pInner.y, pOuter.y, 0.45);
        let xm2 = lerp(pInner.x, pOuterNext.x, 0.65);
        let ym2 = lerp(pInner.y, pOuterNext.y, 0.65);
        brush.line(xm1, ym1, xm2, ym2);
      }
    }
  }
}

// ===========================================================================
// 6. WATER MENISCUS SHIMMER & TERRACE STEP SHADOWS BETWEEN RINGS
// ===========================================================================
function drawTerraceShadowsAndReflections() {
  for (let k = 0; k < NUM_RINGS - 1; k++) {
    let steps = floor(map(k, 0, NUM_RINGS - 2, 40, 160));

    for (let s = 0; s < steps; s++) {
      let theta1 = (s / steps) * TWO_PI;
      let theta2 = ((s + 0.85) / steps) * TWO_PI;
      if (isRimBroken(k + 1, theta1)) continue;

      let p0a = getRingPoint(k, theta1);
      let p1a = getRingPoint(k + 1, theta1);
      let p0b = getRingPoint(k, theta2);
      let p1b = getRingPoint(k + 1, theta2);

      let sweat = getSweatStrength(p0a.r, theta1);

      // 6A. Crisp terrace drop-shadow immediately under plaited band k
      let sx1 = lerp(p0a.x, p1a.x, 0.20);
      let sy1 = lerp(p0a.y, p1a.y, 0.20);
      let sx2 = lerp(p0b.x, p1b.x, 0.20);
      let sy2 = lerp(p0b.y, p1b.y, 0.20);

      brush.set("2B", sweat > 0.5 ? "#1a1109" : "#2e2115", sweat > 0.5 ? 0.52 : 0.38);
      brush.line(sx1, sy1, sx2, sy2);

      // 6B. Shimmering water meniscus & reflected-sky silver ripple line inside the step trough
      if ((s + k) % 2 === 0) {
        let frac = 0.55 + 0.22 * sin(s * 29 + k * 43);
        let wx1 = lerp(p0a.x, p1a.x, frac);
        let wy1 = lerp(p0a.y, p1a.y, frac);
        let wx2 = lerp(p0b.x, p1b.x, frac);
        let wy2 = lerp(p0b.y, p1b.y, frac);

        let rippleCol = (s + k) % 4 === 0 ? "#e3f2fa" : "#5ec4ad";
        brush.set("cpencil", rippleCol, 0.42);
        brush.line(wx1, wy1, wx2, wy2);
      }

      // 6C. Lower terrace water pool edge (just inside ring k+1)
      if (s % 2 === 0) {
        let lx1 = lerp(p0a.x, p1a.x, 0.88);
        let ly1 = lerp(p0a.y, p1a.y, 0.88);
        let lx2 = lerp(p0b.x, p1b.x, 0.88);
        let ly2 = lerp(p0b.y, p1b.y, 0.88);

        brush.set("2H", "#195e4c", 0.30);
        brush.line(lx1, ly1, lx2, ly2);
      }
    }
  }
}

// ===========================================================================
// 7. PRECISION PENCIL CONTOURS: EVERY PLAITED BAND & RATTAN STITCHING
// ===========================================================================
function drawPlaitedBands() {
  for (let k = 0; k < NUM_RINGS; k++) {
    let normK = k / (NUM_RINGS - 1);
    // Band thickness grows subtly from crown to outer rim
    let bandHalfWidth = map(k, 0, NUM_RINGS - 1, 2.6, 5.4);
    let contourSteps = floor(map(k, 0, NUM_RINGS - 1, 48, 180));

    // 7A. Continuous Inner and Outer Precision Pencil Contours of the Plaited Band
    let innerSeg = [];
    let outerSeg = [];
    let centerSeg = [];

    for (let i = 0; i <= contourSteps; i++) {
      let theta = (i / contourSteps) * TWO_PI;

      if (isRimBroken(k, theta)) {
        if (innerSeg.length > 2) {
          drawBandContours(innerSeg, outerSeg, centerSeg, k);
        }
        innerSeg = [];
        outerSeg = [];
        centerSeg = [];
        continue;
      }

      let pt = getRingPoint(k, theta);
      let radX = Math.cos(theta);
      let radY = Math.sin(theta);

      let pVal = 0.45 + 0.35 * sin(i * 19 + k * 31);
      innerSeg.push([pt.x - radX * bandHalfWidth, pt.y - radY * bandHalfWidth, pVal]);
      outerSeg.push([pt.x + radX * bandHalfWidth, pt.y + radY * bandHalfWidth, pVal]);
      centerSeg.push([pt.x, pt.y, pVal * 0.85]);
    }

    if (innerSeg.length > 2) {
      drawBandContours(innerSeg, outerSeg, centerSeg, k);
    }

    // 7B. Individual Plaited Herringbone / Chevron Weave Strands & Rattan Ties
    let numPlaits = floor(map(k, 0, NUM_RINGS - 1, 36, 260));
    let dTheta = TWO_PI / numPlaits;

    for (let p = 0; p < numPlaits; p++) {
      let theta1 = p * dTheta;
      let theta2 = (p + 0.92) * dTheta;
      let thetaMid = (p + 0.46) * dTheta;

      if (isRimBroken(k, thetaMid)) continue;

      let pt1 = getRingPoint(k, theta1);
      let ptMid = getRingPoint(k, thetaMid);
      let pt2 = getRingPoint(k, theta2);

      let r1x = Math.cos(theta1) * bandHalfWidth * 0.88;
      let r1y = Math.sin(theta1) * bandHalfWidth * 0.88;
      let r2x = Math.cos(theta2) * bandHalfWidth * 0.88;
      let r2y = Math.sin(theta2) * bandHalfWidth * 0.88;

      let sweat = getSweatStrength(ptMid.r, thetaMid);

      // Alternating herringbone plait strands (inner-to-center and outer-to-center)
      let strandCol = sweat > 0.55
        ? (p % 2 === 0 ? "#2e1c0e" : "#4f341d")
        : (p % 2 === 0 ? "#3d2a18" : "#785834");

      brush.set("2H", strandCol, k === NUM_RINGS - 1 ? 0.44 : 0.32);

      // Upper chevron slant
      brush.line(
        pt1.x - r1x,
        pt1.y - r1y,
        ptMid.x,
        ptMid.y
      );
      // Lower chevron slant
      brush.line(
        pt2.x + r2x,
        pt2.y + r2y,
        ptMid.x,
        ptMid.y
      );

      // Sunlit golden straw highlight on every 3rd plait segment
      if (p % 3 === 0 && sweat < 0.5) {
        brush.set("cpencil", "#f0d999", 0.35);
        brush.line(
          pt1.x + r1x * 0.6,
          pt1.y + r1y * 0.6,
          ptMid.x - r1x * 0.3,
          ptMid.y - r1y * 0.3
        );
      }

      // Crisp dark rattan thread lashing knots binding the bamboo rib at regular intervals
      if (p % 6 === 0) {
        brush.set("rotring", "#17100a", 0.48);
        let tieX1 = ptMid.x - Math.cos(thetaMid + 0.015) * (bandHalfWidth * 1.18);
        let tieY1 = ptMid.y - Math.sin(thetaMid + 0.015) * (bandHalfWidth * 1.18);
        let tieX2 = ptMid.x + Math.cos(thetaMid - 0.015) * (bandHalfWidth * 1.18);
        let tieY2 = ptMid.y + Math.sin(thetaMid - 0.015) * (bandHalfWidth * 1.18);
        brush.line(tieX1, tieY1, tieX2, tieY2);
      }
    }
  }
}

function drawBandContours(innerSeg, outerSeg, centerSeg, k) {
  let isRim = k === NUM_RINGS - 1;
  // Crisp outer & inner boundaries of the plaited bamboo ring
  brush.set("2H", "#24180e", isRim ? 0.58 : 0.42);
  brush.spline(innerSeg, 0.25);

  brush.set("HB", "#1c120a", isRim ? 0.65 : 0.46);
  brush.spline(outerSeg, 0.25);

  // Split bamboo core ridge line running down the center of the plait
  brush.set("2H", "#664b2c", 0.30);
  brush.spline(centerSeg, 0.25);
}

// ===========================================================================
// 8. CONICAL APEX ROSETTE (THE WOVEN CROWN BUTTON AT THE PEAK)
// ===========================================================================
function drawConicalApex() {
  // Center of ring 0 (accounting for conical overhead tilt)
  let pCenter = getRingPoint(0, 0);
  let ax = CX - 14;
  let ay = CY - 11;

  // Deep shadow under the woven apex cap
  brush.noStroke();
  brush.fill("#362110", 125);
  brush.fillBleed(0.18, "out");
  brush.circle(ax, ay, 16, 0.25);

  // Starburst of 24 tightly bound straw tips converging at the peak
  for (let i = 0; i < 24; i++) {
    let a = (i / 24) * TWO_PI;
    let rOut = 15 + (i % 2) * 3;
    brush.set("2H", i % 2 === 0 ? "#1f140b" : "#5c4124", 0.4);
    brush.line(
      ax + Math.cos(a) * 2.5,
      ay + Math.sin(a) * 2.5,
      ax + Math.cos(a + 0.12) * rOut,
      ay + Math.sin(a + 0.12) * rOut
    );
  }

  // Tightly wound spiral rattan thread binding the apex cone
  let spiralPts = [];
  for (let t = 0; t <= 42; t++) {
    let a = t * 0.48;
    let r = map(t, 0, 42, 1.5, 13.5);
    spiralPts.push([ax + Math.cos(a) * r, ay + Math.sin(a) * r, 0.55]);
  }
  brush.set("rotring", "#1a1109", 0.45);
  brush.spline(spiralPts, 0.3);
}

// ===========================================================================
// 9. FRAYED STRAW ENDS, SPLINTERS & OVERLAPPING RIM DETAILS
// ===========================================================================
function drawFrayedStrawEnds() {
  // 9A. Intermediate frayed straw ends poking out from weathered rings across the hat
  for (let k = 2; k < NUM_RINGS - 1; k++) {
    let numFrays = floor(map(k, 2, NUM_RINGS - 2, 10, 42));
    for (let f = 0; f < numFrays; f++) {
      let theta = random(0, TWO_PI);
      if (isRimBroken(k, theta)) continue;

      let pt = getRingPoint(k, theta);
      let sweat = getSweatStrength(pt.r, theta);

      // Fray probability and length increase in weathered/sweat-darkened areas
      if (random() > 0.52 + sweat * 0.38) continue;

      let frayLen = random(9, 26) * (1 + sweat * 0.35);
      let frayAng = theta + random(-0.42, 0.42);
      let bend = random(-0.35, 0.35);

      let mx = pt.x + Math.cos(frayAng) * (frayLen * 0.55);
      let my = pt.y + Math.sin(frayAng) * (frayLen * 0.55);
      let ex = pt.x + Math.cos(frayAng + bend) * frayLen;
      let ey = pt.y + Math.sin(frayAng + bend) * frayLen;

      // Cast hairline shadow on the terrace water below
      brush.set("2H", "#1c130b", 0.32);
      brush.line(pt.x + 1.5, pt.y + 1.8, ex + 2.2, ey + 2.5);

      // Crisp straw splinter body & pencil contour
      let strawCol = random() < 0.45 ? "#e6c983" : "#9c7438";
      brush.set("cpencil", strawCol, 0.48);
      brush.spline([[pt.x, pt.y, 0.8], [mx, my, 0.55], [ex, ey, 0.2]], 0.35);

      brush.set("rotring", "#2b1c0f", 0.28);
      brush.spline([[pt.x, pt.y, 0.65], [mx, my, 0.45], [ex, ey, 0.15]], 0.35);
    }
  }

  // 9B. Dense, hyper-detailed frayed straw ends around the outer rim (and broken rim gaps)
  // Breaking into the blurred green seedling rows below
  let rimFrays = 340;
  for (let i = 0; i < rimFrays; i++) {
    let theta = (i / rimFrays) * TWO_PI + random(-0.008, 0.008);
    let broken = isRimBroken(NUM_RINGS - 1, theta);
    let sourceRing = broken ? NUM_RINGS - 2 : NUM_RINGS - 1;
    if (isRimBroken(sourceRing, theta)) sourceRing = NUM_RINGS - 3;

    let pt = getRingPoint(sourceRing, theta);

    // Straw ends fan outward at slight woven angles
    let frayLen = broken ? random(22, 62) : random(12, 46);
    let outAng = theta + random(-0.38, 0.38);
    let curl = random(-0.45, 0.45);

    let mx = pt.x + Math.cos(outAng) * (frayLen * 0.52);
    let my = pt.y + Math.sin(outAng) * (frayLen * 0.52);
    let ex = pt.x + Math.cos(outAng + curl) * frayLen;
    let ey = pt.y + Math.sin(outAng + curl) * frayLen;

    // Drop shadow onto the flooded paddy below
    brush.set("HB", "#172419", 0.38);
    brush.line(pt.x + 2, pt.y + 2.5, ex + 3.5, ey + 4);

    // Golden-ochre or weathered-umber straw fiber body
    let fiberCol = i % 3 === 0 ? "#edd495" : i % 3 === 1 ? "#b88a44" : "#6e4e2a";
    brush.set("cpencil", fiberCol, random(0.45, 0.72));
    brush.spline([[pt.x, pt.y, 0.85], [mx, my, 0.6], [ex, ey, 0.2]], 0.4);

    // Fine pencil contour tracing the frayed straw edge
    brush.set("2H", "#24170c", random(0.28, 0.42));
    brush.spline([[pt.x, pt.y, 0.75], [mx, my, 0.5], [ex, ey, 0.15]], 0.4);

    // Split bifid tip on longer frayed ends
    if (frayLen > 30 && i % 2 === 0) {
      let splitAng = outAng + curl + (random() < 0.5 ? 0.32 : -0.32);
      let sx = mx + Math.cos(splitAng) * (frayLen * 0.48);
      let sy = my + Math.sin(splitAng) * (frayLen * 0.48);
      brush.set("2H", "#362312", 0.26);
      brush.line(mx, my, sx, sy);
    }
  }
}

// Helper to draw a closed curved polygon safely with p5.brush
function drawCurvedShape(pts, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}
